  str_item_3420136 = "3주년 추억 협력 상자",
  str_item_intro_3420136 = "사용 시 지정 5성 오로리안 명단 중 1명을 선택해 함께 싸울 수 있습니다. 선택 범위: <color=#ffffff>도엔/보나시외/알루라/피트만/로라/루즈/모모&안즈/메이/레인보우/새디/브랜디/리청/마티외/아나톨리/쟈키니/보프/33호/버질</color>",
