  str_item_intro_3420137 = "지정 6성 오로리안 명단 중 1명을 선택해 함께 싸울 수 있습니다. 선택 범위: <color=#ffffff>티아라/진예/알골/이스타반 더 스칼드 피스/선극/레베카/단당/자리야/안토니/로렐라이/세나/조슈아/솔라드 디 올마이티 클레머/잉겔/레오/하티/티나/레인/예리아/목월백/종서/비크/악셀리아/리리카/미노스/폴룩스/제노/피아/카렌 더 스몰더링 소울/니나/바튼 더 데프트 블레이드/길스/레노어/아주르/요우/아메모리/린네/플로리나/루비/시오반/노비오/헤이디/베델/루크/파로마/그람/레비/스모키/플뢰르/베릴/히이로/사메야마/이브/우리엘/카렌/시로나/샤리/라파엘/코놀리/카론/엘시/빅토리아/요나/나시리스/가브리엘/미자드/미카엘/그로누/이리돈/레이스</color>\n※주의: 3주년 특선 소집상자는 사용 기한이 존재하며, 기간 만료 시 자동으로 3000루맘버로 전환되어 우편으로 지급됩니다. 사용 기간: 2024년 8월 16일 18:00",
