  str_item_6002016 = "트윈 하프",
  str_item_6002017 = "톱니 전차",
  str_item_6002018 = "거대괴수 요새 횡단",
  str_item_6002019 = "공허의 사색",
  str_item_6002020 = "사막의 준마",
  str_item_6002021 = "무너지는 국면",
  str_item_6002022 = "주마등",
  str_item_6002023 = "선성탑",
  str_item_6002024 = "겨울잠에 빠진 괴수",
  str_item_6002025 = "타오르는 불꽃",
  str_item_6000620 = "엔진 7호",
  str_item_6000621 = "방어포탑",
  str_item_6001500 = "점취",
  str_item_6001507 = "눈의 과거",
  str_item_6001508 = "폴라로이드 사진",
  str_item_6001510 = "여전한 꽃향기",
  str_item_6001511 = "촉음의 불씨",
  str_item_6001512 = "양치기의 지팡이",
  str_item_6001515 = "수호자-가상 머신",
  str_item_6001516 = "설탕 인형",
  str_item_6001517 = "하이테크 밴드",
  str_item_6001520 = "수장의 목걸이",
  str_item_6001521 = "전우의 인식표",
  str_item_6001524 = "게임 콘솔",
  str_item_6001525 = "영감이 빛나는 순간",
  str_item_6001526 = "타오르는 훈장",
  str_item_6001529 = "핏빛 성전",
  str_item_6001530 = "친구의 증거",
  str_item_6001531 = "사랑의 노래",
  str_item_6001532 = "그대를 위한 별빛",
  str_item_intro_6000001 = "동행 기념훈장. 오랜 세월이 지나며 놀라울 정도로 돈이 쌓였다. 지갑으로 집을 가득 채울 수 있을 정도다.",
  str_item_intro_6000002 = "동행 기념훈장. 계산할 수 없을 정도의 재산. 그냥 보고만 있어도 머리가 어지러워지고 마음을 주체할 수 없을 정도다. 특히 움브라톤의 상인이라면 더더욱 그럴 것이다.",
  str_item_intro_6000101 = "동행 기념훈장. 그저 몇 번의 시도일 뿐이지만, 미래는 가늠할 수 없는 법이다.",
  str_item_intro_6000102 = "동행 기념훈장. 콜로서스를 자유롭게 조종할 수 있게 되었다! 파이어플라이들 간의 결속도 더욱 굳건해진 느낌이다.",
  str_item_intro_6000103 = "동행 기념훈장. 눈앞도, 주위도 온통 구름뿐이다. 흰 구름 너머로 대지와 구름 위의 파란 하늘을 둘러본다.",
  str_item_intro_6000104 = "동행 기념훈장. 「스카이워커호」를 타고 긴 여행을 하는 동안, 하늘은 마음대로 노닐 수 있는 조종사의 정원이나 다름없게 되었다.",
  str_item_intro_6000201 = "동행 기념훈장. 지금까지 보아온 대륙을 마음속에 새기고 손을 들어 그려내니, 마치 평면 위의 세상 같다.",
  str_item_intro_6000202 = "동행 기념훈장. 긴 시간을 보내며 이제 대륙의 지형에 대해서도 충분히 파악했겠지? 머릿속으로 그 모습을 떠올릴 수 있지 않아?",
  str_item_intro_6000301 = "동행 기념훈장. 앞에 놓인 길은 끝없이 이어져 있을 것이다. 수많은 동료는 모두 믿을 수 있는 사람들이다.",
  str_item_intro_6000302 = "동행 기념훈장. 많은 곳을 여행하며 눈이 어지러울 정도로 많은 친구를 사귀었을 것이다.",
  str_item_intro_6000303 = "동행 기념훈장. 어디를 가든 항상 동료들이 주위에 가득하다. 함께 많은 도전을 마주하고 즐거움과 고통, 이야기를 나눈다.",
  str_item_intro_6000401 = "동행 기념훈장. 진정한 힘을 각성하는 동료가 생길 때마다 하늘에서 신비한 빛이 반짝이는 것 같다. 어쩌면 이게 「빛」의 힘에 담긴 신비한 결속이겠지...",
  str_item_intro_6000402 = "동행 기념훈장. 그들이 「빛」의 힘을 손에 넣자, 하늘 위에서 반짝이던 빛이 그들의 손에 내려앉았다.",
  str_item_intro_6000403 = "동행 기념훈장. 「빛」의 힘을 가지고 있는 동료들이 그들의 힘을 모아 특별한 이가 빛날 수 있도록 했고, 이제 빛이 없는 자도 사방을 밝힐 수 있다.",
  str_item_intro_6000501 = "동행 기념훈장. 서로를 향해 반짝이는 두 개의 별은 서로 간의 믿음을 보여준다. 마치 이 두 별처럼 서로를 비추며 영원히 함께한다.",
  str_item_intro_6000502 = "동행 기념훈장. 별들은 이동하며 그 경로 속에서 한데 모인다. 그들의 마음과 생각처럼 「믿음」이라는 길에서 모이고 이어지며 공명한다.",
  str_item_intro_6000503 = "동행 기념훈장. 동료는 하늘 위의 별들과도 같다. 그 빛은 절대적인 믿음뿐만 아니라 이념과 모여드는 의지를 의미한다.",
  str_item_intro_6000601 = "동행 기념훈장. 비록 첫 만남이지만 그 일치감은 이미 심겨 있었다. 네 손이 마치 하나의 손처럼 움직이며 마음이 연결된다.",
  str_item_intro_6000602 = "동행 기념훈장. 기나긴 매몰에도 불구하고 하늘을 날던 그 느낌을 잊을 수 없다. 처음이라 해도 그걸로 충분하다.",
  str_item_intro_6000603 = "동행 기념훈장. 가까워지는 발소리는 위험일 뿐만 아니라 다가오는 붕괴 또한 알려주고 있다.",
  str_item_intro_6000604 = "동행 기념훈장. 무수한 적 앞에서 그는 굉음과 함께 「동귀어진」을 택했다. 이는 무의미한 희생이 아니라 현명한 전술이었다.",
  str_item_intro_6000605 = "동행 기념훈장. 일족의 소식이다! 하지만 그 희미한 소리 속에는 어떤 마음과 어떤 과거가 담겨 있을까?",
  str_item_intro_6000606 = "동행 기념훈장. 그것은 아주라이트, 문명의 중심이자 영원히 무너지지 않는 광명의 상징이다.",
  str_item_intro_6000607 = "동행 기념훈장. 「미래는 빛이 아닌 어둠에 속한다.」 지금 이 순간, 그녀의 미소는 그 무엇보다 사악했다. 본래는 동족이었지만 이제는 각자의 길을 가게 되었다.",
  str_item_intro_6000608 = "동행 기념훈장. 적의 음모에 당하여 의기소침해 있을 때, 바람을 타고 날아온 민들레가 눈에 들어왔다. 미래는 어떻게 될까? 아니면 내일이 있기는 할까?",
  str_item_intro_6000609 = "동행 기념훈장. 아스트라 대륙의 속담 중에는 「노력보다는 선택」이라는 말이 있다. 많은 이들이 운명의 길목에서 망설이고는 한다. 이때는 자신의 마음과 직감, 동료를 믿어야만 한다.",
  str_item_intro_6000610 = "동행 기념훈장. 빛의 다발을 무기로 삼는다는 것은 아마 영원히 추락하지 않는 도시만이 해낼 수 있을 것이다. 그 대가는 엄청나지만, 적을 처치하기 위해 그럴만한 가치가 있다.",
  str_item_intro_6000611 = "동행 기념훈장. 검은 콜로서스는 이미 한 줄기의 검은 연기로 화했다. 하지만 녀석과 그 주인은 아직 살아있다...",
  str_item_intro_6000612 = "동행 기념훈장. 힘을 추구하는 사람은 결국 그 힘에 죽기 마련이다. 그녀가 어둠에 투항했을 때, 어둠 속에 몸이 가라앉는 것은 그녀에게 정해진 결말이었다.",
  str_item_intro_6000613 = "동행 기념훈장. 선은 수학적 언어로 표현되는 '자연'이며, 노틸러스는 가치를 담는 용기이므로 연속이 반드시 필요한 것은 아니다.",
  str_item_intro_6000614 = "동행 기념훈장. 과거에서 유래된 이념으로, 전쟁을 위해 일하던 둘은 이제 다른 길을 가고 있다.",
  str_item_intro_6000615 = "동행 기념훈장. '화음 연결' 아래에서 그녀는 한없이 깊은 잠에 빠졌다. 깨어나기만 한다면 깊이 잠들어 있는 강한 힘을 발휘할 것이 분명하다.",
  str_item_intro_6000616 = "동행 기념훈장. 귀환의 탑 아래에서 마침내 아이테르는 자신의 집을 갖게 되었다. 그리고 다시 나타난 그 탑은 그의 운명까지 바꾸어 놓았다.",
  str_item_intro_6000617 = "동행 기념훈장. 영원한 밤의 지대 탐색을 앞두고, 백야성의 기사와 일루미나 연방 군인들도 연합을 준비했다. 그곳은 웬만큼 위험한 곳이 아니기 때문이다.",
  str_item_intro_6000618 = "동행 기념훈장. 많은 세력이 연합 훈련에 참여했다. 이 상은 더없이 큰 명예를 상징한다.",
  str_item_intro_6000619 = "동행 기념훈장. 지하성의 가장 깊은 곳, 무거운 대문은 중요한 물건이 도둑의 손에 떨어지지 않도록 모든 침략자를 막아낸다.",
  str_item_intro_6000701 = "동행 기념훈장. 이것은 시작일 뿐만 아니라 단서가 드러나는 순간이다. 그 도전들 앞에서 계속해서 승리하는 것은 정상에 오를 유력한 자일 것이다.",
  str_item_intro_6000702 = "동행 기념훈장. 끊임없이 뛰어넘고 끊임없이 기어오른다. 비록 수많은 위험과 어려움이 있었지만 쉬지 않고 나아간다. 이것이 바로 각성 후의 힘일까?",
  str_item_intro_6000703 = "동행 기념훈장. 높은 정상에 도착했을 때, 그 업적은 사람들을 굽어볼 수 있을 정도였다. 하지만 등반하는 이는 만족하지 않는다. 마지막 목표를 아직 달성하지 못했기 때문이다.",
  str_item_intro_6000704 = "동행 기념훈장. 정상에 도달한 등반가들은 대부분의 도전자들을 능가한 것이다. 하지만 아직 만족하지 못한 발걸음은 멈추지 않는다.",
  str_item_intro_6000705 = "동행 기념훈장. 정상에서 겪은 수많은 전투.\n정상에서의 어려움을 어찌 알리.\n정상에 앉아 왕좌를 차지하고,\n오르내리는 많은 사람을 내려본다.",
  str_item_intro_6000706 = "동행 기념훈장. 처음이라고는 하지만 이 경지까지 들어설 수 있는 사람은 분명 평범하지 않다. 이 한 번으로 이미 많은 이들을 아득히 뛰어넘은 것이다.",
  str_item_intro_6000801 = "동행 기념훈장. 뜻하지 않은 수감, 뜻하지 않은 만남.\n감옥에서 사슬을 부수는 자가 그 안에 갇히길 원할 리가.",
  str_item_intro_6000802 = "동행 기념훈장. 고양이가 원하는 게 뭘까? 가장 좋아하는 통조림이 아니라면, 그건...",
  str_item_intro_6000803 = "동행 기념훈장. '홀리데이'의 가족이며, 이 카페야말로 자신의 거처이자 집이라는 걸 깨닫게 한 존재...",
  str_item_intro_6000804 = "동행 기념훈장. 눈과 얼음 속 궁전은 굳게 닫혀 있다. 오로라를 바라보는 작고 앙상한 그림자가 나타나야만 활짝 열린다.",
  str_item_intro_6000901 = "동행 기념훈장. 지면에 생긴 수많은 균열이 벌집처럼 모여 거미줄처럼 이어져 있다. 일이 쉽지 않음을 말하는 불길한 냄새가 솟아난다...",
  str_item_intro_6000902 = "동행 기념훈장. 칠흑같이 어두운 동굴 안. 그곳에 들어간 자의 빛만이 반짝거린다. 그러나 결코 조용하지 않은 이곳엔 많은 원주민이 방문자를 환영하고 있다.",
  str_item_intro_6000903 = "동행 기념훈장. 끝이란 게 있는 걸까? 계속 탐색하다 보면 이런 생각이 머릿속을 맴돈다. 그러나 꿋꿋한 탐색자는 위험을 무릅쓰고 다시 도전할 것이다.",
  str_item_intro_6001001 = "동행 기념훈장. 영상도 하나의 무기이며, 거짓도 하나의 칼날이다. 때로는 두 눈이 강인한 팔보다 더 유용할 때가 있다.",
  str_item_intro_6001002 = "동행 기념훈장. 타올라라! 활활 타오르는 불꽃을 보고 있으면 모든 적을 파멸시킬 것이다.",
  str_item_intro_6001003 = "동행 기념훈장. 커다란 외침은 적의 존재를 알리는 것이고, 침묵은 그의 무덤이자 결말이다.",
  str_item_intro_6001004 = "동행 기념훈장. 과연 두려운 것은 적인가, 공허인가. 이 같은 존재를 정복하려면 영원한 봉인에 가두는 수밖에 없다.",
  str_item_intro_6001005 = "동행 기념훈장. 형체가 없는 몸은 떠도는 의식뿐이다. 하지만 빛의 쓰나미에도 결국은 사라질 수밖에 없다.",
  str_item_intro_6001006 = "동행 기념훈장. 운명의 불의는 사람을 미치게 하고, 나아가 어둠에 빠지게 한다. 이 지경에 이르면 남는 것은 총과 검의 징벌뿐.",
  str_item_intro_6001007 = "동행 기념훈장. 매 순간 끝없는 고통을 받고, 매 순간 극도의 광기에 빠져 이 모든 것을 끝내라! 그것이야말로 최고의 선물이다.",
  str_item_intro_6001008 = "동행 기념훈장. 하루 중 새벽녘이 가장 어둡다. 고통을 견디면 아침의 첫 햇살 아래서 달릴 수 있다.",
  str_item_intro_6001009 = "동행 기념훈장. 온전치 못한 소리와 귀에 담을 수 없는 소리들이 만나 적의 고통이 된다.",
  str_item_intro_6001010 = "동행 기념훈장. 갈 곳이 없는 사람이 추방될 수 있을까? 가능할지도 모른다. 다만 사람들이 볼 수 없을 뿐.",
  str_item_intro_6001011 = "동행 기념훈장. 피의 돌은 오염된 목표에서 비롯된다. 위험의 굴레에서 벗어나면 가장 아름다운 보석이 탄생한다.",
  str_item_intro_6001012 = "동행 기념훈장. 사람은 아무런 가치가 없다. 오직 영혼의 신만이 다툴 뿐이니, 포기하면 폐물이 될 뿐이다.",
  str_item_intro_6001013 = "동행 기념훈장. 백야성 기사가 아닌 오랜 적수의 것이다. 위장이 들킨 이상 남은 것은 사생결단뿐이다.",
  str_item_intro_6001101 = "동행 기념훈장. 페이지를 넘길 때마다 듣기 좋은 소리가 뇌리에 들어오고, 모든 것을 담은 아름다운 글이 눈 앞에 펼쳐진다.",
  str_item_intro_6001102 = "동행 기념훈장. 책을 몸 아래 둔 것은 그것을 존중하지 않는 것이 아니라 책에 기록된 일들이 이미 가슴에 와닿았기 때문이다.",
  str_item_intro_6001103 = "동행 기념훈장. 성서를 침대 삼고 베개 삼아 꿈속에서도 방대한 지식의 바다를 헤엄치며 즐긴다.",
  str_item_intro_6001201 = "동행 기념훈장. 모든 새싹은 모두 직접 기른 것이다. 양손에 진흙이 가득하지만, 새싹들이 그 신비한 식물로 자라나는 걸 확인했을 때 마음속에 차오르는 기쁨은 말할 필요도 없다.",
  str_item_intro_6001202 = "동행 기념훈장. 그 신비한 식물들이 무성하게 자라나서 거대한 자연을 이뤄냈을 때, 헤븐즈 가든의 저녁노을은 무척이나 아름다웠다.",
  str_item_intro_6001203 = "동행 기념훈장. 이 희귀 물고기들은 그가 고수라는 것을 증명한다.",
  str_item_intro_6001204 = "동행 기념훈장. 이는 낚시꾼의 성대한 축제다. 시기가 됐기 때문이 아니라, 그 낚시 고수가 나타났기 때문이다.",
  str_item_intro_6001205 = "동행 기념훈장. 어느새 이토록 많은 건축법을 알게 되었다. 산골짜기의 공터도 더는 황량하지 않을 것이다.",
  str_item_intro_6001206 = "동행 기념훈장. 이토록 많은 건축법을 알고 있으니, 원하기만 한다면 헤븐즈 가든을 번영하는 도시로 건설할 수 있다. 이게 바로 헤븐즈 가든 주인의 실력이다.",
  str_item_intro_6001301 = "동행 기념훈장. 고요의 땅, 과거의 전설... 깊이 잠들어 있던 영웅을 깨우면 과연 그들과 어떤 인연을 맺게 될까?",
  str_item_intro_6001302 = "동행 기념훈장. 지난날의 계약은 거스를 수 없으며, 과거의 적은 여전히 뒤를 노리고 있다. 단지 말뿐인 약속이었다 해도, 그들이 원하는 뜻을 꺾고, 그들의 움직임을 저지할 수는 없다.",
  str_item_intro_6001400 = "동행 기념훈장. 게임은 인생과 같고, 손 안에서 펼쳐지는 모험도 현실과 똑같이 흥미진진합니다. 가혹한 조건에서 스테이지를 클리어할 수 있는 사람은 아마 현실에서도 무언가를 얻을 수 있겠죠.",
  str_item_intro_6001401 = "동행 기념훈장. 그것은 편파적이거나 숨김이 없는 충실한 기록자이며, 지나간 시간을 보여주는 기억의 저장자이다.",
  str_item_intro_6001402 = "동행 기념훈장. 하늘 위를 떠도는 무대에서 온 세상을 축복하는 노래가 울려 퍼진다. 꿈과 미래 사이, 사랑과 치유를 이어주는 음률의 향연.",
  str_item_intro_6001403 = "동행 기념훈장. 끝없이 펼쳐진 바다에 없어서는 안 될 도움이다. 배가 올바른 항로로 이동할 수 있게 도울 뿐만 아니라 삶에서도 바른길을 갈 수 있도록 해 주는 놀라운 효과가 있다고 한다.",
  str_item_intro_6001404 = "동행 기념훈장. 그것은 선물이자 마음이며, 더 나아가 언어이다. 고백할 필요 없이 상대방에게 건네는 것으로 충분하다.",
  str_item_intro_6001405 = "동행 기념훈장. 특별한 날의 꽃은 특별한 시간에 피어납니다. 향기로 가득한 지금 이 순간을 즐기세요.",
  str_item_intro_6001406 = "동행 기념훈장. 그는 탐정의 곁을 떠나지 않습니다. 손만 내밀면 그의 도움을 받을 수 있고, 그 어떤 사소한 단서라도 찾아낼 수 있습니다.",
  str_item_intro_6001407 = "동행 기념훈장. 가족의 날의 기억, 수정 속의 환영. 허망한 세상 속 허망한 사람, 허망한 물건들 사이에서 일어나는 허망한 일이라지만, 모든 것이 직접 경험한 듯 진실하다.",
  str_item_intro_6001408 = "허상의 세계에 갇혀버린 진짜 사람들... 강제로 부수려 하면 오히려 그 안에 묶여 영원히 빠져나올 수 없게 된다...",
  str_item_intro_6001409 = "동행 기념훈장. 데누오 협곡의 은둔자, 가볍게 춤을 추면 비늘 가루가 날리며, 넘쳐나는 빛의 알갱이 사이에서 보는 이를 매혹시킨다...",
  str_item_intro_6001410 = "동행 기념훈장. 승리는 전쟁에 의해서만 이루어지는 것이 아니라, 일상적인 건설, 발전과 번영의 나날들에 더 많이 의존하는 법이다.",
  str_item_intro_6002001 = "동행 기념훈장. 선량한 사람을 수호하는 신들의 사자는 과연 존재하는가? 아니면 그저 인간의 환상일까?",
  str_item_intro_6002002 = "동행 기념훈장. 빛의 바퀴와 무장, 태양이 떠오른다고 해도 어둠의 위협은 영원토록 잊을 수 없다. 평화 속에서도 어둠 속의 적은 영원히 경계해야만 한다.",
  str_item_intro_6002003 = "동행 기념훈장. 북방의 전설, 미지의 고대 생명체. 그 숨결만으로도 불길을 얼려버리고 마을을 얼음 속에 가둘 수 있다고 한다.",
  str_item_intro_6002004 = "동행 기념훈장. 세상에는 자신의 그림자만을 비추는 그림자가 있다. 그리고 그 그림자 또한 생명... 심지어 영혼까지도 가지고 있다.",
  str_item_intro_6002005 = "동행 기념훈장. 아주 일반적인 물건이지만, 지혜를 가진 사람의 손에 들어가면 의식과 영혼을 얻어 사명을 완수할 수 있다.",
  str_item_intro_6002006 = "동행 기념훈장. 강철이 공기보다 백 배는 무거운데 어떻게 하늘에 뜰 수 있을까? 「강철은 물보다 무거운데 어떻게 배를 만들 수 있을까?」라는 질문이 떠오른다. 지식과 논리는 가끔 상식마저 누르는 법이다.",
  str_item_intro_6002007 = "동행 기념훈장. 무거운 강철을 형태가 없는 소리인 양 질주시키는 것은 신만이 할 수 있는 일이다.",
  str_item_intro_6002008 = "동행 기념훈장. 하늘과 땅을 뒤덮은 사막을 왜 이렇게 거닐었는지는 아무도 모른다. 단지 배회하기 위함이었을까.",
  str_item_intro_6002009 = "동행 기념훈장. 그 누구도 상응하는 대가 없이 즐기기만 할 수는 없다. 비록 지금은 대가가 없더라도 미래에는 분명 지불해야 할 것이다. 그것도 더욱 많은 대가를 말이다.",
  str_item_intro_6002010 = "동행 기념훈장. 공포의 울부짖음과 아군의 환호. 전쟁의 위력은 정복, 계략, 용기가 아니라 '승리'라는 제단 위에서 인간이 부득불 만들어 낸 또 하나의 '왕'이다.",
  str_item_intro_6002011 = "동행 기념훈장. 평범한 인간을 강한 전사로 만들려면 조화, 유연 그리고 끈기 없이 껍데기만으론 부족하다.",
  str_item_intro_6002012 = "동행 기념훈장. 이런 병이 있을까? 안과 밖의 구분이 없으며, 공간의 구분도 없다. 어쩌면 그 공간은 무한일지도 모른다. 이런 병은 분명 평범한 물건이 아닐 것이며. 신만이 이해하고 만들어 낼 수 있을 것이다.",
  str_item_intro_6002013 = "동행 기념훈장. 종이 한 장이 한쪽 면만 가지고 있을 수 있다고? 그리고 이것이 그 질문에 「대답」을 해 줬다. 중요한 것은 바로 이음매다. 이 점을 이해하면 「세상의 이음매」에 대한 이치도 이해할 수 있을 것이다...",
  str_item_intro_6002014 = "동행 기념훈장. 아무리 작은 곳이라 해도 만물이 존재할 수 있다. 이 병 안의 세상을 응시하면서 어떤 존재가 눈 아래의 세상을 응시하고 있을지도 모른다고 생각해본 적이 있는가.",
  str_item_intro_6002015 = "동행 기념훈장. 어떤 전설은 만물이 한 나무로부터 탄생한 거라고 말한다. 많은 이들이 이 이야기에 코웃음 쳤다. 하지만 어떤 생물의 유래를 연구해 냈을 때, 그들은 자신이 했던 얘기를 의심해 볼 수밖에 없었다...",
  str_item_intro_6002016 = "동행 기념훈장. 하프의 현 한 줄로도 신나는 소리가 되는데, 만약 두 줄이라면? 연주자들의 기술과 체력도 뛰어날 게 분명하다.",
  str_item_intro_6002017 = "동행 기념훈장. 바퀴가 곧 몸통이기 때문에, '압도'가 주요 공격 방식이 되었다. 회전하는 날카로운 칼날을 직접 마주하지 않기를 기도하자.",
  str_item_intro_6002018 = "동행 기념훈장. 언젠가 요새도 전설 속 거대괴수처럼 대륙을 누빌 수 있다면 어떤 것도 적수가 되지 않을 것이다.",
  str_item_intro_6002019 = "동행 기념훈장. 한 사람이 「공허」에 대해 생각하면 「공허」는 실체를 가지게 된다. 녀석은 형태가 없지만, 그 사람들의 눈 속에 조용히 담기고, 머릿속에 스며들어 또 다른 공허를 만들어낸다.",
  str_item_intro_6002020 = "동행 기념훈장. 지치지 않고 불평하지 않아서 사막을 누비고 다니는 사람들에겐 최고의 말이다.",
  str_item_intro_6002021 = "동행 기념훈장. 세상 사람들은 체스에 열광한다. 높은 자리에 앉아있는 사람은 세상을 보드로 여긴다. 하지만 체스 말들은 자신의 의지를 갖추고 있으며, 보드 또한 그렇다. 그렇기에 그 게임은 결국 산산이 조각나고 만다. 과거의 무수한 게임들이 그랬던 것처럼 말이다.",
  str_item_intro_6002022 = "동행 기념훈장. 「영원의 파멸에 빠져들어라... 눈앞의 세상을 다시 봐 두거라. 그게 네 마지막 기억이 될 테니.」 어둠으로부터 나타난 사악한 이는 대륙의 생명들에게 이렇게 말했다.",
  str_item_intro_6002023 = "동행 기념훈장. 예로부터 별은 인간의 운명을 상징해서 인간은 탑을 세워 별의 위치를 관찰해 미래를 읽었다. 하지만 아이러니하게도 탑은 자신의 결말을 알 수 없다.",
  str_item_intro_6002024 = "동행 기념훈장. 강인한 신체와 재빠른 동작, 영락없는 사나운 짐승이다. 하지만 진짜 무서운 건 녀석의 뛰어난 지성, 그리고 맹독을 가진 꼬리 가시다.",
  str_item_intro_6002025 = "동행 기념훈장. 마치 지옥의 사자가 산 자의 노여움을 담고 인간 세상에 온 것만 같다. 지옥은 그의 끝이 아니다. 죽었다가 부활하는 윤회야말로 그의 전부다.",
  str_item_intro_6001500 = "동행 기념훈장.\n넓은 음률 속 해당화 피어나고, 귀를 기울이면 메아리가 있네. 멀리 동풍이 불어와 흐드러지면, 쌍사의 현 위에 작화가 오르리.",
  str_item_intro_6001507 = "동행 기념훈장.\n북방의 대지에 쌓인 눈 중에는 최근 내린 것도 있고, 태곳적에 내린 것도 있다. 당신의 손에 쥔 눈은 과연 어떤 것일까.",
  str_item_intro_6001508 = "동행 기념훈장.\n함께 겪은 모험의 모든 순간들이 소중하게 간직될 것이다.",
  str_item_intro_6001510 = "독극물에 오염되지 않은 꽃, 너무나 아름답고 맑다.\n마치 그녀의 모습처럼.",
  str_item_intro_6001511 = "동행 기념훈장.\n비상한 지혜는 대륙과 통하는 배를 만드는 데 쓰일 수도 있고, 혼돈을 퍼트리는 무기를 만드는 데 쓰일 수도 있다. 이때 어떻게 선택하느냐가 이 지혜의 방향을 결정한다.",
  str_item_intro_6000620 = "동행 기념훈장.\n일루미나가 만든 이 거대 전투 메카는 단단한 외피와 강력한 화력을 지니고 있다. 이처럼 거대한 녀석의 약점은 종종 표면이 아닌 다른 곳에 있기 마련이다...",
  str_item_intro_6000621 = "동행 기념훈장.\n최후의 방어선을 지키는 포탑은 침입하는 모든 적을 섬멸한다.",
  str_item_intro_6001512 = "동행 기념훈장.\n누구나 얻기를 갈망하는 것이 꼭 누구나 감당할 수 있는 것은 아니다.",
  str_item_intro_6001515 = "동행 기념훈장.\n미지의 위험이 남아 있는 기계다. 가동해 온 시간은 고증할 수조차 없으며, 한밤중에 늘 무서운 잡음을 낸다.",
  str_item_intro_6001516 = "동행 기념훈장.\n오로리안과 수요령 사이에 다른 점은 없다. 모두 춘삭절의 불꽃 아래에서 달콤한 설탕 인형을 즐기고, 상서로운 기념일을 함께 축하하고 있으니 말이다.",
  str_item_intro_6001517 = "동행 기념훈장.\n알골이 개발한 하이테크 밴드다. 실시간으로 심박수, 혈압, 혈중 산소 포화도 등 건강 데이터를 모니터링하고, 착용자의 운동 데이터를 기반으로 피트니스 계획을 세울 수 있다.",
  str_item_intro_6001520 = "동행 기념훈장.\n「수호」는 무거운 뜻을 지닌 단어지만, 그들은 자신을 긍정하며 눈보라 속에 머물렀다.",
  str_item_intro_6001521 = "동행 기념훈장.\n희생은 결코 이른바 명예를 위한 것이 아니다. 「너흰 영웅이지만, 단순히 영웅일 뿐인 건 아냐.」",
  str_item_intro_6001524 = "동행 기념훈장.\n「정말 재밌네. 2회차 가자!」",
  str_item_intro_6001525 = "동행 기념훈장.\n머릿속에 있던 영감은 순간적으로 빛을 발했고, 기록 속 기념할 만한 순간으로 바뀌었다.",
  str_item_intro_6001526 = "동행 기념훈장.\n「이 힘은 나 혼자만의 것이 아니야.」",
  str_item_intro_6001529 = "동행 기념훈장.\n「오랜만이로군, 나의 계약자여. 이 여정은 비록 위험하나, 진리를 향하게 될 것이다.」",
  str_item_intro_6001530 = "동행 기념훈장.\n왕자의 모험은 비록 귀환으로 이어지지는 않았지만, 그는 백성들을 위해 길을 열어주었다. 그들의 마음은 언제라도 늘 이어져 있으며, 미래의 언젠가, 그들은 대륙에서 다시 만날 수 있을지도 모른다.",
  str_item_intro_6001531 = "동행 기념훈장.\n사랑은 세상 속 아름다운 꿈이라고 그녀는 들었다.",
  str_item_intro_6001532 = "동행 기념훈장.\n이것은 험난한 여정이었지만, 그 결말은 당신이 타인의 재회의 행복을 지켜보는 것이었다.\n별들을 도와준 당신에게 가장 깊은 감사를 전하지 않을 이유가 있을까.",
  str_item_6100001 = "동행 기념판",
  str_item_6100002 = "동행 전기 기념판",
  str_item_6100003 = "동행 흑석 기념판",
  str_item_6100004 = "동행 기계 기념판",
  str_item_intro_6100001 = "동행 기념판. 헤븐즈 가든에 두기 좋은 기념판. 동료들이 동행 기념훈장을 놓을 수 있다.",
  str_item_intro_6100002 = "동행 기념판. 이 벽에는 전투적인 분위기가 물씬 풍기지만, 다른 기념 훈장도 무리 없이 놓을 수 있다.",
  str_item_intro_6100003 = "동행 기념판. 검은 산바위가 황야의 분위기를 풍긴다. 도대체 누가 여기에 옮긴 걸까? 벽 위의 작은 굴곡 때문에 기념 훈장을 안정적으로 놓을 수 있긴 하다.",
  str_item_intro_6100004 = "동행 기념판. 이 배경은... 거대한 기계 속에, 또는 공장 사이에 놓여 있는 듯해 저절로 기념 훈장들을 가지런히 놓게 만든다. 하지만 아무렇게나 놓아도 괜찮다. 그만의 감성이 있달까?",
  str_item_6400001 = "칭호-대국을 여는 자",
  str_item_6400002 = "칭호-전술의 대가",
