  str_item_9995012 = "홀로그램 렌즈",
  str_item_9995013 = "운명의 주사위함",
  str_item_9995014 = "쌍성란",
  str_item_9995015 = "여명의 접시",
  str_item_9995016 = "저주의 손",
  str_item_9995017 = "죽음의 편지",
  str_item_9995018 = "글레어 고글",
  str_item_4090334 = "기억의 벚꽃",
  str_item_intro_1400851 = "움브라톤의 증언자. 언제든지 중립을 유지한다. 가지고 다니는 상자에는 방대한 기록이 저장되어 있어, 가히 움브라톤의 이동 문서고라 할 수 있다.",
  str_item_intro_3000220 = "행동력: 이벤트 내 특정 스테이지 도전에 필요한 수치로, 시간에 따라 회복된다.",
  str_item_intro_3000221 = "희귀한 겨우살이 열매로, 북방 사람들은 이것이 희망과 풍요를 상징한다고 믿는다. 눈소나무 시장에서 선물로 교환할 수 있다.",
  str_item_intro_3000001 = "특수 공정으로 제조된 광원 저장매체. 각종 탐험에 필수적인 물자다.",
  str_item_intro_3000002 = "백야성이 발행한 화폐. 품질이 뛰어나고 수량이 풍부하다. 대륙에서 모두에게 인정받은 화폐.",
  str_item_intro_3000003 = "라피스를 연마해 얻은 보석이다.\n오로리안 소집, 특별 소집 스타 마커 및 스타 마커 교환, 프리즘 구매에 사용할 수 있다.",
  str_item_intro_3000004 = "각종 작전을 지휘해 획득한 경험치. 레벨이 높을수록 콜로서스와의 감응도 더욱 긴밀해져, 콜로서스에 대한 더 많은 정보를 알 수 있다.",
  str_item_intro_3000005 = "파이어플라이는 자동으로 회복되며, 회복 속도는 루미나 저장실의 영향을 받는다. 또한 제련실에서 콜로서스 기재를 제련해 증가시킬 수 있다.\n파이어플라이는 콜로서스 제어자의 명령을 듣는 소형 구조체로, 콜로서스의 수리, 일상 정비 등의 업무를 수행한다.",
  str_item_intro_3000006 = "「루미나미터」에 표시되는 수치로 0까지 떨어지면 반드시 떠나야 한다. 그렇지 않으면 위험할 수 있다.",
  str_item_intro_3000007 = "비경에서 발견된 고문서 조각. 일부 기관은 그 가치를 인정하여 이를 사들이고 있다.",
  str_item_intro_3000008 = "각종 일일 퀘스트를 완료 시 지급하는 보상 점수. 지정된 수치까지 모으면 추가 보상을 획득할 수 있다.",
  str_item_intro_3000009 = "업적의 증명",
  str_item_intro_3000010 = "오로리안과 더욱 친밀해집니다.",
  str_item_intro_3000011 = "성물 주사위",
  str_item_intro_3000012 = "자원 휴대실에서 발견된 특수한 구조물. 탐색자를 도와 각종 물자를 수집할 수 있다.\n[연속 소탕 시 사용하며, 이번 도전에 필요한 프리즘을 소모하고 즉시 수익을 획득함] ",
  str_item_intro_3000013 = "콜로서스 제련실에서 만든 특수 생산품. 제작 원리는 고대 기술에서 유래했다고 하며, 이를 이용해 특정 물건의 기본 성질을 변환해 새로운 물건으로 바꿀 수 있다.",
  str_item_intro_3000014 = "루미나를 담고 있는 천연의 크리스탈이다.\n라피스를 사용해 상점에서 패키지 또는 오로리안 코스튬을 구매할 수 있고, 라피스를 루맘버로 전환해 오로리안 소집 및 프리즘 회복을 진행할 수도 있다.",
  str_item_intro_3000015 = "하트스톤과 함께 발견된 투명한 보석. 강렬한 광채를 내며, 스타젬 상점에서 귀중한 상품으로 교환할 수 있다.",
  str_item_intro_3000016 = "더욱 희귀한 스타젬, 가치가 상당하다. 스타젬 가운데에서도 더욱 진귀한 물건이라 할 수 있다. 트윙클 상점에서 매우 인기가 많다.",
  str_item_intro_3000017 = "콜로서스의 활동에 필수적인 물질. 루미나 저장실에서 공급되어, 콜로서스에게 필요한 에너지를 공급합니다.",
  str_item_intro_3000018 = "헤븐즈 가든 곳곳에서 발견되는 돌 조각이다. 유물로 보이지만 구체적인 용도는 알 수 없다. 츄브들이 좋아하며, 이것을 가지고 다른 물건과 교환할 수 있다.",
  str_item_intro_3000019 = "매우 희귀한 스타젬으로, 대부분의 사람은 그 가격을 감당할 수 없을 정도로 귀하다. 전문적으로 이를 다루는 샤인젬 상점에서만 거래할 수 있다.",
  str_item_intro_3000021 = "「스카이워커호」의 함교와 시뮬레이터의 합동 제작을 통해 만들어진 저장 매체다. 조종사의 기억을 입력해 콜로서스의 클라우드 스토리지에 홀로그램 영상을 생성할 수 있다.",
  str_item_intro_3000022 = "일종의 진귀한 목재로, 어떤 기이한 식물에서 얻어낸 것이나, 지금은 거의 볼 수 없다고 한다. 그 희소성과 천연적으로 윤택한 외형 덕분에 유명 인사들 사이에서 인기가 많으며, 움브라톤에는 이를 취급하는 전문 상회도 있어 등가물로 좁은 범위에서 쓰이고 있다.",
  str_item_intro_3000025 = "「추방되지 않은 존재」의 언어가 기록되어 있다고 하나, 아직까지 해독되지 않아 그저 추측에 불과하다. 상태가 비교적 온전하며, 진리를 추구하는 어떤 조직의 눈에는 일정한 가치가 있기에 이를 사들이고 있다고 한다.",
  str_item_intro_3000026 = "「추방되지 않은 존재」의 언어가 기록되어 있다고 하나, 아직까지 해독되지 않아 그저 추측에 불과하다. 심하게 부서진 탓에 일정 수량을 모아야만 구매자의 흥미를 끌 수 있을 것 같다.",
  str_item_intro_3000029 = "특별 사건부를 읽은 엘리트 조종사에게 제공되는 황금 책갈피.\n[사건부 상점]에서 아이템 보상으로 교환할 수 있다.",
  str_item_intro_3000030 = "특별 사건부를 읽은 조종사에게 제공되는 책갈피.\n[사건부 상점]에서 아이템 보상으로 교환할 수 있다.",
  str_item_intro_3000031 = "특별 사건부를 읽은 조종사에게 제공되는 아이템.\n[사건부 상점]에서 일반 코스튬으로 교환할 수 있다.",
  str_item_intro_3000032 = "특별 사건부를 읽은 조종사에게 제공되는 아이템.\n[사건부 상점]에서 콜로서스 가구로 교환할 수 있다.",
  str_item_intro_3501001 = "장비의 정련 레벨을 높일 수 있는 아이템.\n이 신비한 물질은 어떤 물건과 주인이 서로 더 강하게 연결되도록 만들지만, 순식간에 증발해 버리는 성질 탓에 특수한 용기에 보관해야만 한다.",
  str_item_intro_3000100 = "소집 신호를 발사할 수 있는 장치.\n일반 소집에서 오로리안을 획득할 수 있다.",
  str_item_intro_3000101 = "특수한 소집 신호를 발사할 수 있는 장치.\n한정 소집에서 오로리안을 획득할 수 있다.",
  str_item_intro_3000110 = "핼러윈 특전 소집 전용 아이템. 핼러윈 특전 소집에서 10회 소집을 진행할 수 있다.\n본 아이템은 기간 한정 아이템이며, [핼러윈 특전 소집] 종료 시 아이템은 3000루맘버로 전환된다.",
  str_item_intro_3000112 = "크리스마스 특전 소집 전용 아이템. 크리스마스 특전 소집에서 10회 소집을 진행할 수 있다.\n본 아이템은 기간 한정 아이템이며, [크리스마스 특전 소집] 종료 시 아이템은 3000루맘버로 전환된다.",
  str_item_intro_3000113 = "콜라보 한정 소집 전용 아이템. 콜라보 한정 소집에서 10회 소집을 진행할 수 있다.\n본 아이템은 기간 한정 아이템이며, (UTC +9) 2022년 1월 26일 18:00 이전까지 사용해야 합니다. 기간 만료 시 아이템은 사라지며, 다른 어떤 아이템으로도 전환되지 않습니다.",
  str_item_intro_3000114 = "콜라보 한정 소집 전용 아이템. 콜라보 한정 소집에서 10회 소집을 진행할 수 있다.\n본 아이템은 기간 한정 아이템이며, (UTC +9) 2022년 2월 12일 18:00 이전까지 사용해야 합니다. 기간 만료 시 아이템은 사라지며, 다른 어떤 아이템으로도 전환되지 않습니다.",
  str_item_intro_3000343 = "콜라보 한정 소집 전용 아이템. 콜라보 한정 소집에서 10회 소집을 진행할 수 있다.\n본 아이템은 기간 한정 아이템이며, 2023년 11월 7일 18:00 이전까지 사용해야 합니다. 기간 만료 시 아이템은 사라지며, 다른 어떤 아이템으로도 전환되지 않습니다.",
  str_item_intro_3000115 = "축제 특전 소집 전용 아이템. 축제 특전 소집에서 10회 소집을 진행할 수 있다.\n본 아이템은 기간 한정 아이템이며, [축제 특전 소집] 종료 시 아이템은 3000 루맘버로 전환된다.",
  str_item_intro_3000116 = "[여명의 빛] 한정 소집에서 1회 소집을 진행할 수 있습니다.\n본 아이템은 기간 한정 아이템으로, [여명의 빛] 한정 소집 종료 전에 사용해야 합니다. 기간 만료 시 아이템은 사라지며, 다른 아이템으로 전환되지 않습니다.",
  str_item_intro_3000117 = "[여명의 빛] 한정 소집에서 10회 소집을 진행할 수 있습니다.\n본 아이템은 기간 한정 아이템으로, [여명의 빛] 한정 소집 종료 전에 사용해야 합니다. 기간 만료 시 아이템은 사라지며, 다른 아이템으로 전환되지 않습니다.",
  str_item_intro_3000141 = "[여명의 빛] 한정 소집 또는 [고독한 자경단원] 추천 소집에서 10회 소집을 진행할 수 있습니다.\n본 아이템은 기간 한정 아이템으로, [여명의 빛] 한정 소집 종료 전에 사용해야 합니다. 기간 만료 시 아이템은 사라지며, 다른 아이템으로 전환되지 않습니다.",
  str_item_3000142 = "틈새 특별 소집 스타 마커",
  str_item_3000143 = "틈새 10연속 소집령",
  str_item_intro_3000142 = "[초월의 현현] 특별 한정 소집 또는 [안개의 고성] 한정 소집에서 1회 소집을 진행할 수 있습니다.\n본 아이템은 기간 한정 아이템으로, [초월의 현현] 한정 소집 종료 전에 사용해야 합니다. 기간 만료 시 아이템은 사라지며, 다른 아이템으로 전환되지 않습니다.",
  str_item_intro_3000143 = "[초월의 현현] 특별 한정 소집 또는 [안개의 고성] 한정 소집에서 10회 소집을 진행할 수 있습니다.\n본 아이템은 기간 한정 아이템으로, [초월의 현현] 한정 소집 종료 전에 사용해야 합니다. 기간 만료 시 아이템은 사라지며, 다른 아이템으로 전환되지 않습니다.",
  str_item_3000145 = "연금술 10연속 소집령",
  str_item_intro_3000145 = "[연금술의 여행자] 콜라보 한정 소집 또는 [상인의 선율] 콜라보 한정 소집에서 10회 소집을 진행할 수 있습니다.\n본 아이템은 기간 한정 아이템으로, [이상의 소집 종료 전에 사용해야 합니다. 기간 만료 시 아이템은 사라지며, 다른 아이템으로 전환되지 않습니다.",
  str_item_intro_3000118 = "콜라보 한정 소집 전용 아이템. 콜라보 한정 소집에서 10회 소집을 진행할 수 있다.\n본 아이템은 기간 한정 아이템이며, (UTC+9) 2022년 8월 3일 18:00 이전까지 사용해야 합니다. 기간 만료 시 아이템은 사라지며, 다른 어떤 아이템으로도 전환되지 않습니다.",
  str_item_intro_3000119 = "[북방의 여왕] 한정 소집에서 1회 소집을 진행할 수 있습니다.\n본 아이템은 기간 한정 아이템으로, [북방의 여왕] 한정 소집 종료 전에 사용해야 합니다. 기간 만료 시 아이템은 사라지며, 다른 아이템으로 전환되지 않습니다.",
  str_item_intro_3000120 = "[북방의 여왕] 한정 소집에서 10회 소집을 진행할 수 있습니다.\n본 아이템은 기간 한정 아이템으로, [북방의 여왕] 한정 소집 종료 전에 사용해야 합니다. 기간 만료 시 아이템은 사라지며, 다른 아이템으로 전환되지 않습니다.",
  str_item_intro_3000121 = "훈풍 특전 소집 전용 아이템, 훈풍 특전 소집에서 10회 소집을 진행할 수 있다.\n본 아이템은 기간 한정 아이템으로, [훈풍 특전 소집] 종료 시 아이템은 3000 루맘버로 전환된다.",
  str_item_3000146 = "눈보라를 넘는 매 10연속 특전 소집령",
  str_item_intro_3000146 = "눈보라를 넘는 매 특전 소집 전용 아이템, 눈보라를 넘는 매 특전 소집에서 10회 소집을 진행할 수 있다.\n본 아이템은 기간 한정 아이템으로, [눈보라를 넘는 매 특전 소집] 종료 시 아이템은 3000 루맘버로 전환된다.",
  str_item_intro_3000122 = "첫눈 특전 소집 전용 아이템, 첫눈 특전 소집에서 10회 소집을 진행할 수 있다.\n본 아이템은 기간 한정 아이템으로, [첫눈 특전 소집] 종료 시 아이템은 3000 루맘버로 전환된다.",
  str_item_intro_3000123 = "이번 [북방의 여왕] 한정 소집에서 1회 소집을 진행할 수 있습니다.\n본 아이템은 기간 한정 아이템으로, 이번 [북방의 여왕] 한정 소집 종료 전에 사용해야 합니다. 기간 만료 시 아이템은 사라지며, 다른 아이템으로 전환되지 않습니다.",
  str_item_intro_3000124 = "이건 평범한 기념책이 아니라 골디의 사인이 담긴 책입니다! 가지고 있으면 이 아이돌과 특별한 인연이 생길지도 모릅니다!\n이번 [행운의 별] 한정 소집에서 1회 소집을 진행할 수 있습니다.\n본 아이템은 기간 한정 아이템으로, [행운의 별] 한정 소집 종료 전에 사용해야 합니다. 기간 만료 시 아이템은 사라지며, 다른 아이템으로 전환되지 않습니다.",
  str_item_intro_3000125 = "춘삭 특전 소집 전용 아이템, 춘삭 특전 소집에서 10회 소집을 진행할 수 있다.\n본 아이템은 기간 한정 아이템으로, [춘삭 특전 소집] 종료 시 아이템은 3000 루맘버로 전환된다.",
  str_item_intro_3000126 = "순찰 특전 소집 전용 아이템, 순찰 특전 소집에서 10회 소집을 진행할 수 있다.\n본 아이템은 기간 한정 아이템으로, [순찰 특전 소집] 종료 시 아이템은 3000 루맘버로 전환된다.",
  str_item_intro_3000127 = "[지난날의 잔영] 한정 소집에서 1회 소집을 진행할 수 있습니다.\n본 아이템은 기간 한정 아이템으로, [지난날의 잔영] 한정 소집 종료 전에 사용해야 합니다. 기간 만료 시 아이템은 사라지며, 다른 아이템으로 전환되지 않습니다.",
  str_item_intro_3000128 = "[지난날의 잔영] 한정 소집에서 10회 소집을 진행할 수 있습니다.\n본 아이템은 기간 한정 아이템으로, [지난날의 잔영] 한정 소집 종료 전에 사용해야 합니다. 기간 만료 시 아이템은 사라지며, 다른 아이템으로 전환되지 않습니다.",
  str_item_intro_3000129 = "바캉스 특전 소집 전용 아이템, 바캉스 특전 소집에서 10회 소집을 진행할 수 있다.\n본 아이템은 기간 한정 아이템으로, [바캉스 특전 소집] 종료 시 아이템은 3000 루맘버로 전환된다.",
  str_item_intro_3000133 = "겨울의 송가 특전 소집 전용 아이템, 겨울의 송가 특전 소집에서 10회 소집을 진행할 수 있다.\n본 아이템은 기간 한정 아이템으로, [겨울의 송가 특전 소집] 종료 시 아이템은 3000 루맘버로 전환된다.",
  str_item_intro_3000138 = "축제 특전 소집 전용 아이템, 축제 특전 소집에서 10회 소집을 진행할 수 있다.\n본 아이템은 기간 한정 아이템으로, [축제 특전 소집] 종료 시 아이템은 3000 루맘버로 전환된다.",
  str_item_intro_3000201 = "레디젤 렌치의 어떤 멤버가 직접 너트를 개조해 만든 휘장으로 「사막이 널 인정한다」라는 의미이다. 그렇기 때문에 이 휘장은 레디젤 렌치에게 인정받은 사람에게만 지급된다.",
  str_item_intro_3000211 = "플라티나 선라이즈 호텔 프런트에서 특별한 선물로 교환할 수 있는 쿠폰이다. 위에 찍힌 도장은 호텔 총지배인의 초상화라고 한다.",
  str_item_intro_3000212 = "특별 사건부의 임무를 완료하면 일정량의 움브라톤 공헌도를 획득할 수 있으며, 해당하는 보상을 개방하는 데 사용할 수 있다. 움브라톤에서는 꿈과 욕망을 품은 모험가들의 기대를 결코 저버리지 않을 것이다.",
  str_item_intro_3000213 = "행동력: 이벤트 내 일부 스테이지 도전에 필요한 수치로, 시간에 따라 회복된다.",
  str_item_intro_3000214 = "쿠리어 길드 전용 식품, 작업 시 소모된 체력을 보충할 수 있다. 사실은 아무 때나 먹어도 상관없다.",
  str_item_intro_3000215 = "재건 진행도(상세정보 없음)",
  str_item_intro_3000217 = "전공: 군인이 이룬 공적을 뜻하며, 일루미나 연방을 위한 그의 공헌을 상징한다.",
  str_item_intro_3000219 = "땀을 흘리고, 고통을 견디라. 주먹과 발로 지하격투장에서 명성을 얻고, 온 움브라톤에 당신의 이름을 알려라.",
  str_item_intro_3000202 = "이벤트 아이템. 복달걀 추첨방에서 추첨에 사용할 수 있으며, 일정 수량만큼 누적 획득하면 히이로의 전용 스토리를 개방할 수 있다.\n운산의 특산품 중 하나로, 벚꽃에서 떨어진 꽃잎이다. 운산 주민들은 이 꽃잎이 행운을 가져다준다고 생각한다.",
  str_item_intro_3000224 = "「영원한 백야」 이벤트 아이템. 일정 수량 누적 시 영광의 계단에서 보상을 수령할 수 있다.",
  str_item_intro_3000225 = "「메이드래곤의 휴일」 이벤트 아이템, [토르의 주방]에서 추첨에 사용할 수 있다.\n따끈따끈한 식사가 곧 준비될 거예요. 어서 접시를 가져와 테이블에 놓으세요!",
  str_item_intro_3000226 = "아스트라에서는 흔히 볼 수 없는 음료로, 마시면 정신이 번쩍 든다.",
  str_item_intro_3000227 = "마개조된 현대 화폐로, 낡아빠진 모습이다.",
  str_item_intro_3000229 = "탐험가와 모험가에게 있어 영광의 상징이며, 종종 고된 노력이나 스릴 넘치는 위험을 극복해야만 얻을 수 있다.",
  str_item_intro_3000236 = "도전 완료 후 획득할 수 있는 포인트로, 도전 난이도에 따라 획득할 수 있는 포인트 수량이 다르다.",
  str_item_intro_3000238 = "축제의 계절이 되면 운도 사람들은 이런 종이에 축복의 말을 적으며, 한 해가 행복하길 기원한다.",
  str_item_intro_3000239 = "극동 지역 사람들이 좋아하는 음식이다. 보기에도 귀엽고 휴대도 간편하며, 같이 먹을 수 있는 반찬도 있다.",
  str_item_intro_3000240 = "「흩날리는 꿈」 소원의 거울 전용 아이템. 「흩날리는 꿈」 소원의 거울에서 소원을 빌 수 있다.\n본 아이템은 기간 한정 아이템이며, [「흩날리는 꿈」 소원의 거울] 종료 시 아이템은 100 루맘버로 전환된다.",
  str_item_intro_3000241 = "품질이 좋고 유통량이 많은 은전으로, 운도에서 주로 통용되는 화폐다.",
  str_item_intro_3000242 = "선수들의 성적을 기록한 카드로, 각 기록 지점의 담당자 서명을 확인할 수 있다.",
  str_item_intro_3000244 = "그 오묘한 힘은 이곳에 빠진 사람들을 자유롭게 행동하게 만들고, 심지어는 이곳의 속박을 떨쳐내게 할 수도 있다...",
  str_item_intro_3000245 = "어느 영혼들의 파편이 아공간에 남아 이루어진 「산물」이라 하며, 어떤 사람들은 이 물건에 매우 관심이 많다고 한다.",
  str_item_intro_3000246 = "수집한 데이터를 양자화하고 종합적으로 측정하여 획득한 정보다. 이것을 가지고 정해진 범위에 따라 탐색을 진행할 수 있다.",
  str_item_intro_3000247 = "휴대용 탐지기로 탐색한 일반 신호",
  str_item_intro_3000248 = "휴대용 탐지기로 탐색한 특수 신호",
  str_item_intro_3000253 = "한때 방대한 세력을 자랑하던 안데르센 상회가 발급한 어음이다. 이를 인정하는 사람을 찾는다면, 이것을 가지고 원하는 물건과 교환할 수 있을 것이다.",
  str_item_intro_3000256 = "도적단의 거점 공격에 필요한 포인트다. 잠입 중 마주치는 적을 물리치면서 나아가자.",
  str_item_intro_3000258 = "각종 소식, 재미있는 소문, 해프닝 등이 쓰여 있습니다. 사건의 전모를 알기 위해서는 이것들을 단서로 삼아 직접 찾아야 합니다.",
  str_item_intro_3000259 = "축제 기간 동안 하버 시티에서 시민들에게 배포하는 특별한 주화로, 축제 상점가에서 상품권 대용으로 쓸 수 있다.",
  str_item_intro_3000266 = "신규 개장한 아쿠아리움입니다~ 최고의 설비 및 수중생물을 선보이며, 아직 관람객도 매우 적답니다! 절호의 기회를 놓치지 마세요~\n아쿠아리움 투어 전용 아이템, 아쿠아리움 투어에서 소원을 빌 수 있다. 본 아이템은 기간 한정 아이템이며, 아쿠아리움 투어 종료 시 아이템은 100 루맘버로 전환된다.",
  str_item_intro_3000267 = "휴대용 탐지기로 탐색한 일반 신호",
  str_item_intro_3000268 = "휴대용 탐지기로 탐색한 특수 신호",
  str_item_intro_3000270 = "마술사의 말에 따르면 이 카드는 겉보기엔 단순해 보이지만, 신비로운 힘을 지녀 여러 모습으로 변신할 수 있게 해준다고 한다!\n이벤트 기간에 프리즘을 소모하여 클리어 시 획득.",
  str_item_intro_3000271 = "그런대로 회수할 수 있는 탄피. 물자 보급소에서 일부 물자로 교환할 수 있다.\n이벤트 기간에 프리즘을 소모해 스테이지 클리어 시 획득할 수 있다.",
  str_item_intro_3000275 = "이 영화표만 있으면 그 「유명 배우」의 영화를 볼 수 있으며, 직접 인터뷰까지 할 수 있다고 한다!\n[인 더 스포트라이트] 전용 아이템으로, [인 더 스포트라이트]에서 소원을 빌 수 있다. [인 더 스포트라이트] 종료 시 아이템은 100 루맘버로 전환된다.",
  str_item_intro_3000276 = "니나가 유령의 집에 으스스한 분위기를 조성하기 위해 만든 주화다. 관광지 기념품으로 교환할 수 있다.",
  str_item_intro_3000278 = "도처에 흩어져 있는 부품이다. 어쩌면 유용하게 쓰일지도 모른다!\n이벤트 기간에 프리즘을 소모해 스테이지 클리어 시 획득할 수 있다.",
  str_item_intro_3000280 = "복각 「흩날리는 꿈」 소원의 거울 전용 아이템. 복각 「흩날리는 꿈」 소원의 거울에서 소원을 빌 수 있다.\n본 아이템은 기간 한정 아이템이며, [복각 「흩날리는 꿈」 소원의 거울] 종료 시 아이템은 100 루맘버로 전환된다.",
  str_item_intro_3000281 = "어느 천재 감독의 작품이라고 한다. 소문에 의하면 자신이 찍은 공포 영화를 보고 웃다가 숨넘어가서 죽었다고 한다.",
  str_item_intro_3000282 = "환상적인 모험 시나리오 대본으로 보인다. 이 대본은 낭만적이고 상상력이 풍부하기도 하지만, 가끔은 진부하고 무미건조할 때도 있다.",
  str_item_intro_3000283 = "대본은 실화를 바탕으로 각색한 것 같다. 단, 원래 이야기 주인공의 마지막은 아무도 모르기 때문에, 결말을 예술적으로 가공했다.",
  str_item_intro_3000284 = "조무는 이 대본을 은근슬쩍 당신의 손에 쥐여주었고, 일이 잘되면 고액의 보상이 있을 것이라고 한다.",
  str_item_intro_3000285 = "리리카가 맡긴 대본이다. 그녀는 당신에게 연출에 재능이 있다고 판단하고 광고 촬영을 맡긴 것 같다.",
  str_item_intro_3000286 = "비비안이 맡긴 대본이다. 그녀는 이것이 일루미나 징병 홍보에 새로운 시도가 될 것이라고 한다.",
  str_item_intro_3000288 = "베들레헴이 당신과 함께 창작할 때 쓴 노트다. 두 사람이 함께 느꼈던 생각이 담겨 있다.\n「달콤한 선율에 안겨」 이벤트 전용 아이템. 「달콤한 선율에 안겨」 이벤트에서 소원을 빌 수 있다. 본 아이템은 기간 한정 아이템이며, 「달콤한 선율에 안겨」 이벤트 종료 시 아이템은 100 루맘버로 전환된다.",
  str_item_intro_3000291 = "여행 중에 찾은 기록이다. 돌아가는 시간 동안 많은 중요한 정보를 떠올릴 수 있다.",
  str_item_intro_3000292 = "대륙에서 가장 인기 있는 아이돌의 굿즈를 놓칠 수야 없지! 굿즈를 수집하는 데 열을 올리는 열혈 팬을 노리고 한몫 챙기려는 사람들이 생겨났다...",
  str_item_intro_3000293 = "북방의 풍속 중 하나로, 겨울 축제의 밤에 아이들이 침대 머리맡에 걸어두고, 안에 원하는 선물을 적으면 다음 날 아침 양말 안에 선물이 나타난다고 한다! 누가 넣어 둔 것인지는 알 수 없다.",
  str_item_intro_3000294 = "아무것도 적혀 있지 않은 이 카드는 모종의 「마력」이 있어서, 이 위에 소원을 쓰면 이루어진다고 한다. 신빙성은 높지 않지만, 축복이 가득한 이런 선물을 과연 누가 거절할까.",
  str_item_intro_3000297 = "익명의 인물로부터 입수한 시나리오다. 스릴과 자극, 낭만을 담고 있는 이야기처럼 보인다.\n하지만 시나리오 속 이야기가 어딘가 익숙하다...",
  str_item_intro_3000298 = "거리에 떠도는 이야기를 각색해 만든 시나리오다. 위험이 가득한 강호의 모습이 담겨 있다.",
  str_item_intro_3000299 = "최근 운도에서 가장 인기 있는 소설 중 하나로, 정체불명의 사람이 바다를 건너와서 당신에게 준 것이다.\n언뜻 보기에는 칼싸움과 종말을 주제로 하는 이야기인 것 같다...",
  str_item_intro_3000300 = "린 가문 상회의 어음이다. 적혀 있는 금액에 따라 부둣가 상점에서 물건으로 교환할 수 있다!",
  str_item_intro_3000307 = "매우 이상하게 생긴 석고 조각이다. 어떤 조각상에서 떨어져 나온 것 같다. 자세히 살펴보면 단서를 찾을 수 있을지도 모른다.",
  str_item_intro_3000311 = "누군가와 마주 앉아 술을 마실 때 이런 와인잔을 사용하면, 계속 맑은 정신을 유지할 수 있다고 한다.\n「매혹의 밤」 전용 아이템. 「매혹의 밤」에서 소원을 빌 수 있다. 본 아이템은 기간 한정 아이템이며, 「매혹의 밤」 종료 시 아이템은 100루맘버로 전환된다.",
  str_item_intro_3000313 = "일루미나 연방 보급센터의 통용 화폐로, 이는 그 안의 보급품을 운송하고 분배할 수 있는 유일한 증명서다.",
  str_item_intro_3000321 = "왠지 어떤 기묘한 수정의 조각인 것 같다. 안에는 더 기묘한 물방울이 담겨 있다...\n용도: [점술의 방]에서 마음에 드는 상품을 구매할 수 있습니다.\n획득 경로: 프리즘을 소모하는 메인 스테이지 또는 자원 정비 스테이지를 완료하면 획득할 수 있습니다.",
  str_item_intro_3000326 = "꽤 정교한 주화다. 하지만 뭔가 위험한 분위기가 느껴진다... 미즈 로트는 이것으로 물건과 교환할 수 있다고 했으니, 아마 문제는 없을 것이다...\n획득 경로: 미즈 로트가 의뢰한 임무 완료",
  str_item_intro_3000330 = "가시덩굴에 휘감긴 꽃이다. 꽃을 피울지 말지는 세간의 생각이 아닌, 온전히 자신에게 달려 있다. 「흐드러진 피라칸타」 이벤트 전용 아이템. 「흐드러진 피라칸타」 이벤트에서 소원을 빌 수 있다. 본 아이템은 기간 한정 아이템이며, 「흐드러진 피라칸타」 이벤트 종료 시 아이템은 100루맘버로 전환된다.",
  str_item_intro_3000332 = "업무는 산더미처럼 쌓여 있고, 암귀의 방해에도 대비해야 하며, 전방의 동향까지 정찰해야 한다... 따라서 레이스는 부족한 인력을 적재적소에 배치하여 더스크 타운의 일부 재건 작업을 완료해야 한다.",
  str_item_intro_3000334 = "레이스에 대한 바튼의 전략 인정도",
  str_item_intro_3000335 = "레이스에 대한 히이로의 전략 인정도",
  str_item_intro_3000336 = "레이스에 대한 비비안의 전략 인정도",
  str_item_intro_3000337 = "레이스에 대한 시로나의 전략 인정도",
  str_item_intro_3000353 = "마음 속에 생각한 것을 소망해 보세요.",
  str_item_intro_3000354 = "소원의 고치가 일정 수량 누적되면 교환센터에서 선물로 교환할 수 있다.",
  str_item_intro_3000356 = "제나라 사람들이 자주 사용하는 향, 정교한 외관에 고상한 향을 가지고 있다.\n「나무로 연기를 피워 하늘과 땅에 제사를 올리는 문화는 이 몸도 잘 알고 있느니라. 허나 매워서 눈을 못 뜰 정도로 향이 가득한 건 여전히 힘들구나...」",
  str_item_intro_3000361 = "고장으로 인해 뒤죽박죽이 된 영상 데이터는 수집하고 정리하는 것만 해도 상당한 노력이 필요하다.\n일정량 소모 시 새로운 영상 복구 스테이지를 개방할 수 있다.",
  str_item_intro_3000366 = "특정 오로리안과 계약을 맺기 위한 필수품이다.",
  str_item_intro_3000367 = "움브라톤에서 온 막대사탕이다. 맛이 랜덤으로 변하며, 놀라움으로 가득하다. 물자가 부족한 사막에서는 화폐만큼 귀한 물건이다.",
  str_item_intro_3000368 = "부지런한 조종사를 위한 보급상자다.\n모든 노력과 성장이 기록되어 실질적인 보상으로 바뀌게 될 것이다.",
  str_item_intro_3000374 = "추억이 떠오르는 모양이지만 손에 쥐기엔 힘든 게임코인이다. 최강의 게이머는 코인 하나로도 밤새도록 게임을 할 수 있다고 한다.",
  str_item_intro_3000376 = "자난성에서 일상생활 물자 교환에 사용하는 배급권이다. 일루미나에 특별한 공헌을 한 자는 이것으로 개인 맞춤형 물품도 신청할 수 있다.",
  str_item_intro_3000377 = "성자의 피는 헛되이 흘리는 법이 없으며, 마치 호박처럼 영원히 존재합니다. 주님을 향해 경건하게 바치듯이 진리를 향해 그것을 바치십시오.",
  str_item_intro_3000381 = "큰 꿈에서 처음으로 깨어났을 때, 그 이슬은 나뭇잎에 맺혀 찰나의 순간에 사라져 버렸다. 마치 아름다운 꿈을 더는 찾을 수 없는 것처럼. 꿈속의 신룡에게 바치면 보상을 받을 수 있을지도 모른다.",
  str_item_intro_3000383 = "헤븐즈 밸리에서 만든 색지다. 부드럽고 질겨서 창가에 장식하기 적합하며, 오색 인형을 만들 때도 사용할 수 있다. 윈델리온의 색지는 과거의 그리움만 아니라 앞으로 나아갈 신념도 전할 수 있다.",
  str_item_intro_3100001 = "오로리안의 레벨을 증가시키며, 숲 계열 오로리안에게는 효과가 50% 증가한다.\n초록색 옥. 이 옥을 통해 명상하면 전투 시의 일부 기억을 회복할 수 있으며, 소량의 경험치를 획득한다.",
  str_item_intro_3100002 = "오로리안의 레벨을 증가시키며, 숲 계열 오로리안에게는 효과가 50% 증가한다.\n비교적 진귀한 초록색 옥을 통해 꽤 많은 전투 감각을 회상할 수 있으며, 꽤 많은 경험치를 획득한다.",
  str_item_intro_3100003 = "오로리안의 레벨을 증가시키며, 숲 계열 오로리안에게는 효과가 50% 증가한다.\n매우 진귀한 초록색 옥. 과거의 전투를 생생하게 느낄 수 있으며, 대량의 경험치를 획득한다.",
  str_item_intro_3100004 = "오로리안의 레벨을 증가시키며, 물 계열 오로리안에게는 효과가 50% 증가한다.\n파란색 옥을 통해 명상하면 일부 전투 기억을 회복할 수 있으며, 소량의 경험치를 획득한다.",
  str_item_intro_3100005 = "오로리안의 레벨을 증가시키며, 물 계열 오로리안에게는 효과가 50% 증가한다.\n비교적 진귀한 파란색 옥을 통해 꽤 많은 전투 감각을 회상할 수 있으며, 꽤 많은 경험치를 획득한다.",
  str_item_intro_3100006 = "오로리안의 레벨을 증가시키며, 물 계열 오로리안에게는 효과가 50% 증가한다.\n매우 진귀한 파란색 옥. 과거의 전투를 생생하게 느낄 수 있으며, 대량의 경험치를 획득한다.",
  str_item_intro_3100007 = "오로리안의 레벨을 증가시키며, 번개 계열 오로리안에게는 효과가 50% 증가한다.\n노란색 옥을 통해 명상하면 일부 전투 기억을 회복할 수 있으며, 소량의 경험치를 획득한다.",
  str_item_intro_3100008 = "오로리안의 레벨을 증가시키며, 번개 계열 오로리안에게는 효과가 50% 증가한다.\n비교적 진귀한 노란색 옥을 통해 꽤 많은 전투 감각을 회상할 수 있으며, 꽤 많은 경험치를 획득한다.",
  str_item_intro_3100009 = "오로리안의 레벨을 증가시키며, 번개 계열 오로리안에게는 효과가 50% 증가한다.\n매우 진귀한 노란색 옥. 과거의 전투를 생생하게 느낄 수 있으며, 대량의 경험치를 획득한다.",
  str_item_intro_3100010 = "오로리안의 레벨을 증가시키며, 불 계열 오로리안에게는 효과가 50% 증가한다.\n빨간색 옥을 통해 명상하면 일부 전투 기억을 회복할 수 있으며, 소량의 경험치를 획득한다.",
  str_item_intro_3100011 = "오로리안의 레벨을 증가시키며, 불 계열 오로리안에게는 효과가 50% 증가한다.\n비교적 진귀한 빨간색 옥을 통해 꽤 많은 전투 감각을 회상할 수 있으며, 꽤 많은 경험치를 획득한다.",
  str_item_intro_3100012 = "오로리안의 레벨을 증가시키며, 불 계열 오로리안에게는 효과가 50% 증가한다.\n매우 진귀한 빨간색 옥. 과거의 전투를 생생하게 느낄 수 있으며, 대량의 경험치를 획득한다.",
  str_item_intro_3100013 = "오로리안의 레벨업에 사용할 수 있다.\n회백색 옥. 특수한 에너지를 약간 지니고 있으며, 모든 오로리안이 이것을 통해 소량의 경험치를 얻을 수 있다.",
  str_item_intro_3100014 = "오로리안의 레벨업에 사용할 수 있다.\n비교적 진귀한 회백색 옥. 모든 오로리안이 이것을 통해 전투 감각을 재구성할 수 있으며, 약간의 경험치를 획득한다.",
  str_item_intro_3100015 = "오로리안의 레벨업에 사용할 수 있다.\n매우 진귀한 회백색 옥. 모든 오로리안이 이것을 통해 과거의 전투를 생생하게 느낄 수 있으며, 꽤 많은 경험치를 획득한다.",
  str_item_intro_3210101 = "초급 각성 재료. 백야성 세력 오로리안의 각성에 쓰인다.\n백야성 여명 아카데미에서 보관하고 있는 물건. 독특한 마법 체계로 힘이 강화되어, 오로리안의 힘을 높일 수 있다.",
  str_item_intro_3210201 = "초급 각성 재료. 움브라톤 세력 오로리안의 각성에 쓰인다.\n움브라톤에서 유행하는 독한 술. 맛이 좋으며, 마신 이의 힘을 강화시킨다.",
  str_item_intro_3210301 = "초급 각성 재료. 북방 세력 오로리안의 각성에 쓰인다.\n소나무에서 응집된 아침 이슬. 북방의 특수한 환경의 영향을 받은 것으로, 북방인에게 강력한 힘을 갖게 만들 수 있다.",
  str_item_intro_3210401 = "초급 각성 재료. 레디젤 렌치 세력 오로리안의 각성에 쓰인다.\n특수한 레디젤. 매우 자극적인 냄새가 나서, 강한 레디젤 렌치 멤버만 맛볼 수 있다.",
  str_item_intro_3210501 = "초급 각성 재료. 일루미나 연방 세력 오로리안의 각성에 쓰인다.\n일루미나 연방의 실전 기록. 읽은 사람의 전투 기술을 향상시켜 준다.",
  str_item_intro_3210601 = "초급 각성 재료. 진리의 결사 세력 오로리안의 각성에 쓰인다.\n고대의 지식이 적혀 있는 스크롤. 이것을 해독하면 진리의 결사 멤버의 능력이 꽤 향상된다.",
  str_item_intro_3210701 = "초급 각성 재료. 무소속자 오로리안의 각성에 쓰인다.\n각양각색의 사람들이 기록한 견문록. 용어가 매우 뒤죽박죽이다. 무소속자가 읽으면 각종 생존 경험을 획득할 수 있다.",
  str_item_intro_3210801 = "초급 각성 재료. 용주 세력 오로리안의 각성에 쓰인다.\n용주의 약방에서 정제한 단약으로, 순도가 높아 체력 증강과 근골 강화에 도움을 줄 수 있다.",
  str_item_intro_3210102 = "중급 각성 재료. 백야성 세력 오로리안의 각성에 쓰인다.\n백야성 여명 아카데미에서 보관하고 있는 물건. 새벽의 빛에서 얻은 힘으로 만들어져, 오로리안의 힘을 대폭 높일 수 있다.",
  str_item_intro_3210202 = "중급 각성 재료. 움브라톤 세력 오로리안의 각성에 쓰인다.\n운명의 샴페인의 프레스티지 버전. 훨씬 좋아진 맛으로, 마신 이의 힘을 크게 강화시킨다.",
  str_item_intro_3210302 = "중급 각성 재료. 북방 세력 오로리안의 각성에 쓰인다.\n소나무에서 응집된 아침 이슬. 서리와 같은 모양으로 비교적 희귀하며, 북방인의 체내 마력의 중요한 근원 중 하나다.",
  str_item_intro_3210402 = "중급 각성 재료. 레디젤 렌치 세력 오로리안의 각성에 쓰인다.\n레디젤 사막 깊은 곳에서만 발견되는 레디젤 에센스. 레디젤 렌치 멤버의 전투력을 향상시켜 준다.",
  str_item_intro_3210502 = "중급 각성 재료. 일루미나 연방 세력 오로리안의 각성에 쓰인다.\n일루미나 연방에서 수많은 데이터를 모아 만든 실전 기록. 읽은 사람의 전투 기술을 대폭 향상시켜 준다.",
  str_item_intro_3210602 = "중급 각성 재료. 진리의 결사 세력 오로리안의 각성에 쓰인다.\n고대의 지식이 많이 적혀 있는 서적. 이것을 해독하면 진리의 결사 멤버의 능력이 크게 향상된다.",
  str_item_intro_3210702 = "중급 각성 재료. 무소속자 오로리안의 각성에 쓰인다.\n각양각색의 사람들의 생존 방법 가이드. 무소속자가 읽으면 더 많은 경험을 체득할 수 있다.",
  str_item_intro_3210802 = "중급 각성 재료. 용주 세력 오로리안의 각성에 쓰인다.\n용주의 수행자들이 정제한 단약으로, 영기가 풍부한 재료를 다양하게 사용했다. 근골을 바꾸고 골수를 씻어내는 효과가 있다고 전해진다.",
  str_item_intro_3210103 = "고급 각성 재료. 백야성 세력 오로리안의 각성에 쓰인다.\n백야성 여명 아카데미에서 보관하고 있는 물건. 독특한 마법으로 힘이 강화되어, 오로리안의 힘을 한 단계 높일 수 있다.",
  str_item_intro_3210203 = "고급 각성 재료. 움브라톤 세력 오로리안의 각성에 쓰인다.\n가장 희귀한 운명의 샴페인. 힘을 대폭 증대시킬 수 있으며, 환상적인 맛이 느껴진다.",
  str_item_intro_3210303 = "고급 각성 재료. 북방 세력 오로리안의 각성에 쓰인다.\n완벽한 아침 이슬이라고 하며, 「북방의 눈물」로도 불린다. 북방인에게 강력한 마법의 힘을 제공할 수 있다.",
  str_item_intro_3210403 = "고급 각성 재료. 레디젤 렌치 세력 오로리안의 각성에 쓰인다.\n가장 순수한 레디젤. 반유체 형태를 보이며, 가장 강한 레디젤 렌치 멤버만 사용할 수 있다.",
  str_item_intro_3210503 = "고급 각성 재료. 일루미나 연방 세력 오로리안의 각성에 쓰인다.\n일루미나 연방에서 엄청난 양의 데이터를 모아 만든 실전 기록. 읽는 사람의 전투 기술을 한 단계 높여 준다.",
  str_item_intro_3210603 = "고급 각성 재료. 진리의 결사 오로리안의 각성에 쓰인다.\n고대의 지식이 적혀 있는 고서. 이것을 해독하면 진리의 결사 멤버의 능력이 비약적으로 향상된다.",
  str_item_intro_3210703 = "고급 각성 재료. 무소속자 오로리안의 각성에 쓰인다.\n각양각색의 사람들의 모든 견문과 경험이 뒤섞여 있는 책. 읽으면 뛰어난 생존 능력을 얻을 수 있다.",
  str_item_intro_3210803 = "고급 각성 재료. 용주 세력 오로리안의 각성에 쓰인다.\n용주의 은거기인이 정제한 단약으로, 천지의 정수가 단약 하나에 모여 재생의 공력을 지니고 있다. 복용자가 수행의 장벽을 돌파하고 대성할 수 있도록 돕는다.",
  str_item_intro_3201011 = "초급 각성 재료. 물 속성 오로리안 각성의 필수 아이템이다.\n물가의 토층에 많이 존재하는 플레어더스트로 대규모 공업 가공의 원재료 중 하나이다.",
  str_item_intro_3201012 = "초급 각성 재료. 물 속성 오로리안 각성의 필수 아이템이다.\n기묘한 파란색 빛으로 반짝이는 희귀한 수정 입자이다.",
  str_item_intro_3201013 = "초급 각성 재료. 물 속성 오로리안 각성의 필수 아이템이다.\n특수한 루미나틱스 배합을 통해 만들어진 순백색의 마법 가루이다.",
  str_item_intro_3201014 = "물 속성초급 각성 재료. 물 속성 오로리안 각성의 필수 아이템이다.\n신비한 물질 중 하나로 바닷물이 응고되어 만들어진 돌로 딱딱하지 않고 공기 구멍이 많다.",
  str_item_intro_3201021 = "초급 각성 재료. 불 속성 오로리안 각성의 필수 아이템이다.\n일반적으로 지열대에서 발견되는 플레어더스트로 대규모 공업 가공의 원재료 중 하나이다.",
  str_item_intro_3201022 = "초급 각성 재료. 불 속성 오로리안 각성의 필수 아이템이다.\n강렬한 빨간색으로 반짝이는 희귀한 수정 입자이다.",
  str_item_intro_3201023 = "초급 각성 재료. 불 속성 오로리안 각성의 필수 아이템이다.\n특수한 루미나틱스 배합을 통해 만들어진 붉은색의 마법 가루이다.",
  str_item_intro_3201024 = "초급 각성 재료. 불 속성 오로리안 각성의 필수 아이템이다.\n신비한 물질 중 하나로 고온에서 돌을 가루로 만들고 연소시킨 후 얻을 수 있다.",
  str_item_intro_3201031 = "초급 각성 재료. 숲 속성 오로리안 각성의 필수 아이템이다.\n암석층에 존재하는 플레어더스트로 대규모 공업 가공의 원재료 중 하나다.",
  str_item_intro_3201032 = "초급 각성 재료. 숲 속성 오로리안 각성의 필수 아이템이다.\n짙은 초록색의 희귀한 수정 입자이다.",
  str_item_intro_3201033 = "초급 각성 재료. 숲 속성 오로리안 각성의 필수 아이템이다.\n특수한 루미나틱스 배합을 통해 만들어진 청록색의 마법 가루이다.",
  str_item_intro_3201034 = "초급 각성 재료. 숲 속성 오로리안 각성의 필수 아이템이다.\n신비한 물질 중 하나로 고대 식물을 분해하여 만든 물건이라고 한다.",
  str_item_intro_3201041 = "초급 각성 재료. 번개 속성 오로리안 각성의 필수 아이템이다.\n전도성이 좋은 플레어더스트로 공업 분야에서 많은 곳에 쓰이지만, 대부분 가공해야 사용할 수 있다.",
  str_item_intro_3201042 = "초급 각성 재료. 번개 속성 오로리안 각성의 필수 아이템이다.\n가끔씩 금색으로 번쩍이는 희귀한 수정 입자이다.",
  str_item_intro_3201043 = "초급 각성 재료. 번개 속성 오로리안 각성의 필수 아이템이다.\n특수한 루미나틱스 배합을 통해 만들어진 황금색의 마법 가루이다.",
  str_item_intro_3201044 = "초급 각성 재료. 번개 속성 오로리안 각성의 필수 아이템이다.\n신비한 물질 중 하나로 썬더스톰의 땅에서 채집할 수 있는 돌이며, 번개의 힘을 지녔다고 한다.",
