  str_item_intro_3205034 = "고급 각성 재료. 숲 속성 오로리안 각성의 필수 아이템이다.\n대량의 희귀한 식물 종자를 수집해서 신비한 방법으로 분해와 제련을 진행해 만든 미스릴 조각으로 매우 비싼 물건이다.",
  str_item_intro_3205041 = "고급 각성 재료. 번개 속성 오로리안 각성의 필수 아이템이다.\n번개의 플레어브릭을 특수한 공법으로 가공하고, 다른 재료와 혼합해 만든 스틸로 최고급 공업 제품이다.",
  str_item_intro_3205042 = "고급 각성 재료. 번개 속성 오로리안 각성의 필수 아이템이다.\n수많은 노란색 크리스탈에 루미나의 힘을 더해 만들어진 희귀한 보석으로 엄청난 루미나를 가지고 있다.",
  str_item_intro_3205043 = "고급 각성 재료. 번개 속성 오로리안 각성의 필수 아이템이다.\n번개의 에센스를 정제한 산물로 오로리안의 힘을 대폭 증대시킬 수 있다.",
  str_item_intro_3205044 = "고급 각성 재료. 번개 속성 오로리안 각성의 필수 아이템이다.\n전기를 은 덩어리에 흘려 넣어서 얻은 마법 재료로 굉장히 견고하며, 안에는 마치 벼락 같은 힘이 내재되어 있다.",
  str_item_intro_3220000 = "오로리안 돌파에 특별한 역할을 한다.\n어떤 오로리안의 손에 있으면 특별한 효과를 내는 희귀한 보석. 신비한 에너지를 품고 있어서, 이것을 다룰 수 있다면 오로리안의 잠재된 힘을 발휘할 수 있다.",
  str_item_intro_3220001 = "나시리스 돌파 시 필수 아이템.\n마치 거울 같은 독특한 보석. 자세히 보면 하얀 옷을 입은 소녀의 모습이 보인다.",
  str_item_intro_3220002 = "히이로 돌파 시 필수 아이템.\n이 보석에는 가끔씩 분홍색 용의 모습이 드러나며, 매우 귀하다.",
  str_item_intro_3220004 = "쿠마&페기 돌파 시 필수 아이템.\n쿠마와 페기가 이 보석을 착용하면 보석이 차가운 기운을 발산한다. 때문에 쿠마와 페기가 가장 좋아하는 보석이다.",
  str_item_intro_3220005 = "미아 돌파 시 필수 아이템.\n이 보석 속에는 미아의 다른 모습이 봉인된 것 같다... 어쩌면 미아의 진짜 속마음을 찾을 수 있을지도.",
  str_item_intro_3220006 = "카렌 돌파 시 필수 아이템.\n이 보석은 가끔씩 장창 모양의 흰 빛을 발산한다.",
  str_item_intro_3220009 = "파우스트 돌파 시 필수 아이템.\n가끔씩 괴상하고 비뚤어진 도안이 나타나는 보석. 다른 사람이 착용한다면 당황스럽겠지만, 파우스트는 꺼리지 않고 오히려 친근하게 여긴다.",
  str_item_intro_3220010 = "루이스 돌파 시 필수 아이템.\n밝은 기운을 지닌 보석, 루이스 캐롤에게 수많은 이야기의 영감을 준다고 한다.",
  str_item_intro_3220011 = "시로나 돌파 시 필수 아이템.\n이 희귀한 보석을 자세히 보면 흐릿하게 큰 용의 그림자가 나타나있다.",
  str_item_intro_3220012 = "네메시스 돌파 시 필수 아이템.\n단단하기 그지없으며 절단면이 매우 아름다운 보석. 사람을 뒤흔드는 힘이 있다.",
  str_item_intro_3220013 = "노아 돌파 시 필수 아이템.\n만져 보면 강한 한기가 느껴지지만, 동상은 입히지 않는 기묘한 보석. 노아가 좋아하는 물건이다.",
  str_item_intro_3220014 = "솔라드 돌파 시 필수 아이템.\n강렬한 빛으로 반짝이는 하얀색 보석. 솔라드가 자신과 백야성을 나타낸다고 여기는 물건이다.",
  str_item_intro_3220015 = "호넷&실버 돌파 시 필수 아이템.\n호넷과 실버는 이 보석에서 다양한 광경을 보고, 특별한 예술적 영감을 얻을 수 있다.",
  str_item_intro_3220016 = "카프카 돌파 시 필수 아이템.\n이 보석은 극도로 단단하며, 한때 누군가를 위해 치명적인 공격을 막아낸 적이 있다고 한다.",
  str_item_intro_3220017 = "라비 돌파 시 필수 아이템.\n자세히 보면 보석 속에 날뛰는 토끼처럼 타오르는 불꽃이 있다. 라비의 행운의 상징.",
  str_item_intro_3220018 = "레지나 돌파 시 필수 아이템.\n태양 같은 빛을 발산하는 보석. 가장 어두운 곳이라도 빛을 가져다주며, 레지나의 음악을 한 단계 더 업그레이드해 준다.",
  str_item_intro_3220019 = "빅토리아 돌파 시 필수 아이템.\n이 보석 안에는 무수한 눈물방울 모양의 알갱이가 있는데, 빅토리아 자신의... 피라는 말이 있다.",
  str_item_intro_3220021 = "유라 돌파 시 필수 아이템.\n유라가 이 보석을 만진 순간, 보석 주변에 초록색 물결이 일어날 것이다.",
  str_item_intro_3220023 = "코놀리 돌파 시 필수 아이템.\n응결된 검은색 물방울로, 코놀리의 손에서 매우 단단한 보석으로 변한다.",
  str_item_intro_3220024 = "베니&쿠로 돌파 시 필수 아이템.\n붉은색과 검은색 빛이 뒤섞인 채 반짝이며, 가까이 다가가면 검으로 베는 소리와 총기를 발사하는 소리를 들을 수 있다.",
  str_item_intro_3220025 = "카론 돌파 시 필수 아이템.\n빨간색과 검은색 줄무늬가 반짝이며, 카론이 가장 좋아하는 보석이다.",
  str_item_intro_3220026 = "우리엘 돌파 시 필수 아이템.\n가끔 회색과 검은색 불빛이 반짝이는 보석. 매우 아름답지만 환멸감을 준다...",
  str_item_intro_3220027 = "미카엘 돌파 시 필수 아이템.\n이 보석은 천둥번개로 심술궂은 날씨에 발견되었다고 하며, 진정한 주인에게 강력한 힘을 가져다줄 수 있다고 한다.",
  str_item_intro_3220028 = "라파엘 돌파 시 필수 아이템.\n기묘한 힘을 지닌 투명한 보석. 라파엘이 사용하면 치유의 힘을 강화시켜 준다.",
  str_item_intro_3220029 = "가브리엘 돌파 시 필수 아이템.\n가브리엘이 이 보석을 사용하면 매우 아름다운 녹색의 빛이 드러난다.",
  str_item_intro_3220030 = "사메야마 돌파 시 필수 아이템.\n이 보석은 항상 뜨거운 열을 발산하고 있어서 사메야마만 착용할 수 있다.",
  str_item_intro_3220033 = "바이스 돌파 시 필수 아이템.\n볼 때마다 다른 색의 기이한 광채를 내는 보석. 어떤 과거의 일이 봉인되어 있는 듯하다...",
  str_item_intro_3220036 = "휴라드 돌파 시 필수 아이템.\n심상치 않은 기운을 발산하는 보석. 하지만 휴라드는 무서워하지 않으며, 오히려 항상 「녀석은... 나와 같지.」라고 말한다.",
  str_item_intro_3220038 = "그로누 돌파 시 필수 아이템.\n이 보석에는 다양한 인공 원소가 들어있다고 한다. 따라서 자연적으로 만들어진 보석은 아닌 것 같고... 고대 문명의 잔재로 보인다.",
  str_item_intro_3220040 = "봄버 존 돌파 시 필수 아이템.\n이 보석을 만지면 불꽃이 나올 것만 같다... 조심해야 하며, 함부로 가지고 놀지 말 것.",
  str_item_intro_3220041 = "Ms. 블랑 돌파 시 필수 아이템.\n우아하게 빛나는 보석. 이를 가까이 두면 차분해지는 느낌이 들며, 단정한 여성에게 잘 어울린다.",
  str_item_intro_3220042 = "바튼 돌파 시 필수 아이템.\n이 보석 속에는 바튼만이 볼 수 있는 전쟁의 불길처럼 타오르는 붉은 반점이 숨어 있는데, 어쩌면 그의 내면의 욕망이 구현된 것일지도 모른다.",
  str_item_intro_3220044 = "비비안 돌파 시 필수 아이템.\n강렬한 빛을 방출하는 보석. 칼자루에 장식하기 좋다.",
  str_item_intro_3220045 = "나일즈 돌파 시 필수 아이템.\n이 보석의 가장자리는 무척 날카롭다. 누군가의 말에 따르면 그것은 「징벌」을 상징한다고 한다...",
  str_item_intro_3220046 = "키팅 돌파 시 필수 아이템.\n키팅의 멤버들이 이 보석을 착용하면 머릿속에서 더 많은 「시구」가 떠오른다고 한다.",
  str_item_intro_3220048 = "디나 돌파 시 필수 아이템.\n디나가 이 보석을 착용하면 더 많은 전투 기술을 깨달을 수 있다고 한다.",
  str_item_intro_3220054 = "나딘 돌파 시 필수 아이템.\n이 하얀색 보석은 언제나 따스하고 온화한 빛을 발산한다.",
  str_item_intro_3220055 = "피트만 돌파 시 필수 아이템.\n진실을 찾기 위한 여정에서 피트만도 한때 혼란에 빠졌지만, 이 수정이 그에게 굳건한 힘을 가져다주었다.",
  str_item_intro_3220056 = "콘스탄틴 돌파 시 필수 아이템.\n콘스탄틴이 암귀를 사냥하면 자동으로 상세 내용을 기록하는 수정으로, 콘스탄틴의 파트너다.",
  str_item_intro_3220057 = "필리시 돌파 시 필수 아이템.\n이 보석은 가끔씩 검은 기운을 발산하는데, 가까이 가면 필리시의 진짜 속마음을 발견할 수 있을지도 모른다.",
  str_item_intro_3220060 = "요나 돌파 시 필수 아이템.\n이 수정의 밑부분은 녹은 황동인 것으로 보이는데, 이는 요나가 쓰는 권총의 총알로 만들어진 것이며, 그녀의 옛 전적을 나타낸다.",
  str_item_intro_3220061 = "찬드라 돌파 시 필수 아이템.\n투명한 보석. 자세히 보면 안에서 어떤 기운이 끊임없이 움직이는데, 그녀가 수집한 여러 가지 감정 같다.",
  str_item_intro_3220062 = "실바 돌파 시 필수 아이템.\n풍맥의 숲 깊은 곳에서 발견된 보석이라고 한다. 만지면 상당히 차가우며, 숲지기 실바의 상징이다.",
  str_item_intro_3220064 = "레이스 돌파 시 필수 아이템.\n이 보석은 매우 무겁지만, 레이스의 손에서는 무척 가벼워져 마치 공중에 뜰 수 있을 것만 같다...",
  str_item_intro_3220065 = "트위티 돌파 시 필수 아이템.\n트위티가 이 수정을 응시하면, 마치 운산의 그림자가 눈앞에 보이는 듯하다. 그곳은 바로 그녀의 고향이다.",
  str_item_intro_3220067 = "앨리스 돌파 시 필수 아이템.\n앨리스가 만지면 하트로 변하는 보석으로 특별한 활력을 발산한다.",
  str_item_intro_3220068 = "웬디 돌파 시 필수 아이템.\n이 보석은 가볍지만 매우 단단하며, 웬디의 성격과 무척 닮았다.",
  str_item_intro_3220070 = "레오나 돌파 시 필수 아이템.\n이 수정을 보고 있으면 악룡의 포효를 들을 수 있다.",
  str_item_intro_3220071 = "타키 돌파 시 필수 아이템.\n이 수정에서는 가끔 거대한 용이 불을 뿜는 장면이 나타난다. 그것은 타키를 대표하는 것이어서 이 수정은 틀림없이 그의 것이다.",
  str_item_intro_3220073 = "파티&파시 돌파 시 필수 아이템.\n이 보석은 피처럼 붉은 빛과 검은 기운이 번갈아 나타난다.",
  str_item_intro_3220075 = "오디 돌파 시 필수 아이템.\n이 보석을 귓가에 대면 희미한 전류의 소리가 들린다. 어쩌면 통신에 사용할 수 있을 것 같다.",
  str_item_intro_3220076 = "클레이튼 돌파 시 필수 아이템.\n이 기묘한 보석은 보는 각도에 따라 색깔이 달라지며, 클레이튼의 손에서는 특히 다양하게 변한다.",
  str_item_intro_3220077 = "베들레헴 돌파 시 필수 아이템.\n이 보석은 맑고 투명하면서도 차갑기 그지없다. 이 세상의 첫 얼음으로 만들어졌다고 하며, 북방의 여왕만이 지닐 수 있다.",
  str_item_intro_3220078 = "로빈 돌파 시 필수 아이템.\n비취색 보석. 몸에 지니면 모든 독에 대항할 수 있다는 로빈의 수호 부적이다.",
  str_item_intro_3220079 = "미제니 돌파 시 필수 아이템.\n아주 반듯한 모양의 보석으로, 무게 중심이 완벽하다. 저울의 균형을 유지하는 데 사용할 수 있다고 한다.",
  str_item_intro_3220081 = "렉커 돌파 시 필수 아이템.\n이 보석은 만지면 매우 뜨겁다. 마치 결코 줄어들지 않는 누군가의 활력처럼 말이다.",
  str_item_intro_3220083 = "리리암 돌파 시 필수 아이템.\n이 보석이 진정한 주인과 가까워지면 전자 회로와 같은 기묘한 무늬가 드러난다.",
  str_item_intro_3220084 = "이스타반 돌파 시 필수 아이템.\n이 보석 주변에는 때때로 푸른 불꽃이 튀어 오르는데, 가까이 다가가면 보석에서 「섀도우마스터」를 부르는 소리가 희미하게 들린다.",
  str_item_intro_3220085 = "제인 돌파 시 필수 아이템.\n이 검은 보석을 쳐다보면 기록된 문자를 잔뜩 볼 수 있을지도 모른다...",
  str_item_intro_3220086 = "우라이아 돌파 시 필수 아이템.\n이 하얀색 옥에는 꽃잎 형태가 조각되어 있으며, 우아하고 고상하다.",
  str_item_intro_3220087 = "베벌리 돌파 시 필수 아이템.\n이 보석은 가끔 창 모양의 스파크가 반짝이는데, 마치 베벌리의 뇌창과 닮았다.",
  str_item_intro_3220088 = "마지 돌파 시 필수 아이템.\n이 수정은 가끔씩 기괴한 노란색 빛을 발산하며, 가까이 다가가면 그 안에서 한 소녀의 모습을 볼 수 있다.",
  str_item_intro_3220089 = "이리돈 돌파 시 필수 아이템.\n이 보석은 가끔씩 파란색 번개를 발산하며, 강력한 힘을 품고 있다.",
  str_item_intro_3220090 = "바바라 돌파 시 필수 아이템.\n붉은색 밑받침을 가진 보석. 가까이 다가가면 떠들썩한 음악이 희미하게 들린다.",
  str_item_intro_3220091 = "크로이 돌파 시 필수 아이템.\n이 흰색 수정에는 항상 이슬이 눈물 방울처럼 맺히며, 가까이 가면 은은한 칠현금 소리가 들린다.",
  str_item_intro_3220092 = "펙트 돌파 시 필수 아이템.\n이 보석은 매우 튼튼하며, 어떤 흠집도 나지 않는다고 한다.",
  str_item_intro_3220093 = "미자드 돌파 시 필수 아이템.\n인공 생물의 척추에서 뽑아낸 것만 같은 보석으로 수수께끼 같은 에너지를 가지고 있다...",
  str_item_intro_3220095 = "레스터 돌파 시 필수 아이템.\n마치 황야에 있는 것 같은 느낌을 주는 보석으로 레스터는 이것을 가지고 자신의 맘에 드는 향을 찾는다.",
  str_item_intro_3220096 = "샤리 돌파 시 필수 아이템.\n샤리의 손에서 원래의 형태를 잃고 물방울처럼 변하는 보석으로 샤리에게 강한 힘을 준다.",
  str_item_intro_3220097 = "와타리 돌파 시 필수 아이템.\n이 보석은 아주 차갑고 모서리가 날카로워 칼을 대신할 수 있을 것 같다.",
  str_item_intro_3220098 = "쿠스쿠타 돌파 시 필수 아이템.\n이 수정을 자세히 보면 그 속에 시든 검은색 꽃송이가 보인다...",
  str_item_intro_3220099 = "아이리나 돌파 시 필수 아이템.\n아이리나가 이 수정을 보았을 때 저주의 힘이 많이 약해진 것 같았다...",
  str_item_intro_3220100 = "스칼렛 돌파 시 필수 아이템.\n이 보석에는 「별」이 담겨있는데, 그것이 스칼렛의 힘의 진정한 근원이라고 한다.",
  str_item_intro_3220101 = "안시아 돌파 시 필수 아이템.\n기묘한 황동색 빛, 그리고 가벼운 진동이 느껴진다. 이 진동은 어떤 소리의 주파수와 매우 비슷하다...",
  str_item_intro_3220102 = "테사 돌파 시 필수 아이템.\n이 보석은 항상 불규칙한 스파크가 흘러, 섣불리 다가가면 갑자기 스파크가 일어난다. 유일하게 테사만이 이 보석을 잘 다룰 수 있다.",
  str_item_intro_3220103 = "엘시 돌파 시 필수 아이템.\n수정 안에서 어떤 「방사선」이 방출되고 있어 무섭다...",
  str_item_intro_3220104 = "도엔 돌파 시 필수 아이템.\n도엔의 보석, 그녀가 움켜쥐면 보석에 새하얀 꽃의 그림자가 비친다. 그것이 바로 도엔의 희망이다...",
  str_item_intro_3220105 = "이브 돌파 시 필수 아이템.\n이브가 만지면 수정 주변에 미세한 아크가 나타나는데, 그것이 바로 이브가 가지고 있는 특별한 힘이다.",
  str_item_intro_3220107 = "프리토리언 솔람버",
  str_item_intro_3220108 = "히에로플람마 솔람버",
  str_item_intro_3220109 = "네니아 솔람버",
  str_item_intro_3220110 = "레퀴엠 솔람버",
  str_item_intro_3220111 = "베릴 돌파 시 필수 아이템.\n베릴이 이 수정을 손에 쥐면 피처럼 붉은색으로 변하며, 베릴의 몸에 있는 수정들과 같은 모습이 된다...",
  str_item_intro_3220112 = "스모키 돌파 시 필수 아이템.\n이 보석은 근처의 가연성 물질을 불태우는 능력이 있다. 오직 스모키의 손에 있을 때만 그 능력을 잠재울 수 있다.",
  str_item_intro_3220113 = "보나시외 돌파 시 필수 아이템.\n보나시외가 이 보석을 건드리면, 머릿속에 수많은 영감이 떠올라 새로운 음악을 작곡할 수 있게 해준다.",
  str_item_intro_3220114 = "제네비브 돌파 시 필수 아이템.\n이글거리는 화염처럼 항상 붉게 빛나고 있으며, 가끔씩 말의 울음소리가 들린다.",
  str_item_intro_3220115 = "나로세르 돌파 시 필수 아이템.\n나로세르가 이 수정을 착용하고 있으면 대자연의 소리를 들을 수 있는 듯하며, 동식물과의 교류도 더욱 순조로워진다.",
  str_item_intro_3220116 = "플뢰르 돌파 시 필수 아이템.\n이 보석은 플뢰르에게 설계의 영감을 주며, 「로봇 제작 계획」이 한 걸음 더 나아갈 수 있도록 돕는다.",
  str_item_intro_3220117 = "그람 돌파 시 필수 아이템.\n그람이 이것을 손에 쥐면, 마치 자신이 「용사 별동대」에 있던 시절로 돌아간 것처럼 감회에 젖곤 한다.",
  str_item_intro_3220119 = "레비 돌파 시 필수 아이템.\n레비가 이 보석을 만질 때면, 대검이 쇠사슬과 마찰되는 소리를 들을 수 있으며, 가끔씩 전류가 느껴지기도 한다.",
  str_item_intro_3220120 = "헤이디 돌파 시 필수 아이템.\n태양 광선 아래서 이 보석은 갑옷 같은 흰색 광택을 발산한다.",
  str_item_intro_3220121 = "파로마 돌파 시 필수 아이템.\n이 보석에는 가끔씩 단발머리 소녀의 모습이 나타나는데, 그것은 파로마에게 매우 익숙하면서도 다시는 익숙하게 대할 수 없는 사람이다...",
  str_item_intro_3220122 = "알루라 돌파 시 필수 아이템.\n알루라가 이 보석을 귓가에 대면 시계가 움직이는 「째깍」 소리가 들리는데, 그녀는 이를 통해 시간을 더 정밀하게 제어할 수 있게 된다.",
  str_item_intro_3220123 = "커디 돌파 시 필수 아이템.\n이 보석을 손에 넣은 뒤로, 커디는 긴급 상황을 더 수월하게 처리할 수 있게 됐다.",
  str_item_intro_3220126 = "베델 돌파 시 필수 아이템.\n이 수정은 그녀의 가슴에 있는 보석과 어우러져 더욱 화려한 색채를 발한다.",
  str_item_intro_3220127 = "파솔로 돌파 시 필수 아이템.\n파솔로의 손안에서 이 수정은 매우 얇고 가볍게 변하며, 공중에 떠다닐 수 있게 된다.",
  str_item_intro_3220129 = "루크 돌파 시 필수 아이템.\n무척 가벼운 수정이다. 루크는 이것을 공중에 띄우고 나비처럼 춤추게 만들 수 있다.",
  str_item_intro_3220131 = "노비오 돌파 시 필수 아이템.\n보석 표면에는 이해하기 어려운 문자가 새겨져 있다. 왠지 노비오만이 이 문자의 뜻을 알 수 있을 것 같다.",
  str_item_intro_3220132 = "로라 돌파 시 필수 아이템.\n벌꿀에 잠겨 있는 보석. 은은한 빛을 내며 달콤한 꿀의 향기를 발산한다.",
  str_item_intro_3220133 = "토르 돌파 시 필수 아이템.\n이 보석은 다른 이들에게 다가가면 타오르는 불꽃을 일으키지만, 코바야시 근처에서는 부드러운 분홍색으로 변한다.",
  str_item_intro_3220134 = "칸나 돌파 시 필수 아이템.\n때때로 보석에 작은 빛이 번쩍이며, 손에 쥐고 있으면 왠지 모르게 무척 부드럽다.",
  str_item_intro_3220135 = "엘마 돌파 시 필수 아이템.\n보석에 규칙적으로 난류가 흐른다. 마음이 진정되면 맑은 봄의 소리를 들을 수 있다.",
  str_item_intro_3220136 = "루코아 돌파 시 필수 아이템.\n이 보석을 오랫동안 보고 있으면 점점 더 많은 광경이 눈에 들어온다. 하늘, 바다, 산, 마을... 그리고 마지막에는 깊이를 알 수 없는 기이한 색의 눈동자를 보게 될 것이다.",
  str_item_intro_3220137 = "파프닐 돌파 시 필수 아이템.\n이 보석 근처에서는 불길한 포효가 들리며, 파프닐의 목소리가 그 안에 섞여서 낮은 목소리로 뭔가 말하고 있다.",
  str_item_intro_3220138 = "시오반 돌파 시 필수 아이템.\n시오반이 이 보석을 가지고 있을 때면 녹색의 선이 보이는 듯하다...",
  str_item_intro_3220139 = "에리카 돌파 시 필수 아이템.\n이 보석에 귀를 기울이고 자세히 들어보면 미지의 존재가 부르는 소리가 들릴지도 모른다.",
  str_item_intro_3220140 = "플로리나 돌파 시 필수 아이템.\n잘 문질러져 광택이 나는 보석이다. 양피지와 잉크 냄새가 나며, 안에서 독서와 기도의 메아리가 들리는 것만 같다.",
  str_item_intro_3220141 = "루비 돌파 시 필수 아이템.\n매우 단단한 보석으로, 방망이로 치면 선명한 소리를 낸다. 루비의 스윙 연습에 적합하다.",
  str_item_intro_3220142 = "루즈 돌파 시 필수 아이템.\n이 보석은 조금 평범해 보이지만, 루즈가 쓰다듬으면 타오르는 불꽃의 환상이 나타난다.",
  str_item_intro_3220143 = "린네 돌파 시 필수 아이템.\n때때로 옅은 분홍색으로 빛나는 보석이다. 가볍게 흔들면 선명하고 경쾌한 종소리가 울린다.",
  str_item_intro_3220144 = "카야노 돌파 시 필수 아이템.\n눈에 잘 띄지 않는 보석이다. 서늘한 온도를 유지하며, 고요한 밤에는 희미한 빛을 발한다.",
  str_item_intro_3220145 = "아메모리 돌파 시 필수 아이템.\n이 보석은 아메모리의 손에서는 매우 가볍게 변하며, 가끔씩 「인(忍)」이라는 글자가 깜빡거리곤 한다.",
  str_item_intro_3220146 = "요우 돌파 시 필수 아이템.\n이 보석은 음식의 향기를 풍기며, 자세히 살펴보면 보석에 기묘한 붉은빛이 반짝이는 듯하다.",
  str_item_intro_3220147 = "모모&안즈 돌파 시 필수 아이템.\n형형색색의 보석으로, 은연중에 맛있을 것 같다는 느낌이 들게 만든다. 자세히 보면 보석 안에서 두 가지 유사한 빛이 깜박이는 것을 알 수 있다.",
  str_item_intro_3220148 = "아주르 돌파 시 필수 아이템.\n시원한 촉감이 느껴지는 보석으로, 햇살 아래에서 푸른 빛을 반사한다.",
  str_item_intro_3220149 = "로이 돌파 시 필수 아이템.\n재질이 곱고 윤기가 나는 보석으로, 그다지 눈에 잘 띄지는 않으며, 가끔씩 표면에 은발머리를 한 누군가의 모습이 보인다. 그러나 제대로 보려고 할 때마다 로이가 가져가 버리고, 로이의 큰 키 탓에 다시 뺏을 수가 없다.",
  str_item_intro_3220150 = "레노어 돌파 시 필수 아이템.\n왜인지는 모르겠지만 이 보석은 계속 「띡띡」 소리를 내는데, 왠지 인형의 태엽을 감아주는 소리 같기도 하다...",
  str_item_intro_3220151 = "길스 돌파 시 필수 아이템.\n매우 단단하고 뜨거운 보석으로, 길스가 만지면 보석이 놀랍게도 양의 뿔 모양으로 변하는 것을 볼 수 있다.",
  str_item_intro_3220152 = "메이 돌파 시 필수 아이템.\n메이가 이 보석을 손에 쥐면 표면에 고양이의 형상이 나타나며, 가끔씩 한 오로리안의 모습도 나타나는데, 그것이 누구인지는 아무도 알아볼 수 없었다.",
  str_item_intro_3220153 = "라인하르트 돌파 시 필수 아이템.\n이 보석은 일루미나에서 가장 존경받는 보석 장인이 직접 가공한 것으로, 일루미나 연방의 정점에 선 자만이 손에 넣을 수 있다.",
  str_item_intro_3220154 = "바이스 더 킨사이트 돌파 시 필수 아이템.\n바이스가 가까이 가면 보석이 미세하게 진동을 시작하며, 붉은빛과 초록빛이 번갈아 가며 빛난다.",
  str_item_intro_3220187 = "이천간 돌파 시 필수 아이템.\n약간 끈적한 보석으로, 가까이 다가가면 달콤한 냄새가 난다. 이천간은 이 보석을 사용할 때마다 정말 맛있다는 듯한 웃음을 짓는데, 설마 사탕일까?",
  str_item_intro_3220188 = "단당 돌파 시 필수 아이템.\n이 보석은 촉감이 매끄럽고, 가까이 가면 은은한 꽃향기가 난다. 자세히 보면 표면의 주름이 해당화 모양이다.",
  str_item_intro_3221000 = "한정 오로리안 솔람버로 교환할 수 있다.",
  str_item_intro_3221001 = "5성 숲 속성 오로리안(한정 제외) 솔람버 교환에 사용한다.",
  str_item_intro_3221002 = "5성 번개 속성 오로리안(한정 제외) 솔람버 교환에 사용한다.",
  str_item_intro_3221003 = "5성 불 속성 오로리안(한정 제외) 솔람버 교환에 사용한다.",
  str_item_intro_3221004 = "5성 물 속성 오로리안(한정 제외) 솔람버 교환에 사용한다.",
  str_item_intro_3221005 = "6성 숲 속성 오로리안(한정 제외) 솔람버 교환에 사용한다.",
  str_item_intro_3221006 = "6성 번개 속성 오로리안(한정 제외) 솔람버 교환에 사용한다.",
  str_item_intro_3221007 = "6성 불 속성 오로리안(한정 제외) 솔람버 교환에 사용한다.",
  str_item_intro_3221008 = "6성 물 속성 오로리안(한정 제외) 솔람버 교환에 사용한다.",
  str_item_intro_5840001 = "기본종 환상수 씨앗 주머니, 안에 든 씨앗으로 가장 기본적인 환상수를 재배할 수 있다.",
  str_item_intro_5840002 = "우량종 환상수 씨앗 주머니, 안에 든 씨앗으로 미세하게 변이한 환상수를 재배할 수 있다.",
  str_item_intro_5840003 = "특산종 환상수 씨앗 주머니, 안에 든 씨앗으로 여러 차례의 변이를 거친 특산종 환상수를 재배할 수 있다.",
  str_item_intro_5840004 = "절세의 환상수 씨앗 주머니, 안에 든 씨앗으로 복잡한 변이를 거친 환상수를 재배할 수 있다.",
  str_item_intro_3220155 = "바튼 더 데프트 블레이드 돌파 시 필수 아이템\n단단하고 무거운 보석이다. 간혹 안에서 거대한 검은 그림자를 볼 수 있는데, 맹수의 낮은 울음소리가 들려오는 것만 같다.",
  str_item_intro_3220156 = "니나 돌파 시 필수 아이템.\n매우 희귀한 보석으로, 유심히 보면 그 속에서 흘러나오는 광택이 계속해서 변하는 것을 알 수 있다. 왠지 불굴의 의지를 드러내고 있는 것 같다.",
  str_item_intro_3220157 = "사나에 돌파 시 필수 아이템.\n이 원석은 경도가 매우 높아 어떻게 떨어뜨려도 부서지지 않는데, 이것이 어떻게 발견되었는지는 아마 사나에만 알고 있을 것이다.",
  str_item_intro_3220158 = "조커 돌파 시 필수 아이템.\n강한 광택을 지닌 보석으로. 그 안에서 강렬한 반역의 의지를 느낄 수 있다.",
  str_item_intro_3220159 = "퀸 돌파 시 필수 아이템.\n수정처럼 맑은 보석으로, 그 안에서 강렬한 반역의 의지를 느낄 수 있다.",
  str_item_intro_3220160 = "폭스 돌파 시 필수 아이템.\n부드러운 촉감의 보석으로. 그 안에서 강렬한 반역의 의지를 느낄 수 있다.",
  str_item_intro_3220161 = "바이올렛 돌파 시 필수 아이템.\n작은 꽃 모양의 보석으로, 그 안에서 강렬한 반역의 의지를 느낄 수 있다.",
  str_item_intro_3220162 = "모나 돌파 시 필수 아이템.\n표면에 날카로운 발톱 자국 같은 흠집이 있는 보석으로, 그 안에서 강렬한 반역의 의지를 느낄 수 있다.",
  str_item_intro_3220164 = "카렌 더 스몰더링 소울 돌파 시 필수 아이템.\n언뜻 보기에 이 보석의 내부는 수증기가 가득 응결되어 있는 것 같았지만, 순식간에 화염으로 변했다. 그러나 보석의 내부가 어떻게 변하더라도, 이 보석의 견고한 본질은 변하지 않는다.",
  str_item_intro_3220165 = "시엘 돌파 시 필수 아이템.\n시엘이 이 수정을 자세히 볼 때면 마치 신비한 공식들을 볼 수 있는 것 같다. 그 공식들은 시엘에게 끝없는 영감을 선사한다.",
  str_item_intro_3220166 = "피아 돌파 시 필수 아이템.\n근처에 환상동물이 나타나면 이 보석이 세차게 진동한다.",
  str_item_intro_3220167 = "제노 돌파 시 필수 아이템.\n신비로운 보석으로, 근처에 자신의 환영을 만들어 낸다... 속지 않도록 조심하자.",
  str_item_intro_3220168 = "레인보우 돌파 시 필수 아이템.\n만졌을 때 차가운 느낌이 드는 보석이다. 가끔은 안에서 파도 소리가 들려올 때도 있다.",
  str_item_intro_3220169 = "새디 돌파 시 필수 아이템.\n이 보석을 꽉 움켜쥘 때마다, 새디는 손바닥을 통해 끝없는 용기가 흘러 들어와 온몸에 퍼져 심장 박동까지 바뀌는 것 같은 느낌을 받는다.",
  str_item_intro_3220170 = "폴룩스 돌파 시 필수 아이템.\n화약 연기로 가득 찬 보석이다. 신기한 것은 이 보석의 표면에 때때로 칼 한 자루의 모습이 나타난다는 것이다.",
  str_item_intro_3220171 = "카스타 돌파 시 필수 아이템.\n귀를 기울이면 보석 내부에서 까마귀가 우는 듯한 소리가 들리는 신기한 보석이다.",
  str_item_intro_3220172 = "리리카 돌파 시 필수 아이템.\n이 보석을 자세히 보다 보면, 가끔은 놀라운 영화 속 장면들이 보석에 아른거린다. 이 보석이 있다면 리리카의 연기 실력도 더욱 성장할 수 있을 것이다!",
  str_item_intro_3220173 = "미노스 돌파 시 필수 아이템.\n미노스의 총구가 불을 뿜을 때마다, 이 보석에 소의 머리를 한 악마의 모습이 비치는 것 같다.",
  str_item_intro_3220175 = "악셀리아 돌파 시 필수 아이템.\n상처투성이의 보석이다. 손에 쥐면 날카로운 모서리가 느껴지지만, 계속 쥐다 보면 묘한 온기를 느낄 수 있다.",
  str_item_intro_3220176 = "베르타 돌파 시 필수 아이템.\n빛깔이 아름다운 보석이다. 아직 다듬어지지 않았지만 환한 빛을 발하며, 가끔씩 보석 안에 새가 나는 모습을 볼 수 있다.",
  str_item_intro_3220177 = "골디 돌파 시 필수 아이템.\n아름다운 색과 따뜻한 촉감을 지닌 보석으로, 오랫동안 몸에 지니고 있으면 골디의 행운을 나눠 가질 수 있을 것 같다.",
  str_item_intro_3220178 = "비크 돌파 시 필수 아이템.\n단단한 재질의 보석으로, 망치로 힘껏 두드려도 흠집 하나 나지 않는다.",
  str_item_intro_3220180 = "브랜디 돌파 시 필수 아이템.\n만져보면 단단하지만, 누르면 바로 퉁겨져 나온다. 브랜디가 셔터 빨리 누르는 법을 연습할 때 사용한다고 전해진다.",
  str_item_intro_3220181 = "종서 돌파 시 필수 아이템.\n이 원석을 손으로 만져보면 따뜻한 숨결을 느낄 수 있고, 이는 종서의 뜨거운 마음을 증명한다.",
  str_item_intro_3220182 = "목월백 돌파 시 필수 아이템.\n얇고 만지면 조금 딱딱한 보석이다. 비늘처럼 빛의 각도에 따라 다른 색을 드러낸다.",
  str_item_intro_3220183 = "리청 돌파 시 필수 아이템.\n희미한 풀 냄새가 나며, 약간 쓴 맛이 나는 것이 리청의 약방 안 냄새를 떠올리게 만든다.",
  str_item_intro_3220184 = "예리아 돌파 시 필수 아이템.\n만져보면 모진 비바람을 겪은 듯한 거친 느낌이 나면서도, 투명하고 아름답다.",
  str_item_intro_3220185 = "키아 돌파 시 필수 아이템.\n만질 때 나는 매끈한 감촉을 보면 키아가 자주 쓰다듬는 것 같다. 안을 들여다보니 시계판이 움직이고 있다. 설마 시계였던 걸까?",
  str_item_intro_3220186 = "티나 돌파 시 필수 아이템.\n순백의 성스러운 빛에 감싸여 있는 보석이다. 함부로 만졌다가는 이 빛을 더럽혀 버릴 것만 같다.",
  str_item_intro_3220189 = "레인 돌파 시 필수 아이템.\n만지면 딱딱하고, 어두운 곳에 놓아두면 눈부신 빛을 반사한다. 자세히 냄새를 맡아 보면 은은하게 꽃향기가 느껴진다.",
  str_item_intro_3220190 = "마티외 돌파 시 필수 아이템.\n매우 정교하게 다듬어진 보석, 어떤 기술을 활용해 다듬었는지는 알 수 없지만, 유명하고 값비싸다는 티가 나는 만큼, 그만 만지고 내려놓는 편이 좋겠다.",
  str_item_intro_3220191 = "하티 돌파 시 필수 아이템.\n매우 단단해 보이지만, 만지면 의외로 부드럽고, 강아지의 발바닥 같아서 자꾸 만지고 싶어진다.",
  str_item_intro_3220192 = "레오 돌파 시 필수 아이템.\n이 보석은 광택이 없고, 만지면 매우 거칠다. 레오의 말에 따르면 그것은 변방의 모래바람에 의해 마모된 흔적이라고 한다.",
  str_item_intro_3220193 = "크리스틴 돌파 시 필수 아이템.\n가까이 귀를 기울이면 물소리가 들리는 것 같다. 크리스틴의 마음속에도 이런 암류가 소용돌이치고 있을지 모른다.",
  str_item_intro_3220199 = "잉겔 돌파 시 필수 아이템.\n보석의 맑고 투명한 광택 속에는 새의 노랫소리 같은 선명한 메아리가 전해진다.",
  str_item_intro_3220200 = "아나톨리 돌파 시 필수 아이템.\n아나톨리가 수집한 보석으로, 영원한 밤의 땅 내의 한 광맥에서 생산된 것이 일루미나까지 먼 길을 거쳐 전해진 것이라고 한다. 이 보석은 촉감이 따뜻하고, 그 표면에는 사람의 모습이 비치는 것 같다.",
  str_item_intro_3220201 = "미아 더 러스트러스 소울 돌파 시 필수 아이템.\n그냥 지나치기 쉬운 돌멩이 같지만, 귀를 기울이면 두 목소리가 얽혀서 울리고, 점점 더 눈부셔 보이게 만든다.",
  str_item_intro_3220202 = "솔라드 디 올마이티 클레머 돌파 시 필수 아이템.\n이 보석을 통해 뇌우가 지나간 후의 화창한 날을 볼 수 있는 것 같다. 그리고 그것은 그가 통치하는 백야성의 미래가 될 것이다.",
  str_item_intro_3220203 = "쟈키니 돌파 시 필수 아이템.\n아름다운 보석이다. 햇빛을 받아 형형색색의 빛을 발산하며, 점술서의 모습을 투사한다.",
  str_item_intro_3220204 = "조슈아 돌파 시 필수 아이템.\n따뜻한 빛이 보석 주변을 감싸고 있다. 마치 겨울의 촛불처럼, 어둠 속의 가로등처럼 길을 잃은 이들에게 방향을 안내한다.",
  str_item_intro_3220205 = "블랑 더 푸라 코르디스 돌파 시 필수 아이템.\n블랑은 종종 이 정교한 보석을 가지고 논다. 그녀는 보석의 아래쪽에 붉은 빛이 반사된다고 말하지만, 다른 사람들에게는 전혀 보이지 않는다.",
  str_item_intro_3220206 = "로렐라이 돌파 시 필수 아이템.\n로렐라이는 종종 보석에서 돈 냄새가 난다고 비웃지만, 그래도 그녀는 이 보석을 무척 좋아한다.",
  str_item_intro_3220207 = "세나 돌파 시 필수 아이템.\n동글동글해 보이지만 날렵한 수정이다. 화려한 겉모습 안에는 과거의 상처를 숨기고 있는 것일까.",
  str_item_intro_3220208 = "보프 돌파 시 필수 아이템.\n뜨겁고 눈부신 수정이 낮은 속도로 회전하고 있다...",
  str_item_intro_3220209 = "레이스 더 프라우드 퍼버 솔람버 돌파 시 필수 아이템.\n만지면 따끔한 통증이 느껴진다. 결정 내부에는 적색 번개가 꿈틀거리고 있으며, 자신만의 전장에 나설 날을 기다리고 있다.",
  str_item_intro_3220210 = "조셀린 돌파 시 필수 아이템.\n자세히 보면 따뜻한 빛이 보석의 중심에서 박동하고 있다. 기도가 담긴 신도의 아리아 같기도 하며, 밤의 장막을 가르는 성스러운 빛 같기도 하다.",
  str_item_intro_3220211 = "안토니 돌파 시 필수 아이템.\n이 보석은 오랫동안 지하에 묻혀 있었는데, 안토니가 이를 파내고 먼지를 털어내면서 그 비밀이 드러났다.",
  str_item_intro_3220212 = "자리야 돌파 시 필수 아이템.\n그것은 보석이라기보다는 천연 얼음 결정에 가깝다. 어쩌면 자리야가 직접 만들어 낸 것일지도 모른다.",
  str_item_intro_3220213 = "33호 돌파 시 필수 아이템.\n33호가 폐허 근처에서 발견한 보석이다. 극도로 외로울 때 33호는 이것을 「동료」로 여기고 소통을 시도한다.",
  str_item_intro_3220214 = "레베카 돌파 시 필수 아이템.\n레베카의 부모님이 그녀에게 준 보석이다. 레베카는 이 보석을 꼭 쥘 때마다 결코 식지 않는 가족의 따스함을 느낄 수 있다.",
  str_item_intro_3220215 = "이사 돌파 시 필수 아이템.\n레베카의 독액을 응결시켜 만든 보석이다. 가지고만 있으면 이사는 온몸에 힘이 넘친다.",
  str_item_intro_3220216 = "선극 돌파 시 필수 아이템.\n평범해 보이는 돌이지만, 그 안에는 알 수 없는 힘이 숨겨져 있다. 과연 선극은 이 돌을 어떤 기관에 달아줄까.",
  str_item_intro_3220218 = "샤엘 돌파 시 필수 아이템.\n나이티움 한 개의 무게를 지닌 신비한 보석이다. 잘 들어보면 보석 속에서 나이티움이 달그락거리는 소리가 들리는 것만 같다.",
  str_item_intro_3220219 = "이스타반 더 스칼드 피스 돌파 시 필수 아이템.\n꽤 무게가 있는 찬란한 보석이다. 손에 쥐면 희미한 떨림과 오랜 감정을 느낄 수 있고, 그 깊숙이 묻혀 있던 과거의 사건들이 당장이라도 솟구쳐 나올 것만 같다.",
  str_item_intro_3220220 = "버질 돌파 시 필수 아이템.\n버질이 감정한 보석으로, 예술적 가치가 매우 높다. 그는 이 보석을 마치 자신을 지켜주는 부적처럼 늘 가지고 다닌다.",
  str_item_intro_3220221 = "알골 돌파 시 필수 아이템.\n유래를 알 수 없는 보석이다. 사람의 마음을 빨아들일 것처럼 극도로 심오하며, 마치 신비롭고 헤아릴 수 없는 오로리안의 미래에 대한 계시를 보여주는 듯하다...",
  str_item_intro_3220223 = "진예 돌파 시 필수 아이템.\n아득한 연대의 비늘이 변하여 이루어진 돌이다. 어쩌면 그녀의 일족이 여기에 요원한 생각을 담아 전했을지도 모른다.",
  str_item_intro_3220224 = "나송 돌파 시 필수 아이템.\n신비한 힘이 담겨 있을지도 모르는 돌이다. 나송은 어쩌면 이 돌로 악행을 일삼는 수요령의 머리를 때려줄지도 모른다.",
  str_item_intro_3220225 = "티아라 돌파 시 필수 아이템.\n보호색을 지닌 보석이다. 눈밭에 떨어지면 눈과 합쳐져 다시 찾기 어려우므로 꼭 잘 보관해야 한다.",
  str_item_intro_3220227 = "레이첼 돌파 시 필수 아이템.\n모서리가 매우 날카로운 보석이다. 무심코 집어 들면 손바닥이 베일 수도 있을 것 같다. 하지만 조심해서 만져 보면 보석에서 희미한 온기를 느낄 수 있다.",
  str_item_intro_3220228 = "제타 돌파 시 필수 아이템.\n형형색색의 광채를 뿜어내는 화려한 보석이다. 가까이 다가가면 은은한 사탕 냄새가 풍긴다.",
  str_item_intro_3220229 = "바티아 돌파 시 필수 아이템.\n평범한 돌이지만, 바티아는 곡괭이와 용광로를 통해 얻을 수 있다고 하며, 다른 방법도 가능하다고 한다.",
  str_item_intro_3220230 = "빅토리아 디 엘레지 돌파 시 필수 아이템.\n이 보석을 만지는 순간, 고대의 속삭임을 듣게 되는데, 그 소리는 먼 곳도, 귓가도 아닌 머릿속 깊은 곳에서 고동치는 듯하고, 밖을 향해 발버둥치는 일종의 오랫동안 살아 있는 생물처럼 느껴진다.",
  str_item_intro_3220231 = "빌헬름 돌파 시 필수 아이템.\n기이한 색을 지닌 보석이다. 접촉한 순간 피가 천천히 사방의 벽을 타고 흘러내린다. 그리고 놀라서 손을 거두면 모든 것이 환상일 뿐이라는 것을 깨닫게 된다.",
  str_item_intro_3220232 = "나일즈 더 세이크리드 라이트 돌파 시 필수 아이템.\n이 보석을 쥐는 순간 수천 개의 날카로운 칼날이 하늘에서 떨어져 당신의 살과 피를 찢는 듯한 느낌이 든다. 극심한 고통에 비명을 지르며 몸을 자세히 살펴보지만, 실제로는 전혀 다치지 않는다.",
  str_item_intro_3220233 = "라이자 돌파 시 필수 아이템.\n유적에서 발굴한 보석이다. 이 안에서 모험의 열정을 느낄 수 있을지도 모른다.",
  str_item_intro_3220234 = "클라우디아 돌파 시 필수 아이템.\n유적에서 발굴한 보석이다. 이 안에서 음악의 사랑을 느낄 수 있을지도 모른다.",
  str_item_intro_3220235 = "파트리샤 돌파 시 필수 아이템.\n유적에서 발굴한 보석이다. 이 안에서 고귀한 기품을 느낄 수 있을지도 모른다.",
  str_item_intro_3220237 = "마야 돌파 시 필수 아이템.\n수정처럼 투명한 보석이다. 구름 속의 시원한 바람과 깊은 바다의 부드러움이 느껴진다. 손에 쥐면 은은한 목소리가 들리는 듯하다.\n「두려워하지 말렴. 세계는 네 꿈속에 잠들어 있으니까.」",
  str_item_intro_3220238 = "미트라 돌파 시 필수 아이템.\n언뜻 보기에는 매우 평범해 보이지만, 가장자리를 만져보면 그제서야 보기보다 더 날카롭다는 것을 알게 된다. 그 안에는 고동치는 힘이 담겨 있는데, 그야말로 침묵의 분노와도 같다.",
  str_item_intro_3231101 = "일반 선물. 백야성 세력의 오로리안에게 선물하면 효과가 더 좋다.\n깃털처럼 가볍고 얇은 은박. 매우 정교하며, 백야성 사람들이 좋아한다.",
  str_item_intro_3232101 = "고급 선물. 백야성 세력의 오로리안에게 선물하면 효과가 더 좋다.\n루맘버를 금박으로 포장해 만든 아름다운 장식품. 백야성 상류층의 주요 보석이다.",
  str_item_intro_3233101 = "백야성 세력 오로리안에게 선물하면 효과가 더 좋다.\n매우 귀한 공예품. 루미나를 지닌 보석을 진귀한 하얀 수정에 박아 넣어서 만들었다.",
  str_item_intro_3231102 = "일반 선물. 움브라톤 세력의 오로리안에게 선물하면 효과가 더 좋다.\n각종 유명한 유화의 모사본. 움브라톤에서 인기가 높다.",
  str_item_intro_3232102 = "고급 선물. 움브라톤 세력의 오로리안에게 선물하면 효과가 더 좋다.\n진귀한 술. 움브라톤의 졸부들만 가끔 한 잔씩 마실 수 있다.",
  str_item_intro_3233102 = "움브라톤 세력 오로리안에게 선물하면 효과가 더 좋다.\n독특한 형광 초록색이 아주 매력적인 보석. 움브라톤의 사람들이 아주 좋아한다.",
  str_item_intro_3231103 = "일반 선물. 레디젤 렌치 세력의 오로리안에게 선물하면 효과가 더 좋다.\n구시대로부터 남겨진 기름. 레디젤 렌치 멤버들은 이것으로 장식을 하거나 그들의 콜로서스의 비위를 맞춘다.",
  str_item_intro_3232103 = "고급 선물. 레디젤 렌치 세력의 오로리안에게 선물하면 효과가 더 좋다.\n화약에 불을 붙이는 중요한 물질. 총알이나 폭약 모두에 쓰이며, 레디젤 렌치 내부의 화폐이다.",
  str_item_intro_3233103 = "레디젤 렌치 세력 오로리안에게 선물하면 효과가 더 좋다.\n보기 드문 독한 술. 한 잔만 마셔도 굉장히 흥분되어, 레디젤 렌치 사람들이 즐겨 마신다.",
  str_item_intro_3231104 = "일반 선물. 일루미나 연방 세력의 오로리안에게 선물하면 효과가 더 좋다.\n일루미나 연방의 기초 지식 서적. 자연에 대한 각종 지식이 많이 실려 있는 도감으로, 삽화가 정교하고 내용이 간결명료하다.",
  str_item_intro_3232104 = "고급 선물. 일루미나 연방 세력의 오로리안에게 선물하면 효과가 더 좋다.\n일루미나 연방의 가이드 서적. 각종 과학 지식의 활용 방법과 각종 문제 처리 방법을 친절하게 알려 준다.",
  str_item_intro_3233104 = "일루미나 세력 오로리안에게 선물하면 효과가 더 좋다.\n일루미나 연방의 내부 서적. 일루미나 연방에서 지금까지 발견된 각종 지식이 포함되어 있어, 큰 도움이 된다.",
  str_item_intro_3231105 = "일반 선물. 북방 세력의 오로리안에게 선물하면 효과가 더 좋다.\n물이 눈꽃으로 얼은 모습으로, 북방인은 그 안에 강력한 마법이 숨겨져 있다고 생각해서 즐겨 수집한다.",
  str_item_intro_3232105 = "고급 선물. 북방 세력의 오로리안에게 선물하면 효과가 더 좋다.\n무지개 아래에서 발견한 보석. 북방 사람들은 오랜 행운을 가져온다고 생각하여, 매우 귀하게 여긴다.",
  str_item_intro_3233105 = "북방 세력 오로리안에게 선물하면 효과가 더 좋다.\n북방의 영원히 얼지 않는 거울 호수에서 떠온 물을 얼려서 만들었다. 색채가 화려하며, 북방인이 가장 좋아하는 물건이다.",
  str_item_intro_3231106 = "일반 선물. 진리의 결사 세력의 오로리안에게 선물하면 효과가 더 좋다.\n고대로부터 남겨진 호박화된 갑충. 진리의 결사 사람들은 그것에 신비한 마력이 담겨져 있다고 생각한다.",
  str_item_intro_3232106 = "고급 선물. 진리의 결사 세력의 오로리안에게 선물하면 효과가 더 좋다.\n신비한 「천계의 지식」이 담긴 서적. 진리의 결사 사람들은 그것을 해독하면 아무도 모르는 많은 지식을 발굴할 수 있을 거라고 여기고 있다.",
  str_item_intro_3233106 = "진리의 결사 세력 오로리안에게 선물하면 효과가 더 좋다.\n진리의 결사 사람들은 그것에 오늘날 문명 세계의 인식을 바꿀 수 있을 만큼 궁극적인 비밀이 숨겨져 있다고 생각한다.",
  str_item_intro_3231107 = "일반 선물. 무소속자 오로리안에게 선물하면 효과가 더 좋다.\n탈수 기술로 만든 압축 식량. 가볍고 휴대하기 편해, 작은 부락에서 인기가 높다.",
  str_item_intro_3232107 = "고급 선물. 무소속자 오로리안에게 선물하면 효과가 더 좋다.\n신비한 마법 치료 약제. 작은 정착지에서 의사 역할을 하기에 충분하다.",
  str_item_intro_3233107 = "무소속자 오로리안에게 선물하면 효과가 더 좋다.\n많은 사람들이 귀하게 여기는 보물지도 조각. 모두가 노릴 만한 엄청난 보물이라고 한다.",
  str_item_intro_3232108 = "일반 선물. 용주 세력의 오로리안에게 선물하면 효과가 더 좋다.\n접을 수 있는 부채로, 보통 대나무를 뼈대로 삼고, 종이로 부채의 면을 만든다. 위에는 산천의 아름다운 모습이 그려져 있어 용주 사람들에게 인기가 많다.",
  str_item_intro_3233108 = "고급 선물. 용주 세력의 오로리안에게 선물하면 효과가 더 좋다.\n붉은 밧줄로 만든 장식 매듭으로, 마음과 감정의 연결을 상징한다. 용주 사람들이 높이 사는 선물 중 하나라고 할 수 있다.",
  str_item_intro_3231201 = "일반 선물. 동심을 간직한 오로리안에게 선물하면 효과가 더 좋다.\n동심을 간직한 사람이 좋아하는 캔디. 다섯 가지 맛이 있으며, 가장 큰 매력이라면 휘파람 소리를 낼 수 있다는 것이다.",
  str_item_intro_3232201 = "고급 선물. 동심을 간직한 오로리안에게 선물하면 효과가 더 좋다.\n동심을 간직한 사람이 좋아하는 게임북. 사용자는 언어 묘사를 통해 특수한 어드벤처 게임을 진행할 수 있다.",
  str_item_intro_3233201 = "동심을 가진 오로리안에게 선물하면 효과가 더 좋다.\n동심을 가진 사람이 좋아하는 모형. 거의 완벽한 내부 디테일을 가졌으며, 지금은 절판되었다.",
  str_item_intro_3231202 = "일반 선물. 낭만을 사랑하는 오로리안에게 선물하면 효과가 더 좋다.\n낭만적인 사람의 마음에 쏙 드는 핸드메이드 봉제 인형. 토끼 같기도 하고 곰 같기도 한데, 원작자는 알 수 없다.",
  str_item_intro_3232202 = "고급 선물. 낭만을 사랑하는 오로리안에게 선물하면 효과가 더 좋다.\n비교적 어두컴컴한 곳에서 본 아름다운 노을의 빛을 담은 병. 굉장히 낭만적이다.",
  str_item_intro_3233202 = "낭만을 사랑하는 오로리안에게 선물하면 효과가 더 좋다.\n「순화」라고 불리는 희귀 식물로 만든 아름다운 책갈피. 다이나믹한 무늬와 색채를 지녔다.",
  str_item_intro_3231203 = "일반 선물. 기괴한 취미가 있는 오로리안에게 선물하면 효과가 더 좋다.\n이 곤충은 이상한 모습으로 유명한데, 기이한 것을 좋아하는 사람들이 이 표본을 수집한다.",
  str_item_intro_3232203 = "고급 선물. 기괴한 것을 좋아하는 오로리안에게 선물하면 효과가 더 좋다.\n알 수 없는 생물의 결정화된 뼈. 가시가 잔뜩 나 있으며, 기이한 것을 좋아하는 사람들이 이것을 수집한다.",
  str_item_intro_3233203 = "기괴한 것을 좋아하는 오로리안에게 선물하면 효과가 더 좋다.\n기이한 것을 좋아하는 사람들이 수집하는 썩은 나무토막. 그 단면에서 가끔씩 신비한 속삭임이 들려온다고 한다.",
  str_item_intro_3231204 = "일반 선물. 고귀한 오로리안에게 선물하면 효과가 더 좋다.\n가볍고 정교하며, 아름답게 조각된 실버벨. 고상한 성격을 가진 사람들은 그것이 행운을 가져온다고 생각한다.",
  str_item_intro_3232204 = "고급 선물. 고귀한 오로리안에게 선물하면 효과가 더 좋다.\n빛의 세기에 따라 다채로운 색이 나타나는 희귀 광물. 귀족들이 선물로 많이 쓴다.",
  str_item_intro_3233204 = "고귀한 오로리안에게 선물하면 효과가 더 좋다.\n귀족에게 사랑받는 희귀한 특수 재료. 대부분 추운 곳에서 생산되며, 부드럽고 얇으며, 잘 마모되지 않는다.",
  str_item_intro_3231205 = "일반 선물. 시원시원한 성격의 오로리안에게 선물하면 효과가 더 좋다.\n사막 지역의 유명한 특산물. 시원시원한 성격을 가진 사람들이 그 독특한 맛을 좋아한다.",
  str_item_intro_3232205 = "고급 선물. 솔직한 성격의 오로리안에게 선물하면 효과가 더 좋다.\n대부분의 제작과 수리에 쓸 수 있는 공구 상자. 특히 솔직한 성격을 가진 사람들이 좋아한다.",
  str_item_intro_3233205 = "솔직한 성격의 오로리안에게 선물하면 효과가 더 좋다\n생물과 기계의 기능 수치를 검사할 수 있어서, 직관적인 성격을 가진 사람들이 매우 좋아하는 물건이다.",
  str_item_intro_3239997 = "다양한 맛이 있는 캔디. 오로리안에게 선물 시 호감도가 대폭 증가한다.",
  str_item_intro_3239998 = "오로리안에게 선물 시 호감도가 대폭 증가한다.",
  str_item_intro_3239999 = "맛있는 초콜릿! 오로리안에게 선물 시 호감도가 대폭 증가한다.",
  str_item_intro_3300001 = "굉장히 단단한 물질이지만, 금속은 아니다... 고대로부터 내려온 생물 결합 재료 같다. 콜로서스의 파손된 곳을 수리하거나 에너지원 통로를 연결할 수 있다.",
  str_item_intro_3300002 = "강화된 콜로서스 기재로 보이며, 콜로서스 내부의 방을 더 견고하게 구축할 수 있다.",
  str_item_intro_3300003 = "표면에 해독 불가능한 문자가 희미하게 떠오르곤 하는 이 소재는 단단할 뿐만이 아니라 탄력도 가지고 있다. 콜로서스의 특정 시설을 수복하는데에 필요한 필수소재.",
  str_item_intro_3300004 = "「함교」라고 불리는 콜로서스 코어 업그레이드에 필수적인 플러그. 매우 희귀하니 아껴 쓸 것.",
  str_item_intro_3300005 = "기묘한 구조를 지닌 큐브. 어떤 용감한 탐험가의 유물인 듯하다. 이 위에 새겨진 정보를 콜로서스의 데이터베이스에 기록한다면, 새로운 방을 개방할 수 있을지도 모른다.",
  str_item_intro_3300006 = "이 플러그는 지하에 오랜 시간 매장되어 있었다. 아무래도 17년 전 스카이워커호에서 떨어진 물건 같다. 사용 시 콜로서스의 특정 방을 개방할 수 있다.",
  str_item_intro_3400001 = "파란색의 초급 강화상자. 사용 시 물 속성의 초급 각성 재료를 1개씩 획득할 수 있다.",
  str_item_intro_3400002 = "빨간색의 초급 강화상자. 사용 시 불 속성의 초급 각성 재료를 1개씩 획득할 수 있다.",
  str_item_intro_3400003 = "초록색의 초급 강화상자. 사용 시 숲 속성의 초급 각성 재료를 1개씩 획득할 수 있다.",
  str_item_intro_3400004 = "노란색의 초급 강화상자. 사용 시 번개 속성의 초급 각성 재료를 1개씩 획득할 수 있다.",
  str_item_intro_3400005 = "파란색의 중급 강화상자. 사용 시 물 속성의 중급 각성 재료를 1개씩 획득할 수 있다.",
  str_item_intro_3400006 = "빨간색의 중급 강화상자. 사용 시 불 속성의 중급 각성 재료를 1개씩 획득할 수 있다.",
  str_item_intro_3400007 = "초록색의 중급 강화상자. 사용 시 숲 속성의 중급 각성 재료를 1개씩 획득할 수 있다.",
  str_item_intro_3400008 = "노란색의 중급 강화상자. 사용 시 번개 속성의 중급 각성 재료를 1개씩 획득할 수 있다.",
  str_item_intro_3400009 = "파란색의 고급 강화상자. 사용 시 물 속성의 고급 각성 재료를 1개씩 획득할 수 있다.",
  str_item_intro_3400010 = "빨간색의 고급 강화상자. 사용 시 불 속성의 고급 각성 재료를 1개씩 획득할 수 있다.",
  str_item_intro_3400011 = "초록색의 고급 강화상자. 사용 시 숲 속성의 고급 각성 재료를 1개씩 획득할 수 있다.",
  str_item_intro_3400012 = "노란색의 고급 강화상자. 사용 시 번개 속성의 고급 각성 재료를 1개씩 획득할 수 있다.",
  str_item_intro_3400013 = "파란색의 초급 보급상자. 사용 시 랜덤으로 물 속성의 초급 각성 재료를 1개 획득할 수 있다.",
  str_item_intro_3400014 = "빨간색의 초급 보급상자. 사용 시 랜덤으로 불 속성의 초급 각성 재료를 1개 획득할 수 있다.",
  str_item_intro_3400015 = "초록색의 초급 보급상자. 사용 시 랜덤으로 숲 속성의 초급 각성 재료를 1개 획득할 수 있다.",
  str_item_intro_3400016 = "노란색의 초급 보급상자. 사용 시 랜덤으로 번개 속성의 초급 각성 재료를 1개 획득할 수 있다.",
  str_item_intro_3400017 = "파란색의 중급 보급상자. 사용 시 랜덤으로 물 속성의 중급 각성 재료를 1개 획득할 수 있다.",
  str_item_intro_3400018 = "빨간색의 중급 보급상자. 사용 시 랜덤으로 불 속성의 중급 각성 재료를 1개 획득할 수 있다.",
  str_item_intro_3400019 = "초록색의 중급 보급상자. 사용 시 랜덤으로 숲 속성의 중급 각성 재료를 1개 획득할 수 있다.",
  str_item_intro_3400020 = "노란색의 중급 보급상자. 사용 시 랜덤으로 번개 속성의 중급 각성 재료를 1개 획득할 수 있다.",
  str_item_intro_3400021 = "파란색의 고급 보급상자. 사용 시 랜덤으로 물 속성의 고급 각성 재료를 1개 획득할 수 있다.",
  str_item_intro_3400022 = "빨간색의 고급 보급상자. 사용 시 랜덤으로 불 속성의 고급 각성 재료를 1개 획득할 수 있다.",
  str_item_intro_3400023 = "초록색의 고급 보급상자. 사용 시 랜덤으로 숲 속성의 고급 각성 재료를 1개 획득할 수 있다.",
  str_item_intro_3400024 = "노란색의 고급 보급상자. 사용 시 랜덤으로 번개 속성의 고급 각성 재료를 1개 획득할 수 있다.",
  str_item_intro_3400025 = "종합 성질의 초급 강화상자. 사용 시 모든 초급 각성 재료를 1개씩 획득할 수 있다.",
  str_item_intro_3400026 = "종합 성질의 중급 강화상자. 사용 시 모든 중급 각성 재료를 1개씩 획득할 수 있다.",
  str_item_intro_3400027 = "종합 성질의 고급 강화상자. 사용 시 모든 고급 각성 재료를 1개씩 획득할 수 있다.",
  str_item_intro_3400028 = "응급 성질의 초급 보급상자. 사용 시 랜덤으로 초급 각성 재료를 1개 획득할 수 있다.",
  str_item_intro_3400029 = "응급 성질의 중급 보급상자. 사용 시 랜덤으로 중급 각성 재료를 1개 획득할 수 있다.",
  str_item_intro_3400030 = "응급 성질의 고급 보급상자. 사용 시 랜덤으로 고급 각성 재료를 1개 획득할 수 있다.",
  str_item_intro_3400031 = "흔히 볼 수 있는 옥 원석. 사용 시 랜덤으로 1급 옥(물, 불, 번개, 숲 중 하나) 1개를 획득할 수 있다.",
  str_item_intro_3400032 = "각종 옥과 다양한 색의 공생석이 담겨 있다. 사용 시 1급 옥(물, 불, 번개, 숲)을 1개씩 획득할 수 있다.",
  str_item_intro_3400033 = "흔히 볼 수 있는 옥 원석. 사용 시 랜덤으로 2급 옥(물, 불, 번개, 숲 중 하나) 1개를 획득할 수 있다.",
  str_item_intro_3400034 = "각종 옥과 풍부한 색의 공생석이 담겨 있다. 사용 시 2급 옥(물, 불, 번개, 숲)을 1개씩 획득할 수 있다.",
  str_item_intro_3400035 = "색채가 더욱 찬란해진 옥 원석. 사용 시 랜덤으로 3급 옥(물, 불, 번개, 숲 중 하나) 1개를 획득할 수 있다.",
  str_item_intro_3400036 = "각종 옥과 현란한 색의 공생석이 담겨 있다. 사용 시 3급 옥(물, 불, 번개, 숲)을 1개씩 획득할 수 있다.",
  str_item_intro_3400037 = "누가 보냈는지 알 수 없는 선물 주머니. 선물이 들어 있으니, 안에 뭐가 들어있는지 살펴보자.\n사용 시 랜덤으로 일반 선물 1개를 획득할 수 있다.",
  str_item_intro_3400038 = "돌연히 나타난 알 수 없는 정교한 선물 패키지. 안에 더 좋은 선물이 들어 있겠지?\n사용 시 랜덤으로 고급 선물 1개를 획득할 수 있다.",
  str_item_intro_3400039 = "곱게 포장된 선물 상자. 안에 들어 있는 선물은 틀림없이 귀중할 것일 테니, 얼른 열어 보자.\n사용 시 랜덤으로 가치가 아주 높은 오로리안 선물 1개를 획득할 수 있다.",
  str_item_intro_3400040 = "수정으로 만들고 루미나틱스로 강화한 투명한 상자. 작고 견고하며, 안에는 진귀한 루맘버가 들어 있다.\n사용 시 50루맘버 획득 가능.",
  str_item_intro_3400041 = "백야성에서 발행한 금화를 보관하는 금고. 나이티움이 유통되면서, 이 상자도 어디서나 볼 수 있게 되었다.\n100000 나이티움이 들어 있다.",
  str_item_intro_3400042 = "희미한 빛을 나는 투명 크리스탈 상자. 안에 저장된 루미나로 프리즘을 충전할 수 있으며, 고유의 에너지를 회복시킬 수 있다.\n사용 시 10프리즘 획득 가능.",
  str_item_intro_3400043 = "외관이 반듯한 크리스탈 상자. 중심에서 빛이 나며, 프리즘에 많은 에너지를 제공할 수 있다.\n사용 시 60프리즘 획득 가능.",
  str_item_intro_3400044 = "대형 크리스탈을 다듬어 화려하게 장식한 작은 박스. 안에는 매우 많은 루미나가 들어있어서 프리즘이 더 많은 에너지를 회복할 수 있다.\n사용 시 50프리즘 획득 가능",
  str_item_intro_3400045 = "희미한 빛으로 반짝이는 대형 크리스탈 상자. 안에 저장된 루미나로 프리즘 몇 개를 충전할 수 있으며, 고유의 에너지를 회복시킬 수 있다.\n사용 시 60프리즘 획득 가능.",
  str_item_intro_3400046 = "일전에 오로리안 연합군이 개발했던 보급상자. 사용 시 다음 재료 중에서 랜덤으로 1개 획득: 백야석, 운명의 샴페인, 아침의 이슬, 레디젤 클로티드, 초급 실전 기록, 과거의 잔본, 대륙 생존 견문록, 장골산단.",
  str_item_intro_3400047 = "일전에 오로리안 연합군이 개발했던 보급상자. 사용 시 다음 재료 중에서 랜덤으로 1개 획득: 서광의 돌, 운명의 샴페인 프레스티지, 아침의 서리, 레디젤 에센스, 중급 도전 기록, 과거의 고서, 대륙 생존 가이드, 세수영단.",
  str_item_intro_3400048 = "일전에 오로리안 연합군이 개발했던 보급상자. 사용 시 다음 재료 중에서 랜덤으로 1개 획득: 여명의 돌, 운명의 샴페인 마스터피스, 아침의 눈물, 레디젤 알코올, 고급 도전 기록, 과거의 전적, 대륙 생존 백과사전, 재조금단.",
  str_item_intro_3400049 = "북방에는 우뚝 솟은 등대가 하나 있다. 그것이 빛을 발하는 한, 암귀는 이 북방의 땅에 어떤 위협도 가할 수 없다.",
  str_item_intro_3400050 = "획득 시 어시스턴트-바이스 평상복 개방.\n바이스의 평상복 모습이다.",
  str_item_intro_3400052 = "획득 시 배경-눈 덮인 숲 개방.\n북방의 변두리에 있는 울창한 숲이다. 겨울에는 두꺼운 눈으로 덮여 있다. 그 아름다운 모습은 안에 들어선 사람들이 쉽게 방향을 잃게 만든다.",
  str_item_intro_3400053 = "획득 시 배경-극동의 도장 개방.\n극동 지역에서 사람들이 무예를 연마하는 장소이자, 마음을 다스리는 곳이다.",
  str_item_intro_3400054 = "획득 시 배경-마음 속 하늘 개방.\n이 하늘은 한때 잃어버린 고대의 도시 속 주민들에게 가장 큰 위로가 되어 주곤 했다.",
  str_item_intro_3400055 = "획득 시 배경-소녀들의 무대 개방.\n소녀들이 여름날의 한때에 춤을 추었던 곳이다. 비록 오랜 시간이 지났지만, 여전히 당시의 분위기를 간직하고 있다.",
  str_item_intro_3400056 = "획득 시 배경-벚꽃의 복도 개방.\n극동의 특색이 느껴지는 복도와 정원이다. 벚꽃이 만개하는 계절에는 특별한 풍경이 펼쳐진다.",
  str_item_intro_3400057 = "획득 시 배경-군단장 전용열차 개방.\n일루미나 연방의 네 군단장이 함께 전용열차에 탑승했다면, 뭔가 중요한 일이 발생한 것일지도 모른다...",
  str_item_intro_3400058 = "획득 시 배경-오아시스 개방.\n레디젤 렌치의 주요 거점 중 하나로, 주변 지형이 매우 복잡하다.",
  str_item_intro_3400059 = "획득 시 배경-사천사 개방.\n이 네 명의 기사장은 백야성 귀족의 강력한 힘을 상징한다.",
  str_item_intro_3400060 = "획득 시 배경-여름밤의 콘서트 개방.\n한여름의 밤, 소녀들은 음악을 마음껏 즐겼고, 오늘날까지도 그 웃음과 노랫소리가 들려오는 것만 같다.",
  str_item_intro_3400061 = "획득 시 배경-작염의 송곳니 개방.\n송곳니 모양을 하고 있어서 이름이 지어진 협곡으로, 지형이 매우 복잡해 통행이 어렵다.",
  str_item_intro_3400062 = "획득 시 배경-신비한 저택 개방.\n수수께끼의 내력을 지닌 호화 저택으로, 주인이 누구인지도 알 수 없다. 이곳에선 왠지 여유로운 시간을 즐길 수 있을 것만 같다.",
  str_item_intro_3400063 = "획득 시 배경-서클 시스템 개방.\n고대의 공간에는 과연 어떤 비밀이 있을까?",
  str_item_intro_3400064 = "획득 시 배경-화음 연결 개방.\n신비한 공간, 신비한 힘...",
  str_item_intro_3400065 = "획득 시 배경-연탄 연주 개방.\n기억하고 있나요? 바이스와 함께 스카이워커호를 가동하던 그 순간을...",
  str_item_intro_3400066 = "획득 시 배경-헤븐즈 밸리 콜로서스 개방 가능\n콜로서스가 다시금 헤븐즈 밸리에 나타났다면, 무엇을 암시하는 것일까.",
  str_item_intro_3400067 = "획득 시 배경-바람에 실려온 편지 개방.\n바람이 전해준 소식은 그 아이테르에게 집으로 돌아갈 때가 되었음을 알려주었다.",
  str_item_intro_3400068 = "획득 시 배경-고요한 묘지 개방.\n헤븐즈 밸리의 으슥한 곳에 있는 지역이다. 이곳은 시간의 흐름조차 멈춘 듯하다.",
  str_item_intro_3400069 = "획득 시 배경-단장한 쿠리어 센터 개방 가능\n새롭게 단장한 헤븐즈 밸리의 쿠리어 센터에서 앞으로 펼쳐질 기념일 밤을 기대해 보세요.",
  str_item_intro_3400070 = "획득 시 배경-기념일의 추억 개방.\n그것은 헤븐즈 밸리에서 보낸 첫 번째 기념일의 밤이었다.",
  str_item_intro_3400071 = "획득 시 배경-움브라톤의 밤거리 개방.\n움브라톤에 밤이 찾아오면, 거리는 고요해진다. 하지만 위험은 늘 어둠 속에 숨어 있다.",
  str_item_intro_3400072 = "획득 시 배경-밤과 안개의 그림자 개방.\n움브라톤은 밤과 안개로 뒤덮여 있다. 사람들은 그곳에 빛을 되찾아 줄 수 있을까?",
  str_item_intro_3400073 = "획득 시 배경-안데르센 저택 개방.\n위엄이 넘치는 저택이다. 주인의 부유함과 우아함을 드러낸다.",
  str_item_intro_3400074 = "획득 시 배경-운앵 여관 개방.\n음식도 숙박도 좋고, 온천은 더 좋답니다. 유카타도 제공한다구요~",
  str_item_intro_3400075 = "획득 시 배경-하버 항구 개방.\n맑은 하늘 아래, 기분 좋은 미풍, 이 시기의 하버 시티 항구는 가장 좋은 행선지랍니다~",
  str_item_intro_3400076 = "획득 시 배경-해변의 여름밤 개방.\n이런 순간이 영원히 지속될 수 있다면, 그게 바로 인생 최고의 즐거움이 아닐까.",
  str_item_intro_3400077 = "획득 시 배경-백사장의 경고 개방.\n이걸 내려치면... 곧바로 게임 오버가 되고 말걸~",
  str_item_intro_3400078 = "획득 시 배경-그날의 교회 개방.\n유포리아에 있는 황폐한 건물로, 다른 곳들처럼 비바람 정도나 피할 수 있는 곳이다.",
  str_item_intro_3400079 = "획득 시 배경-신비의 땅 개방.\n이름 없는 비밀스러운 땅, 그곳에는 너무나도 많은 과거와 비밀이 묻혀 있다. 과연 그것들이 다시 세상에 드러나는 때가 올까.",
  str_item_intro_3400080 = "획득 시 배경-희생? 개방.\n밀려오는 암귀들 앞에서 그는 「희생」을 선택했다. 하지만 그것은 그의 계획 중 하나일 뿐이었다...",
  str_item_intro_3400082 = "획득 시 배경-진리의 추구 개방.\n대륙의 모두가 알고 있는 지식과 마주했을 때, 그들은 그것이 거짓이라고 생각했다. 진정한 진실은 여전히 머나먼 저편에서 그들이 찾고 얻기만을 기다리고 있다.",
  str_item_intro_3400083 = "획득 시 배경-콜로서스 무대 개방.\n「스카이워커호」 바의 무대는 설비가 잘 갖추어져 있어 모두의 재능을 보여주기에 충분한 곳이다.",
  str_item_intro_3400084 = "획득 시 배경-고대 폐허 도시 개방.\n무너진 거대한 건물들만 봐도 고대 전쟁의 참혹함이 느껴진다.",
  str_item_intro_3400085 = "획득 시 배경-겨울 아래 개방.\n빛나는 장검과 흩날리는 금발 머리를 봤다면, 그것은 행차에 나선 북방의 여왕이 틀림없다. 추운 겨울이 찾아오면 여왕은 세상을 살피기 위해 길을 나선다.",
  str_item_intro_3400086 = "획득 시 배경-오로라의 하늘 개방.\n북방에서도 하늘을 가득 뒤덮은 오로라를 보기란 쉽지 않다. 형형색색의 오로라는 미래에 알 수 없는 영향을 준다는 이야기가 전해진다...",
  str_item_intro_3400087 = "획득 시 배경-노래의 길 개방.\n사방을 떠도는 콜로서스 속, 그 복도에는 이미 그 소녀의 그림자가 퍼져 있다. 희망을 품은 그 천상의 노래는 이제 곧 온 대륙에 퍼질 것이다.",
  str_item_intro_3400088 = "획득 시 배경-신풍호 갑판 개방.\n오직 이 거대하고 튼튼한 갑판만이 우뚝 솟은 선루를 버틸 수 있다.",
  str_item_intro_3400089 = "획득 시 배경-동방의 부두 개방.\n반대편 대륙에 있는 부두다. 집도 배도 아스트라 대륙과는 판이하다. 같은 점이라면 역시나 소란스럽고 분주하다는 것이다.",
  str_item_intro_3400090 = "획득 시 배경-갈라선 전우 개방.\n대원수와 함께 수많은 적을 물리쳤던 전우들이 이제는 그녀를 향해 칼을 겨눈다. 이것은 운명의 장난일까.",
  str_item_intro_3400091 = "획득 시 배경-레디젤 쿠리어 개방.\n레디젤 사막에 있는 쿠리어 길드 지부다. 아무래도 이미 이곳 생활에 잘 적응한 모양이다.",
  str_item_intro_3400092 = "획득 시 배경-예리아의 사무실 개방.\n평소 업무를 처리할 때도 예리아는 이곳에 자신만의 스타일을 불어넣었다.",
  str_item_intro_3400093 = "획득 시 배경-안식처 개방.\n카페, 레스토랑, 바... 모두 이런 분위기 속에서 휴식과 긴장을 풀고, 사람들이 여가를 즐길 수 있는 장소를 제공한다는 공통점이 있다.",
  str_item_intro_3400094 = "획득 시 배경-눈과 얼음의 결혼식 개방.\n수정처럼 맑은 장식은 두 사람의 모습을 반영하며, 그 티없는 깨끗함과 투명함은 그들의 순수한 감정을 표현한다. 비록 눈과 얼음의 영역에서 펼쳐지는 결혼식이지만, 매서운 추위조차 그 뜨거운 두 마음이 서로 다가가는 것을 결코 막을 수 없다.",
  str_item_intro_3400099 = "획득 시 배경-불길 속 그림자 개방.\n타오르는 악마들이 사방에서 몰려들던 그때, 내밀던 구원의 손길...",
  str_item_intro_3400100 = "획득 시 배경-창고 전경 개방.\n어디에나 있는 창고지만, 알려지지 않은 과거가 있을지도 모른다.",
  str_item_intro_3400101 = "획득 시 배경-업타운의 풍경 개방.\n말끔하고, 우아하며, 「난공불락」이라 칭송받는 시가지. 이곳은 백야성의 중심, 아니 대륙의 중심이라 할 수 있다...",
  str_item_intro_3400102 = "획득 시 배경-자매의 웃음 개방.\n두 자매가 함께 놀던 순간은 수천의 낮과 밤이 지나갔지만, 여전히 눈앞에 있는 듯 생생하다.",
  str_item_intro_3400103 = "획득 시 배경-한밤중의 광장 개방.\n백야성의 중앙 광장은 밤하늘 아래에서도 낮처럼 찬란하게 빛나고 있다.",
  str_item_intro_3400109 = "획득 시 배경-여명 아카데미 개방.\n백야성에는 빛의 신을 섬기는 독실한 신자를 양성하는 곳이 있는데, 이곳의 사람들은 모두 경건한 마음을 가지고 있다.",
  str_item_intro_3400110 = "획득 시 배경-신비한 유적 개방.\n이곳은 북방 지하에 있는 미지의 공간으로, 모종의 인조 장치가 여전히 활동하고 있는 것 같다.",
  str_item_intro_3400111 = "획득 시 배경-고요한 밤하늘 개방.\n함교 위, 별이 빛나는 하늘 아래, 혼자 잠 못 이루는 밤. 컨트롤러의 건반을 치지 않아도 우주에서 전해지는 음악을 들을 수 있다.",
  str_item_intro_3400112 = "획득 시 배경-한적한 오후 개방.\n백야성에는 정교하고 아늑한 소형 정원이 많이 있는데, 귀족들은 이곳에서 애프터눈 티를 즐기곤 한다. 세상의 종말은 마치 이들과 아주 머나먼 이야기처럼 느껴진다.",
  str_item_intro_3400113 = "획득 시 배경-지하 진료소 개방.\n누추해 보이는 진료소지만, 소중한 기억이 담겨 있는 곳이다.",
  str_item_intro_3400114 = "획득 시 배경-어두운 구석 개방.\n어둠 속에서도 그녀는 다시 한번 빛을 품에 안고 싶었다.",
  str_item_intro_3400115 = "획득 시 배경 접대의 방법 개방.\n샤엘의 인정을 받은 사람만이 이 호화롭고 편안한 방에 묵을 수 있다.",
  str_item_intro_3400116 = "획득 시 배경-신대륙 개방.\n신풍호는 신대륙에 성공적으로 도착했다. 그러나 이것이 모험의 끝을 의미하지는 않는다. 더 많은 미지의 세계가 그들을 기다리고 있기 때문이다.",
  str_item_intro_3400117 = "획득 시 배경-그림자는 어디에나 있다 개방.\n저택에 앉아 있는 동안에도 섀도우마스터는 여전히 움브라톤을 관찰하고 있다. 그림자는 항상 당신을 지켜보고 있다.",
  str_item_intro_3400118 = "획득 시 배경-역사의 그림자 개방.\n먼지 쌓인 역사는 언젠가 드러나게 될 날이 올 것이다. 그는 움브라톤을 지배하는 독재자일까, 아니면 움브라톤을 구한 영웅일까.",
  str_item_intro_3400119 = "획득 시 배경-응접실 개방.\n적당한 조명이 있는 방 안에는 모든 물건과 장식이 질서정연하게 배열되어 있다. 이곳은 업무 및 손님 접대를 위한 전용 공간이다.",
  str_item_intro_3400120 = "획득 시 배경-용주의 요소 개방.\n쌍사성 서쪽은 움브라톤이 관리하고 있으나, 사람들의 풍습 측면에서는 여전히 용주의 독특한 매력을 엿볼 수 있다. 거리와 골목에 걸린 등롱부터 용주의 맛있는 간식까지 모두 용주의 선명한 특색을 보여주고 있다. 이곳에 오는 사람들은 용주의 문화와 풍속을 마음껏 즐길 수 있을 것이다.",
  str_item_intro_3400121 = "획득 시 배경-쌍사성 항구 개방.\n용주 대륙에서 출항하는 화물선은 최종적으로 모두 쌍사성 부두에 정박한다. 그들은 이곳에서 화물 매매 및 교환을 진행하고, 다시 용주 대륙으로 돌아간다. 따라서 이 항구들은 용주 대륙과 아스트라 대륙의 해운 산업에 있어 핵심적인 역할을 한다고 말할 수 있을 것이다.",
  str_item_intro_3400122 = "획득 시 배경-제나라의 춘삭절 개방.\n춘삭절은 용주 대륙의 가장 중요한 명절로, 이 시기가 되면 왕실은 귀빈을 대접하고, 백성들은 한자리에 모여 여가를 즐겼다. 제나라 사람들은 축제 기간에 사원 장터를 열고 용녀를 참배하며, 년수를 쫓아내고 새해의 건강과 행운을 기원했다. 일부 상인은 수요령을 고용해서 년수를 쫓아내는 의식을 거행해 축제에 재미를 더하기도 한다.",
  str_item_intro_3400126 = "획득 시 배경-춘삭절 만찬 개방.\n용주에서 춘삭절의 밤은 재회의 시간이다. 용주의 친구들은 아이테르 곁에 모여 그와 함께 맛있고 길한 명절 음식을 나누며, 그가 더 멋진 한 해를 맞이할 수 있기를 기원했다.",
  str_item_intro_3400123 = "획득 시 배경-장원의 풍경 개방.\n아주라이트에 위치한 이 저택은 경치가 아름답고, 독특한 지리적 위치와 심오한 문화적 가치를 지니고 있어 백야성 귀족들이 선호하는 곳이다. 귀족들은 종종 이곳을 산책하며 기분을 풀곤 한다.",
  str_item_intro_3400129 = "획득 시 배경-변방의 동굴 개방.\n눈 덮인 동굴 깊은 곳에는 고드름이 신의 조각품처럼 둥근 천장과 지면을 연결하고 있다. 오로라가 쏟아져 들어올 때면, 동굴 벽에 쌓인 높고 가파른 고드름과 얼음꽃들이 기묘한 형태로 굳어지며, 오직 그 엄숙하고 차가운 분위기를 기다린다.",
  str_item_intro_3400130 = "획득 시 배경-설경의 끝자락 개방.\n눈이 내리는 어두침침한 하늘, 끝없이 펼쳐졌던 설원 황무지도 마침내 끝이 나타난 듯, 높은 봉우리가 성벽처럼 멀리 서서 세계를 갈라놓고 있다. 산기슭에는 얼음과 눈으로 뒤덮인 작은 집 몇 채가 어렴풋이 보인다. 이곳에서 산다는 것은 반드시 외로움으로 가득한 일이 아닐까.",
  str_item_intro_3400133 = "획득 시 배경-지하 화산의 핵 개방.\n지나간 세월 속, 사막을 질주했던 레디젤 렌치 사람들은 이 지하 화산이 여전히 활동하고 있다는 사실을 알지 못했다.",
  str_item_intro_3400134 = "획득 시 배경-사막의 달밤 개방.\n영원히 만날 일이 없을 것 같았던 사람들이 지금은 사막의 별빛 아래 함께 앉아 있다. 그녀들의 눈은 반짝이고, 각자의 추억이 서로 교차했다.",
  str_item_intro_3400135 = "획득 시 배경-어썰트호 개방 가능.\n내부 구조는 스카이워커호에 비해 간결하면서도 매끄럽고, 모든 컨트롤러에서는 위험한 분위기를 풍기고 있다.",
  str_item_intro_3400136 = "획득 시 배경-끝까지 불태워라 개방 가능.\n반역과 복종은 그저 형태가 서로 다른 장작일 뿐, 충분한 온도만 있다면 타오르는 것은 똑같은 불길이다.",
  str_item_intro_3400138 = "획득 시 배경-성명제의 행진 개방 가능.\n그대는 온 진리의 결사가 지닌 지혜의 구현이요. 그대가 겪은 모든 경험이 진리의 결사를 미래로 인도하리라.",
  str_item_intro_3400139 = "획득 시 배경-유적 섬의 해변 개방 가능.\n머나먼 해역에는 세상 사람들로부터 잊힌 외딴섬이 있다. 그 섬의 사방은 한없이 푸른색으로 둘러싸여 있고, 섬 위는 울창한 숲으로 덮여 있다. 고대 유적은 이 원시의 자연 속에 잠든 채, 오랜 세월을 겪어 왔다.",
  str_item_intro_3400140 = "획득 시 배경-물놀이 시간 개방 가능.\n섬의 침묵은 과거의 시간을 깊이 묻고, 새로운 여름의 모험이 그 돛을 펼친다.\n함께하는 동료는 가장 소중한 보물이다.\n유한한 시간 속, 동료들과 함께 끝없는 모험을 즐겨 보자.",
  str_item_intro_3400141 = "획득 시 배경-천 년을 뛰어넘은 그리움 개방 가능.",
  str_item_intro_3400142 = "획득 시 배경-예정된 재회 개방 가능.\n별들이 돌아갈 곳에 도달할 때.\n그는 발을 내딛고, 태양 아래에서 친구들을 향해 나아갈 것이다.",
  str_item_intro_3410101 = "파란색의 초급 주문상자. 사용 시 물 속성의 초급 각성 재료를 1개 선택해 획득할 수 있다.",
  str_item_intro_3410102 = "파란색의 중급 주문상자. 사용 시 물 속성의 중급 각성 재료를 1개 선택해 획득할 수 있다.",
  str_item_intro_3410103 = "파란색의 고급 주문상자. 사용 시 물 속성의 고급 각성 재료를 1개 선택해 획득할 수 있다.",
  str_item_intro_3410104 = "파란색의 특급 주문상자. 사용 시 물 속성의 특급 각성 재료를 1개 선택해 획득할 수 있다.",
