  str_item_intro_3410402 = "노란색의 중급 주문상자. 사용 시 번개 속성의 중급 각성 재료를 1개 선택해 획득할 수 있다.",
  str_item_intro_3410403 = "노란색의 고급 주문상자. 사용 시 번개 속성의 고급 각성 재료를 1개 선택해 획득할 수 있다.",
  str_item_intro_3410404 = "노란색의 특급 주문상자. 사용 시 번개 속성의 특급 각성 재료를 1개 선택해 획득할 수 있다.",
  str_item_intro_3410501 = "오로리안 연합군이 제작한 주문상자. 사용 시 초급 세력 각성 재료를 1개 선택해 획득할 수 있다.",
  str_item_intro_3410502 = "오로리안 연합군이 제작한 주문상자. 사용 시 중급 세력 각성 재료를 1개 선택해 획득할 수 있다.",
  str_item_intro_3410503 = "오로리안 연합군이 제작한 주문상자. 사용 시 고급 세력 각성 재료를 1개 선택해 획득할 수 있다.",
  str_item_intro_3410504 = "오로리안 연합군이 제작한 주문상자. 사용 시 특급 세력 각성 재료를 1개 선택해 획득할 수 있다.",
  str_item_intro_3410601 = "움브라톤 상회가 제작한 주문상자. 사용 시 1급 옥을 1개 선택해 획득할 수 있다.",
  str_item_intro_3410602 = "움브라톤 상회가 제작한 주문상자. 사용 시 2급 옥을 1개 선택해 획득할 수 있다.",
  str_item_intro_3410603 = "움브라톤 상회가 제작한 주문상자. 사용 시 3급 옥을 1개 선택해 획득할 수 있다.",
  str_item_intro_3410604 = "오로리안 연합군이 사용했던 선물. 사용 시 고급 세력 선물을 1개 선택해 획득할 수 있다.",
  str_item_intro_3410605 = "카타스트로피에서 자신만의 공적을 세우고 손에 넣은 보상이다.\n사용 시 랜덤으로 각종 육성 재료를 획득하며, 낮은 확률로 스타 마커를 획득할 수 있다.",
  str_item_intro_3410606 = "이 보물상자는 당신이 [사일런트 예거]의 일원들과 깊은 유대를 이루었다는 증거입니다. 사용 시 풍성한 보상을 획득할 수 있습니다.",
  str_item_intro_3410607 = "특수한 구조체가 들어있는 보물상자. 사용 시 운반자 1개를 획득할 수 있다.",
  str_item_intro_3410608 = "정신없는 축제 이벤트에서 획득한 상자다. 뭐가 들어 있는지는 잘 모르겠지만, 그래도 깜짝 선물은 항상 즐거운 법이다.",
  str_item_intro_3410609 = "특별 주문 패키지, 사용 시 고급 선물을 1개 선택해 획득할 수 있다.",
  str_item_intro_3410610 = "고급 주문 합성 상자. 사용 시 고급 각성 재료를 1개 선택해 획득할 수 있다.",
  str_item_intro_3410611 = "특급 주문 합성 상자. 사용 시 특급 각성 재료를 1개 선택해 획득할 수 있다.",
  str_item_intro_3410612 = "번개의 솔람버 클러스터, 물의 솔람버 클러스터, 숲의 솔람버 클러스터, 불의 솔람버 클러스터 중 하나를 선택할 수 있다.",
  str_item_intro_3410613 = "초급 주문 합성 상자. 사용 시 초급 각성 재료를 1개 선택해 획득할 수 있다.",
  str_item_intro_3410614 = "중급 주문 합성 상자. 사용 시 중급 각성 재료를 1개 선택해 획득할 수 있다.",
  str_item_intro_3410615 = "오로리안 3단계 각성에 필요한 재료를 획득할 수 있습니다. 패키지 내용은 2급 옥·공통*300, 나이티움*750000, 연합군 초급 주문상자*10, 연합군 중급 주문상자*10, 연합군 고급 주문상자*10, 초급 주문 합성 상자*30, 중급 주문 합성 상자*50, 고급 주문 합성 상자*50, 특급 주문 합성 상자*20입니다.",
  str_item_intro_3410616 = "엄격한 순찰, 위험한 추격... 작전은 결코 수확이 없지 않았습니다. 안에 과연 어떤 전리품이 있을지 확인해 보세요!",
  str_item_intro_3420101 = "와타리가 당신을 지원해 앞으로의 모험을 돕겠다고 한다.\n「와타리」 및 각성 1단계 10레벨 달성에 필요한 모든 육성 재료를 획득할 수 있다.",
  str_item_intro_3420102 = "레오나가 당신을 지원해 앞으로의 모험을 돕겠다고 한다.\n「레오나」 및 각성 1단계 10레벨 달성에 필요한 모든 육성 재료를 획득할 수 있다.",
  str_item_intro_3420103 = "미아가 당신을 지원해 앞으로의 모험을 돕겠다고 한다.\n「미아」 및 각성 1단계 10레벨 달성에 필요한 모든 육성 재료를 획득할 수 있다.",
  str_item_intro_3420104 = "아이리나가 당신을 지원해 앞으로의 모험을 돕겠다고 한다.\n「아이리나」 및 각성 1단계 10레벨 달성에 필요한 모든 육성 재료를 획득할 수 있다.",
  str_item_intro_3420105 = "바튼이 당신을 지원해 앞으로의 모험을 돕겠다고 한다.\n「바튼」 및 각성 1단계 25레벨 달성에 필요한 모든 육성 재료를 획득할 수 있다.",
  str_item_intro_3420106 = "마지가 당신을 지원해 앞으로의 모험을 돕겠다고 한다.\n「마지」 및 각성 1단계 25레벨 달성에 필요한 모든 육성 재료를 획득할 수 있다.",
  str_item_intro_3420107 = "네메시스가 당신을 지원해 앞으로의 모험을 돕겠다고 한다.\n「네메시스」 및 각성 1단계 25레벨 달성에 필요한 모든 육성 재료를 획득할 수 있다.",
  str_item_intro_3420108 = "스칼렛이 당신을 지원해 앞으로의 모험을 돕겠다고 한다.\n「스칼렛」 및 각성 1단계 25레벨 달성에 필요한 모든 육성 재료를 획득할 수 있다.",
  str_item_intro_3420109 = "휴라드가 당신을 지원해 앞으로의 모험을 돕겠다고 한다.\n「휴라드」 및 각성 2단계 1레벨 달성에 필요한 모든 육성 재료를 획득할 수 있다.",
  str_item_intro_3420110 = "이스타반이 당신을 지원해 앞으로의 모험을 돕겠다고 한다.\n「이스타반」 및 각성 2단계 1레벨 달성에 필요한 모든 육성 재료를 획득할 수 있다.",
  str_item_intro_3420111 = "비비안이 당신을 지원해 앞으로의 모험을 돕겠다고 한다.\n「비비안」 및 각성 2단계 1레벨 달성에 필요한 모든 육성 재료를 획득할 수 있다.",
  str_item_intro_3420112 = "루이스가 당신을 지원해 앞으로의 모험을 돕겠다고 한다.\n「루이스」 및 각성 2단계 1레벨 달성에 필요한 모든 육성 재료를 획득할 수 있다.",
  str_item_intro_3420113 = "지정 6성 오로리안 명단 중 1명을 선택해 함께 싸울 수 있습니다. 선택 범위: <color=#ffffff>히이로/사메야마/이브/우리엘/카렌/시로나/샤리/라파엘/코놀리/카론/엘시/빅토리아/요나/나시리스/가브리엘/미자드/미카엘/그로누/이리돈/레이스</color>\n※주의: 새해 특선 소집상자는 사용 기한이 존재하며, 기간 만료 시 자동으로 3000루맘버로 전환되어 우편으로 지급됩니다. 사용 기간: 2022년 2월 28일 18:00",
  str_item_intro_3420114 = "사용 시 특정 5성 오로리안 중 1명을 선택해 함께 모험을 진행할 수 있습니다.\n(<color=#ffffff>네메시스, 바튼, 마지, 스칼렛</color>)",
  str_item_intro_3420115 = "사용 시 <color=#ffffff>루코아</color>, <color=#ffffff>엘마</color> 중 1명을 선택해 함께 모험을 진행할 수 있습니다.",
  str_item_intro_3420116 = "사용 시 특정 5성 오로리안 중 1명을 선택해 함께 모험을 진행할 수 있습니다.\n(<color=#ffffff>파우스트, 클레이튼, 펙트, 베벌리</color>)",
  str_item_intro_3420134 = "사용 시 특정 6성 오로리안 중 1명을 선택해 함께 모험을 진행할 수 있습니다.\n(<color=#ffffff>사메야마, 이브, 플뢰르, 요나</color>)",
  str_item_3420134 = "레디젤 정예 선택상자",
  str_item_intro_3420117 = "지정 5성 오로리안 명단 중 1명을 선택해 함께 싸울 수 있습니다. 선택 범위: <color=#ffffff>카야노/에리카/디나/비비안/미아/네메시스/레지나/로빈/파우스트/클레이튼/바튼/키팅/루이스/노아/휴라드/솔라드/마지/이스타반/바바라/레오나/펙트/오디/필리시/와타리/베니&쿠로/쿠스쿠타/아이리나/스칼렛/베벌리/타키/제네비브/나로세르/커디</color>.",
  str_item_intro_3420118 = "지정 6성 오로리안 명단 중 1명을 선택해 함께 싸울 수 있습니다. 선택 범위: <color=#ffffff>히이로/사메야마/이브/우리엘/카렌/시로나/샤리/라파엘/코놀리/카론/엘시/빅토리아/요나/나시리스/가브리엘/미자드/미카엘/그로누/이리돈/레이스/베릴/플뢰르/스모키/레비/그람/파로마/베델/루크/헤이디/노비오</color>\n※주의: 1주년 특선 소집상자는 사용 기한이 존재하며, 기간 만료 시 자동으로 3000루맘버로 전환되어 우편으로 지급됩니다. 사용 기간: 2022년 8월 31일 18:00",
  str_item_intro_3420119 = "사용 시 특정 5성 오로리안 중 1명을 선택해 함께 모험을 진행할 수 있습니다.\n(<color=#ffffff>휴라드, 이스타반, 루이스, 비비안</color>)",
  str_item_intro_3420120 = "사용 시 특정 5성 오로리안 중 1명을 선택해 함께 모험을 진행할 수 있습니다.\n(<color=#ffffff>아이리나, 필리시, 솔라드, 나로세르</color>)",
  str_item_intro_3420121 = "사용 시 특정 5성 오로리안 중 1명을 선택해 함께 모험을 진행할 수 있습니다.\n(<color=#ffffff>폭스, 바이올렛</color>)",
  str_item_intro_3420122 = "사용 시 특정 5성 오로리안 중 1명을 선택해 함께 모험을 진행할 수 있습니다.\n(<color=#ffffff>와타리, 베니&쿠로, 오디, 솔라드</color>)",
  str_item_intro_3420123 = "지정 5성 오로리안 명단 중 1명을 선택해 함께 싸울 수 있습니다. 선택 범위: <color=#ffffff>사나에/로이/카야노/에리카/디나/비비안/미아/네메시스/레지나/로빈/파우스트/클레이튼/바튼/키팅/루이스/노아/휴라드/솔라드/마지/이스타반/바바라/레오나/펙트/오디/필리시/와타리/베니&쿠로/쿠스쿠타/아이리나/스칼렛/베벌리/타키/제네비브/나로세르</color>.",
  str_item_intro_3420124 = "사용 시 특정 5성 오로리안 중 1명을 선택해 함께 모험을 진행할 수 있습니다.\n(<color=#ffffff>노아, 바바라, 오디, 키팅</color>)",
  str_item_intro_3420125 = "지정 5성 오로리안 명단 중 1명을 선택해 함께 싸울 수 있습니다. 선택 범위: <color=#ffffff>카스타/시엘/사나에/로이/카야노/에리카/커디/나로세르/제네비브/타키/디나/비비안/미아/네메시스/레지나/로빈/파우스트/클레이튼/바튼/키팅/루이스/노아/휴라드/솔라드/마지/이스타반/바바라/레오나/펙트/오디/필리시/와타리/베니&쿠로/쿠스쿠타/아이리나/스칼렛/베벌리/</color>.",
  str_item_intro_3420126 = "한때 함께 모험했던 동료들이 보낸 축복입니다. 사용 시 지정 5성 오로리안 명단 중 1명을 선택해 함께 싸울 수 있습니다. 선택 범위: <color=#ffffff>휴라드/이스타반/루이스/로이</color>",
  str_item_intro_3420127 = "지정 6성 오로리안 명단 중 1명을 선택해 함께 싸울 수 있습니다. 선택 범위: <color=#ffffff>빅토리아/라파엘/코놀리/우리엘/그로누/카론/카렌/사메야마/시로나/가브리엘/나시리스/이브/요나/미카엘/레이스/이리돈/샤리/엘시/미자드/히이로/베릴/플뢰르/스모키/레비/그람/파로마/베델/루크/헤이디/노비오/시오반/플로리나/루비/린네/아메모리/요우/아주르/레노어/길스/바튼 더 데프트 블레이드</color>\n※주의: 1.5주년 특선 소집상자는 사용 기한이 존재하며, 기간 만료 시 자동으로 3000루맘버로 전환되어 우편으로 지급됩니다. 사용 기간: 2023년 3월 31일 18:00",
  str_item_intro_3420128 = "사용 시 특정 5성 오로리안 중 1명을 선택해 함께 모험을 진행할 수 있습니다.\n(<color=#ffffff>휴라드, 이스타반, 루이스, 로이</color>)",
  str_item_intro_3420129 = "지정 5성 오로리안 명단 중 1명을 선택해 함께 싸울 수 있습니다. 선택 범위: <color=#ffffff>베르타/카스타/시엘/사나에/로이/카야노/에리카/커디/나로세르/제네비브/타키/디나/비비안/미아/네메시스/레지나/로빈/파우스트/클레이튼/바튼/키팅/루이스/노아/휴라드/솔라드/마지/이스타반/바바라/레오나/펙트/오디/필리시/와타리/베니&쿠로/쿠스쿠타/아이리나/스칼렛/베벌리</color>.",
  str_item_intro_3420132 = "지정 5성 오로리안 명단 중 1명을 선택해 함께 싸울 수 있습니다. 선택 범위: <color=#ffffff>조셀린/블랑 더 푸라 코르디스/크리스틴/키아/베르타/카스타/시엘/사나에/로이/카야노/에리카/커디/나로세르/제네비브/타키/디나/비비안/미아/네메시스/레지나/로빈/파우스트/클레이튼/바튼/키팅/루이스/노아/휴라드/솔라드/마지/이스타반/바바라/레오나/펙트/오디/필리시/와타리/베니&쿠로/쿠스쿠타/아이리나/스칼렛/베벌리</color>.",
  str_item_intro_3420135 = "지정 5성 오로리안 명단 중 1명을 선택해 함께 싸울 수 있습니다. 선택 범위: <color=#ffffff>이천간/이사/조셀린/블랑 더 푸라 코르디스/크리스틴/키아/베르타/카스타/시엘/사나에/로이/카야노/에리카/커디/나로세르/제네비브/타키/디나/비비안/미아/네메시스/레지나/로빈/파우스트/클레이튼/바튼/키팅/루이스/노아/휴라드/솔라드/마지/이스타반/바바라/레오나/펙트/오디/필리시/와타리/베니&쿠로/쿠스쿠타/아이리나/스칼렛/베벌리</color>.",
  str_item_intro_3420130 = "지정 6성 오로리안 명단 중 1명을 선택해 함께 싸울 수 있습니다. 선택 범위: <color=#ffffff>빅토리아/라파엘/코놀리/우리엘/그로누/카론/카렌/사메야마/시로나/가브리엘/나시리스/이브/요나/미카엘/레이스/이리돈/샤리/엘시/미자드/히이로/베릴/플뢰르/스모키/레비/그람/파로마/베델/루크/헤이디/노비오/시오반/플로리나/루비/린네/아메모리/요우/아주르/레노어/길스/바튼 더 데프트 블레이드/니나/카렌 더 스몰더링 소울/피아/제노/폴룩스/리리카/미노스/악셀리아/비크</color>\n※주의: 2주년 특선 소집상자는 사용 기한이 존재하며, 기간 만료 시 자동으로 3000루맘버로 전환되어 우편으로 지급됩니다. 사용 기간: 2023년 8월 31일 18:00",
  str_item_intro_3430101 = "사용 시 「와타리」, 「레오나」, 「미아」, 「아이리나」 중 임의의 1명을 선택해 해당 오로리안 및 각성 1단계 10레벨 달성에 필요한 모든 육성 재료를 획득할 수 있다.",
  str_item_intro_3430102 = "사용 시 「바튼」, 「마지」, 「네메시스」, 「스칼렛」 중 임의의 1명을 선택해 해당 오로리안 및 각성 1단계 25레벨 달성에 필요한 모든 육성 재료를 획득할 수 있다.",
  str_item_intro_3430103 = "사용 시 「휴라드」, 「이스타반」, 「비비안」, 「루이스」 중 임의의 1명을 선택해 해당 오로리안 및 각성 2단계 1레벨 달성에 필요한 모든 육성 재료를 획득할 수 있다.",
  str_item_intro_3440001 = "사용 시 다크 초콜릿, 루맘버 및 랜덤 오로리안 육성 재료를 획득할 수 있다.",
  str_item_intro_3440002 = "사용 시 트릭 캔디, 루맘버 및 랜덤 오로리안 육성 재료를 획득할 수 있다.",
  str_item_intro_3440003 = "「신풍호」에서 「춘삭절」을 보낼 때 목월백 선장이 모두에게 나눠 준 금일봉이다. 과연 안에 어떤 깜짝 선물이 들어 있을까?",
  str_item_intro_3440005 = "사용 시 루맘버 및 랜덤 오로리안 육성 재료를 획득할 수 있다.",
  str_item_intro_3500001 = "고대 유적에서 발견된 신비한 물질. 기묘한 힘을 지니고 있으며, 장비 개조에 반드시 필요한 재료다.",
  str_item_intro_3500003 = "사용 시 오로리안이 각성 2단계 1레벨로 성장한다.\n신비한 고대의 유물. 태양과도 같은 찬란한 빛이 담겨 있는 물질이며, 오로리안의 능력을 대폭 향상시켜 준다.",
  str_item_intro_3511001 = "물 속성 계몽 레벨을 높이는 데 사용할 수 있다.\n계몽자가 제공하는 신비로운 정육면체다. 석판에 한 몸처럼 장착해 활성화할 수 있으며, 계몽 훈련 중 찰나의 부분을 보여준다.",
  str_item_intro_3511002 = "물 속성 계몽 레벨을 높이는 데 사용할 수 있다.\n계몽자가 제공하는 신비로운 정육면체다. 석판에 한 몸처럼 장착해 활성화할 수 있으며, 계몽 훈련 중 짧은 부분을 보여준다.",
  str_item_intro_3511003 = "물 속성 계몽 레벨을 높이는 데 사용할 수 있다.\n계몽자가 제공하는 신비로운 정육면체다. 석판에 한 몸처럼 장착해 활성화할 수 있으며, 계몽 훈련 중 일부분을 보여준다.",
