  str_item_intro_3514005 = "번개 속성 계몽 레벨을 높이는 데 사용할 수 있다.\n계몽자가 제공하는 신비로운 정육면체다. 석판에 한 몸처럼 장착해 활성화할 수 있으며, 계몽 훈련 중 핵심 부분을 보여준다.",
  str_item_intro_3621001 = "방석이 있는 높은 등받이 의자. 등을 기댈 수 있다. 머리를 기대고 잠깐 눈을 붙일 수도 있을 것 같다.",
  str_item_intro_3621002 = "혼자서 앉기에 적당한 소파. 등받이가 없어서 기댈 순 없다. 앞에 낮은 테이블을 놓아야 할 것 같은 기분이 든다...",
  str_item_intro_3621003 = "두 사람이 같이 앉을 수 있는 넓은 소파. 물론 혼자 누워도 상관없다...",
  str_item_intro_3621004 = "보기 드문 긴 소파. 4명이 함께 앉을 수 있다. 함께 모였을 때 사용하기 좋다.",
  str_item_intro_3621005 = "육각형의 낮은 테이블. 보통 음료수 병, 찻주전자, 물컵, 간식 접시를 올려놓는 데 사용한다. 작은 파티가 열리는 방에 두는 것이 가장 적합하다.",
  str_item_intro_3621006 = "길고 낮은 테이블. 2인용 소파, 4인용 소파와 잘 어울린다. 큰 파티가 열리는 방에 두는 것이 가장 적합하다.",
  str_item_intro_3621007 = "음료수를 자동으로 만들 수 있는 기계. 넣는 재료에 따라 만들어지는 음료수가 결정된다. 예를 들어 커피 가루를 넣으면 블랙 커피, 각설탕을 넣으면 평범한 설탕물이 나온다...",
  str_item_intro_3621008 = "어떤 마을에서 사용하던 북 종류의 악기가 발전된 것이라고 하며, 움브라톤에서 먼저 유행하기 시작했다. 일반적으로 1개의 큰 북과 몇 개의 중간 북 및 심벌즈로 구성되어 있다. 연주에 따라 다른 타악기를 추가하는 경우도 있지만 구성된 악기의 수와 상관없이 한 사람이 연주한다.",
  str_item_intro_3621009 = "작은 화분에 심어져 있는 키가 작은 식물. 방 안에 약간의 푸릇함을 가져다주며, 공기도 정화한다.",
  str_item_intro_3621010 = "사람 키만 한 큰 분재. 공기를 정화할 뿐만 아니라 방 안에 자연의 기운을 더욱 가져다 준다. 필요할 땐 숨을 수도 있다...",
  str_item_intro_3622001 = "정교하고 세밀한 풍경화. 벽에 걸어두면 문밖으로 나가지 않고서도 여러 곳의 아름다운 풍경을 감상할 수 있다.",
  str_item_intro_3623001 = "바닥 부분을 천장에 붙일 수 있는 램프. 태양과 닮은 데다가 조명 범위가 넓어서 사각지대가 거의 없다. 그래서 많은 사람이 「태양등」이라고 부른다.",
  str_item_intro_3623002 = "철로 만든 샹들리에. 실내 천장에 설치하는 조명으로 가볍고, 설치하기가 편리하다. 또한 각종 장식을 덧붙일 수 있어 널리 쓰인다.",
  str_item_intro_3623003 = "방에서 시원한 바람을 쐬게 해 주는 장치. 초기에는 일루미나 연방에서 지하성의 환기를 위해 사용했던 설비라고 한다. 이후 사람들이 방을 시원하게 해준다는 새로운 효능을 발견하게 되었다.",
  str_item_intro_3623004 = "천장에 설치하는 막대형 형광등. 에너지 소비가 적고 조명 범위가 넓으며, 공간을 많이 차지하지 않아 여러 도시에서 사용하고 있다.",
  str_item_intro_3623005 = "천장에 드리워진 조명등. 체인을 엮은 구조로 조절하기가 매우 편리하다. 하지만 지진이나 강풍이 불면 샹들리에가 흔들려서 매우 위험하다. 이 때문에 배에서는 이 샹들리에의 사용이 금지됐다.",
  str_item_intro_3631001 = "수입품. 대양을 정복한 함대가 극동 지역에서 가지고 온 호화로운 장식품이다. 부드러운 질감과 우아한 배색을 가지고 있지만 쉽게 깨질 수 있으니 조심히 진열해야 한다.",
  str_item_intro_3631002 = "태양 모양의 조각상. 장엄하고 엄숙한 분위기여서 방구석에 가만히 세워두기만 해도 강력한 신앙의 힘을 느낄 수 있다.",
  str_item_intro_3631003 = "유명한 장인이 만든 큰 통으로 외관이 화려하다. 그 안에 반드시 오래된 좋은 술을 담아야 화려한 장식과 어울린다.",
  str_item_intro_3631004 = "극동 지역에서 유래되었다고 한다. 바람을 막고, 차단하며, 은폐하는 용도로 사용하며, 그와 동시에 방을 장식하고 아름답게 꾸며주는 효과도 있다. 주인에 대한 신비로운 느낌을 주기 때문에 아스트라 대륙의 많은 도시에서 빠르게 유행하고 있다고 한다.",
  str_item_intro_3631005 = "금으로 도금된 거대한 점치는 도구. 위에는 다양한 보석이 박혀있는데 별의 위치를 대표한다. 점성술에 익숙한 학자라면 빠르게 점을 칠 수 있지만 그 정확도는...",
  str_item_intro_3632001 = "일루미나 연방의 제품으로 원래는 지하성 간의 통신을 위해 사용되었다. 교류가 점차 많아지면서 다른 도시들도 이러한 발전된 의사소통 장치를 사용하게 되었다.",
  str_item_intro_3632002 = "보통 백야성에서 축제가 열릴 때 진열하는 화려하게 장식된 금도금 잔이다. 제작자가 특수한 루미나틱스를 추가하여 날개 한 쌍이 움직이는 환영을 만들어낼 수 있다.",
  str_item_intro_3632003 = "양각이 새겨진 이 보드는 백야성이 오래된 문명을 가지고 있음을 의미하며, 그림마다 옛 이야기가 얽혀 있다고 할 수 있다. 볼 때마다 오래된 역사를 생각하게 만든다...",
  str_item_intro_3632004 = "특수한 루미나틱스로 강화된 촛대로 연기에 절대 그슬리지 않으며, 그 위에 있는 초는 자동으로 켜지고 꺼진다.",
  str_item_intro_3632005 = "일루미나 연방의 기계 기술 및 백야성 장인의 정교한 구상이 합쳐져 화려한 벽시계를 만들어냈다. 이 벽시계의 시간 표시 기능은 부차적인 기능일 뿐이며, 주로 장식용으로 사용된다.",
  str_item_intro_3641101 = "백야성 귀족의 전통적인 장식품. 특히 무예를 숭상하는 가문에서는 전신 갑옷이 장식되어 있다. 이는 단순한 장식품이 아닌 일종의 상징으로, 가문의 후대에 무예의 정신을 포기하고 세상 물정 모르는 도련님이 되지 말라는 뜻이 담겨있다.",
  str_item_intro_3641201 = "움브라톤의 고상한 사람들이 좋아하는 장식품. 귀한 목재를 사용했으며, 그 위에는 고전 서적, 유명하고 귀한 그릇 등이 올려져 있다. 하지만 이 골동품의 진위가 의심되는데...",
  str_item_intro_3641301 = "일루미나 연방의 제품으로 소총을 놓아두는 받침대이다. 방안에 두면 전장에 있는 것 같다. 암귀에 대항하는 주요 세력답게 가구에도 전쟁의 기운이 가득하다. 기존의 2개 모델과 비교하면 3식 소총 받침대는 무게 중심의 균형을 더 잘 잡았고, 전체적인 무게가 상당히 가벼워졌다.",
  str_item_intro_3641501 = "축소된 자동차 모델. 파이프, 리벳 및 각종 용접한 금속판, 심지어 목재도 넣어서 잘 조립되어 있다. 원형은 레디젤 렌치에서 만든 왜건인 「프레셔」다.",
  str_item_intro_3641102 = "값비싼 옷감, 정교한 방직 공예. 이것은 백야성의 장인이 만든 카펫으로 평범한 사람이 구매할 수 있는 것은 아니다... 금전적인 가치는 물론 신분의 상징이기도 하다.",
  str_item_intro_3641202 = "움브라톤에서 생산된 큰 검은색 카펫. 촘촘하게 짜여있어 부드럽고 도톰하며, 밟았을 때 거의 소리가 나지 않는다.",
  str_item_intro_3641302 = "네모반듯한 카펫. 가로와 세로 선 모두 매우 가지런한 것이 일루미나 연방의 공업 스타일이 강하게 느껴진다. 한눈에 봐도 자난성 공장에서 만든 제품임을 알 수 있으며, 오래 쓸 수 있다.",
  str_item_intro_3641402 = "이 카펫은 매우 무겁다. 북방에서 생산된 면으로 짰으며, 또 대량의 동물 털이 들어가 있어서 가장 추운 날씨에도 땅에서 올라오는 한기를 막을 수 있다.",
  str_item_intro_3641502 = "레디젤 렌치의 거친 녀석들이 헌 옷을 내키는 대로 꿰매서 만든 것인 것 같다... 약간 레디젤의 냄새도 나는 것이 그걸 이용해서 염색을 한 것 같다. 이 물건을 사서 집에 장식할 사람이 과연 있을까?",
  str_item_intro_3641602 = "엄청나게 눈에 띄는 붉은색 카펫이다. 도안은 거의 무시한 듯하다. 자세히 보면 카펫의 짜임에 미세한 진동이 있는데 보고 있으면 왠지 당황스럽다. 이런 카펫을 좋아하는 사람이 과연 있을까...?",
  str_item_intro_3642102 = "가구, 콜로서스의 방에 배치할 수 있다.\n백야성의 한 무명 화가의 걸작으로, 진품은 어느 대귀족이 가지고 있고, 이것은 모사본이다. 그림에 드러난 뛰어난 실력은 보는 이들의 마음은 편안하게 만들며, 따라서 수많은 모작이 존재하게 되었고, 이 그림 역시 그중의 하나다. 그러나 모작임에도 불구하고 상당한 가격을 자랑하며, 이를 구매하길 원하는 사람도 많다.",
  str_item_intro_3642201 = "움브라톤의 각종 지하 세력들 사이에는 각종 암투가 벌어진다.분쟁이 해결되지 않을 때 이 세검을 이용한다. 분쟁 중인 양측에서 한 명씩 검사를 보내고, 검사는 이 세검으로 대결하여 최종 판결을 내린다.",
  str_item_intro_3642301 = "일루미나 연방의 장식품은 모두 밀리터리 스타일 느낌이 가득하다. 이들이 당시 벽에 뭔가 걸어야겠다고 생각했을 때 처음으로 생각한 것이 바로 이 소총이었다고 한다. 일루미나 연방의 멤버들은 정말로 언제든지 싸울 준비가 되어 있다.",
  str_item_intro_3642401 = "가구, 콜로서스의 방에 배치할 수 있다.\n얼음과 눈이 내리는 북방에서도 이 식물은 일 년 내내 푸르름을 간직하고 있다. 따라서 북방 주민들은 이것이 희망과 풍요를 상징한다고 믿으며, 「겨우살이가 없으면 행복도 없다」고 말하는 사람도 많다고 한다. 북방의 주민들은 종종 겨우살이를 모아 고리로 엮어서 집에 걸어 놓고, 행운이 찾아오길 빈다.",
  str_item_intro_3641103 = "가구, 콜로서스의 방에 배치할 수 있다.\n백야성의 귀족이 지니고 있는 권력을 상징한다. 장식이 화려하고, 전체가 귀금속으로 이루어져 있다. 이는 권력의 유혹을 보여줄 뿐만 아니라 권력의 무게를 상징하기도 한다.",
  str_item_intro_3641503 = "낡은 철근, 철판과 리벳을 이어 만든 것이다. 위에는 어디서 주워 온 건지 알 수 없는 쿠션이 있다. 비록 좀 낡긴 했지만, 앉으면 그런대로 편안하고, 의외로 튼튼하다.",
  str_item_intro_3651001 = "오벨리스크의 축소 모형. 생동감이 넘치고, 모형 또한 복원이 매우 잘 되어서 마치 오벨리스크 내부에 봉인된 힘도 같이 가지고 온 것만 같다.",
  str_item_intro_3651002 = "오벨리스크를 축소해 놓은 것처럼 정말 진짜 같다. 가까이 가면 오벨리스크의 신비로운 힘도 느껴진다.",
  str_item_intro_3651003 = "오벨리스크의 높은 층을 탐색한 자만 획득할 수 있는 장식품. 외형만 닮은 것이 아니라 오벨리스크의 힘이 일부 봉인되어 있다. 사람들은 이것을 보면 마치 진짜 오벨리스크에 서있는 것 같이 느낀다.",
  str_item_intro_3651004 = "오벨리스크를 탐색한 사람만 획득할 수 있는 매우 희귀한 기념품이다. 모형이지만 오벨리스크와 똑같은 모습을 하고 있으며, 자세히 들여다보면 오벨리스크 구조의 자세한 부분을 그대로 복원했음을 알 수 있다. 이 물건으로 진짜 오벨리스크에도 영향을 줄 수 있는데...",
  str_item_intro_3651005 = "오벨리스크에서 「선물」로 주는 기념품이라고 한다. 오벨리스크에 대한 이해가 해박한 사람만 손에 넣을 수 있다. 이는 일부 오벨리스크의 의지와 탐험가에 대한 인정을 상징한다.",
  str_item_intro_3651101 = "비경에서 발견된 축소된 암귀 모형. 분명 다른 탐색자가 남긴 기념품일 것이다. 움직이지 않으며, 암귀의 무서운 분위기도 없다 보니 딱히 공포감이 생기진 않는다. 이 존재에 익숙해지면 조금 귀엽다고 느껴질지도...",
  str_item_intro_3651102 = "비경 깊은 곳에서 발견한 모형. 어떤 고위 암귀의 조각상인 것 같다. 모습이 흉악해 가만히 보고만 있어도 공포가 느껴진다. 하지만 이것에 익숙해지면 오히려 방에 몰래 들어오는 도둑들을 놀래켜줄 수 있는데...",
  str_item_intro_3651201 = "매우 희귀한 축소 모형. 보기엔 「스카이워커호」와 똑같아 보인다. 조종사의 동료들이 자신의 루미나틱스를 모아, 「스카이워커호」의 신비로운 기술을 통해서 만들었다. 동료들과 조종사 그리고 「스카이워커호」의 견고한 인연을 의미한다.",
  str_item_intro_3662001 = "암귀의 추격을 벗어난 후 모두와의 첫 만남을 기념하기 위하여 스카이워커호는 특별히 파이어플라이에게 자신이 기록한 영상을 그림으로 그리게 했다. 당시의 모습이 생생하게 그려져 있어 모든 사람이 사진이라고 생각했다.",
  str_item_intro_3661101 = "크림슨 밸리에서 찾은 암석. 지금도 화산과 같은 힘을 가지고 있어 만지면 매우 뜨겁다. 가끔은 희미하게 「쾅」하는 소리나, 「분출」하기도 한다. 하지만 모두 무해한 것으로 간이 큰 사람은 이걸로 밥을 만들거나 고기를 구울지도 모른다.",
  str_item_intro_3661102 = "도엔이 크림슨 밸리에 심은 하얀 꽃. 몇 년에 한 번씩 피어난다. 매우 아름다운 꽃으로, 「새벽을 깨는 희망」이라는 꽃말을 가지고 있다.",
  str_item_intro_3662101 = "이브는 병 때문에 한동안 15도 정도의 찬물이나 45도 정도의 뜨거운 물만 마실 수 있었다. 레디젤 사막은 물이 부족하기 때문에 사메야마는 동생이 언제라도 물을 마실 수 있게 항상 보온병 2개를 들고 다녔다. 여동생을 즐겁게 하려고 병에는 웃는 모습을 그려놨다.",
  str_item_intro_3661103 = "무도관은 사라졌지만 이 에이카쿠 무도관의 칼걸이는 여전히 잘 보존되어 있다. 먼지를 털어내고 칼을 올려두니 에이카쿠 영도관의 과거 영광이 어렴풋이 되살아난다.",
  str_item_intro_3661104 = "운산에서만 만날 수 있는 희귀한 벚나무로 색채가 화려하다. 사람들은 이 위에 소원 쪽지를 매달고 자신의 소원이 이루어지길 기도한다.",
  str_item_intro_3662102 = "이국적인 색채의 그림. 거대한 용이 이빨을 드러내고 발톱을 휘두르는 모습은 두려움을 주기보단 알 수 없는 안정감을 준다. 그건 극동의 독특한 문화 때문일지도 모른다.",
  str_item_intro_3661105 = "운산에서 유행하는 장난감. 집에 두면 행운이 따르며, 어쩌면 주인의 어떤 소망을 이루어 줄지도 모른다.",
  str_item_intro_3661106 = "좀 흉악해 보이는 복달걀. 집에 두면 액을 없애고 악인이 찾아오는 것을 막아준다.",
  str_item_intro_3661107 = "가끔 금빛으로 빛나는 복달걀. 보고 있으면 곧 굴러올 복이 보이는 것 같기도 하니 한번 기대해보자.",
  str_item_intro_3661108 = "지식을 대표하는 복달걀. 시험을 잘 보게 해준다고 하여 많은 학생이 이 복달걀을 구한다. 자난성으로 가지고 간다면 앞다투어 팔릴 것이다.",
  str_item_intro_3661109 = "사람마다 가장 어울리는 복달걀이 있다고 한다. 그것은 당신의 아름다운 소망을 실현해 주고, 편안한 일생을 보장해줄 것이다.",
  str_item_intro_3661110 = "가구, 콜로서스의 방에 배치할 수 있다.\n바다에서 모습을 드러낸 기괴한 고성의 모형으로, 신비롭고 기이한 느낌이 든다. 때때로 희미한 소리가 들려서, 이 성에 대한 고대의 전설을 떠올리게 만든다.",
  str_item_intro_3661111 = "가구, 콜로서스의 방에 배치할 수 있다.\n스카이워커호의 기술을 참고하여 플뢰르가 제작한 로봇 「레디젤 파워 게키간V 0호기」의 모형이다. 실물보다 성능이 대폭 향상된 완벽한 로봇이지만, 그저 크기가 작을 뿐이다.",
  str_item_intro_3661112 = "가구, 콜로서스의 방에 배치할 수 있다.\n바이스가 부수입을 벌기 위해 만든 카트다. 특별한 장치로 얼음을 준비하고, 빙수를 만들어 팔아 무더운 여름에 한줄기 시원한 즐거움을 선사한다. 비록 장사는 끝났지만, 카트의 장비는 계속해서 사용할 수 있다. 가끔식 저절로 가동되는 경우도 있는데, 이는 자신이 아직 「현역」임을 과시하려는 것으로 보인다.",
  str_item_intro_3661113 = "가구, 콜로서스의 방에 배치할 수 있다.\n「플라티나 선라이즈」 호텔에서 제작한 에어 소파다. 뒷면에 달린 물총이 주기적으로 물을 뿌려 사람들을 시원하게 만든다.",
  str_item_intro_3661114 = "가구, 콜로서스의 방에 배치할 수 있다.\n「플라티나 선라이즈」 호텔에서 제작한 에어 소파다. 쿠션 뒤의 분사 장치는 주기적으로 분수 역할을 한다. 더 시원해지긴 했지만, 분수의 힘이 너무 강한 탓에 앉아 있는 사람을 놀라게 만들 때도 있다.",
  str_item_intro_3661115 = "가구, 콜로서스의 방에 배치할 수 있다.\n「플라티나 선라이즈」 호텔에서 제작한 에어 소파다. 뒷면에 자동 폭죽 발사기가 달려 있다. 가동되면 각종 폭죽이 발사돼 소소한 불꽃놀이를 감상할 수 있다. 발사 각도가 잘 맞춰져 있으므로 소파에 앉아 있는 사람을 다치게 하진 않겠지만, 대신 깜짝 놀랄 수 있어 주의해야 한다.",
  str_item_intro_3661116 = "가구, 콜로서스의 방에 배치할 수 있다.\n「플라티나 선라이즈」 호텔에서 제작한 에어 소파다. 양쪽 팔걸이는 사실 거품 기계다. 가동하면 거품이 사방으로 날아다니며, 아이들에게 인기가 많다.",
  str_item_intro_3661117 = "가구, 콜로서스의 방에 배치할 수 있다.\n「플라티나 선라이즈」 호텔에서 제작한 워터 소파다. 휴대가 편리하며, 펼친 후에는 야자수 장식을 추가할 수 있다. 물을 가득 채우고 소파에 앉으면 해변에 있는 듯한 느낌을 받을 수 있다.",
  str_item_intro_3661118 = "가구, 콜로서스의 방에 배치할 수 있다.\n「플라티나 선라이즈」 호텔에서 제작한 서프보드다. 특수한 재료로 만들어 가볍고 내구성이 뛰어나며, 서핑을 즐기는 서퍼들에게 인기가 많다.",
  str_item_intro_3662103 = "가구, 콜로서스의 방에 배치할 수 있다.\n「해신제」 참가 기념 그림이다. 그림 속 푸른 바다와 하늘, 해변의 나무들을 보고 있으면, 마치 즐거운 시간을 보냈던 그날의 해변으로 다시 돌아간 듯한 기분이 든다.",
  str_item_intro_3661119 = "가구, 콜로서스의 방에 배치할 수 있다.\n24호 지하성은 사막 방어선에 위치한 중요한 기지 중 하나로, 사막 방어선 전체의 보급, 신병 훈련, 의무지원 등을 담당한다. 이 미니어처는 앞선 특징들을 완벽하게 표현해내고 있다.",
  str_item_intro_3661120 = "가구, 콜로서스의 방에 배치할 수 있다.\n일루미나 연방 사관학교에서 사용하는 지형도다. 측량 전문가들의 현장 측량 제도를 거친 후, 동일 비율로 축소하여 모래와 목재, 모형을 사용해 만들어졌으며, 전장의 환경을 현실적으로 재현하여 사관생도들이 더 효과적인 지휘 훈련을 수행할 수 있다.",
  str_item_intro_3661121 = "가구, 콜로서스의 방에 배치할 수 있다.\n수많은 구멍이 나 있는 철판에 훈장이 달려 있는 컬렉션이다. 당시 「용사 별동대」가 암귀에 맞서 싸웠던 증거이자 그들의 자부심이 담긴 것이라고 한다. 이 위의 훈장들은 「용사 별동대」가 결코 사라지지 않았고, 다른 전사들과 함께 사막 방어선을 지키며 암귀와 맞서고 있음을 의미한다.",
  str_item_intro_3662104 = "가구, 콜로서스의 방에 배치할 수 있다.\n사막 방어선의 수비군이 암귀의 대규모 침입을 막아낸 것을 격려하기 위해, 일루미나 연방에서 그들을 위해 제작한 깃발이다. 방어선의 수비군들은 이 깃발을 볼 때마다 명예로움을 느끼며, 그들의 신조 「우리가 있는 곳이 곧 방어선이다」를 다시 한번 되새긴다.",
  str_item_intro_3661122 = "걱정 마세요. 여긴 누구도 묻혀 있지 않으니까요. 그러니까 「묘비」라고 할 수 없겠죠. 네? 손이 어쨌다구요? 괜찮아요~ 그냥 연출일 뿐이니까요~",
  str_item_intro_3661123 = "나이티움을 안 주면 유령이 나타나요! 그래요. 사실 녀석은 말도 못 하고, 진짜 유령도 아니에요. 그저 침대보를 뒤집어쓴 닭일 뿐이랍니다~",
  str_item_intro_3662105 = "사실은 나무판을 이어서 호박 모양으로 만든 등이다. 「눈」, 「코」, 「입」에서 불빛이 새어 나오면 기괴한 느낌이 든다.",
  str_item_intro_3661124 = "새하얀 곧은 산봉우리, 우뚝 솟은 흰색 탑은 헤븐즈 밸리의 상징이다. 이 정교한 모형은 흰색 탑의 모습을 생생하게 재현했다.",
  str_item_intro_3661125 = "아이테르 소년 인형이다. 바닥에 두고 보면 꽤나 귀엽고, 왠지 파이어플라이들이 좋아하는 것 같다.",
  str_item_intro_3661126 = "민들레를 심은 화분이다. 겉보기엔 매우 섬세한 꽃이지만, 이 강인한 식물은 물과 진흙만 있으면 살아갈 수 있다.",
  str_item_intro_3661127 = "가구, 콜로서스의 방에 배치할 수 있다.\n모형이라기보다는 마치 축소된 세계처럼 보인다. 산과 나무 같은 자연경관에 움직이는 기차까지 있다. 산 주위를 도는 모형 열차의 모습을 보고 있으면, 마치 실제 같은 아름다움에 감탄하게 된다.",
  str_item_intro_3661128 = "가구, 콜로서스의 방에 배치할 수 있다.\n진짜 가을 나무를 콜로서스로 옮겨온 것 같다... 원리는 알 수 없지만 이 분재는 계절의 색을 고스란히 유지하고 있다. 가끔씩 노란 낙엽이 떨어져 가을의 정취를 느끼게 하지만, 청소하는 사람은 귀찮을지도 모른다.",
  str_item_intro_3661129 = "가구, 콜로서스의 방에 배치할 수 있다.\n언제나 태양을 바라보는 꽃이다. 화분을 보고 있으면 기분이 좋아지며, 방에 두면 분위기가 한껏 따스해진다.",
  str_item_intro_3661130 = "가구, 콜로서스의 방에 배치할 수 있다.\n명예를 상징하는 황금 벨트, 움브라톤의 「지하격투장」에서 흘린 피와 땀을 상징한다. 아무나 건드리지 못하게 잘 보관해야 한다.",
  str_item_intro_3661131 = "가구, 콜로서스의 방에 배치할 수 있다.\n합리적인 거래는 당사자 모두에게 공정해야 한다. 이 도금된 저울은 거래하는 양측이 인정한 공정성을 상징하며, 움브라톤의 상회에서 장식으로 흔히 사용된다. 이는 손님들에게 이 상회가 공정하게 거래하고 있다는 것을 보여주기 위해서다.",
  str_item_intro_3662106 = "가구, 콜로서스의 방에 배치할 수 있다.\n수입산 부채다. 부드러우면서도 튼튼한 종이로 만들어졌으며, 그 위에 그려진 그림은 이국적이고 독특한 예술적 분위기가 느껴진다.",
  str_item_intro_3662107 = "가구, 콜로서스의 방에 배치할 수 있다.\n백야성의 장인들이 스테인드글라스 기술로 만든 그림이다. 빛을 비추면 풍부하고 다채로운 색상을 반사하며, 그 화려한 모습에 시선을 빼앗긴다.",
  str_item_intro_3661132 = "가구, 콜로서스의 방에 배치할 수 있다.\n한때 북방 상공을 순찰하던 빙룡이라고 하는데, 지금의 「녀석」은 전혀 위협적이지 않은 것 같다. 그저 동상일 뿐이니 말이다. 집에 두면 냉기가 느껴져서 여름에 매우 유용하다.",
  str_item_intro_3661133 = "가구, 콜로서스의 방에 배치할 수 있다.\n옷걸이와 망토는 간단해 보이지만, 일부 나이 든 북방 주민들의 말에 따르면 여기에는 신기한 이야기가 전해진다고 한다.",
  str_item_intro_3661134 = "가구, 콜로서스의 방에 배치할 수 있다.\n일부 북방 주민들의 전설에 따르면 이것을 신으면 진정한 사랑을 얻을 수 있다고 한다. 남자든 여자든 말이다.",
  str_item_intro_3661135 = "가구, 콜로서스의 방에 배치할 수 있다.\n북방에서 가장 흔한 주택의 모형이다. 지붕에 쌓인 눈과 이따금 굴뚝에서 피어오르는 흰 연기가 모두 진짜처럼 생생하다. 창문 안에서 반짝거리는 등불을 보면 정말로 안에 난쟁이가 살고 있을 것만 같다.",
  str_item_intro_3662109 = "가구, 콜로서스의 방에 배치할 수 있다.\n순록의 머리처럼 생겼지만, 진짜 표본은 아니니 무서워할 필요는 없다. 사실 이는 북방 주민들이 모피와 나무를 사용해 만든 장식품이다. 안에는 특별한 장치가 있어서 가끔씩 눈이 움직이기도 한다.",
  str_item_intro_3661136 = "가구, 콜로서스의 방에 배치할 수 있다.\n요리로 사랑을 표현하고 싶다면 자신의 신체 일부를 재료로 사용하는 것보다 더 적절한 것은 없다. 토르는 자신의 꼬리 고기에 매우 자신감이 있으며, 꼬리의 지방 분포와 풍미는 다른 그 어떤 식재료보다도 뛰어나다고 믿는다. 토르는 불의 세기를 제어하는 것도 매우 능숙하며, 요리의 맛도 매우 좋다. 하지만 조심해야 한다. 안에는 독이 있기 때문이다.",
  str_item_intro_3661137 = "가구, 콜로서스의 방에 배치할 수 있다.\n토르가 심심풀이로 만든 나무 조각이다. 드래곤은 사람들이 말하는 「예술」이라는 것을 잘 이해하지 못하는데, 이는 주제 선정이든 제작 과정이든 드래곤의 입장에선 너무 단순해 보이기 때문이다. 토르가 다른 사람의 작품을 바탕으로 이 나무 조각을 만들었다. 비록 자신은 무슨 뜻인지 모르지만, 다른 사람들이 마음에 들어 한다면 그것으로 충분하다.",
  str_item_intro_3662110 = "가구, 콜로서스의 방에 배치할 수 있다.\n놀러 나왔으면 같이 사진을 찍어야지! 다들 가까이 서 봐! 드래곤 다섯 마리를 안에 담으려니까 쉽지가 않네... 그럼 셋, 둘, 하나, 치~즈!",
  str_item_intro_3661138 = "가구, 콜로서스의 방에 배치할 수 있다.\n잃어버린 도시에서 발견된 피아노다. 아스트라 대륙의 일부 피아노와 스타일이 비슷하지만, 재질이 매우 특이하며, 오랜 시간이 지났음에도 아름다운 음색을 낸다. 충돌로 인해 음정이 약간 변했지만, 독특한 내부 구조 덕분에 음정 조율이 가능하다. 음악가들에게는 매우 값진 보물이다.",
  str_item_intro_3661139 = "가구, 콜로서스의 방에 배치할 수 있다.\n스타일은 매우 단순하지만, 일루미나가 추구하는 「소박」한 스타일과는 결이 다르다. 독특한 광택 소재와 아름다운 디자인으로 인해 백야성 사람이라 해도 마음에 들어 할 것이다.",
  str_item_intro_3661140 = "가구, 콜로서스의 방에 배치할 수 있다.\n잃어버린 도시에서 발견된 카펫으로, 재질도 특수할 뿐만 아니라 교차하는 다이아몬드 패턴이 매우 눈길을 끈다. 잃어버린 도시에 살던 옛 주민들은 미적 감각도 뭔가 남달랐던 모양이다.",
  str_item_intro_3661141 = "가구, 콜로서스의 방에 배치할 수 있다.\n잃어버린 도시의 거리 어디에서나 볼 수 있는 것으로, 가로등보다 수가 많다. 때로는 도로 표지판으로도 사용할 수 있을 것 같다는 생각이 든다... 화면에는 온갖 잡다한 이미지가 가득하고, 끊임없이 깜박이고 있다. 안에 무엇이 들어 있는지는 알 수 없는데, 그걸 알아내려면 이것을 부수는 수밖에 없을 듯하다.",
  str_item_intro_3661142 = "가구, 콜로서스의 방에 배치할 수 있다.\n잃어버린 도시에서 발견된 우체통이다. 적혀 있는 글씨가 흐릿한 탓에 처음 보면 비상식량을 보관한 소형 보관함으로 오인하곤 하며, 안에 있는 편지를 보고서야 사람들은 이것이 우체통임을 알게 된다. 그러나 이제는 아무도 이 안에 편지를 넣지 않는다.",
  str_item_intro_3661143 = "가구, 콜로서스의 방에 배치할 수 있다.\n잃어버린 도시에서 흔히 볼 수 있는 벤치다. 보통은 행인들이 쉴 수 있도록 길가에 설치된다. 물론 집에 가져와서도 쓸 수 있고, 누워서 잠을 잘 수도 있다.",
  str_item_intro_3661144 = "가구, 콜로서스의 방에 배치할 수 있다.\n오랜 세월이 흘렀지만 아직도 고장이 나지 않았다. 잃어버린 도시의 기술은 정말 놀라운 것 같다. 종이를 넣기만 하면 종이가 조각조각 잘려서 정보를 알아볼 수 없게 된다. 아무래도 그들은 보안 의식이 매우 강했던 것 같다.",
  str_item_intro_3661145 = "가구, 콜로서스의 방에 배치할 수 있다.\n오랜 시간이 흘렀지만 여전히 좋은 상태를 유지하고 있다.... 하지만 이제 더는 사용하는 사람이 없다. 청소를 마쳐 깨끗하게 정돈된 책상과 각종 사무용품을 보면 업무의 활력이 넘치게 된다.",
  str_item_intro_3661146 = "가구, 콜로서스의 방에 배치할 수 있다.\n이 기묘한 의자는 자유롭게 회전할 뿐만 아니라, 시트의 높이도 조절하고 등받이도 접을 수 있다. 사용자는 의자에 편안하게 누워 낮잠을 잘 수 있다. 책상과 함께 놓아 두면 색감이 조화를 이루며, 앉아 있으면 시간을 잊고 일에 몰두할 수 있다.",
  str_item_intro_3661147 = "가구, 콜로서스의 방에 배치할 수 있다.\n극동 지역의 장식품이다. 대나무로 만들어졌으며, 흐르는 물에 의해 움직인다. 정교한 구조로 만들어져 주기적으로 대나무가 「딸깍」 부딪히는 경쾌하고 듣기 좋은 소리를 낸다. 시간을 재는 데 사용할 수도 있다.",
  str_item_intro_3661148 = "가구, 콜로서스의 방에 배치할 수 있다.\n거대한 대나무 화분이다. 성장 속도가 매우 빨라서 자주 가지치기가 필요하다. 조금 번거롭긴 하지만 그래도 대나무 마디를 많이 얻을 수 있다는 장점이 있다. 바람에 대나무 잎이 날릴 때면 「바스락」 소리가 들려서 운치가 있다.",
  str_item_intro_3663001 = "가구, 콜로서스의 방에 배치할 수 있다.\n처마 밑에 매달린 인형이다. 만들기도 간단하고 무척 귀엽다. 산들바람이 불 때면 바람을 따라 춤을 추는데, 마치 정말로 비가 오지 않기를 기도하는 듯하다. 만약 정말 효과가 있다면, 아마도 녀석이 춤추는 모습을 신이 봤기 때문일지도 모른다.",
  str_item_intro_3661149 = "가구, 콜로서스의 방에 배치할 수 있다.\n극동 지역의 무사가 착용하는 투구다. 무척 과장된 장식이 달려 있는데, 이는 무사가 지닌 권력이나 그 가문을 상징하기도 하며, 더 중요한 것은 그 장식이 바로 명예의 상징이라고 한다.",
  str_item_intro_3661150 = "가구, 콜로서스의 방에 배치할 수 있다.\n원래 군인이나 무사가 등에 달고 다니는 깃발이라고 한다. 후방의 군대를 안내하는 역할을 한다. 집에 두면 엄숙한 느낌이 든다.",
  str_item_intro_3662111 = "가구, 콜로서스의 방에 배치할 수 있다.\n극동 지역 사람들이 좋아하는 글씨본이다. 보통은 서예의 대가가 쓴 것인데, 물론 대부분은 모사본이다. 어쨌거나 이 글씨들은 극동 사람들의 눈에는 특별한 아름다움을 지니고 있으며, 다른 지역의 사람들은 그 느낌을 잘 이해할 수 없다.",
  str_item_intro_3661151 = "가구, 콜로서스의 방에 배치할 수 있다.\n「산수」라곤 하지만, 「고」라는 단어에서 이 풍경 미니어처에는 물이 없다는 것을 알 수 있다. 고운 모래로 물을 표현했고, 돌멩이로 석가산을 표현했다. 극동에서는 이런 고요한 풍경이 명상에 도움이 되고, 마음을 진정시키는 효과가 있다고 믿는다.",
  str_item_intro_3661152 = "가구, 콜로서스의 방에 배치할 수 있다.\n운도의 어디에서나 볼 수 있는 가로등이다. 극동 스타일로 장식이 되어 있다. 이곳의 주민들은 조명뿐만 아니라 도로 표지판 용도로도 사용한다.",
  str_item_intro_3663002 = "가구, 콜로서스의 방에 배치할 수 있다.\n강부성 사람들이 즐겨 사용하는 등롱이다. 평소에는 문에 걸어 조명으로 사용하며, 집집마다 달린 등롱이 거리를 대낮처럼 밝힌다. 또한 대나무 막대에 걸어서 들고 다니면 밤길을 밝힐 수도 있다.",
  str_item_intro_3661159 = "가구, 콜로서스의 방에 배치할 수 있다.\n카렌이 정식 기사로 봉해졌을 때 주어졌던 장창으로, 그 뒤로 그녀와 생사를 함께한 무기가 되었다. 이것은 그 창의 복제품으로, 비록 실제는 아니지만 집에 놓아두면 「달의 고치」의 위력을 느낄 수 있다...",
  str_item_intro_3662116 = "가구, 콜로서스의 방에 배치할 수 있다.\n「유명」 제작자 투어독이 매우 좋아하는 장식이다. 이 클래퍼보드를 집에 걸어두면 막대가 부딪히는 경쾌한 소리가 난다. 업무의 시작을 상징하는 이 소리는 그에게 무한한 동력을 제공하며, 그가 이처럼 노력하는 모습을 보면 주변 사람들도 감화되어 함께 노력하게 된다고 한다.",
  str_item_intro_3661153 = "가구, 콜로서스의 방에 배치할 수 있다.\n랠리를 응원하는 치어리더들은 이 폼폼을 들고 다양한 춤을 추며 선수들을 격려한다. 하지만 이 폼폼은 누군가가 개조해 기괴한 장치를 추가했고, 자신을 응원할 수 있게 만들었다. 처음에는 이상하게 보일 수도 있지만, 익숙해지면 나름대로 재미있다.",
  str_item_intro_3661154 = "가구, 콜로서스의 방에 배치할 수 있다.\n원래 경주용으로 쓰던 타이어지만, 장기간의 사용 끝에 파손되어 폐품 신세가 되었고, 겹겹이 쌓아서 의자로 만들어지게 되었다. 거칠어 보이지만 앉으면 의외로 부드럽다.",
  str_item_intro_3662112 = "가구, 콜로서스의 방에 배치할 수 있다.\n「버닝 랠리」의 종점에 꽂혀 있는 깃발이라고 하며, 많은 선수들이 이를 가지고 가서 집에 장식으로 두거나 기념으로 차에 달아둔다.",
  str_item_intro_3661155 = "가구, 콜로서스의 방에 배치할 수 있다.\n레디젤 렌치가 개최한 랠리는 거의 대부분의 멤버가 참가했고, 다른 세력의 사람들도 참가해 실력을 뽐냈다. 이 트로피는 랠리에 참가해 뛰어난 성적을 거두었음을 의미한다.",
  str_item_intro_3661156 = "가구, 콜로서스의 방에 배치할 수 있다.\n거의 사막에서만 자라는 식물로, 내한성이 매우 강하고 물 없이도 살 수 있다고 한다. 따라서 이 화분은 매우 키우기 쉽다. 하지만 가시에 조심해야 하며, 너무 자주 물을 주지 않도록 주의해야 한다.",
  str_item_intro_3662113 = "가구, 콜로서스의 방에 배치할 수 있다.\n「동력 타이어」라고 불리지만, 실제로는 그냥 평범한 레이싱 타이어일 뿐이다. 대신 벽에 걸어두면 지금도 랠리에 참가하고 있는 듯한 느낌을 준다.",
  str_item_intro_3661157 = "가구, 콜로서스의 방에 배치할 수 있다.\n진리의 결사 멤버들의 말에 따르면 이 두루마리는 고대의 폐허에서 발견되었다고 한다. 비록 안에는 아무 내용도 없지만, 많은 진리의 결사 멤버들은 이 안에서 특별한 「계시」를 보았다고 한다...",
  str_item_intro_3642602 = "가구, 콜로서스의 방에 배치할 수 있다.\n한 이름을 알 수 없는 진리의 결사 멤버가 그린 것이다. 그는 자신이 「세상의 진실」을 보았다고 주장하며 이 그림을 그렸고, 그 후 불가사의하게 사라졌다고 한다. 또한 아무도 그가 한 말을 사실로 믿지 않았다. 무척이나 기괴한 그림이지만, 사람을 끌어당기는 묘한 힘을 가지고 있다...",
  str_item_intro_3661158 = "가구, 콜로서스의 방에 배치할 수 있다.\n「나눌 수 없는」, 「완벽한」, 「순환」, 「진실」, 「유일」... 많은 진리의 결사 멤버들은 이 패턴을 두고 서로 다른 해석을 내리곤 한다. 이들은 칠각성을 발밑에 두면 「최후의 진상」을 더 잘 엿볼 수 있다고 믿는다.",
  str_item_intro_3662115 = "가구, 콜로서스의 방에 배치할 수 있다.\n사막! 레이싱! 가장 용감하고 강인하며, 가장 민첩한 레이서를 버닝 랠리에 초대합니다! 속도의 경쟁 속에서 한없이 질주하세요! 세상의 끝까지!",
  str_item_intro_3661169 = "가구, 콜로서스의 방에 배치할 수 있다.\n신비한 힘으로 움직이는 소형 기계, 조금만 밀면 멈추지 않고 돌아간다. 일부러 멈추게 하지 않는 이상 아주 오래도록 움직인다고 한다.",
  str_item_intro_3661170 = "가구, 콜로서스의 방에 배치할 수 있다.\n원래 헤븐즈 가든에 놓여있던 문이다. 시원시원한 느낌을 주며, 다른 곳에 장식으로 사용하기도 좋다.",
  str_item_intro_3661162 = "가구, 콜로서스의 방에 배치할 수 있다.\n물고기 뼈를 완벽하게 발라내서 가지런히 정돈할 수 있는 사람이라면 물고기에 대해 잘 알고 있는 사람일 것이다. 이 물고기 뼈 장식은 단순한 장식품이 아니라 기술을 뽐내는 것이기도 하다.",
  str_item_intro_3662117 = "가구, 콜로서스의 방에 배치할 수 있다.\n낚시꾼의 솜씨를 엿볼 수 있다. 이렇게 거대한 몸집을 가진 물고기라면 사투를 벌일 때 거센 파도가 일 정도였을 것이다. 낚시꾼은 한바탕 격전을 치렀고, 그것을 정복한 후 기념으로 이것을 남겼을 것이다.",
  str_item_intro_3661163 = "가구, 콜로서스의 방에 배치할 수 있다.\n동그란 말뚝으로 만들어진 의자, 표면이 울퉁불퉁하고 나무의 나이테도 보인다. 방에 거친 들판의 기운을 더해 특별한 운치가 있다.",
  str_item_intro_3661164 = "가구, 콜로서스의 방에 배치할 수 있다.\n아이테르들이 사용했던 카펫이라고 한다. 위에는 각종 선과 도형으로 이루어진 문양이 그려져 있다. 이 문양을 오래 보고 있으면 누군가는 탑의 일부분이라고도 하고, 누군가는 하늘이 생각난다고 하는 정말 신기한 무늬다.",
  str_item_intro_3661165 = "가구, 콜로서스의 방에 배치할 수 있다.\n이세계에서 「버스」라고 불리는 교통수단의 모형이다. 마음의 괴도단 멤버들에게는 친숙한 디자인인 듯하다. 모형을 쳐다보는 모나의 표정이 왠지 우쭐대는 것 같은데... 착각이겠지?",
  str_item_intro_3661166 = "가구, 콜로서스의 방에 배치할 수 있다.\n이세계의 특정 지역에 사는 요정을 본떠 만든 봉제 인형이다. 눈사람의 형태를 떠올리게 하며, 무척 매력적이다. 가끔 「히~호」라는 소리가 들리는 것 같은데... 착각이겠지?",
  str_item_intro_3661167 = "가구, 콜로서스의 방에 배치할 수 있다.\n고대 유적에서 발견된 신비한 장치로, 음식을 자동으로 튀기고 맛을 내기까지 한다고 한다! 너무 희귀한 탓에 많은 사람들이 그것을 얻기 위해 「미식 포장마차」 경기를 벌이기도 했다고 전해진다...",
  str_item_intro_3661168 = "가구, 콜로서스의 방에 배치할 수 있다.\n식용유, 껍질을 벗긴 곡물 및 조미료(보통은 설탕)를 넣고 가동하면 곡물이 부풀어 올라 기묘한 간식이 완성된다. 하지만 아쉽게도 여기 있는 건 그저 장식이라서 사용할 수 없다...",
  str_item_intro_3661160 = "가구, 콜로서스의 방에 배치할 수 있다.\n놀이동산에서 빼놓을 수 없는 필수품으로, 아이들이 말을 타는 즐거움을 체험할 수 있게 해 준다. 하지만 이 회전목마는 조금 작아서... 구경만 할 수 있다.",
  str_item_intro_3661161 = "가구, 콜로서스의 방에 배치할 수 있다.\n시소다! 시소! 하지만 너무 작아 보인다... 기껏해야 작은 동물들이나 탈 수 있을 것 같다. 그런데 콜로서스의 파이어플라이들은 무척 환영하는 것 같다. 파이어플라이들은 왠지 시소를 통해 서로 맞추어 움직이는 훈련을 할 수 있다고 생각하는 것 같다. 그래서인지 녀석들이 시소에서 흔들거리는 모습을 자주 볼 수 있다.",
  str_item_intro_3661001 = "가구, 콜로서스의 방에 배치할 수 있다.\n공기를 채우면... 아주 강해 보이는 암귀의 모습 같지만... 아무튼 수영 튜브일 뿐이다. 게다가 핑크색이라서 그리 흉악해 보이지도 않고, 오히려 조금 귀여운 느낌도 든다.",
  str_item_intro_3661002 = "가구, 콜로서스의 방에 배치할 수 있다.\n원래 일루미나 연방에서 제작해 외부에 판매한 자동 선풍기였으나, 한 마을의 사람들이 여름 분위기가 느껴지도록 새롭게 도색했다. 이 선풍기를 켜면 무척 상쾌한 바람이 분다고 하는데, 진실인지 거짓인지는 아무도 모른다...",
  str_item_intro_3661003 = "가구, 콜로서스의 방에 배치할 수 있다.\n백야성 셔틀허브 정거장의 표지판이다. 무척 견고하고 내구성이 좋은 재질로, 오랜 시간의 햇살과 비바람을 맞으면서도 녹이 슬지 않았다. 표지판의 배색은 간결하고, 형태도 보기 좋아서 기념품으로 집에 가져가기 좋다.",
  str_item_intro_3661004 = "가구, 콜로서스의 방에 배치할 수 있다.\n이 티아라는 권력을 나타내는 평범한 왕관이 아니라, 진정한 매력을 상징한다. 움브라톤에서 개최하는 미인대회의 우승자는 이 티아라를 받게 된다. 한 나라의 재력에 버금가는 진귀한 보석이 장식되어 있으며, 보는 이들에게 매우 깊은 인상을 준다.",
  str_item_intro_3661005 = "가구, 콜로서스의 방에 배치할 수 있다.\n사막에서 유행하는 모자의 일종으로, 챙이 특히 넓으며, 바람과 모래를 견디는 데 쓴다고 한다. 사막 근처의 주민들은 이 모자와 가면을 쓰고, 기념일에 춤과 노래로 외지인들에게 특별한 경험을 선사한다.",
  str_item_intro_3661006 = "가구, 콜로서스의 방에 배치할 수 있다.\n사막 근처의 일부 주민들은 감자로 「빈백」이라는 요리를 만드는데, 「빈백」 모양의 소파도 여기서 유래되어 탄생했다. 바느질로 귀여운 표정까지 더해져, 보고 있으면 무척이나 안기고 싶은 생각이 든다.",
  str_item_intro_3661007 = "가구, 콜로서스의 방에 배치할 수 있다.\n링 위의 선수들의 모습이 「격투」를 벌여 경기의 과정이 재현되며, 콜로서스에서도 격투 대회의 분위기를 느낄 수 있도록 한다.",
  str_item_intro_3661008 = "가구, 콜로서스의 방에 배치할 수 있다.\n커다란 단풍잎 분재다. 화분 하나만으로 충분한 장식이 된다. 물론 다른 분재와 함께 배치한다면 더 좋을 것이다.",
  str_item_intro_3661009 = "가구, 콜로서스의 방에 배치할 수 있다.\n작은 단풍나무가 있는 화분이다. 여러 화분을 함께 놓으면 더 예쁘게 보인다.",
  str_item_intro_3661010 = "가구, 콜로서스의 방에 배치할 수 있다.\n어떤 마을의 주민들은 이 얼굴이 적을 겁주고 행운을 불러올 수 있다고 생각한다. 따라서 중요한 가구로 사용되었고, 가족을 축복하는 뜻에서 눈에 띄는 곳에 배치됐다.",
  str_item_intro_3661011 = "가구, 콜로서스의 방에 배치할 수 있다.\n극동에서 유행하는 가구의 일종으로, 최근 대륙에서도 점차 유행하기 시작했다. 겨울철에 사람들에게 따뜻함과 마음의 평안을 선사하며, 한 번 앉으면 온종일 가만히 있게 되어 「이불탁자의 저주」라는 말도 전해진다.",
  str_item_intro_3661012 = "가구, 콜로서스의 방에 배치할 수 있다.\n가문비나무는 북방에서 가장 흔히 볼 수 있는 나무이자, 집과 가구의 재료로 흔히 쓰인다. 이에 북방 주민들은 이를 「가정」의 상징으로 여긴다. 새해가 되면 북방 주민들은 이 나무에 각종 장식물을 건 다음에 아래에 선물을 놓고, 함께 열어보며 기념일을 축하한다.",
  str_item_intro_3661013 = "가구, 콜로서스의 방에 배치할 수 있다.\n극동 지방 사람들은 기념일에 이 장식을 사용하는데, 원래는 일종의 음식이었다고 한다. 사람들은 이것이 축복을 상징한다고 생각하여, 진흙과 천으로 대신 만든 것이다. 하지만 아무리 봐도 트위티와 비슷해 보인다.",
  str_item_intro_3661014 = "가구, 콜로서스의 방에 배치할 수 있다.\n「좋은 날에 사랑하는 사람을 위한 하트 케이크를 만들어 보세요.」 언제부터 유행한 것인지는 모르겠지만, 젊은 여자애들 사이에서 꽤 인기가 많다고 한다. 예쁘기만 한 게 아니라 맛도 좋다. 그 달콤한 느낌은 정말 말로 설명할 수 없다.",
  str_item_intro_3661015 = "가구, 콜로서스의 방에 배치할 수 있다.\n아마도 극동 지방에 전해지는 일종의 장식품일 것이다. 가볍고 편리하며, 처마나 문에 걸 수 있다. 바람이 불 때 나는 「딸랑딸랑」 경쾌한 소리는 마음을 편안하게 만들어 준다.",
  str_item_intro_3661016 = "가구, 콜로서스의 방에 배치할 수 있다.\n무척이나 귀여운 곰인형으로, 좋아하는 사람에게 선물하면 좋을 것 같다. 귀엽게 생겼을 뿐만 아니라 맛도 놀라울 정도로 맛있다. 하지만 과연 정말로 먹어버릴 사람이 있을까...",
  str_item_intro_3661017 = "가구, 콜로서스의 방에 배치할 수 있다.\n고대의 국왕 곁을 모시던 「농신」을 모티브로 한 장난감이라고 한다. 바보 같으면서도 귀엽게 생겼다. 특별한 날 친구에게 선물하면 색다른 즐거움을 줄 수 있을 것이다.",
  str_item_intro_3661018 = "가구, 콜로서스의 방에 배치할 수 있다.\n레디젤 렌치 멤버들이 즐겨 착용하는 헬멧으로, 각종 사고에 대한 보호는 물론 운전 중 불어오는 모래도 막아주며, 밝은 색상의 헬멧을 착용하면 사람들의 눈에 띄어 자신을 과시하는 효과도 있다.",
  str_item_intro_3661019 = "가구, 콜로서스의 방에 배치할 수 있다.\n다양한 조각으로 만들어진 스카이워커호다. 어떤 아이들이 만든 걸작으로 보인다. 스카이워커호를 최대한 모방한 것처럼 보이지만, 어딘가 아이들다운 유치한 면모가 있다.",
  str_item_intro_3661020 = "가구, 콜로서스의 방에 배치할 수 있다.\n1주년을 기념하기 위해 특별히 제작된 케이크의 탑, 눈앞에 놓으면 정말 깜짝 놀란다. 왜냐하면... 정말로 높기 때문이다! 그리고 케이크 층마다 살짝 돌려보면 화려하고 다양한 테두리 장식을 볼 수 있다.",
  str_item_intro_3661021 = "가구, 콜로서스의 방에 배치할 수 있다.\n아... 벌써 1년이라는 시간이 흘렀다. 과거의 추억은 모두 이곳에서 찾아볼 수 있다.",
  str_item_intro_3662118 = "가구, 콜로서스의 방에 배치할 수 있다.\n이세계에서 마음의 괴도단이 표적에게 보내는 「예고장」 포스터다. 독특한 디자인에서 예술성이 느껴진다. 포스터를 쳐다보는 폭스의 표정이 왠지 우쭐대는 것 같은데... 착각이겠지?",
  str_item_intro_3661022 = "가구, 콜로서스의 방에 배치할 수 있다.\n익숙한 배색인가요? 맞습니다. 렉커를 모델로 만든 서프보드입니다. 렉커 본인과 마찬가지로 이 서프보드는 내구성이 매우 좋고 성능도 안정적이며 조종도 쉽답니다.",
  str_item_intro_3661176 = "가구, 콜로서스의 방에 배치할 수 있다.\n야자수를 감상하기 위해... 나무를 화분에 옮겨 심었다! 이런 발상을 해낸 사람은 아마 정말로 야자수를 아주 많이 좋아하는 모양이다.",
  str_item_intro_3661171 = "가구, 콜로서스의 방에 배치할 수 있다.\n생생한 불가사리 조각은 언뜻 보기에 정말로 녀석이 육지에 온 것처럼 보인다. 모래로 만든 것임에도 불구하고 대체 어떻게 붙인 것인지 부드러운 모래에 찰싹 달라붙어 있으며, 의외로 매우 견고하다.",
  str_item_intro_3661172 = "가구, 콜로서스의 방에 배치할 수 있다.\n매우 단단하지만 결국 모래로 만들어진 것이므로 이름 그대로 받아들이면 안 된다. 이름의 원래 의도는 이 성이 더 오래 보존될 수 있길 바란 것이라고 한다. 그리고 이 성의 상태로 봤을 때 그 의도는 효과가 뛰어났다.",
  str_item_intro_3661173 = "가구, 콜로서스의 방에 배치할 수 있다.\n어서 와서 보세요! 각종 기묘한 공연이 펼쳐지는 성대한 행사는 관객들에게 「이런 공연도 있다니」라는 감탄을 선사하기 충분할 겁니다. 한 번만 봐도 결코 잊을 수 없는 이 공연의 포스터는 비록 그림일지라도 무척 매력적으로 보입니다.",
  str_item_intro_3661174 = "가구, 콜로서스의 방에 배치할 수 있다.\n여러 색상의 공으로 이루어져 있으며, 다양한 저글링 동작은 물론이고, 가벼운 조작만으로도 무대 위 관객들의 시선을 사로잡기에 충분하다. 멋진 공연을 위한 필수 소품 중 하나다.",
  str_item_intro_3661175 = "가구, 콜로서스의 방에 배치할 수 있다.\n풍선이 잔뜩 있다! 색깔도 다양하고, 잡아당겼을 때 약간의 부력을 느낄 수 있다! 너무 어린 아이들이 가지고 놀지 않게 하는 것이 좋다. 잘못하면 아이들이 하늘로 날아가 버릴지도 모른다!",
  str_item_intro_3661177 = "가구, 콜로서스의 방에 배치할 수 있다.\n이런 나무는 어떻게 자라는 걸까? 가지가 이렇게 꺾여 있어도 살아 있다니... 무서운 이야기에 등장해서 으스스한 분위기를 내기 좋을 것 같다. 가지에 등불을 몇 개 걸어 놓으면 많은 사람들이 보고 깜짝 놀랄 것이다.",
  str_item_intro_3661178 = "가구, 콜로서스의 방에 배치할 수 있다.\n그녀는 뭐 때문에 웃고 있는 걸까? 그 이유는 가면의 제작자만이 알 것이다. 오랫동안 이 가면을 들여다보고 있으면 가면의 미소가 조금 이상하다는 느낌이 든다. 사실은 미소를 짓고 있는 게 아닐지도...",
  str_item_intro_3661179 = "가구, 콜로서스의 방에 배치할 수 있다.\n보글보글... 보글보글... 이 신기하고 커다란 솥 안에서 끓고 있는 건 대체 무엇일까? 동화에 나오는 마법약일까? 아니면... 뒤틀린 황천의 요리?",
  str_item_intro_3661180 = "가구, 콜로서스의 방에 배치할 수 있다.\n움브라톤의 몇몇 이상한 상인들이 만든 인형이다. 겉보기에는 평범한 콜로서스 모형이지만, 속이 비어 있으며, 살짝 누르면 이상한 비명을 지른다. 대체 무슨 클리셰를 표현한 걸까...",
  str_item_intro_3661023 = "가구, 콜로서스의 방에 배치할 수 있다.\n물만 채우면 안의 장치를 사용해 계속해서 물을 발사해 시원함을 선사할 수 있다. 여름에 사용하기 매우 적합하지만, 놀고 난 뒤에는 바닥을 깨끗이 닦는 것을 잊지 말아야 한다.",
  str_item_intro_3661024 = "가구, 콜로서스의 방에 배치할 수 있다.\n한 바퀴로도 전진할 수 있습니다! 속도는 조금 느리긴 해도... 마치 서커스 같은 주행을 보며 감탄과 걱정이 함께 느껴질 겁니다.",
  str_item_intro_3661025 = "가구, 콜로서스의 방에 배치할 수 있다.\n신비한 유적에서 발견된 것으로 추정되는 기계로, 약간 오래되기는 했지만, 작동에는 전혀 문제가 없어 알차게 영상을 기록할 수 있다.",
  str_item_intro_3701001 = "흩어져 있는 책이다. 카페의 책장에 정리되어 있으니 관심이 있다면 보러 가자.",
  str_item_intro_3701002 = "흩어져 있는 책이다. 카페의 책장에 정리되어 있으니 관심이 있다면 보러 가자.",
