  str_item_intro_3710002 = "흩어져 있는 책이다. 카페의 책장에 정리되어 있으니 관심이 있다면 보러 가자.",
  str_item_intro_3710003 = "흩어져 있는 책이다. 카페의 책장에 정리되어 있으니 관심이 있다면 보러 가자.",
