  str_item_intro_3711001 = "흩어져 있는 책이다. 카페의 책장에 정리되어 있으니 관심이 있다면 보러 가자.",
  str_item_intro_3711002 = "흩어져 있는 책이다. 카페의 책장에 정리되어 있으니 관심이 있다면 보러 가자.",
  str_item_intro_3711003 = "흩어져 있는 책이다. 카페의 책장에 정리되어 있으니 관심이 있다면 보러 가자.",
  str_item_intro_3711004 = "흩어져 있는 책이다. 카페의 책장에 정리되어 있으니 관심이 있다면 보러 가자.",
  str_item_intro_3711005 = "흩어져 있는 책이다. 카페의 책장에 정리되어 있으니 관심이 있다면 보러 가자.",
  str_item_intro_3751002 = "획득 시 해당 아바타 개방.\n「좋은 아이디어가 떠올랐어! 응? 너도 생각났다고? 말하지 마. 우리 사이의 비밀이니까~」",
  str_item_intro_3751003 = "획득 시 해당 아바타 개방.\n「저 사람 좀 봐. 되게 재밌어! 아앗, 저 사람! 헤에~ 설마~ 아니겠지~?」",
  str_item_intro_3751004 = "획득 시 해당 아바타 개방.\n「일이 또 잘 안 풀려! 어떡하지! 아, 거친 말은 하면 안 되는데... 그래도!」",
  str_item_intro_3751005 = "획득 시 해당 아바타 개방.\n「아~ 귀찮아 죽겠네. 어떻게 이럴 수 있지? 아무래도 아직 뭔가 부족한 모양이네. 더 노력해 보자~」",
  str_item_intro_3751006 = "획득 시 해당 아바타 개방.\n「일을 제대로 못 했다고 혼나는 건 아니겠지? 그래도 그렇게 최악은 아니겠지? 히이잉...」",
  str_item_intro_3751009 = "획득 시 해당 아바타 개방.\n「자신을 의심하지 마. 네게도 자신만의 사명이 반드시 있을 테니까. 반드시!」",
  str_item_intro_3751011 = "획득 시 해당 아바타 개방.\n「맡겼던 임무는 모두 마쳤나요? 그럼 예쁜 꽃을 드릴게요~」",
  str_item_intro_3751015 = "획득 시 해당 아바타 개방.\n「이 소리는 무척 듣기 좋고 마음이 차분해져요. 같이 들으실래요~?」",
  str_item_intro_3751017 = "획득 시 해당 아바타 개방.\n「모두의 발목을 잡을 순 없어. 뭔가 새로운 걸 발명해 볼까? 예를 들면~」",
  str_item_intro_3751019 = "획득 시 해당 아바타 개방.\n「풍부한 지식과 넓은 견문으로도 눈앞의 일을 표현할 수가 없구나. 정말 놀라운 일이다.」",
  str_item_intro_3751023 = "획득 시 해당 아바타 개방.\n「뭘 그렇게 서두르죠? 공짜 밥 먹으러 서둘러 가는 건가요? 늦으면 따뜻한 밥 못 먹으니까~」",
  str_item_intro_3751025 = "획득 시 해당 아바타 개방.\n「재미없는 사람, 왜 시간을 허비하려 하는 걸까~? 다른 할 일은 없는 거야~?」",
  str_item_intro_3751030 = "획득 시 해당 아바타 개방.\n「우리의 소중한 콜로서스, 왜 잘난척하며 하늘을 나는 걸까~?」",
  str_item_intro_3751032 = "획득 시 해당 아바타 개방.\n「왜 자신을 모를까? 왜 거울을 안 보는 걸까? 정말 구제불능인 저 사람들은 정말 주제 파악을 못 한다니까~」",
  str_item_intro_3751033 = "획득 시 해당 아바타 개방.\n「함께 잔을 기울여도, 칼날을 피할 수는 없을 터.」",
  str_item_intro_3751034 = "획득 시 해당 아바타 개방.\n「자네가 그림자를 들여다보면, 그림자도 자네를 들여다본다.」",
  str_item_intro_3751035 = "획득 시 해당 아바타 개방.\n「진리는 때로는 구름 속에 숨겨져 있고, 반은 감춰지고 반은 드러나 있단다. 우린 모두 눈을 깨끗하게 닦아야만 해.」",
  str_item_intro_3751036 = "획득 시 해당 아바타 개방.\n「질서? 규칙? 크하하! 그게 뭐지?」",
  str_item_intro_3751037 = "획득 시 해당 아바타 개방.\n「미래는 여전히 어두우나, 나는 이미 한 줄기 빛을 보았다.」",
  str_item_intro_3751038 = "획득 시 해당 아바타 개방.\n「아주 좋아! 나와 함께 암귀에 맞서는 거다! 여명의 빛을 위하여!」",
  str_item_intro_3751301 = "획득 시 해당 아바타 개방.\n「꽤 하잖아! 레디젤 렌치에 가입할 생각 없어?」",
  str_item_intro_3751302 = "획득 시 해당 아바타 개방.\n「다들 고마워. 내 힘은 다시 안정을 되찾았어. 암귀랑 싸우는 걸 도와줄까?」",
  str_item_intro_3751303 = "획득 시 해당 아바타 개방.\n「함께 운산으로 벚꽃 구경을 가시는 건 어떻습니까.」",
  str_item_intro_3751304 = "획득 시 해당 아바타 개방.\n「빙수의 혼」을 지닌 자가 정성껏 만든 빙수는 여름날에 최고의 시원함을 선사한다.",
  str_item_intro_3751305 = "획득 시 해당 아바타 개방.\n「이게 있으면 너도 「레디젤 파워-게키간V 0호기」야!」",
  str_item_intro_3751306 = "획득 시 해당 아바타 개방.\n「휴... 다들 놀러 간 것 같네... 그럼 나도...」",
  str_item_intro_3751307 = "획득 시 해당 아바타 개방.\n「시원해지고 싶어? 얼마든지, 빙화여~」",
  str_item_intro_3751308 = "획득 시 해당 아바타 개방.\n「벌써 100일이나 됐어? 케이크 먹으면서 기념하자~」",
  str_item_intro_3751309 = "획득 시 해당 아바타 개방.\n「아... 난 사막 사람인가 봐.」",
  str_item_intro_3751310 = "획득 시 해당 아바타 개방.\n「왜 이리 무겁나 했더니만... 뭐, 그냥 두자고.」",
  str_item_intro_3751311 = "획득 시 해당 아바타 개방.\n「승리했어? 그럼 폭죽으로 축하할게!」",
  str_item_intro_3751312 = "획득 시 해당 아바타 개방.\n「이번 일에 대한 우리의 견해가 같았으면 좋겠군요.」",
  str_item_intro_3751313 = "획득 시 해당 아바타 개방.\n「가면을 벗은 얼굴을 보고 싶다고? 문제없어. 대신 먼저 내 용병단에 가입해 줘.」",
  str_item_intro_3751314 = "획득 시 해당 아바타 개방.\n「만물은 백야 아래에. 부디 제가 세상의 불공정한 일들을 바로잡을 수 있길 바랍니다.」",
  str_item_intro_3751315 = "획득 시 해당 아바타 개방.\n「움브라톤 지하격투장 최고의 영광을 상징하며, 당신이 에이스 선수가 되었다는 증거입니다.」",
  str_item_intro_3751316 = "획득 시 해당 아바타 개방.\n「오빠야! 지는 인자 마법도 배웠심더!」",
  str_item_intro_3751317 = "획득 시 해당 아바타 개방.\n「함께 분위기를 띄워볼까요!」",
  str_item_intro_3751318 = "획득 시 해당 아바타 개방.\n「순찰 중에 귀여운 고양이들을 만나면 오늘은 기분이 좋아질 것 같아!」",
  str_item_intro_3751319 = "획득 시 해당 아바타 개방.\n백야성의 권력을 상징하며, 오직 귀족만이 가질 수 있다.",
  str_item_intro_3751320 = "획득 시 해당 아바타 개방.\n「북방의 새해에는 모두가 이런 장식을 하지. 나도 예외는 아니다.」",
  str_item_intro_3751321 = "획득 시 해당 아바타 개방.\n「새해에는 부디 행복과 평안을 얻길 바라겠습니다.」",
  str_item_intro_3751322 = "획득 시 해당 아바타 개방.\n「이제 아시겠죠? 전 세계 최고의 메이드라구요!」",
  str_item_intro_3751323 = "획득 시 해당 아바타 개방.\n착한 아이는 잠을 잘 때도 착해서 뒤척이지 않아요. 심지어 머리 위에 귤을 올려놓을 수도 있답니다.",
  str_item_intro_3751324 = "획득 시 해당 아바타 개방.\n「내가... 저들을 하나하나 그려주마.」",
  str_item_intro_3751325 = "획득 시 해당 아바타 개방.\n「이것 좀 보세요... 제 추측대로라면 이건 천 년도 더 된 물건이에요!」",
  str_item_intro_3751326 = "획득 시 해당 아바타 개방.\n「축하할 거야? 기념일에도 자신만의 요구사항이 있는 모양이네.」",
  str_item_intro_3751327 = "획득 시 해당 아바타 개방.\n「헤이~ 같이 바깥 구경하러 갈래?」",
  str_item_intro_3751328 = "획득 시 해당 아바타 개방.\n「아무리 좋은 기억력도 노트 한 권보다 못한 법이야.」",
  str_item_intro_3751329 = "획득 시 해당 아바타 개방.\n「어흥~ 놀라진 않았지?」",
  str_item_intro_3751330 = "획득 시 해당 아바타 개방.\n「진정한 사랑은 귀하나\n자유는 더욱 값진 것\n맹세에 목숨을 건다면\n양자 모두 버려두길」",
  str_item_intro_3751331 = "획득 시 해당 아바타 개방.\n「딸랑~ 방울이 가지고 싶다냥?」",
  str_item_intro_3751332 = "획득 시 해당 아바타 개방.\n「신악의 방울의 소리를 들어주세요.」",
  str_item_intro_3751333 = "획득 시 해당 아바타 개방.\n「난 절대 남한테 내 만두를 양보하지 않아!」",
  str_item_intro_3751334 = "획득 시 해당 아바타 개방.\n「일어났어? 얼른 일하러 가~」",
  str_item_intro_3751335 = "획득 시 해당 아바타 개방.\n「승리했어! 그럼 같이 재미있는 거나 하러 갈까?」",
  str_item_intro_3751336 = "획득 시 해당 아바타 개방.\n「나랑 닮지 않았어?」",
  str_item_intro_3751338 = "획득 시 해당 아바타 개방.\n「아하하, 고양이도 널 지켜보고 있어.」",
  str_item_intro_3751339 = "획득 시 해당 아바타 개방.\n「뭐가... 다른 거지?」",
  str_item_intro_3751340 = "획득 시 해당 아바타 개방.\n「그동안 많이 신경 써 줘서 고마워. 이거 받아줘.」",
  str_item_intro_3751341 = "획득 시 해당 아바타 개방.\n「오늘은 마음을 표현하는 날이라고 하던데... 맞아?」",
  str_item_intro_3751342 = "획득 시 해당 아바타 개방.\n「이 잠옷, 조종사가 유행시킨 특별 제품이라면서? 줄을 한참 서서 겨우 샀다고!」",
  str_item_intro_3751343 = "획득 시 해당 아바타 개방.\n「눈동자 색이... 달라졌어.」",
  str_item_intro_3751344 = "획득 시 해당 아바타 개방.\n「음... 왠지 잊어버린 업무가 있는 것 같은데요...」",
  str_item_intro_3751345 = "획득 시 해당 아바타 개방.\n「중요한 일을 곧바로 기록하는 건 참모장으로서의 좋은 습관이랍니다~」",
  str_item_intro_3751346 = "획득 시 해당 아바타 개방.\n「이 옷? 움브라톤에서 쇼핑하다가 산 거야. 스타일이 독특하지?」",
  str_item_intro_3751347 = "획득 시 해당 아바타 개방.\n「츄브 상인은 좋은 물건을 얻었는지 기쁘게 노래를 흥얼거리고 있습니다.」",
  str_item_intro_3751348 = "획득 시 해당 아바타 개방.\n「일루미나에는 네 힘이 필요하다. 네가 합류하길 기다리겠다!」",
  str_item_intro_3751349 = "획득 시 해당 아바타 개방.\n「응? 내 노래를 듣고 싶다고? 물론 되지. 대신 나랑 같이 게임하자!」",
  str_item_intro_3751350 = "획득 시 해당 아바타 개방.\n「왜 유미 분장을 했냐고? 유미는 귀여우니까!」",
  str_item_intro_3751351 = "획득 시 해당 아바타 개방.\n「이 귀 말이야? 이건 필리시가 꼭 쓰라고 해서 쓴 거야. 안 그러면 시로나 씨의 꼬리를 실수로 밟은 게 나였다는 걸 가서 말해버리겠다고 했거든...」",
  str_item_intro_3751352 = "획득 시 해당 아바타 개방.\n「나랑 한 팀이 되자! 어떤 대결이든 절대 지지 않을 거라고!」",
  str_item_intro_3751353 = "획득 시 해당 아바타 개방.\n「하? 그게 뭐가 어려워?」",
  str_item_intro_3751354 = "획득 시 해당 아바타 개방.\n「가끔 긴장을 푸는 것도 좋겠지.」",
  str_item_intro_3751355 = "획득 시 해당 아바타 개방.\n「어디까지 팠더라?」",
  str_item_intro_3751356 = "획득 시 해당 아바타 개방.\n「앗! 뜨거워라!」",
  str_item_intro_3751357 = "획득 시 해당 아바타 개방.\n「올해 여름은 무덥구나. 차양 모자를 쓰면 일광화상을 예방할 수 있지. 조종사, 열사병에도 주의해야 한다.」",
  str_item_intro_3751358 = "획득 시 해당 아바타 개방.\n더운 여름날 시원하고 맛있는 빙수를 누가 싫어할까요?",
  str_item_intro_3751359 = "획득 시 해당 아바타 개방.\n뜨거운 여름, 카렌 곁에 있으면 항상 시원함이 느껴진다.",
  str_item_intro_3751360 = "획득 시 해당 아바타 개방.\n「정말 기분 좋네. 같이 축제 속의 고요함을 즐겨보자.」",
  str_item_intro_3751361 = "획득 시 해당 아바타 개방.\n「검은 밤은 나의 동료요, 박쥐는 내 신하와 백성들이지. 그렇다면 난 누구지?」",
  str_item_intro_3763022 = "획득 시 해당 아바타 개방.\n「겁내실 필요는 없습니다. 이 괴상한 랜턴은 최근 행사의 분위기를 띄우기 위해 만든 것입니다. 꽤 괜찮지 않습니까?」",
  str_item_intro_3751362 = "획득 시 해당 아바타 개방.\n「무슨 일이 일어났는지 볼까?」",
  str_item_intro_3751363 = "획득 시 해당 아바타 개방.\n「아무리 엄숙할 때라도 아르바가 머리 위에 올라가는 건 허락해 줄 거야.」",
  str_item_intro_3751365 = "획득 시 해당 아바타 개방.\n「사탕을 사고 싶어? 그럼 네 이야기를 가지고 교환하자.」",
  str_item_intro_3751366 = "획득 시 해당 아바타 개방.\n「늑대로 분장하는 거, 조종사라면 절대 거절하지 않겠지?」",
  str_item_intro_3751367 = "획득 시 해당 아바타 개방.\n「카론은 신나게 가짜 송곳니와 망토를 착용하고 공연을 시작했답니다.」",
  str_item_intro_3751368 = "획득 시 해당 아바타 개방.\n「마법사가 되는 것도 히이로에게는 일종의 수행입니다.」",
  str_item_intro_3751369 = "획득 시 해당 아바타 개방.\n「파로마는 자신의 몸을 붕대로 감쌌고, 사탕을 달라고 하는 아이들을 놀라게 만들 준비를 마쳤습니다.」",
  str_item_intro_3751370 = "획득 시 해당 아바타 개방.\n「이 동전은... 내 과거를 상징해.」",
  str_item_intro_3751371 = "획득 시 해당 아바타 개방.\n「각종 색상의 조명은 정말 아름답습니다.」",
  str_item_intro_3751372 = "획득 시 해당 아바타 개방.\n「나랑 같이 아이돌이 되자!」",
  str_item_intro_3751373 = "획득 시 해당 아바타 개방.\n「레디, 액션!」",
  str_item_intro_3751374 = "획득 시 해당 아바타 개방.\n「이건 필리시가 말린 생선으로 바꿔 왔다는 새해 인기 잠옷이에요. 네, 편하긴 하지만 왜 귀가 달려 있는 걸까요?」",
  str_item_intro_3751375 = "획득 시 해당 아바타 개방.\n「향이 독특한 우렁쌀국수는 목월백이 가장 좋아하는 음식입니다.」",
  str_item_intro_3751376 = "획득 시 해당 아바타 개방.\n「어디 불편해? 우리가 좀 봐 줄까?」",
  str_item_intro_3751377 = "획득 시 해당 아바타 개방.\n「묵묵히 남을 관찰하는 건 예리아의 작은 습관이랍니다.」",
  str_item_intro_3751378 = "획득 시 해당 아바타 개방.\n「무표정한 미카엘은 그녀 앞에 보이는 모든 장미를 몰수합니다.」",
  str_item_intro_3751379 = "획득 시 해당 아바타 개방.\n「가끔 위장해서 시찰을 나가는 것도 특별한 체험이라 할 수 있지.」",
  str_item_intro_3751380 = "획득 시 해당 아바타 개방.\n「위험한 동작이니 따라 하지 마세요.」",
  str_item_intro_3751381 = "획득 시 해당 아바타 개방.\n「제노가 블랙커피를 한 잔 마시자고 합니다. 그와 함께할 건가요?」",
  str_item_intro_3751382 = "획득 시 해당 아바타 개방.\n「백야성의 심판관이라면 법봉을 내려칠 기백이 있어야 합니다.」",
  str_item_intro_3751383 = "획득 시 해당 아바타 개방.\n「이 인형은 나랑 비슷하게 생겼어. 안고 있으면 마음이 편안해져.」",
  str_item_intro_3751384 = "획득 시 해당 아바타 개방.\n「전 음악을 좋아해요. 음악은 제 마음을 평온하게 해주거든요.」",
  str_item_intro_3751385 = "획득 시 해당 아바타 개방.\n「딱새와 붙어 있기 좋아하는 잉겔의 속마음은 분명히 따뜻하겠죠?」",
  str_item_intro_3751386 = "획득 시 해당 아바타 개방.\n「외부의 적에게는 칼을 겨누고, 내부의 백성의 손을 잡는 것은 레오가 굳게 지키고 있는 원칙입니다.」",
  str_item_intro_3751387 = "획득 시 해당 아바타 개방.\n「홍차의 향은 미아의 기분을 진정시키고 긴장을 풀어준답니다.」",
  str_item_intro_3751388 = "획득 시 해당 아바타 개방.\n「손에 쥔 비단향꽃무는 과연 누가 가장 좋아하는 꽃일까요?」",
  str_item_intro_3751389 = "획득 시 해당 아바타 개방.\n「수정구슬에서 과거나 미래를 볼 수 있을까요?」",
  str_item_intro_3751390 = "획득 시 해당 아바타 개방.\n「마음이 안 좋을 때 자상하게 안아주면 네 기분이 좀 달래질까?」",
  str_item_intro_3751391 = "획득 시 해당 아바타 개방.\n「제 관객이 되어 주시겠어요? 아니면 저와 함께 춤을 추시겠어요? 당신은 뭘 선택하실 거죠?」",
  str_item_intro_3751392 = "획득 시 해당 아바타 개방.\n「무더운 여름엔 시원한 빙수 한 그릇으로 더위를 식혀 봐!」",
  str_item_intro_3751393 = "획득 시 해당 아바타 개방.\n「나한테 돈을 벌 좋은 아이디어가 있어, 같이 한번 해 볼래?」",
  str_item_intro_3751394 = "획득 시 해당 아바타 개방.\n「뭘 웃고 있냐고? 음... 네가 한번 맞혀보는 건 어때?」",
  str_item_intro_3751395 = "획득 시 해당 아바타 개방.\n「내가 여름에 가장 좋아하는 디저트? 도마뱀 육포가 얻어진 아이스크림이려나.」",
  str_item_intro_3751501 = "획득 시 해당 아바타 개방.\n「이 새벽꽃은 희망의 상징이야. 이걸 달고 과거의 어두운 그림자를 몰아내자!」",
  str_item_intro_3751502 = "획득 시 해당 아바타 개방.\n「벚꽃 일족의 휘장. 히이로가 당신을 인정했다는 것을 의미한다.」",
  str_item_intro_3751503 = "획득 시 해당 아바타 개방.\n「만약 수수께끼의 전사의 도움이 필요하다면, 타키의 흥신소로 연락해라.」",
  str_item_intro_3751504 = "획득 시 해당 아바타 개방.\n「헤헷, 같이 애프터눈 티 드실래요?\n겨우 일곱 잔밖에 안 마셨는데 벌써 지친 건가요~?」",
  str_item_intro_3751505 = "획득 시 해당 아바타 개방.\n「나와 함께 영원한 어둠으로 돌아가자.」",
  str_item_intro_3751506 = "획득 시 해당 아바타 개방.\n「암귀를 못 이기겠다고? 나한테 맡겨!」",
  str_item_intro_3751507 = "획득 시 해당 아바타 개방.\n「윈델리온의 깜짝 선물! 과연 안에 무슨 선물이 들어 있을까요?」",
  str_item_intro_3751508 = "획득 시 해당 아바타 개방.\n「멋진 야경을 함께 감상하지 않겠나.」",
  str_item_intro_3751509 = "획득 시 해당 아바타 개방.\n「아무래도... 제 도움이 필요하신 것 같군요.」",
  str_item_intro_3751510 = "획득 시 해당 아바타 개방.\n「미리 말해두는데, 이건 코바야시 씨를 위해 준비한 거라구요. 아무도 먹으면 안 돼요!」",
  str_item_intro_3751511 = "획득 시 해당 아바타 개방.\n「저요? 밤은 안 새웠는데요...」",
  str_item_intro_3751512 = "획득 시 해당 아바타 개방.\n「아... 방금 일어났더니 목이 말라. 물을 많이 마셔야겠어.」",
  str_item_intro_3751513 = "획득 시 해당 아바타 개방.\n「어머, 제가 조종사님을 어떻게 생각하는지 여쭤보시는 건가요...」",
  str_item_intro_3751514 = "획득 시 해당 아바타 개방.\n「어디 또 먹을 거 없나~」",
  str_item_intro_3751515 = "획득 시 해당 아바타 개방.\n「같이 드라이브하러 가자!」",
  str_item_intro_3751516 = "획득 시 해당 아바타 개방.\n「레노어의 마음이 느껴지나요?」",
  str_item_intro_3751517 = "획득 시 해당 아바타 개방.\n「미래의 전략은...」",
  str_item_intro_3751518 = "획득 시 해당 아바타 개방.\n「가장 멋진 시간은 바로 애프터눈 티를 마실 때야.」",
  str_item_intro_3751519 = "획득 시 해당 아바타 개방.\n「내가 가져가겠어.」",
  str_item_intro_3751520 = "획득 시 해당 아바타 개방.\n「이 몸이 나설 차례인가?」",
  str_item_intro_3751521 = "획득 시 해당 아바타 개방.\n「백야성과 대륙... 분명히 그럴 리 없어. 절대 지금 이 모습은 아닐 거야.」",
  str_item_intro_3751522 = "획득 시 해당 아바타 개방.\n「고민 있어? 그럼 같이 시원해지자~」",
  str_item_intro_3751523 = "획득 시 해당 아바타 개방.\n「자! 같이 게임 한판 하자!」",
  str_item_intro_3751524 = "획득 시 해당 아바타 개방.\n「휴... 해치웠어.」",
  str_item_intro_3751525 = "획득 시 해당 아바타 개방.\n「생존이냐, 파멸이냐, 그것이 문제로다.」",
  str_item_intro_3751526 = "획득 시 해당 아바타 개방.\n「영감이 떠올랐어! 찍자! 이번엔 분명히 대박 날 거야!」",
  str_item_intro_3751527 = "획득 시 해당 아바타 개방.\n「모자에 달린 건 해골, 의적이 날린 건 악당. 새디는 쿠쿠를 번쩍 들고, 랩과 함께 끝까지 싸워.」",
  str_item_intro_3751530 = "획득 시 해당 아바타 개방.\n「꽃을 기르면 심성을 단련할 수 있어!」",
  str_item_intro_3751531 = "획득 시 해당 아바타 개방.\n「그녀는 아름다우면서도... 무척이나 위험합니다.」",
  str_item_intro_3751532 = "획득 시 해당 아바타 개방.\n「아... 따끈따끈하고 보들보들해.」",
  str_item_intro_3751533 = "획득 시 해당 아바타 개방.\n「아직 「그 사람」의 이야기에 푹 빠져 있는 거 같으니까, 방해하지 말자.」",
  str_item_intro_3751534 = "획득 시 해당 아바타 개방.\n「새해 복 많이 받아! 같이 불꽃놀이 하자!」",
  str_item_intro_3751535 = "획득 시 해당 아바타 개방.\n「배는... 정말 매력적이야.」",
  str_item_intro_3751536 = "획득 시 해당 아바타 개방.\n「맛있어! 엄청 맛있어! 더 없어?」",
  str_item_intro_3751537 = "획득 시 해당 아바타 개방.\n「이러다 늦겠어요! 먹으면서 갈 수밖에 없어요!」",
  str_item_intro_3751538 = "획득 시 해당 아바타 개방.\n「저 안 자요... Zzz...」",
  str_item_intro_3751539 = "획득 시 해당 아바타 개방.\n「한 번에 클리어할 수 있겠어?」",
  str_item_intro_3751540 = "획득 시 해당 아바타 개방.\n「아빠, 엄마...」",
  str_item_intro_3751541 = "획득 시 해당 아바타 개방.\n「빌어먹을 범인... 절대 놓치지 않겠어!」",
  str_item_intro_3751542 = "획득 시 해당 아바타 개방.\n「사냥감은 어디 있을까? 내 눈앞에 있구나~」",
  str_item_intro_3751543 = "획득 시 해당 아바타 개방.\n「좋은 기억력도 노트보다는 못한 법입니다...」",
  str_item_intro_3751544 = "획득 시 해당 아바타 개방.\n「연합 훈련이 곧 시작됩니다!」",
  str_item_intro_3751545 = "획득 시 해당 아바타 개방.\n「소홀히 해도 되는 것은 없다. 사소한 것일수록 중요하기 때문이지.」",
  str_item_intro_3751547 = "획득 시 해당 아바타 개방.\n「난 그저 이렇게 가만히 저 아이들을 바라보는 것만으로도 충분히 행복하단다.」",
  str_item_intro_3751548 = "획득 시 해당 아바타 개방.\n「감상하고 싶다고? 그럼 얼마든지 봐도 좋아.」",
  str_item_intro_3751549 = "획득 시 해당 아바타 개방.\n「위험할수록 아름다운 법이라던데, 사실일까?」",
  str_item_intro_3751550 = "획득 시 해당 아바타 개방.\n「좋은 아이디어와 행동력은 성공의 기본이지!」",
  str_item_intro_3751601 = "획득 시 해당 아바타 개방.\n한쪽 면이 갈라진 연 방패다. 연 방패는 백야성 기사단의 전용 장비로, 위는 넓고 아래는 좁은 연 모양의 형태를 하고 있다. 방패의 표면에는 교회를 상징하는 문장이 새겨져 있다.",
  str_item_intro_3751602 = "획득 시 해당 아바타 개방.\n「고목나무 한 그루에 풍선 3개가 걸려 있었다. 마사에게 있어 과거는 이미 수없이 시들었고, 등불로 밝혀진 설경 속에서 그녀는 새로운 인생을 맞이했다.」",
  str_item_intro_3751603 = "획득 시 해당 아바타 개방.\n타이어의 중앙에는 톱니바퀴 한 개가 있다. 로사의 차는 이미 사막 깊은 곳으로 향했고, 뒤를 따른 사람들은 더는 그녀의 모습을 볼 수 없었다. 보이는 것은 그저 타이어가 남긴 기나긴 자국뿐이었다.",
  str_item_intro_3751604 = "획득 시 해당 아바타 개방.\n만발한 백합 속 날카로운 칼날은 언제든지 명령을 기다리고 있다. 이본의 펜 아래 머큐리 부인의 운명은 짙은 안개 속에 가려져 있었다. 그녀가 손에 쥔 장검을 보낼지, 옷섶 위의 백합을 보낼지는 영원히 할 수 없을 것이다.",
  str_item_intro_3751901 = "획득 시 해당 아바타 개방.\n「스카이워커호는 콜로서스일 뿐만 아니라 당신과 17년을 함께한 친구입니다.」",
  str_item_intro_3751902 = "획득 시 해당 아바타 개방.\n「이 헬멧을 쓰고 있으면 백야의 수호자가 된 것만 같아요. 그게 어떤 「백야」인지는 캐묻지 마세요~」",
  str_item_intro_3755004 = "획득 시 해당 아바타 개방.\n「구슬 겹겹이 드리우고, 발 넘어 햇살 드는 창. 꽃송이는 옛적 그대로거늘, 뭇사람은 알고 있을는지.」",
  str_item_intro_3762001 = "획득 시 해당 프레임 개방.\n이 오래된 도안은 「사일런트 예거」가 당신을 인정했음을 뜻합니다. 과거로부터 온 최고의 영광을 받아 주세요.",
  str_item_intro_3762002 = "획득 시 해당 프레임 개방.\n정교한 장신구로 아바타를 장식해 보세요!",
  str_item_intro_3763001 = "획득 시 해당 프레임 개방.\n뜨거운 태양과 푸른 파도, 그리고 잊지 못할 추억이 무더운 해변에 남아 있다.",
  str_item_intro_3763002 = "획득 시 해당 프레임 개방.\n일루미나 연방의 이 모자를 쓰면 마치 그들과 동료가 된 것만 같은 기분이 든다.",
  str_item_intro_3763003 = "획득 시 해당 프레임 개방.\n언제든지 무게를 잴 수 있는 유용한 도구랍니다.",
  str_item_intro_3763004 = "획득 시 해당 프레임 개방.\n이걸 쓰면 파티에서 가장 싱그러운 사람이 될 수 있답니다~",
  str_item_intro_3763005 = "획득 시 해당 프레임 개방.\n우등생에게 주는 우승기! 항상 최선을 다하세요!",
  str_item_intro_3763006 = "획득 시 해당 프레임 개방.\n어때요? 귀여운가요?",
  str_item_intro_3763007 = "획득 시 해당 프레임 개방.\n「우리가 같이 있어 줄게...」",
  str_item_intro_3763008 = "획득 시 해당 프레임 개방.\n금붕어 건지기 놀이의 전리품이다.",
  str_item_intro_3763010 = "획득 시 해당 프레임 개방.\n봄의 기운이 느껴지네요!",
  str_item_intro_3763011 = "획득 시 해당 프레임 개방.\n이걸 쓰면 대단한 레이서가 될 수 있을 것 같다!",
  str_item_intro_3763012 = "획득 시 해당 프레임 개방.\n새빨간 커튼 너머에는 검은 동요가 들려온다...",
  str_item_intro_3763013 = "획득 시 해당 프레임 개방.\n찬란한 면류관으로, 매우 눈에 띈다.",
  str_item_intro_3763014 = "획득 시 해당 프레임 개방.\n이건 대원수만 입을 수 있다고!",
  str_item_intro_3763015 = "획득 시 해당 프레임 개방.\n이걸 쓰면 서비스 정신이 더 높아질까요?",
  str_item_intro_3763016 = "획득 시 해당 프레임 개방.\n이걸 쓰면 당신도 대마술사!",
  str_item_intro_3763017 = "획득 시 해당 프레임 개방.\n햇살이 강하니까 타지 않게 조심하세요~",
  str_item_intro_3763018 = "획득 시 해당 프레임 개방.\n1주년이 되었습니다! 어서 함께 축하해요!",
  str_item_intro_3763019 = "획득 시 해당 프레임 개방.\n이걸 쓰면 당신도 비카처럼 될 수 있답니다~ 복슬복슬~",
  str_item_intro_3763020 = "획득 시 해당 프레임 개방.\n걱정 마세요. 안 뜨거우니까요!",
  str_item_intro_3763021 = "획득 시 해당 프레임 개방.\n박쥐 발톱이 머리를 잡고 있는 것처럼 보이나요? 사실 헤어밴드가 좀 끼어서 그런 거랍니다~",
  str_item_intro_3763023 = "획득 시 해당 프레임 개방.\n이 모자를 쓰면 랩 실력이 좋아진다. 게다가 신기하게 야구도 잘하게 된다.",
  str_item_intro_3763024 = "획득 시 해당 프레임 개방.\n가수에게 필수! 음악 속에 푹 빠져 보세요~",
  str_item_intro_3763025 = "획득 시 해당 프레임 개방.\n먹는 게 아니라 머리에 쓰는 거예요!",
  str_item_intro_3763026 = "획득 시 해당 프레임 개방.\n이걸 쓰면 예리아와 맞먹는 힘을 얻을 수 있을까? 적어도 바람이 무서울 일은 없겠지.",
  str_item_intro_3763027 = "획득 시 해당 프레임 개방.\n사실 이 안경은 도수가 없답니다~",
  str_item_intro_3763028 = "획득 시 해당 프레임 개방.\n알겠어! 범인은 바로 그 사람이야!",
  str_item_intro_3763029 = "획득 시 해당 프레임 개방.\n「2주년이라고요? 자, 이걸 쓰세요! 1주년 때 그건 내려놓고요~」",
  str_item_intro_3763031 = "획득 시 해당 프레임 개방.\n「그 세상이 정말로 존재하냐고요? 존재하지 않는다면 어떻게 여기 있을 수 있죠?」",
  str_item_intro_3763032 = "획득 시 해당 프레임 개방.\n조금만 잘못해도 찔릴 것 같은데, 대체 누가 이걸 쓸까...",
  str_item_intro_3763033 = "획득 시 해당 프레임 개방.\n이것만 쓰면 나도 신사?",
  str_item_intro_3800001 = "50루맘버가 들어있다.",
  str_item_intro_3800002 = "50루맘버가 들어있다.",
  str_item_intro_3800003 = "50루맘버가 들어있다.",
  str_item_intro_3800004 = "50루맘버가 들어있다.",
  str_item_intro_3800005 = "50루맘버가 들어있다.",
  str_item_intro_3801001 = "전설 오로리안 돌파 시 필수 아이템.\n「사일런트 예거」 멤버가 모두 소유하고 있는 문장. 수천 년이 지났지만 여전히 강력한 힘을 유지하고 있어 「사일런트 예거」 멤버의 잠재력을 충분히 끌어올릴 수 있다.",
  str_item_intro_3900101 = "매회 모의 지휘 후, 지휘 비록은 지휘관의 성과에 따라 일정 포인트를 부여하며, 지휘 포인트가 일정 수준에 도달하면 해당하는 지휘 레벨로 레벨업할 수 있다. 이는 전술 지휘의 숙련도를 나타낸다.",
  str_item_intro_3900201 = "시뮬레이션 룸의 지휘 전투를 통해 「데이터 디스크」에 저장된 방대한 데이터에서 귀중한 데이터 조각을 얻을 수 있으며, 누적 시 완전한 정보로 결합할 수 있다.",
  str_item_intro_3910100 = "오랜 훈련만이 승리를 가져온다.\n\n해당 데이터 디스크의 도전에서 모든 적을 물리쳐야만 클리어할 수 있다.",
  str_item_intro_3910200 = "적을 물리치는 것보다 충분한 자원을 모으는 것이 중요할 때가 많다.\n해당 데이터 디스크의 도전에서 특정 아이템 X개를 획득해야만 클리어할 수 있다.",
  str_item_intro_3910300 = "목숨을 잃는 한이 있더라도, 반드시 동료를 지켜내야 한다.\n\n해당 데이터 디스크의 도전에서 X턴간 NPC를 지켜내야만 클리어할 수 있다.",
  str_item_intro_3910400 = "어떤 적을 만날지는 알 수 없지만, 모두 강력한 적이니 조심해야 한다.\n\n해당 데이터 디스크의 도전에서 모든 정예 적을 물리쳐야만 클리어할 수 있다.",
  str_item_intro_3910500 = "머리는 칼을 이기는 법, 지혜로 승리를 쟁취하라.\n\n해당 데이터 디스크의 도전에서 수수께끼를 풀어야만 클리어할 수 있다.",
  str_item_intro_3910600 = "전쟁이란 전장을 무대로 펼쳐지는 게임이다.\n\n해당 데이터 디스크의 도전에서 모든 적을 물리쳐야만 클리어할 수 있다.",
  str_item_intro_3910700 = "잔혹한 전투, 살아남는 자가 곧 유일한 승자다.\n\n해당 데이터 디스크의 도전에서 X턴간 생존해야만 클리어할 수 있다.",
  str_item_intro_3910800 = "파도처럼 계속해서 몰아치는 적들을 막으며 버텨내야 한다.\n\n해당 데이터 디스크의 도전에서 모든 적을 물리쳐야만 클리어할 수 있다.",
  str_item_intro_3910900 = "적의 전술은 당신과 유사하다. 아니... 어쩌면 적은 당신 자신이나 동료들일지도 모른다.\n\n해당 데이터 디스크의 도전에서 모든 적을 물리쳐야만 클리어할 수 있다.",
  str_item_intro_3911000 = "적과 싸울 때는 우두머리를 먼저 노려야만 한다. 이 전쟁을 끝내기 위해 적의 우두머리를 쓰러트려라.\n\n해당 데이터 디스크의 도전에서 적의 보스를 처치해야만 클리어할 수 있다.",
  str_item_intro_4090014 = "쌍둥이의 유대는 깊게 이어져 있고, 깨진 기억들은 서서히 연결되어 간다. 그 눈처럼 하얀 쌍둥이 수선화는 거울 호수 곁에서 검은 눈꽃과 함께 조금씩 피어나며, 거울 속 사람과 다시 재회하길 고대하고 있다.",
  str_item_intro_4090334 = "운앵 여관에서 제공하는 운산 특유의 복장으로, 바이스의 신체 구조에 맞게 임시로 개량된 여성용 유카타다. 간결한 배색, 독특한 허리띠와 노리개, 그리고 귀여운 방울까지... 모두 바이스가 평소와는 다른 분위기를 선보이도록 한다. 그녀는 이 유카타를 입을 때마다 잊지 못할 소중한 추억을 떠올리곤 한다.",
  str_item_intro_4090923 = "「...그렇게 뚫어지게 쳐다보지 마...!」\n이보다 더 난처한 순간이 있을까. 얽힌 가시덩굴이 펙트의 두 발을 들어 올렸고, 얇은 실크 스타킹과 검은 천은 조각조각 찢겨졌다. 다행히 이 혼란 속에서 펙트는 손에 든 와인 잔의 균형을 간신히 유지했다. 이 단정하면서도 화려한 드레스는 아무래도 생각보다 관리가 쉽지 않을 것 같다.",
  str_item_intro_4090383 = "「대위기! 그로누가 장난감 상자에 갇혀버렸어!」\n새해를 축하하기 위해 그로누가 준비한 깜짝 선물이다. 장난감과 함께 상자에 들어간 그녀는 깜찍하고 귀여워 보인다. 빨간색과 하얀색 복장은 기념일의 분위기를 드러내며, 그녀의 기계 팔에도 나비 리본이 장식되어 있다. 하지만 그녀가 들고 있는 악의 넘치는 폭탄은 역시 사양하고 싶다...",
  str_item_intro_4090333 = "바이스가 해신제에 참가하기 위해 선택한 심플하고 편안한 스타일의 수영복이다. 이 의상은 바이스의 착용 습관에 적합하도록 특수한 디자인 구조를 접목했고, 꼬리에도 불편함을 주지 않는다. 또한 블랙과 골드 컬러의 자외선 차단용 외투는 활발하고 활동적인 그녀의 성향에 잘 어울리는 것을 느낄 수 있다. 비치발리볼, 상쾌한 음료, 빙수 카트... 시원한 얼음을 만들고 있는 제빙기 소리, 활짝 웃으며 물놀이를 권하는 단발머리의 소녀... 그 여름, 바이스는 당신과 특별한 추억을 함께 나누었다.",
  str_item_intro_4090853 = "강렬한 상의와 우아한 치마가 결합된 기묘한 의상. 우울함과 순수함, 기이함과 아름다움이 뒤섞여 있다. 정교하게 짜인 소매, 분위기 있는 베일, 그리고 멋들어진 부츠... 제인의 옷차림은 보는 이들을 놀랍게 만들었다. 또한 그녀의 드레스에 피어난 꽃에도 숨은 뜻이 있는 듯하다. 다만 항상 아웃사이더를 자처했던 그녀는 어째서 이런 의상을 입은 것일까.",
  str_item_intro_4090863 = "해신제를 테마로 디자인된 순백의 소녀 스타일 의상이다. 우라이아의 신분을 고려해 특별히 티 없이 새하얀 순백의 염료를 사용했고, 이를 통해 순수함과 경건함을 표현했다. 꽃 덩굴이 그녀의 곁을 지키며 부름을 기다리는 모습, 그리고 그녀의 태도와 기품은 사람들의 눈에는 평소와 다를 바가 없어 보인다. 그러나 해변에 온 우라이아가 처음 입어보는 이 옷에 내심 수줍어하고 있다는 것은 그녀의 주변을 감싸는 꽃들만이 알고 있다. 맑은 하늘, 바다 내음이 담긴 바람, 시원한 파도... 그녀가 손에 든 의례의 검을 휘두를 때면, 아름다운 시와 음악이 다시금 연주된다.",
  str_item_intro_4090573 = "이것은 오후의 달콤한 꿈이었다. 필리시는 푹신한 잠옷을 입고 침대에 웅크리고 잠들었다. 그녀는 유미가 곁에 있는 꿈을 꾸었고, 유미를 껴안고 머리를 쓰다듬어주었다. 그 꿈은 따스한 작은 난로처럼 그녀의 몸과 마음을 따뜻하게 만들었고, 모든 것이 마치 그때로 시간이 돌아간 것만 같았다.",
  str_item_intro_4091023 = "이 단순한 복장은 「타오르는 불꽃」의 정신을 드러내고 있다. 이는 어두컴컴한 지하 격투장을 밝히는 유일한 환한 빛이었다. 도전자는 무대에 올라 근육과 육체, 정신과 의지를 겨루고, 선혈은 맹렬한 불길처럼 타오른다. 그러나 모든 것은 불길처럼 힘차게 타올랐다가 잿더미처럼 사라져 버린다. 손가락 관절을 푸는 그녀의 모습은 이미 눈앞의 모든 것을 사냥할 준비가 된 듯하다.",
  str_item_intro_4090453 = "쏟아지는 함박눈과 함께 추운 겨울이 다가왔다. 거리에는 아무도 다니지 않고, 따스한 노란색 불빛들만 깜박거린다. 만약 당신이 혼자 여행하는 사람이라면 길을 잃을까 걱정할 필요는 없다. 구석에 하얀 턱시도와 검은색 부츠 차림의, 반들반들한 헤어스타일과 우아한 매너를 지닌, 차분하고 정숙한 신사가 마차 곁에서 당신을 계속 기다리고 있을 테니 말이다.",
  str_item_intro_4090993 = "소파에 몸을 웅크리고 있는 아이리나의 모습은 그녀가 수줍어할 때에만 볼 수 있는 자태다. 드러낸 두 발과 아무렇게나 놓인 신발, 입고 있는 드레스는 이제 막 무도회가 끝났음을 보여준다. 마치 「신데렐라」처럼 우아한 마법의 드레스는 비록 시간과 함께 점차 사라지겠지만, 당신과 함께한 시간, 그 추억은 결코 사라지거나 빛이 바래지도 않을 것이다.",
  str_item_intro_4090263 = "존재의 의미, 허무에 대한 인식... 이 이상한 복장으로 갈아입은 후, 우리엘의 머릿속은 하루 종일 이해할 수 없는 질문이 맴돌았고, 그녀를 끝없는 생각에 빠지게 만들었다. 가상의 문학 세계에서 우리엘은 정답을 찾을 수 있을까. 비록 단정할 순 없겠지만, 적어도 당신이 해줄 수 있는 것은 그녀가 문학에 빠져 있을 때, 곁에서 함께 생각하고 느껴주는 것이다.",
  str_item_intro_4090543 = "엄숙함과 진지함, 그것은 나딘이 일에 임하는 태도다. 영원히 지치지 않을 것만 같은 그녀는 항상 노력하며 자신의 임무를 수행하고 있다. 비록 평소와는 전혀 다른 청춘의 분위기가 가득한 의상으로 갈아입었다 해도, 들고 있는 등불에도 귀여운 장식이 더해졌다 해도, 그녀의 성실한 태도를 가릴 수는 없다.",
  str_item_intro_4091113 = "해변에 도착하자 항상 울적해 하던 베릴도 눈에 띄게 편안해 보인다. 이 수영복의 스타일은 무척 심플하지만, 곧잘 베릴의 몸매를 드러내고 있다. 하지만 베릴은 이러한 점을 전혀 의식하지 못하고 모래성 쌓는 것에만 온 힘을 쏟을 뿐이다. 어쩌면 베릴에게는 그것이 바로 해변에 와서 얻은 가장 큰 수확일지도 모른다.",
  str_item_intro_4090883 = "파란 하늘, 흰 구름, 평평한 거리, 평소의 레디젤 사막과는 완전히 다른 풍경. 마지도 평소의 자신과는 다른 모습이다. 그녀는 깔끔한 세일러복을 입고 있고, 커다란 나비 리본은 바람에 흔들리고 있다. 맑은 아침, 빵을 물고 「유유」하게 자전거를 타는 그녀의 모습, 학교에 늦기라도 한 걸까? 이 멋진 옷차림은 레디젤 렌치의 관객들에게 매우 독특한 인상을 주었고, 그녀 스스로도 평소와는 다른 풍경을 볼 수 있게 해주는 듯하다. 어쩌면 그것이 바로 옷이 지닌 마력일지도 모른다.",
  str_item_intro_4090963 = "「서, 선생님? 샤리 씨야?」\n샤리는 이 아르바이트를 매우 진지하게 생각하고 있는 것 같다. 그녀는 이번 일을 위해 특별한 제복으로 갈아입었다. 지금의 샤리는 평소보다 훨씬 믿음직해 보이고, 말투도 온화하면서 무게감이 느껴진다. 아마도 이번 수업에서는 그녀에게 정말 무언가 「지식」을 배울 수 있을 것 같다.",
  str_item_intro_4091053 = "평범한 복장을 입고 있어도 이브는 레디젤 렌치의 최고 인기인이다. 그러나 그녀가 얼마나 인기가 있는지는 그녀 자신도 잘 모르는 것 같다. 모두를 응원하기로 마음먹은 그녀는 어디서 왔는지 알 수 없는 이상한 복장을 입었지만, 인기는 오히려 하늘을 찌를 만큼 높아지고 말았다. 다만 그녀를 빤히 쳐다보거나 하지 않는 게 좋을 것이다. 하늘에서 거대한 렌치가 떨어질지도 모르니 말이다.",
  str_item_intro_4090064 = "하늘하늘하고 매끄러운 실크 리본이 잔뜩인 이 옷이... 파자마라고?! 어째서 이런 상식을 초월한 디자인의 옷이 존재하는 거지? 이런 옷을 정말 사람들 앞에서 입어도 되는 건가? 카렌은 고민에 빠졌고, 어쩔 줄을 몰랐지만 우선 입어보기로 했다. 그러자 항상 지적이고 엄격한 분위기의 카렌에게 전혀 다른 분위기가 드러나게 되었다.\n파자마 파티에 참가하고, 모두와 잘 어울리기 위해 카렌은 과감한 모험을 해보기로 했다.",
  str_item_intro_4090303 = "칠흑 같은 옷에 새빨간 외투, 이른바 천하의 악인을 모조리 베는 무사, 아카나미 사메노스케 등장!\n레디젤 렌치의 대장인 사메야마는 「다른 지방에 가면 그곳의 풍속을 따른다」는 수칙을 몸소 실천했고, 입고 있는 옷뿐만 아니라 허리에 찬 검까지 모두 완벽하게 운도의 정취를 드러내고 있다. 심지어 웃음소리마저 더 호쾌해진 듯한 느낌마저 든다. 하지만 주의해야 할 점은, 이 낭인 무사는 기분이 좋아지면 즉흥적으로 하이쿠를 지어 큰 소리로 노래를 부를지도 모른다는 것이다...",
  str_item_intro_4090443 = "상쾌한 바람이 소나무 숲에 불고, 온화한 햇살이 방안을 비춘다. 도시의 소란과 번잡한 업무에서 벗어나 고요한 「운산 여관」을 찾아온 이상, 잠시 휴식을 취할 기회를 놓칠 순 없다. 「워라밸」이야말로 비비안의 신조, 이곳의 일일 점장이 되어 몸과 마음을 편하게 하면. 다시 일할 의욕도 가득해질 것이다.\n물론 이것도 모두 비비안이 세운 계획의 일부다.",
  str_item_intro_4090643 = "레이스의 새로운 전투복으로, 동방의 명주실로 짜인 천은 가볍고 몸에 잘 맞으며, 아름답게 찰랑대고 있다. 비록 조금 얇아 보이지만 움직이기 편해서 레이스의 전투 능력에 조금도 영향을 미치지 않는다.\n주먹과 발을 마음껏 움직여 용감하게 전진하고, 모든 적을 쓸어버린다. 그 어떤 위험이 닥치더라도 믿음직한 레이스는 언제나처럼 모두 해결해줄 것이다.",
  str_item_intro_4090893 = "드물게 휴가를 얻은 이리돈은 특별히 운도 스타일의 옷을 준비했다. 금빛 천과 자수에 새하얀 모피 숄을 더해 우아함과 화사함이 느껴진다. 이리돈은 이 옷을 입고 운도의 거리를 거닐거나, 열차를 타고 명승지를 둘러볼 생각에 부푼 기대를 하고 있었다.\n그러나 갑작스러운 사건이 그녀의 계획을 방해했고, 모처럼의 휴가를 지키기 위해 이리돈은 운도의 기차역에서 심판소를 개정하는 것도 마다하지 않았다.",
  str_item_intro_4090653 = "「오빠야, 퍼뜩 지랑 깃털공 치입시더!」\n잔뜩 신이 난 트위티가 깃털공과 나무채를 들고 달려왔을 때, 그 얼굴에는 필승의 미소가 드러나 있었다. 처음엔 분명히 단순한 놀이라고 생각했는데, 갑자기 절대고수들의 강력한 대결로 변모?! 화려한 서브와 강력한 스파이크, 이미 일반인은 참가할 수 없는 수준의 경기가 되고 말았다!\n패자는 벌칙으로 얼굴에 낙서를 당한다는데, 부디 트위티가 자비를 베풀어 낙서를 조금만 했으면 좋겠다...",
  str_item_intro_4090233 = "친구들이 모두 「자동차 경주」에 참가하는 것을 본 코놀리는 이에 관심이 생겼고, 비록 부끄러웠지만 치어리더 참가 제안을 받아들여 모두의 응원을 맡게 되었다. 하지만 그녀의 일상복과 비교하면 이 치어리더 유니폼은 조금 「특별」했다.\n그럼에도 불구하고 자신이 더 활기차고 쾌활해지길 바란 코놀리는 어떤 상인이 제안한 이 자유분방한 복장을 수용했다.",
  str_item_intro_4090613 = "「아... 대륙이 이런 모습이었군요!」\n구름 사이에 있는 찬드라는 고소공포증 같은 건 전혀 느끼지 않았고, 오히려 흥미진진하게 지상에서 펼쳐지는 랠리를 지켜보며 치열한 경쟁에 해설을 진행했다. 하지만... 이 열기구와 독특한 스타일의 복장은...\n사실 이 모든 것은 그녀의 신기한 「상상 치료법」의 일환일 뿐이었다. 그러나 이는 오랜 시간 쌓여 있던 타인의 마음속 부정적인 정서를 완벽하게 해소해 줄 수 있었다.",
  str_item_intro_4090843 = "「모래의 뜨거움, 물의 온기와 부드러움, 레트로와 트렌디한 스타일의 겸비」\n「품위를 저버린 거칠고 예의 없는 언사... 무례하기 짝이 없군.」\n비록 평가는 다양했지만, 이스타반이 이 옷을 입고 나타나면 모든 부정적인 의견은 모습을 감춘다. 귀족의 대저택이 아니라도 품격을 느낄 수 있는 것, 어쩌면 그것은 「섀도우마스터」가 지닌 본연의 분위기일지도 모른다. 그리고 이 옷은 그에게 묘한 매력을 더하고 있다.",
  str_item_intro_4090603 = "레이싱 경기에서 심판의 옷은 언제나 유독 눈에 띄는데, 빠른 속도로 달리는 레이서들이 심판을 볼 수 있게 하려면 반드시 눈에 잘 띄어야 하기 때문이다.\n그저 술을 마실 돈이 없을 뿐이었던 요나는 이 경기의 심판 일을 맡게 된 후 경기에 숨겨진 비밀을 금방 알아차렸고, 평소 남의 일에 잘 간섭하지 않았던 요나는 한 소녀를 위해 경주로에 뛰어들었다. 그리고 이 부당한 경기를 꾸민 악당들에게 「정의」가 무엇인지 가르쳐 주었다.",
  str_item_intro_4090713 = "무더운 날씨, 혹독한 기후, 타오르는 태양 아래서 경주용 자동차는 연기를 내고 있고, 땀방울은 사막의 모래 위에 떨어져 한순간에 증발해 버린다.\n그러나 타키는 「완전 무장」을 하고 이 경기에 참가했고, 기회를 노리는 경쟁자들을 물리치고 단숨에 우승을 차지할 생각이다. 그를 이렇게 진지하게 만든 것이 과연 그저 돈 때문일까.",
  str_item_intro_4091263 = "창작의 슬럼프에 빠진 베스트셀러 작가, 영감을 얻고자 변장을 하고 거리로 나섰다. 변장을 하는 이유? 아마 평소 위엄이 넘치는 상회의 책임자에게 이런 「소녀다운」 취미가 있다는 사실을 알리고 싶지 않아서일지도 모른다.\n하지만 이 취미에 대한 베델의 집착을 결코 우습게 봐서는 안 된다. 번뜩이는 창작의 영감을 위해서라면 그녀는 어떠한 위험도 마다하지 않을 테니 말이다...",
  str_item_intro_4090673 = "산들바람이 불자 새하얀 치마가 가볍게 흔들리고, 사이에 수 놓인 붉은 꽃이 드러난다. 앨리스의 옷은 뭔가 케이크를 떠올리게 만드는 것 같은데... 그렇다. 바로 생일에 먹을 수 있는 딸기 케이크다. 하지만 「판타지 디저트 하우스」에서는 가게 주인인 앨리스의 질문에 성실하게 답하기만 하면 무료로 원하는 디저트를 맛볼 수 있다. 이건 앨리스가 주는 특별한 벌, 아니... 특별한 「보상」이다.",
  str_item_intro_4090103 = "「깔끔한 복장은 메이드의 자존심이죠!」\n그럼 리타가 직접 만든 메이드 복으로 갈아입고, 레이스가 달린 헤어밴드를 착용할게요. 아! 맞다, 금색 나비 리본이 달린 앞치마 매는 것도 잊으면 안 되죠.\n오늘 루이스는 주인님의 몸단장뿐만 아니라 애프터눈 티도 책임질 거예요. 걱정 마세요. 아기 꿀벌, 아기 순록, 구름 아저씨가 도와주러 올 테니까요.\n저길 보세요. 메이드 아가씨가 벌써 일을 시작했네요~",
  str_item_intro_4090283 = "「흠흠, 자, 여러분! 애플턴 저택의 메이드장님을 박수로 맞이해 주세요! 네? 낯이 익다고요? 맞아요, 잘 맞히셨네요. 바로 우리의 사랑스러운 라파엘이랍니다~」\n최근 라파엘은 특별한 임무 하나를 받았는데, 바로 백야성의 메이드들이 일정 수준의 전투 기술을 습득할 수 있도록 훈련시키는 것이었다. 이제 학기가 곧 끝날 시간이 되었고, 라파엘의 세심한 지도 덕분에 메이드들은 훌륭한 성적을 거두었다. 하지만... 정작 라파엘의 메이드 수행은 왠지 그리 순조롭지 않은 것 같다.",
  str_item_intro_4091163 = "플뢰르는 자신의 기억 속 「그 빵」을 만들기 위해 많은 고민과 시도를 해 왔지만 단 한 번도 성공하지 못했다. 그리고 그는 이번 도전을 위해 더 많은 준비를 했다. 깔끔한 봉재선의 셔츠, 잘 다려진 앞치마, 광이 나게 닦인 가죽구두까지... 이렇게 차려입으면 맛있는 빵을 만들 수 있다는 소문이 있기 때문이었다. 비록 그다지 신빙성은 없는 소문이었지만, 플뢰르는 마음속에 담아 둔 근심을 위해 그것을 믿기로 결정했다.",
  str_item_intro_4090703 = "이런 눈빛에 주시된다면 분위기가 뜨거워지고, 숨이 가빠지면서... 이건 긴장감일까? 아마 그럴 것이다. 강하면서도 아름다운 레오나 앞에서 긴장하지 않는 사람은 아마 거의 없을 것이다. 가느다란 레이스업 샌들은 그녀의 두 다리를 감싸고, 평소와는 사뭇 다른 액세서리들로 몸을 장식했지만, 그녀는 나른하게 세상 모든 것이 자신의 것이라는 듯한 분위기를 드러내고 있다.",
  str_item_intro_4090813 = "렉커가 「무언가」를 찾기 위해 특별히 준비한 의상이다. 활동이 쉬운 수영복, 자신만의 개성이 담긴 서프보드, 우비의 디자인을 참고한 투명 재킷... 투명 재킷? 이 투명 재킷을 준비한 렉커의 진짜 목적은 어쩌면 당신의 칭찬을 듣기 위해서일지도 모른다. 단백질 파우더와 고된 트레이닝, 햇살과 땀으로 빚어진 이 몸은 지금 이 순간 당신의 칭찬을 기다리고 있다.",
  str_item_intro_4091123 = "최근 움브라톤에는 한 전설이 회자되고 있다. 범죄 예고장... 모든 사람을 어쩔 줄 모르게 만드는 괴도... 도둑맞은 보석... 과연 의심을 받고 있는 이 용의자는 우리 앞에서 늘 무심하게 구는 그 스모키가 맞을까? 진실을 알고 싶다면 먼저 그녀의 수갑을 풀어줘야 할 것 같다. 물론 그녀의 새 칭호인 「검은 고양이 괴도」 또한 새로운 복장만큼이나 사람들을 궁금하게 만들고 있다. 그리고 그녀는 예고한 대로 3일 뒤에 보석을 훔치러 나타날 것이다.",
  str_item_intro_4090384 = "이 옷이 만들어지고 나서 그 게임이 생긴 걸까? 아니면 그 반대일까? 이 옷의 출처는 중요하지 않다. 중요한 건 그로누가 이 옷을 입고는 휴가 모드로 들어가 버렸다는 사실이다. 다시 말해서 그로누는 휴가를 위해 이 옷을 준비했다. 비록 이번 휴가에는 해변에 간 게 아니라 수족관을 구경했지만 말이다.",
  str_item_intro_4090413 = "그녀에게는 대체 몇 가지 신분이 있는 걸까? 그녀는 백야성의 안내자일 뿐만 아니라 여러 일을 겸업하고 있는데, 그중 하나는 심지어 「플라티나 선라이즈」 호텔의 홍보 대사였다. 이 수영복은 전단지에 쓸 사진을 촬영할 때 착용한 것인데, 원단과 재단 모두 무척이나 아름답다. 이 푸른 바다와 하늘 아래, 나도 모르게 그 호텔에 가 보고 싶어진다.",
  str_item_intro_4090873 = "한 섬에 있는 영지를 시찰하러 갔을 때, 현지 환경에 더 잘 어울릴 수 있도록 베벌리는 갑옷 모양의 이 수영복으로 갈아입었다. 평소의 옷차림보다 많이 간소해지기는 했지만, 귀족의 기품만은 전혀 바래지 않았다. 아마도 이는 무예를 숭상하는 가풍의 영향도 있기는 하겠지만, 그보다는 베벌리 자신이 귀족으로서의 명예를 추구하기 때문일 것이다.",
  str_item_intro_4091293 = "여름철 특유의 시원해 보이는 복장을 하고 있지만, 루크의 진지한 눈빛은 모든 이들에게 그가 여유를 즐기기 위해서가 아니라, 반드시 해야만 하는 임무를 완수하기 위해 이곳에 왔다는 사실을 잘 알려주고 있다. 이 옷차림은 루크가 습하고 더운 숲에서도 체력을 유지할 수 있게끔 해 줄 뿐만 아니라, 부끄러운 줄 모르는 밀렵꾼들에게서 진귀한 나비를 보호하기 위해 준비한 하나의 「예복」이다.",
  str_item_intro_4091483 = "사막 속 수상 축제가 곧 시작된다. 하지만 수많은 사람들을 유독 설레게 만드는 것은 바로 시선을 도저히 뗄 수 없는 아주르의 모습을 볼 수 있다는 것! 특히 그 얇디얇은 옷차림으로 두드러지는... 크흠, 그래도 너무 오래 쳐다보는 일이 없도록 시선을 주의하는 게 좋다. 이따금 따스하면서 습한 밤바람을 느끼며, 시끄러운 음악 속에서 북적이는 사람들과 함께 춤을 추는 것도 무척 즐거운 일이니 말이다!",
  str_item_intro_4090254 = "전통 있는 귀족적인 분위기, 화려한 무대 스타일... 이 의상이 일반적인 평상복과 전혀 어울리지 않는 것은 카론이 직접 디자인한 연극 의상이기 때문이다. 과해 보이긴 하지만 카메라 앞에 서면 가장 빠르게 관객의 시선을 사로잡을 수 있고, 카론이 자신을 잃어버릴 정도로 몰입하는 것을 도와주기에, 사람들에게 잊지 못할 연기를 선보일 수 있다. 이때의 카론은 이 옷과 연기를 위해 태어난 것이라고 해도 과언이 아닐 것이다.",
  str_item_intro_4090683 = "마케팅! 마케팅! 최근 쿠리어 길드는 움브라톤의 신문사와 제휴를 맺었고, 그로 인해 쿠리어는 어쩔 수 없이 새로운 임무를 맡게 되었는데, 바로 신문 구독을 권유하는 것이었다. 그렇게 웬디는 아동복을 입게 되었는데, 이런 모습으로 신문을 들고 다니면 판매가 매우 쉽기 때문이다. 신문과 함께 날아다니는 웬디의 모습을 보니, 새로운 업무라 해도 속도를 추구하는 웬디의 정신은 절대로 그녀를 뒤처지게 하지 않을 것이다.",
  str_item_intro_4091003 = "과거에 얽매여 있던 스칼렛, 이제는 다른 옷으로 갈아입었다. 언뜻 평범해 보이는 의사지만, 들고 다니는 의료 상자는 결코 평범하지 않은 그녀의 「작업 내용」을 알게 해준다. 그녀는 환자의 병을 돌볼 뿐만 아니라, 죽은 사람에게도, 「무덤」에서 나오는 소리에도 차별 없이 일해야 하기 때문이다...",
  str_item_intro_4091203 = "이것은 쌍방의 우호를 위해 개최하는 교류 행사이다. 백야성의 헤이디는 초대를 받아 일루미나 연방의 자난성으로 향했고, 교통안전과 범죄 예방을 홍보하는 「일일 치안관」이 되었다. 이로 인해 비록 백야성의 기사지만 헤이디는 명령에 따라 일루미나의 제복을 입었다. 비록 조금은 어색한 듯했지만, 그녀만의 자신감과 매력에는 전혀 영향을 주지 않았다.",
  str_item_intro_4091193 = "추억 속의 잊을 수 없는 맛을 찾기 위해 레비는 위험을 무릅쓰고 감옥에 들어가기로 결심했다. 그곳은 회색지대에서 활동하는 범죄자들로 가득 찬 위험한 곳이었다... 일루미나 연방에서 이 혼란스러운 땅에 처음으로 발을 딛은 레비, 그녀는 이곳에서 자신의 목표를 순조롭게 달성하고, 특별한 개인 잠입 임무를 완수할 수 있을까.",
  str_item_intro_4091213 = "붉은 꽃, 가시로 뒤덮인 가지... 파로마의 복장은 낯선 이의 접근을 금지하는 분위기로 가득하며, 그 얕은 미소는 위험하고 매혹적인 기질을 더욱 강조한다. 만약 실수로 그녀를 화나게 한다면, 좋은 결말은 없을 것 같다는 생각이 든다. 마치 전설적인 움브라톤 클랜의 보스가 상대를 처리하는 것처럼 말이다. 어쩌면 지금 그녀는 이미 그 보스일지도...",
  str_item_intro_4090123 = "자난성에서 「정의 집행 a.k.a. 저지먼트」에 관한 전설이 갑자기 퍼지기 시작했다. 누군가 규율을 어길 때마다 고막을 찢을 듯한 거대한 천둥소리와 함께 네메시스가 그 앞에 나타나, 번개로 벌을 내린 뒤에 펀치라인으로 상대가 자신의 죄를 뉘우치도록 이끈다는 것이다. 「정의」를 집행한 사자는 천둥 속에서 홀연히 모습을 감춘 뒤 다른 곳으로 이동한다고 한다.",
  str_item_intro_4090773 = "휴식을 취하던 베들레헴은 우연히 천재 여가수의 이야기를 다룬 책을 읽게 되었다. 이야기에 푹 빠진 베들레헴은 자신이 마치 이야기 속 여가수가 된 것만 같았고, 그녀가 홀연히 나타나 인기를 얻고, 끝내 목소리를 잃게 되는 과정을 온몸으로 느꼈다. 「자신도 그녀처럼 될 수 있다면?」 이 문제에 베들레헴은 선뜻 대답하지 못했다. 자신이 그녀가 되는 것을 상상하고, 악기를 들어 열정적으로 창작을 하며, 마지막 무대에서 목소리를 잃게 되는 그녀의 인생을 모두 체험한 후에야, 베들레헴은 자신을 위한 미래의 가능성도 찾을 수 있었다.",
  str_item_intro_4090833 = "자신들이 지키는 「리리」를 깨우기 위해 그녀들이 할 수 있는 건... 아이돌이 되는 것? 하지만 단조로운 메이드의 규칙을 줄곧 지켜온 그녀들이 과연 아이돌 생활을 감당할 수 있을까? 아이돌이라는 것은 지칠 줄 모르는 에너지와 개성을 갖춰야 하는 법. 하지만 표준적인 프로세스가 있다면, 여기에 다양한 멤버로 구성된 그녀들의 장점을 더한다면 어쩌면 정말로 가능할지도 모른다...",
  str_item_intro_4091313 = "비록 다른 견해를 가지고 있긴 했지만, 노비오는 이날이 되면 여전히 평소와 다른 옷을 입고, 순식간에 피아니스트의 모습으로 변한다. 북방에서 힘겹게 살아가는 사람들에게 온기와 축복을 전하고, 희망을 간직한 사람들이 앞으로도 흔들리지 않고 자신의 길을 씩씩하게 나아가는 것을 응원하기 위해...",
  str_item_intro_4091383 = "상사가 억지로 참여시킨 아이돌 오디션이지만, 그래도 시오반은 착실히 여러 준비를 했다. 개인기를 갈고닦으며, 의상의 연구와 디자인에도 아낌없이 상당한 열정을 투자했다. 그리고 이 연구 정신은 시오반을 그 누구보다도 찬란하게 빛나는 전도유망한 스타로 탈바꿈시켜 주었다.",
  str_item_intro_4090273 = "백야성 연인들 사이에서는 무서운 전설이 전해지는데, 매년 관월제가 되면 흰옷을 입은 기사가 백야성 구석구석을 돌며 열애 중인 사람들을 찾아내서, 「연애 금지」 처벌 통지서를 내민다고 한다. 때문에 그녀는 연인들로부터 「사랑을 끊는 뇌광」으로 불리며 두려움의 존재가 되었다.",
  str_item_intro_4090553 = "평소의 엄숙한 옷차림과 달리 오늘의 피트만은 거리의 관월제 분위기에 영향을 받았는지, 여느 때의 의연한 분위기를 잃지 않으면서도 흔치 않은 다정함을 품고 있다. 물론 이는 그가 마음에 품은 사람을 만나기 위해서 준비한 것이 아니라, 다른 이의 염원을 이루어 주기 위한 사자로서 어울리는 복장을 선택한 것이다.",
  str_item_intro_4090913 = "크로이에게 사랑은 언제나 이별과 함께하고 있다. 그런 그녀에게 행복이 가득한 사랑을 찬양하는 곡을 연주하게 하는 것은 조금 무리가 있을지도 모른다. 그렇다면 차라리 신의 이름으로 영원한 사랑을 노래하는 것은 어떨까. 사람들이 품는 사랑은 한정된 세월과 함께 스러진다. 하지만 그것 또한 무방한 일이다. 빛은 언제나 평등하게 이 세상의 모든 사람을 축복하고 사랑해 줄 테니 말이다.",
  str_item_intro_4091673 = "이 사교 장소에는 다양한 마술이 존재하는데, 그 핵심은 바로 「비밀성」이다. 카드 한 장, 말 한마디, 한순간의 눈빛, 술잔이 오가는 찰나의 순간, 성대하고 절묘한 퍼포먼스는 이미 완성되어 있다. 비록 평소와 같은 박수갈채는 들려오지 않지만, 친구를 위해 인정을 베푸는 제노의 모습도 나쁘지 않은 것 같다.",
  str_item_intro_4090043 = "차가운 시신, 표시된 단서, 겹겹의 경계선들... 이 고전적이면서도 긴장감 넘치는 현장은 항상 사람들에게 무한한 상상을 불러일으킬 것이다. 예를 들어 형사가 범인이라거나, 이미 범인과 오래전부터 공모했다거나... 어쩌면 범인은 우리 사이에 있거나, 모든 증인이 범인일지도 모른다거나 하는 생각들 말이다. 하지만 희생자와 탐정이 애초에 한 팀이었다는 것은 누가 생각해낼 수 있을까?",
  str_item_intro_4090483 = "움브라톤의 평화로운 거리에 불길한 기운이 서서히 피어나고 있다. 지나가는 행인들은 고요한 밤을 즐기는 듯하지만, 오직 순찰대원의 경계하는 눈빛은 범죄의 흔적을 결코 놓치지 않는다. 놈들이 이 도시에 숨어 있는 한, 평화를 지키는 그녀는 결코 그 발걸음을, 순찰을 멈추지 않을 것이다. 그리고 이 모든 것은... 그녀의 하나뿐인 여동생을 위한 일이다.",
  str_item_intro_4091484 = "밝고 깨끗한 창문이 있는 사무소, 푹신한 소파, 흠뻑 취하게 만드는 멋진 와인, 그리고 소파에 누워 있는 「임시 대표」... 그녀의 게으른 태도에 속아서는 안 된다. 이 아름다운 여인은 무척이나 위험하며, 특히 곧 찾아올 사냥감에게 있어서는... 말 그대로 「위험」 그 자체라 할 수 있다.",
  str_item_intro_4091663 = "「음... 그 귀여운 녀석들은 어디 갔을까?」 환상동물들을 찾고, 진상을 밝히기 위해 피아는 탐정으로 변신해서 이 「미스터리 사건」을 조사하기 시작했다. 찾아낸 각종 증거들을 상세하게 조사하면서, 그 속에 담긴 핵심 의문점을 생각하는 그녀의 진지한 모습을 보면, 왠지 정말로 뭔가를 발견할 수 있을 것 같다는 생각이 든다.",
  str_item_intro_4090983 = "항상 집에만 틀어박혀 있었던 쿠스쿠타도 섀도우마스터의 명령 때문에 어쩔 수 없이 탐정으로서 최근 날뛰는 범죄자 체포에 나설 수밖에 없었다. 물론, 쿠스쿠타는 현장 심문이나 증거 탐문에는 그리 능숙하지 않을지도 모른다. 하지만 예리한 그녀는 가지고 있는 단서만으로 「안락의자」에 앉아 체스판을 바라보며 깊은 생각에 잠긴 끝에 범인을 추리해낼 수 있었다.",
  str_item_intro_4091034 = "세상 사람들은 죄를 저질러서는 안 된다. 죄를 지으면 하늘의 벌을 받기 때문이다. 그 벌은 세상에서 심문, 판결, 처벌의 형태로 구현되나, 그 과정은 사실 그리 무섭지 않다. 특히 심문 전문가인 엘시는 무척이나 상냥하며, 그 어떤 폭력을 사용하지 않는다. 그저 상대방의 마음의 문을 열 뿐... 물론 그 마음의 문이란 저항은 애초부터 아무 의미가 없을지도 모른다. 따라서 만약 당신이 엘시를 만나게 된다면, 저항하지 말고 모든 것을 그녀에게 맡기는 편이 나을 것이다.",
  str_item_intro_4090293 = "그 「마스터」의 유언을 들어주기 위해, 가브리엘은 이 엄숙한 드레스를 입고 움브라톤에 있는 그 고아원으로 향했다. 어두컴컴하고 낡은 환경은 정교한 복장과 선명한 대비를 이루었고, 가브리엘의 무딘 표현은 고아들이 그녀를 「마녀」로 오해하게 만들었다. 그러나 끝내 고아들은 이곳을 지키려는 가브리엘의 마음을 느낄 수 있었고, 마침 이 드레스는 마음을 위로하는 작은 빛을 발하고 있는 것 같았다.",
  str_item_intro_4090463 = "어른들에게는 무시무시한 흑마법서지만, 녀석들에게는 신비한 세계로 들어가는 입구일 뿐이다. 그곳은 환상과 마법, 불가사의가 가득한 곳으로, 녀석들처럼 호기심 많고 외로운 영혼들을 위해 준비된 곳이다. 그리고 녀석들은 그 「금단의 마법약」을 만들어 내기 위해 사방에서 온갖 기괴한 재료를 모으고 전문적인 복장으로 갈아입었고, 그 모습은 녀석들을 더욱 특별하게 만들었다.",
  str_item_intro_4090623 = "리아가 진행하는 스터디 모임을 순조롭게 진행하기 위해, 실바는 특별히 이 정장으로 갈아입었다. 마치 곧 선생님을 만나러 가는 젊은 학자처럼 총명하고, 지혜롭고, 단정하다. 그의 태도는 자연스럽게 스터디 모임에 좋은 분위기를 가져왔고, 따라서 굳이 표현하자면 그는 「모범생」이라고 할 수 있을 것이다...",
  str_item_intro_4091433 = "숲속의 밤놀이, 갑자기 내리는 뇌우, 일설에는 불길한 존재가 현세를 배회하고 있는 것이라고 한다. 때문에 린네는 엄숙한 무녀복을 입고 신악의 방울을 높이 들어, 부정함을 제거하고 중생을 지키고자 한다.\n「이제 음양을 읊노니, 이 곡조와 함께 그대의 혼은 피안으로 돌아가리라.」\n「삼도의 강물 아래에서 곡의 유생을 원망할지니.」\n「만다라가 부르나니, 금슬은 합하여 울레라.」\n「듣는 이의 넋을 달래노니, 혼백이여 스러질지어다.」",
  str_item_intro_5000001 = "먼 옛날의 정보가 들어있는 신비한 물질. 건물 건설과 가구 제작을 가속할 수 있다.",
  str_item_intro_5000002 = "헤븐즈 가든-보물 갱신 횟수",
  str_item_intro_5002101 = "단단하고 튼튼한 목재다. 건물 건설과 가구 제작에 적합하다.",
  str_item_intro_5002201 = "방금 채굴한 광석이다. 가공이 필요하긴 하지만 시장에서 어느 정도의 가치는 있다.",
  str_item_intro_5003001 = "헤븐즈 가든 곳곳에서 발견되는 돌 조각이다. 유물로 보이지만 구체적인 용도는 알 수 없다. 츄브들이 좋아하며, 이것을 가지고 다른 물건과 교환할 수 있다.",
  str_item_intro_5003101 = "건물 건설 또는 가구 제작 시 흔히 사용되는 접착제다. 소재를 잘 붙일 수 있어서 부재들을 견고하게 만든다.",
  str_item_intro_5003102 = "건물 건설 또는 가구 제작에 쓰기 좋은 접착제다. 적은 접착면으로도 접착력이 강해 부재들을 매우 견고하게 만든다.",
  str_item_intro_5011001 = "1레벨 도끼, 자루 가운데가 비어 무게가 가볍기 때문에 굵고 튼튼한 나무 줄기를 빠르게 베어낼 수 있다.",
  str_item_intro_5011002 = "2레벨 도끼, 자루 가운데가 비어 무게가 가볍기 때문에 굵고 튼튼한 나무 줄기를 빠르게 베어낼 수 있다.",
