  str_item_intro_5012001 = "1레벨 낚싯대, 무게 밸런스가 좋고 탄성이 강하다. 낚싯줄도 튼튼해서 큰 물고기를 낚을 때도 많은 도움이 된다.",
  str_item_intro_5012002 = "2레벨 낚싯대, 무게 밸런스가 좋고 탄성이 강하다. 낚싯줄도 튼튼해서 큰 물고기를 낚을 때도 많은 도움이 된다.",
