  str_item_intro_5014001 = "삽 머리를 두껍게 가공해 단단한 돌과 부딪혀도 휘지 않는다. 땅을 팔 때 훨씬 수월하다.",
  str_item_intro_5011012 = "표면이 거칠고 단단한 돌이다. 무딘 날을 날카롭게 갈 수 있다.\n가방에서 도끼를 레벨업할 수 있다.",
