  str_item_intro_5176204 = "기념의 진열장의 도면이다. 바람의 탑에서 기념의 진열장 제작 방법을 개방할 수 있다.",
  str_item_intro_5176206 = "기념의 저택 테이블의 도면이다. 바람의 탑에서 기념의 저택 테이블 제작 방법을 개방할 수 있다.",
  str_item_intro_5176207 = "기념의 귀족 의자의 도면이다. 바람의 탑에서 기념의 귀족 의자 제작 방법을 개방할 수 있다.",
  str_item_intro_5176208 = "기념의 깃발의 도면이다. 바람의 탑에서 기념의 깃발 제작 방법을 개방할 수 있다.",
  str_item_intro_5176209 = "기념의 야간등의 도면이다. 바람의 탑에서 기념의 야간등 제작 방법을 개방할 수 있다.",
  str_item_intro_5176210 = "기념의 낮은 울타리의 도면이다. 바람의 탑에서 기념의 낮은 울타리 제작 방법을 개방할 수 있다.",
  str_item_intro_5176211 = "기념의 화병의 도면이다. 바람의 탑에서 기념의 화병 제작 방법을 개방할 수 있다.",
  str_item_intro_5176212 = "기념의 덩굴 그늘의 도면이다. 바람의 탑에서 기념의 덩굴 그늘 제작 방법을 개방할 수 있다.",
  str_item_intro_5134049 = "문헌 비석의 도면이다. 바람의 탑에서 문헌 비석의 제작 방법을 개방할 수 있다.",
  str_item_intro_5211001 = "기울어진 기둥이 있는 누각이다. 지붕은 이끼로 뒤덮인 돌 조각으로, 건물의 상식에 그다지 부합하지 않는 듯하지만 실제로는 매우 견고하다.",
  str_item_intro_5211002 = "돌을 통으로 뚫어서 아치형으로 만든 것이라고 한다. 지붕에 이끼가 가득 있지만 견고함은 전혀 걱정할 필요가 없다.",
  str_item_intro_5211003 = "계곡 안에서 물자를 나르다가 잠시 쉴 수 있는 정차역이다. 건설이 빠르고 해체도 쉬워 길 중간에 많이 건설할 수 있다.",
  str_item_intro_5211004 = "지하수가 모이는 곳에 건설한 우물이다. 바닥이 보이지 않아 빠지지 않게 주변에 돌 울타리를 쳤다. 우물을 매우 깊게 파서 지하수가 맑고 시원하다.",
  str_item_intro_5211005 = "독특한 스타일의 풍차다. 크기는 작아 보이지만 풍력을 이용하기에는 충분하다! 또한 어떤 기묘한 기술을 이용한 덕분에 바람이 없어도 천천히 돌아간다.",
  str_item_intro_5221001 = "나무로 만든 울타리다. 울타리를 연결해 설치하면 헤븐즈 가든의 땅을 에워쌀 수 있다.",
  str_item_intro_5221002 = "짧은 울타리다. 아무렇게나 붙여 놓은 나무판에서 시골 분위기가 느껴진다.",
  str_item_intro_5221003 = "목조 울타리다. 제작이 편리하며, 구역을 나누는 용도로 사용하기 좋다.",
  str_item_intro_5221004 = "돌로 만든 울타리다. 무겁고 견고해서 나무 울타리보다 훨씬 오래 사용할 수 있다.",
  str_item_intro_5221005 = "돌로 만든 울타리다. 땅에 꽂기만 하면 바람이 불고 햇볕이 내리쬐어도 오래도록 사용할 수 있다.",
  str_item_intro_5221006 = "굵은 돌 울타리다. 안정적으로 보일 뿐만 아니라 알 수 없는 안전감이 느껴진다.",
  str_item_intro_5223001 = "정방형 타일이다. 가지런하게 쌓을 수 있어 주로 도로와 주요 건물 근처의 바닥을 포장하기에 적합하다.",
  str_item_intro_5223005 = "불규칙한 돌을 이어 붙여 만든 타일이다. 오솔길이나 정원을 장식하는 데 적합하다.",
  str_item_intro_5231001 = "사다리꼴 석판 2개를 다리로 사용한 탁자로, 무겁고 견고하다.",
  str_item_intro_5231002 = "작은 원형 돌 테이블이다. 알맞은 의자를 놓으면 친구 한두 명이서 이야기를 나누기에 적당하다.",
  str_item_intro_5231003 = "4개의 다리로 지탱하는 나무 테이블이다. 넓고 평평하여 많은 사람이 함께 앉아 쉬기에 좋다.",
  str_item_intro_5232001 = "둥근 돌 의자다. 중간에 돌기둥이 받치고 있어 견고할 뿐만 아니라, 가장자리가 매끄러워 모서리에 잘 부딪히지 않는다.",
  str_item_intro_5232002 = "아래가 넓고 위가 좁은 돌 의자다. 위에는 나무판을 대어 돌의 냉기를 차단했다. 시원시원한 느낌에 만들기도 쉽지만, 의자 모서리에 부딪히기 쉽다는 단점이 있다.",
  str_item_intro_5232003 = "심플하고 가벼운 의자로, 양쪽 가장자리를 지탱하는 방식으로 만들었다. 앉으면 약간 흔들린다.",
  str_item_intro_5232005 = "특이한 모양의 돌기둥에 로프를 묶고, 둥근 모양의 침대를 절묘하게 균형을 잡아서 걸어 두었다. 누우면 편안하고, 쓰러지지도 않는다.",
  str_item_intro_5232006 = "돌을 길게 이어서 만든 벤치다. 앉을 수도 있고, 누울 수도 있다. 돌로 만들어서 시원하다.",
  str_item_intro_5233001 = "큰 바위와 작은 바위를 엇갈려 놓았다. 적절한 위치에 놓으면 주변 집과 어우러져 독특한 풍경을 만든다.",
  str_item_intro_5233002 = "크게 확대한 죽순 바위처럼 보인다. 적절한 곳에 두면 색다른 느낌이 난다.",
  str_item_intro_5233003 = "각기 다른 모양의 암석으로 이루어진 무리다. 주로 길가나 정원에 장식으로 배치한다.",
  str_item_intro_5233004 = "시원한 파라솔이다. 일부러 기울어지도록 했는데, 이는 그늘을 더 많이 만들기 위함이라고 한다. 파라솔 위에는 덩굴이 가득해, 바람이 가지와 나뭇잎을 스치면 색다른 느낌을 준다.",
  str_item_intro_5233005 = "겹겹이 쌓아 올린 암석, 맑은 물로 이뤄진 작은 폭포, 무거운 돌 조각으로 둘러싸인 작은 연못, 이 세 가지가 조화를 이루고 있으며, 정원에 물소리가 끊이지 않는다.",
  str_item_intro_5233006 = "곧게 서 있는 돌기둥이다. 중심 장식으로 사용할 수 있다.",
  str_item_intro_5233007 = "삐뚤어진 돌기둥으로 이루어져 있으며, 작은 고개처럼 보인다.",
  str_item_intro_5233008 = "약간 경사진 돌기둥이다. 크기 차이가 큰 바위들 사이에 놓으면 딱 좋다.",
  str_item_intro_5233009 = "돌기둥의 끝이 뾰족하고 전반적으로 가늘어서 매서운 느낌을 준다. 어울리는 암석을 함께 배치하는 것이 좋다.",
  str_item_intro_5233010 = "기울어진 언덕처럼 보이는 바위다. 중심 장식으로 사용할 만하다.",
  str_item_intro_5234001 = "기묘한 기술을 이용해 빛을 유지하는 가로등이다. 키가 작아서 작은 구역만 비출 수 있다.",
  str_item_intro_5234002 = "기둥 하나로 지지하고 있는 가로등이다. 높은 빛으로 멀리까지 충분히 비출 수 있다.",
  str_item_intro_5234007 = "높은 화분 받침이다. 멀리서도 활짝 핀 꽃을 감상할 수 있다.",
  str_item_intro_5234009 = "상단에 방향을 가리키는 팻말이 붙어 있다. 넓은 헤븐즈 가든에서 길을 잃어버리는 불상사를 막으려면 방향을 정확히 표시해야 한다.",
  str_item_intro_5234011 = "서늘한 그늘을 만드는 파라솔이다. 무거워서 쉽게 옮길 수 없다는 것이 단점이다.",
  str_item_intro_5234012 = "태양을 바라보는 모습으로 인해 이름이 붙여졌다. 높이 뻗어 오르는 줄기와 커다란 꽃받침은 늠름한 기질을 풍기며, 누군가는 이를 「빛을 향한 마음」의 표현이라고 여기기도 한다.",
  str_item_intro_5234013 = "돌로 둘러쌓아 만든 구역이다. 바닥이 평평해서 각종 꽃의 재배에 적합하다.",
  str_item_intro_5234014 = "낮은 화분 받침이다. 길가나 문 앞 장식으로 적합하다.",
  str_item_intro_5234018 = "야외에서 사용하는 개인용 텐트다. 원뿔형 텐트는 내부의 높이가 충분하고 설치도 편리하지만, 대신 면적이 협소해서 한 사람만 사용할 수 있다.",
  str_item_intro_5234019 = "갖가지 음식들이 놓인 테이블 매트다. 바깥에서도 맛있는 식사를 즐길 수 있을 것 같다.",
  str_item_intro_5234020 = "화로 본체는 견고하고 내화성이 있으며, 바닥의 틈은 공기 흡입이 원활해 불을 더 강하게 만들어 강렬한 열기를 방출한다.",
  str_item_intro_5234023 = "잡초라 해도 낭비할 순 없다. 수집하면 다른 용도가 있을지도 모른다.",
  str_item_intro_5234024 = "목판으로 만든 상자다. 가공이 쉽고 크기가 커서 자재 보관에 매우 적합하다.",
  str_item_intro_5234025 = "여러 장의 목판 상자를 쌓아 만든 구조로, 딱 봐도 이곳이 대부분 창고라는 것을 알 수 있다.",
  str_item_intro_5234037 = "돌로 둘러쌓은 모닥불 화로대다. 야외에서 불을 피워도 화재가 발생하지 않는다.",
  str_item_intro_5234038 = "해저에서 발견된 닻이다, 매우 견고하여 큰 파도가 이는 바다에서도 배를 잘 고정할 수 있을 것 같다. 하지만 안타깝게도 주인의 종적을 알 수 없으며, 누군가가 다시 사용할 날을 조용히 기다리고 있다.",
  str_item_intro_5234039 = "물결치는 파도를 동력삼아 사용자는 자유롭게 수면 위를 나아갈 수 있으며, 다양한 동작도 할 수 있다. 헤븐즈 가든에 두는 것은 조금 아까울 정도다...",
  str_item_intro_5241002 = "앉으면 가볍게 흔들리는 그네다. 너무 높이 타지 않도록 조심하자! 이 위에서 자는 것을 좋아하는 사람도 있을 만큼 유유히 흔들리는 느낌이 확실히 편안하다.",
  str_item_intro_5241003 = "왠지 탈것 같은 느낌을 주는 장난감이다. 균형감을 키울 수 있다고 한다.",
  str_item_intro_5241004 = "연날리기는 산들바람이 부는 맑은 날에 하기 좋은 활동이다. 연을 하늘에 날린 후 선반에 묶어두면 바람에 날아가지 않는다.",
  str_item_intro_5241005 = "가벼운 이젤이다. 적당한 각도와 크기로 야외 사생용으로 쓰며, 그림에 잘 집중할 수 있도록 도와준다.",
  str_item_intro_5241006 = "무대와 스피커의 위치가 정교하게 설계되어 관객이 다양한 각도에서 공연을 관람할 수 있다. 무대에도 기이한 기술이 사용되어 가끔 프로그램에 따라 다른 특수한 효과를 낸다고 한다.",
  str_item_intro_5241007 = "한때 대륙의 모든 명승지를 전부 다녔던 한 아이테르 여성을 기리기 위해 세워졌다고 한다. 하지만 지금은 아무도 그녀의 이름을 알지 못하고, 그저 이 조각상만이 남아 후대에 기념되고 있다.",
  str_item_intro_5241008 = "볼 때마다 왠지 주먹을 날리고 싶어진다... 영원히 쓰러뜨릴 수 없다는 게 조금 아쉽긴 해도, 스트레스를 풀 수 있다면 그걸로도 나쁘지 않다.",
  str_item_intro_5241016 = "거대한 회랑이다. 회랑의 기둥은 마치 고대 생물의 뼈처럼 보인다... 누군가는 이것이 실제 콜로서스 안에 있는 중요한 구조물이었다고 한다.",
  str_item_intro_5242101 = "겉으로 보기에는 이상하지만, 독특한 구조로 실내 채광이 충분하고 공기가 잘 통해서 매우 쾌적하다.",
  str_item_intro_5243001 = "양분이 충분한 땅이다. 어떤 식물을 심어도 충분한 영양분을 줄 수 있다.",
  str_item_intro_5234008 = "마포로 만든 이 허수아비의 얼굴에는 곰보가 많이 난 것 같다. 이렇게 하면 위협 효과가 더 높아진다고 한다!",
  str_item_intro_5234015 = "천 마디 말보다 그림 한 장이 낫다. 이 표지판을 보면 그 안에 담긴 의미를 알 수 있을 것이다. 「돌무덤쥐를 해치지 마세요!」",
  str_item_intro_5234016 = "햇빛의 투사에 따라 시간을 판단하는 장치로, 시계의 초기 형태라고 할 수 있다. 단점은 흐린 날, 비 오는 날, 밤에는 사용할 수 없다는 것이다.",
  str_item_intro_5234017 = "바람의 방향을 측정하는 데 사용되는 장치로, 매우 민감해서 약한 바람도 정확하게 측정할 수 있다. 대신 바람이 너무 강하고 방향이 자주 바뀐다면 풍향계를 치우는 것이 좋다. 너무 빨리 회전하다 파손될지도 모르니 말이다.",
  str_item_intro_5234026 = "밀기 위해서는 어느 정도 힘이 필요한 맷돌이다. 오래전 사람들은 이것으로 밀가루를 만들었다고 한다. 현대에는 힘들고 비효율적으로 보이겠지만, 그래도 가끔 체력 단련용으로 사용하는 것도 나쁘지 않을 것 같다.",
  str_item_intro_5234027 = "견고하면서도 가벼운 나무통이다. 손잡이에 미끄럼 방지 처리가 되어 있어 실수로 물건을 쏟는 일을 막아준다.",
  str_item_intro_5234028 = "도자기 제품이지만 모서리 부분을 보강해 넘어지거나 파손되는 일이 적다. 또한 손잡이가 있어서 운반하기도 쉽다.",
  str_item_intro_5234029 = "혼자서도 간단하게 조작해서 천을 짤 수 있는 기계다. 대신 유지 보수가 조금 복잡하다...",
  str_item_intro_5234030 = "푸른 풀이 무성한 항아리다. 아주 무거워서 옮기려면 힘이 많이 든다.",
  str_item_intro_5234033 = "덩굴로 덮인 그늘막이다. 여름에는 그늘을 제공하고, 늦가을에도 푸르른 녹색을 감상할 수 있다.",
  str_item_intro_5234036 = "세 겹의 돌로 쌓은 화단이다. 위쪽에 꽃을 심으면 잘 보이기도 하고, 아래 두 층에 풀을 심어서 꽃을 돋보이게 만들 수도 있다.",
  str_item_intro_5241015 = "스위치를 켜고 그 위에 레코드를 올리면 음악이 재생되는 신기한 장치다. 확성 나팔을 사용해 음악이 먼 곳까지 울려 퍼진다.",
  str_item_intro_5241017 = "수조",
  str_item_intro_5251001 = "바람의 탑",
  str_item_intro_5252001 = "전시관",
  str_item_intro_5253001 = "상점",
  str_item_intro_5254001 = "희망의 연못",
  str_item_intro_5255001 = "견고하고 방수 및 방진이 되는 큰 상자다. 많은 물건을 보관할 수 있다.",
  str_item_intro_5256001 = "동료들과의 모험은 도전, 스릴, 모든 종류의 기쁨과 웃음으로 가득 차 있습니다.여정 속 잊지 못할 추억들을 기념하기 위해 동료들은 이 휘장을 만들어 이곳에 두었습니다. 이는 아이테르와 그들 자신을 위한 보상이자 기념품입니다.",
  str_item_intro_5270001 = "재배 토지",
  str_item_intro_5275001 = "사랑과 희망을 위해 온 세상에 노래를 전하자!\n순회공연을 위해 전문적으로 설계된 무대로, 빠른 건설은 물론 다양한 기능을 탑재하고 있을 뿐만 아니라, 상당히 견고한 편이라 모두 안심하고 다양한 공연을 선보일 수 있다.",
  str_item_intro_5275002 = "박자만 조금 타도 공연의 분위기를 후끈 달굴 수 있다! 밴드에 리더가 있다고 하면 그건 당연히 드러머의 차지! 그 때문에 순회공연 무대에 없어서는 안 될 악기라 할 수 있다.",
  str_item_intro_5275003 = "신나는 댄스곡은 순회공연에 없어서는 안 되는 요소로, 키보드는 조작도 쉽고 음색도 다양한 편이라 중요한 역할을 담당한다. 키보드 연주자라면 1인 밴드도 가능하다~",
  str_item_intro_5275004 = "별에 소원을 빌자! 언제부터인가 아이돌 팬들 사이에서 이런 소문이 돌기 시작했다. 이런 별 장식에 소원을 빌면 자신이 좋아하는 아이돌에게 응원의 메시지가 전해진다고 한다.",
  str_item_intro_5275005 = "아이돌을 응원하려면 다양한 응원 도구가 있어야 하기 때문에, 순회공연 무대 근처에 이런 테이블을 놓아두면 팬들이 손쉽게 다양한 응원 도구를 받을 수 있다.",
  str_item_intro_5275006 = "순회공연을 위해 준비된 다양한 기타로, 기타리스트들이 자신의 스타일에 맞는 기타를 마음대로 고를 수 있다. 또한 여러 명의 기타리스트들이 함께 연주하면서 공연의 열기를 더해 주기도 한다.",
  str_item_intro_5275007 = "순회공연에 없어서는 안 될 초대형 스피커다. 아무리 큰 공연장이나 아무리 많은 관객 앞에서도 아이돌의 목소리를 생생하게 들려줄 수 있다. 거기에 귀엽기까지~",
  str_item_intro_5275008 = "순회공연 근처에 설치된 장식이다. 바람에 휘날리는 걸 보고 있으면 아이돌과 함께 춤추는 백댄서처럼 느껴진다.",
  str_item_intro_5275009 = "순회공연 무대 근처에서 사용하는 장식용 등이다. 팬들이 아이돌을 응원하기 위해 쓰는 것 같다. 정품은 아니지만 의외로 잘 어울린다.",
  str_item_intro_5275010 = "순회공연에 아이돌 등신대가 빠질 수는 없는 법! 아이돌을 직접 만나거나 함께 기념사진을 찍을 수 없다면, 등신대라도 보면서 위안을 삼는 수밖에...",
  str_item_intro_5275011 = "생화는 축복을, 수많은 생화는 수많은 축복을 의미한다. 제대로 관리되지 않는다면 팬들이 선물한 화환으로 공연장이 파묻혔을 것이다.",
  str_item_intro_5275012 = "벽에 달린 별 장식은 팬들이 일일이 붙인 것으로, 단순한 장식품이 아니라 자신이 응원하는 아이돌의 공연이 성공하길 바라는 팬들의 축복과 사랑 그 자체라 할 수 있다.",
  str_item_intro_5275013 = "순회공연을 위해 준비한 전문 의자다. 대부분의 팬은 앉아서 응원하기보다 의자 위에 올라가서 아이돌을 응원하고 싶어 한다. 물론 그렇게 하는 데는 또 다른 이유가 있다. 아이돌이 자신을 봐주기를 바라는 간절한 바람 때문이다.",
  str_item_intro_5234043 = "폭신폭신한 눈으로 소파를 만들 수 있을까?\n그렇게 생각하는 사람이 꽤 많은 것 같다. 물론 이 소파는 평범한 소재로 만들어졌지만, 등받이가 설산의 모양을 하고 있는 데다 푹신푹신한 방석까지 더해져 정말 눈 위에 누워있는 듯한 기분이 든다.",
  str_item_intro_5234044 = "영원히 늙지 않는 신비한 생물로 알려져 있다. 이 특이한 구조 역시 그 전설에서 착안한 것으로, 조금만 쳐다봐도 자신도 모르게 빠져든다.",
  str_item_intro_5234045 = "「하늘 끝이나 땅 끝이라 해도, 반드시 그리움과 염원을 전한다!」 이 우편함은 그러한 취지에서 만들어졌다고 하며, 이를 통해 그리움의 거리를 줄여준다.",
  str_item_intro_5234046 = "직접 하기 어려운 말이 있다면 편지에 써서 여기 놔 보자. 상대방이 편지를 보고 알 수도 있다.",
  str_item_intro_5276001 = "「관월제」에 설치하는 단상이다. 각종 모임, 특히 마음이 하나가 된 사람들의 결혼식에 아주 적합하다.",
  str_item_intro_5276002 = "기념일 나들이를 가거나, 이것을 타고 신랑 신부의 마중을 나갈 때에도 좋다. 분위기와 스타일, 편리함까지 모두 갖춘 최고의 차량이다.",
  str_item_intro_5276003 = "새로 떠오르는 놀이방식인 듯하다. 커플이라면 몇 바퀴 돌고 내려와서도 상대방을 배려하는 모습을 통해 서로의 감정을 확인할 수 있다.",
  str_item_intro_5276004 = "정자의 장미는 특별한 재배 과정을 거쳐 관월제에만 피며, 이곳을 찾은 신랑 신부들을 축복한다.",
  str_item_intro_5276005 = "초콜릿 본연의 맛은 쌉쌀하다. 단맛은 설탕으로 내는 것이다. 어쩌면... 이것이 바로 어떤 감정의 참뜻일까? 어쨌든 이제는 관월제의 상징적인 선물 중 하나가 되었다. 아마 그건 아마 대부분의 사람이 단맛만 기억하고 쓴맛은 잊어버리기 때문일 것이다.",
  str_item_intro_5276006 = "독특한 모양의 아치 위에 각양각색의 꽃들이 수놓아져 있다. 신랑 신부들이 기념사진을 찍거나 소원을 빌기에 안성맞춤이다.",
  str_item_intro_5276007 = "「관월제」에 자주 등장하는 장식이다. 음료가 가득 담긴 높은 잔들로 구성되어 있으며, 손님 접대용으로 사용된다.",
  str_item_intro_5276008 = "펄럭이는 유선형 조형의 촛대는 보는 이에게 시각적 즐거움을 제공하며, 그 빛을 사방으로 분산시켜 신랑 신부의 결혼식에 낭만을 더하기도 한다.",
  str_item_intro_5276009 = "아마 모든 결혼식 사회자에게 가장 「이상적인 커플」일 것이다... 이걸로 두 신랑 신부의 서약은 물론, 음악까지 잘 들려줘 행사장 분위기를 돋울 수 있다.",
  str_item_intro_5276010 = "굳이 「관월제」가 아니더라도 이런 벤치는 연인들이 앉기에 안성맞춤이다. 「관월제」 당일이 되면 아마 커플들로 가득 찰 것이다.",
  str_item_intro_5276011 = "어라? 이 둘이 원래 커플이었나? 아... 명절이라 옷만 바꿨을 뿐이지만, 왠지 잘 어울리는 것 같기도 하다.",
  str_item_intro_5276012 = "선물용으로나 장식용으로나 「관월제」에 제격이다. 잔치에 화사한 색감을 더하고, 하객들에게는 은은한 향기를 선사한다.",
  str_item_intro_5276013 = "장미를 깔아 만든 카펫이다! 이런 호화로운 대접은 이 자리를 준비한 주최자의 마음가짐을 보여준다. 아마 신랑 신부들이 지나갈 때 모든 내빈의 주목을 받게 만들기 위한 것 같다.",
  str_item_intro_5276101 = "복고풍 모양의 테이블과 의자 세트다. 다행히 여전히 앉기 무척 편안하며, 특히 추리와 같은 대화를 할 때 매우 적합할 것 같다. 아마 이것도 모두 그 명탐정의 영향일 것이다.",
  str_item_intro_5276102 = "그 명탐정은 종종 이 상황판에서 정보를 취합하고, 단서를 정리해서 분석한다고 한다. 심지어는 이런 단계만으로도 범인을 찾아낼 수 있다고 한다.",
  str_item_intro_5276103 = "그 명탐정이 유명해진 이후로, 그가 가장 좋아하는 자동차도 인기를 얻게 되었다. 내구성이 좋고 튼튼하며, 속도도 빠르고, 다루기도 쉬운 차량은 누구나 좋아하기 마련이다.",
  str_item_intro_5276104 = "「생각이 막히면 커피 한 잔, 그래도 모르겠다면 한 잔 더.」 커피는 사색의 가장 좋은 동반자다. 그 명탐정은 커피 용품을 선택할 때 절대로 돈을 아끼지 않는다고 한다.",
  str_item_intro_5276105 = "범죄는 대부분 추운 밤에 일어나는 것 같다. 명탐정은 보통 트렌치코트와 모자를 착용하는데, 따라서 이 옷걸이는 방에 없어서는 안 될 필수품이다.",
  str_item_intro_5276106 = "작고 가벼운 트롤리에는 커피와 애프터눈 티를 위한 다과가 채워져 있으며, 손님을 접대할 때 하인들이 빠르게 다양한 음식을 준비할 수 있어 편리하다.",
  str_item_intro_5276107 = "추리의 영감이 고갈되거나 생각의 미로에 갇혔을 때 명탐정은 이 악기를 사용해 긴장을 풀곤 하며, 그런대로 괜찮은 그의 연주 소리가 온 거리에 퍼지곤 한다. 다행히 사람들이 신경 쓰는 것은 음악의 수준이 아니라 명탐정의 전설이며, 덕분에 이 악기도 덩달아 인기가 많아졌다.",
  str_item_intro_5276108 = "높은 등받이와 푹신한 방석은 사람들이 좋은 자세를 유지하면서도 최대한의 편안함을 느낄 수 있게 해 주어 「긴장을 풀고 생각하는」 탐정에게 매우 적합하다.",
  str_item_intro_5276109 = "많은 파이프를 둘 수 있는 선반으로, 독특한 모양을 가지고 있으며, 집에서 「탐정 스타일」을 연출할 수도 있다. 물론 이것은 모두 추리광들이 그 명탐정을 따라 하는 것이며, 심지어는 담배를 피우지 않으면서도 장식으로 두고 있다.",
  str_item_intro_5276110 = "「어떤 단서도 놓쳐선 안 된다!」 진상은 때때로 매우 사소한 곳에 숨어 있기도 한다. 따라서 이러한 돋보기는 명탐정의 필수품이다.",
  str_item_intro_5276111 = "밝기와 지속시간 모두 뛰어난 랜턴이다. 바람도 막아주고, 무게도 가벼워서 한 손에 들고 다니기 좋다. 물론 바닥에 두어도 전혀 문제없다.",
  str_item_intro_5276112 = "이 작은 추리판은 높이가 비교적 낮으며, 명탐정이 소파에 앉아서 사건을 정리할 때 사용할 수 있다. 빠른 분석에 도움을 주는 좋은 조수다.",
  str_item_intro_5276113 = "이 두 발 달린 책꽂이의 모양은 제법 특이한데, 명탐정은 이를 무척 좋아했다. 역시 남다른 사람은 취향도 남다른 모양이다. 물론 탐정 애호가라면 반드시 집에 하나쯤 있어야 하는 물건이다.",
  str_item_intro_5276114 = "비가 오는 날씨든, 뜨거운 태양이든, 우산은 매우 좋은 피난처가 되어 준다. 게다가 비상시에는 무기로도 사용할 수 있다. 따라서 다양한 우산을 수납하기 위해서는 이런 우산꽂이를 현관에 둘 필요가 있다.",
  str_item_intro_5234047 = "「폭설로 고립된 산장에 작가를 가둬 두면 그 창작 효율은 10배로 증가한다.」 이것은 많은 움브라톤 편집자들의 신조 중 하나인 것 같다. 하지만 그로 인해 이 타자기가 무척 유행하게 되었고, 이제는 글 쓰는 사람들의 필수품으로 자리 잡았다.",
  str_item_intro_5234048 = "움브라톤에 스타일리시한 사무소를 차리고 싶다면 이런 소파는 필수다. 현실이든 이야기 속이든 사무소의 대표는 이런 소파에 앉아서 손님을 맞이하고, 면담을 하거나, 어떤 거래를 하기도 한다.",
  str_item_intro_5223003 = "원형으로 된 소형 타일이다. 잔디밭과 길가를 꾸미는 데 딱이다.",
  str_item_intro_5223004 = "비교적 큰 형태의 원형 타일이다. 도로 포장뿐만 아니라 도로 디자인의 주요 구성 요소로 사용될 수 있다.",
  str_item_intro_5351001 = "헤븐즈 가든에서 가장 잘 보이는 건물이자 이곳의 랜드마크다. 헤븐즈 가든 재건을 위한 재료가 대량으로 보관되어 있다.",
  str_item_intro_5351002 = "헤븐즈 가든에서 가장 잘 보이는 건물이자 이곳의 랜드마크다. 헤븐즈 가든 재건을 위한 재료가 대량으로 보관되어 있다.",
  str_item_intro_5351003 = "헤븐즈 가든에서 가장 잘 보이는 건물이자 이곳의 랜드마크다. 헤븐즈 가든 재건을 위한 재료가 대량으로 보관되어 있다.",
  str_item_intro_5352001 = "각종 물품과 기록을 보관하고 지식을 보급할 수 있는 전시용 건물이다.",
  str_item_intro_5352002 = "공간이 기존보다 넓어졌고, 조금 더 장식이 추가되었다. 진열품을 편리하게 관람할 수 있다.",
  str_item_intro_5352003 = "더 많은 방을 갖춘 전시관이다. 공간도 많아졌을 뿐만 아니라 더 편리하게 분류할 수 있게 되었다.",
  str_item_intro_5353001 = "헤븐즈 가든에서 거래를 진행하는 장소다. 일반 매매도 가능할 뿐만 아니라 비밀 주문도 이루어지는 곳이다.",
  str_item_intro_5353002 = "풍성한 유선형의 외관 장식을 추가해 전보다 훨씬 화려해졌다.",
  str_item_intro_5353003 = "방이 굉장히 많은 상점으로, 전문적으로 거래에 사용되는 호화 저택이라 할 수 있다.",
  str_item_intro_5354001 = "맑은 샘물에서 아름다운 물고기도 감상할 수 있고, 주화를 던져 소원도 빌 수 있다.",
  str_item_intro_5354002 = "큰 연못이다. 교차하는 물결 아래 움직이는 물고기를 감상할 수 있고, 소원을 비는 것도 더욱 영험해진 것 같다.",
  str_item_intro_5354003 = "분수는 물고기에게 흐르는 물을 공급해주고, 소원도 들어준다고 한다.",
  str_item_intro_5355001 = "견고하고 방수 및 방진이 되는 큰 상자다. 많은 물건을 보관할 수 있다.",
  str_item_intro_5276201 = "일반적으로 백야성 공작을 위해 지어지는 홀이다. 상류 귀족의 기품을 과시하고, 알현하는 자들을 압도해 무의식적으로 긴장하게 만들기에 충분하다. 물론 앉은 사람도 충분히 기품이 있어야 한다.",
  str_item_intro_5276202 = "「작은 수정구슬 속 또 다른 세계」. 이 수정구슬에는 한 도시의 「환상」이 들어 있다고 한다. 다만 누군가에게는 매우 소중한 추억이었을 것이다.",
  str_item_intro_5276203 = "「강한 자에게는 강하게, 약한 자에게는 약하게」. 기사는 백야성의 초석이자 깃발이다. 이름도 모르는 이의 조각상이지만, 그 우뚝 솟은 자태를 보면 평범한 사람도 기사도 정신이 솟아난다.",
  str_item_intro_5276204 = "「모름지기 수집품은 전시해야 하는 법. 창고에 숨겨두면 되려 낭비이다」. 장식이 화려한 진열장이다. 아름다운 외관은 물론, 튼실하고 실용적이기까지 해 수집품 전시에 적합하다.",
  str_item_intro_5234049 = "「글을 비석에 새기면 만 년을 남길 수 있다」. 비석은 조각된 뒤로 100년이 지나 도시가 황폐해지고 문명이 시들어도, 그 자리에 서서 당시의 모습을 보여준다. 아마 그것이 바로 비석의 존재 의미일 것이다.",
  str_item_intro_5276206 = "백야성 귀족 저택에서 주로 사용되는 긴 테이블이다. 크고 튼튼하며, 기품도 있어 손님이나 친구 접대, 가족 모임과 중요 회의에 관계 없이 두루 사용할 수 있다.",
  str_item_intro_5276207 = "백야성 귀족 저택에서 흔히 볼 수 있는 높은 등받이 의자다. 편안함은 기본이며, 앉은 사람들이 격식을 잃지 않고 바른 자세를 유지할 수 있게 도와주기까지 한다.",
  str_item_intro_5276208 = "백색의 깃발, 백색의 도시. 이는 백야성의 상징으로, 보기만 해도 백야성의 기사, 귀족, 하늘과 문명을 떠올리게 한다.",
  str_item_intro_5276209 = "사람들에게 영원히 꺼지지 않는 불이라는 인식을 주며, 이는 백야성의 강력한 루미나틱스 덕분인 것도 사실이다.",
  str_item_intro_5276210 = "아담한 모양의 낮은 울타리다. 외부인의 출입을 막기 위함보다는 귀족 저택과 정원을 경계 짓기 위한 용도다.",
  str_item_intro_5276211 = "작은 화분이라도 백야성의 것은 남다르다. 화병은 모양이 높고 정교하며, 식물마저 크고 무성하다. 하늘 위에 있어서 그런지 햇빛을 충분히 받은 것 같다.",
  str_item_intro_5276212 = "덩굴이 무성하게 자라서 다리를 가득 채웠다. 어긋난 듯 질서정연하고 적당히 맞물린 틈 사이로 햇빛이 살짝 비친다. 산들바람이 불면 여유롭게 차를 즐기기에 좋은 장소다.",
  str_item_intro_5234050 = "진짜 관람차처럼 웅장하진 않지만, 보기엔 충분히 크다. 다만 탑승할 수는 없어서, 멀리서 돌아가는 모습을 보며 관람차를 타던 느낌을 회상해 볼 뿐이다.",
  str_item_intro_5234052 = "남색 마감에 거대한 물탱크, 사막에서 이 물건은 더 이상 전투의 화신이 아니라 빗물을 뿌리는 은혜의 신이며, 가뭄에 시달리는 사람들을 위해 상쾌함을 가져다준다.",
  str_item_intro_5234053 = "마치 살아있는 듯한 조각상이다. 언뜻 보면 불쌍한 새가 모래에 뒤덮인 것 같은 모습인데, 중요한 것은 물에 젖지 않도록 주의해야 한다는 점이다. 그렇지 않으면 모래와 함께 「사라져」 버릴 테니 말이다.",
  str_item_intro_5234054 = "이 의자... 앉아도 되긴 하는 걸까? 꽃은 아름다워 보이지만, 의자 곳곳에 달린 가시가 「바른 자세로 앉지 않으면 다칠 겁니다」라고 경고하고 있다.",
  str_item_intro_5400001 = "환상수의 재배 시간을 크게 단축시키는 신비한 액체다. 쉽게 휘발되므로 반드시 병에 담아 보관해야 한다.",
  str_item_intro_5400002 = "최고급의 환상수에서 추출한 수액을 섞은 것으로 보이며, 제련 후 신비한 공식을 추가하여 만든 점성질의 액체다. 최고급 환상수의 품종을 변화시킬 수 있다.\n외형: 노란색 침전물이 섞인 점성 있는 녹색 액체.",
  str_item_intro_5401001 = "환상수 C-B 100% 돌파 아이템",
  str_item_intro_5401002 = "환상수 B-A 100% 돌파 아이템",
  str_item_intro_5401003 = "환상수 A-S 100% 돌파 아이템",
  str_item_intro_5402001 = "환상수 C-B 지정 돌파 아이템",
  str_item_intro_5402002 = "환상수 B-A 지정 돌파 아이템",
  str_item_intro_5402003 = "환상수 A-S 지정 돌파 아이템",
  str_item_intro_5403001 = "드물게 보이는 작은 결정체다. 여러 가지 색으로 빛나며, 안에 담긴 힘으로 환상수의 색을 다양하게 바꿀 수 있다.",
  str_item_intro_5403002 = "환상수 염색 크리스탈Ⅱ",
  str_item_intro_5403003 = "환상수 염색 크리스탈Ⅲ",
