  str_item_intro_5415421 = "[희귀종] 안개의 버섯나무 씨앗이다.",
  str_item_intro_5415422 = "[희귀종]적색 안개의 버섯나무 씨앗이다.",
  str_item_intro_5415423 = "[희귀종] 남색 안개의 버섯나무 씨앗이다.",
  str_item_intro_5415431 = "[희귀종] 장막의 버섯나무 씨앗이다.",
  str_item_intro_5415432 = "[희귀종] 녹색 장막의 버섯나무 씨앗이다.",
  str_item_intro_5415433 = "[희귀종] 적색 장막의 버섯나무 씨앗이다.",
  str_item_intro_5421111 = "오색 결정으로 키워낸 붉은색 쿤란나무다. 왕성한 생명력을 가진 것 같다.",
  str_item_intro_5421112 = "막 자라난 기본종 쿤란나무다. 딱히 특이한 점은 없어 보이지만, 산들바람이 불면 기묘한 소리를 낸다.",
  str_item_intro_5421113 = "오색 결정으로 키워낸 노란색 쿤란나무다. 조금 쓸쓸한 느낌이 난다.",
  str_item_intro_5421211 = "미세하게 변이한 작은잎 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 붉은 마노의 빛깔과 비슷하다.",
  str_item_intro_5421212 = "미세하게 변이한 우량종 쿤란나무다. 잎이 작고 밀집해 있어 붙여진 이름이다.",
  str_item_intro_5421213 = "미세하게 변이한 작은잎 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 노란 잎이 산들바람에 흔들리면 기묘한 파도가 일렁인다.",
  str_item_intro_5421221 = "미세하게 변이한 큰잎 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 모든 잎이 얇은 붉은색 크리스탈처럼 보인다.",
  str_item_intro_5421222 = "미세하게 변이한 우량종 쿤란나무다. 나뭇잎이 크고 단단해서 그대로 옷을 만들 수 있을 정도다.",
  str_item_intro_5421223 = "미세하게 변이한 큰잎 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 나무 전체에 가을의 분위기가 감돈다.",
  str_item_intro_5421311 = "여러 차례의 변이를 거친 특산종 쿤란나무다. 수관은 둥글고 나뭇잎은 반들반들하여 특별한 멋이 있다.",
  str_item_intro_5421312 = "여러 차례의 변이를 거친 온화한 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 남색 수관이 무척 보기 좋다.",
  str_item_intro_5421313 = "여러 차례의 변이를 거친 온화한 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 노란 나뭇잎이 겹겹이 쌓여 강풍이 불어와도 흩어지지 않는다.",
  str_item_intro_5421321 = "여러 차례의 변이를 거친 해맺이 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 붉은색 수관은 더욱 불이 타오르는 것처럼 보인다.",
  str_item_intro_5421322 = "여러 차례의 변이를 거친 특산종 쿤란나무다. 수관이 무성하고 가지가 굵어 넘치는 활력을 가지고 있다.",
  str_item_intro_5421323 = "여러 차례의 변이를 거친 해맺이 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 멀리서 보면 파란 수관이 호수처럼 마음을 고요하게 한다.",
  str_item_intro_5421331 = "여러 차례의 변이를 거친 찬가지 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 분홍색 나뭇잎이 수관, 나무줄기와 어우러져 봄의 기운을 풍긴다.",
  str_item_intro_5421332 = "여러 차례의 변이를 거친 찬가지 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 붉은색 수관이 차가운 분위기와 강렬한 대조를 이룬다.",
  str_item_intro_5421333 = "여러 차례의 변이를 거친 특산종 쿤란나무다. 들쭉날쭉한 나뭇잎은 차갑지만 냉염한 분위기가 느껴진다.",
  str_item_intro_5421341 = "여러 차례의 변이를 거친 언갈퀴 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 파란색 수관이 본래의 시린 기운에 차가움을 한층 더해준다.",
  str_item_intro_5421342 = "여러 차례의 변이를 거친 특산종 쿤란나무다. 나뭇잎 끝이 날카롭고 불규칙하게 돌출되어 있어, 바람이 불면 칼날이 춤추듯 살을 에는 추위가 느껴진다.",
  str_item_intro_5421343 = "여러 차례의 변이를 거친 언갈퀴 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 옅은 노란색 나뭇잎이 시린 기운을 누그러뜨리고 약간의 따스함을 더해준다.",
  str_item_intro_5421411 = "복잡한 변이를 거친 하늘바라기 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 푸른색 수관이 순결한 사제가 하늘을 향해 기도하는 것처럼 보여 「기도하는 쿤란나무」라고도 불린다.",
  str_item_intro_5421412 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 쿤란나무다. 하늘을 향해 뻗은 나팔 형태를 이루고 있으며, 가냘픈 줄기가 어떻게 거대한 수관을 버티는지 알 수 없다. 이상한 힘이 있다는 것 말고는 설명할 방법이 없다.",
  str_item_intro_5421413 = "복잡한 변이를 거친 하늘바라기 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 노란색 나팔 형태의 수관은 마치 구리 나팔처럼 보인다. 먼 옛날 거인들이 실제로 이것으로 연주했다고 해서 「나팔 쿤란나무」라는 이름도 가지고 있다.",
  str_item_intro_5421421 = "복잡한 변이를 거친 반석의 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 초록색 수관 위에 서 있으면 벌판 언덕에 있는 듯한 착각이 들어서 「언덕 쿤란나무」라고도 불린다.",
  str_item_intro_5421422 = "복잡한 변이를 거친 반석의 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 순백의 수관이 매우 가지런해 위에서 편히 잠들 수 있을 것만 같다.",
  str_item_intro_5421423 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 쿤란나무다. 매우 귀한 수종이며, 수관이 딱딱하게 굳어 작은 돌 받침이 되었다. 나무줄기 속에 나무를 지탱해주는 돌기둥이 있다고 한다. 하지만 그저 돌기둥을 두꺼운 나무껍질이 감싸고 있을 뿐인 이런 환상수를 식물로 불러도 될지는 논의가 필요할 것 같다.",
  str_item_intro_5421431 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 쿤란나무다. 굉장히 희귀한 수종이며, 비단 모양의 부드럽고 가는 나뭇잎이 한 데 엉켜 있다. 전설 속 떠도는 영혼처럼 보이기도 한다. 누군가는 이 쿤란나무에 의식뿐만 아니라 심지어 영혼도 있다고 말한다...",
  str_item_intro_5421432 = "복잡한 변이를 거친 영혼의 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 붉은색 수관이 불길해 보이지만 치명적인 매력이 있다. 가볍고 부드러운 잎이 바람에 흔들리면 금세 빠져들어 몇 날 며칠이라도 보게 된다.",
  str_item_intro_5421433 = "복잡한 변이를 거친 영혼의 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 노란색 나뭇잎이 작은 리본 같아서 수관이 흔들릴 때면 누군가를 환영하듯 보여 「손님맞이 쿤란나무」라고도 불린다.",
  str_item_intro_5421441 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 쿤란나무다. 굉장히 희귀한 수종이며 잎이 서로 교차해 거대하고 촘촘한 수관을 형성한다. 때때로 잎이 밖으로 날아가 「낙엽의 비」가 내리는 듯한 기묘한 풍경을 이룬다.",
  str_item_intro_5421442 = "복잡한 변이를 거친 번성의 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 녹색의 수관은 생명력이 넘쳐 보인다. 게다가 아래로 드리운 가지에 다가가면 가지가 약간 떨리며, 온 나무가 「사사삭」거리는 소리를 내는데, 마치 방문자에게 대답하는 것처럼 보인다...",
  str_item_intro_5421443 = "복잡한 변이를 거친 번성의 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 남색 나뭇잎이 떨어질 때 아래에 서 있으면 마치 바닷속에 있는 듯한 착각이 들어서 「육지의 바다 쿤란나무」라고도 불린다.",
  str_item_intro_5421451 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 쿤란나무다. 매우 희귀하며, 생명력이 왕성해서 잘린 후에도 다시 자랄 수 있다고 한다. 이로 인해 「결코 굴복하지 않는 강자」라고도 불린다.",
  str_item_intro_5421452 = "복잡한 변이를 거친 불굴의 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 황갈색 잎사귀에는 노화의 흔적이 보인다. 하지만 그 생명력은 오히려 더 강인해서, 물을 주지 않아도 생존할 수 있다고 한다.",
  str_item_intro_5421453 = "복잡한 변이를 거친 불굴의 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 성장이 빨라서 거의 하룻밤 사이에 남색 잎의 수관을 이룰 수 있다고 한다. 이로 인해 「끝없는 쪽빛 수해」라는 별명이 붙었다.",
  str_item_intro_5421461 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 쿤란나무다. 매우 희귀하며, 뿌리 양쪽에서 자라나 줄기가 공중에서 고리 모양을 이루어 마치 나무로 만들어진 문처럼 보인다. 때문에 「쿤란의 문」이라고도 불린다.",
  str_item_intro_5421462 = "복잡한 변이를 거친 고리그루 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 남색 수문에는 가끔씩 수증기가 흘러넘친다. 겨울에는 눈꽃을 맺기도 하며, 멀리서 보면 마치 얼음으로 이루어진 것처럼 보인다.",
  str_item_intro_5421463 = "복잡한 변이를 거친 고리그루 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 붉은 수문이지만 보는 이에게 두려움을 주지 않으며, 오히려 마음속에 따스한 평안함이 생겨난다. 누군가는 이 나무가 심은 이에게 행운을 준다고도 한다.",
  str_item_intro_5421471 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 쿤란나무다. 갈라진 나무줄기와 산들바람에 한들거리는 수관이 있고, 여기에 이슬이 맺히면서 물줄기를 이루고 있다. 보는 사람에게 마음의 안정을 가져다주는 매력이 있다고 하여 「여유로운 쿤란」이라고 불린다.",
  str_item_intro_5421472 = "복잡한 변이를 거친 치유의 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 맺힌 이슬은 푸른빛을 띠고 있어 멀리서 보면 마치 얕은 바다에 잠긴 것 같다고 하여 「바닷가 휴식의 땅」이라고도 불린다.",
  str_item_intro_5421473 = "복잡한 변이를 거친 치유의 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 보랏빛 이슬이 나무에 신비로운 기운을 더한다. 이 때문에 산들바람에 유유자적해 보이는 흔들리는 자태가 한층 매혹적으로 변한다.",
  str_item_intro_5421481 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 쿤란나무다. 우뚝 선 나무줄기 위에 불꽃 모양의 수관이 자리 잡고 있어 거대한 불꽃 나무를 연상시킨다. 그 때문에 누군가는 쿤란나무를 조명물로 착각했을지도 모른다.",
  str_item_intro_5421482 = "복잡한 변이를 거친 횃불 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 커다란 분홍색 수관이 마치 기묘한 안개가 나뭇가지 끝에 걸린 듯한 모습을 연상시킨다. 바람이 불면 「분홍색 안개」 수관이 불규칙하게 변해 색다른 느낌을 준다.",
  str_item_intro_5421483 = "복잡한 변이를 거친 횃불 쿤란나무다. 오색 결정 재배를 통해 얻은 품종으로, 이름 그대로 「횃불」을 연상시키는 붉은 수관을 지녔다. 특히 바람에 춤추는 모습은 거센 불길을 보는 듯한 착각마저 일으킨다!",
  str_item_intro_5422111 = "오색 결정으로 키워낸 연녹색 애시르나무다. 한층 더 우뚝 솟아 도도하면서도 봄의 기질을 지니고 있다.",
  str_item_intro_5422112 = "오색 결정으로 키워낸 진녹색 애시르나무다. 형태가 둥그스름해 보는 사람의 마음을 차분하게 만든다.",
  str_item_intro_5422113 = "방금 자라난 기본종 애시르나무다. 딱히 특이한 점은 보이지 않는다. 우뚝 솟은 중심 줄기와 촘촘한 가지, 그리고 위로 자라나는 바늘 모양의 나뭇잎이 유일하게 다른 점이다.",
  str_item_intro_5422211 = "미세하게 변이한 짧은잎 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 붉은색 침엽은 매우 짧다. 잎이 바닥에 떨어지면 나무 밑에 카펫을 깐 것처럼 보여 무척 예쁘다.",
  str_item_intro_5422212 = "미세하게 변이한 짧은잎 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 짧고 작은 침엽에는 초록색 무늬가 있어 알록달록한 에메랄드 같다.",
  str_item_intro_5422213 = "미세하게 변이한 우량종 애시르나무다. 원래의 애시르나무와 비교해 크게 달라졌다. 가지가 밖으로 뻗으면서 수관이 줄고, 나뭇잎도 짧고 굵어졌다. 특별한 표식이 없으면 애시르나무가 변이한 것이라고 알 수 없을 정도다.",
  str_item_intro_5422221 = "미세하게 변이한 긴잎 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 나뭇잎이 떨어지면 빠르게 말라서 밟으면 「바스락」거리는 소리가 난다.",
  str_item_intro_5422222 = "미세하게 변이한 긴잎 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 가늘고 긴 잎은 부드러우면서 질겨 많은 사람이 펜대로 즐겨 사용한다.",
  str_item_intro_5422223 = "미세하게 변이한 우량종 애시르나무다. 외형이 아주 크게 변했다. 가지가 무성하게 자라고 나뭇잎은 가늘어져 우뚝 솟은 애시르나무가 변이한 것이라고 상상하기 어렵다.",
  str_item_intro_5422311 = "여러 차례의 변이를 거친 특산종 애시르나무다. 수관과 줄기가 하나로 어우러져 산봉우리의 반석처럼 보인다. 표면이 단단하고 속은 비어서 두드리면 기묘한 울림이 있다.",
  str_item_intro_5422312 = "여러 차례의 변이를 거친 산고개 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 줄기 한쪽의 초록색 무늬 때문에 이끼가 붙었다는 오해를 받곤 한다.",
  str_item_intro_5422313 = "여러 차례의 변이를 거친 산고개 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 일부 나무껍질이 약간의 붉은색을 띄고 있어 무서운 전설이 있지만, 모두 터무니없는 소리다.",
  str_item_intro_5422321 = "여러 차례의 변이를 거친 특산종 애시르나무다. 수관이 처진 데다 길고 부드러운 줄기도 늘어져 멀리서 보면 작은 숲처럼 보인다. 그래서 「고독한 숲」이라는 별명이 있다.",
  str_item_intro_5422322 = "여러 차례의 변이를 거친 고독한 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 붉은색의 거대한 수관이 우산을 씌운 듯 햇빛을 가려 시원한 그늘을 만든다.",
  str_item_intro_5422323 = "여러 차례의 변이를 거친 고독한 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 초록색의 거대한 수관에 늘어진 굵은 줄기가 더해져, 안에 있으면 작은 숲에 잘못 들어갔다고 착각할지도 모른다.",
  str_item_intro_5422331 = "여러 차례의 변이를 거친 황야의 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 조금 처량한 느낌이 나는 수관과 갈라진 나무줄기 때문에 말라 죽은 것으로 볼 수 있지만, 우뚝 선 나무를 보면 생각이 달라질 것이다.",
  str_item_intro_5422332 = "여러 차례의 변이를 거친 특산종 애시르나무다. 황야에서 자주 보이는 시든 나무 같아 붙여진 이름이다. 그러나 비틀어진 줄기에서 자라난 작은 수관이 강인한 생명력을 보여주며, 모두에게 「나는 살아있어」라고 말하는 것만 같다.",
  str_item_intro_5422333 = "여러 차례의 변이를 거친 황야의 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 초록색 수관과 마른 가지가 강렬한 대비를 이뤄 한 나무인지 의심도 들지만, 둘 다 황야의 애시르나무 한 그루에서 나온 것이 맞다. 이게 이 환상수의 매력일 지도 모른다.",
  str_item_intro_5422341 = "여러 차례의 변이를 거친 샘물의 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 즙은 담황색을 띄며, 처음 입에 넣고 씹으면 딱딱하지만 뒷맛은 달콤하다. 체력 회복에 좋다고 하지만 너무 많이 마시면 어지러울 수 있다.",
  str_item_intro_5422342 = "여러 차례의 변이를 거친 특산종 애시르나무다. 나무뿌리에는 천연 연못이 형성되어 있고, 수관 끝에서는 끊임없이 물이 떨어져서 이러한 이름을 얻었다. 이 나무의 신비한 순환은 지금까지도 미지수이며, 그저 연못의 물을 마시면 느껴지는 기이한 힘에 감탄할 뿐이다.",
  str_item_intro_5422343 = "여러 차례의 변이를 거친 샘물의 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 초록색을 띈 연못은 얼핏 보면 독성이 있을 것 같지만, 실제로는 청량하고 은은한 향기에 놀랄 뿐이다.",
  str_item_intro_5422411 = "여러 차례의 변이를 거친 빛벼루 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 일부 줄기와 수관이 초록색으로 빛나며, 시냇물이 흐르는 것처럼 보여 무척이나 환상적이다.",
  str_item_intro_5422412 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 애시르나무다. 매우 보기 드문 수종이다. 밖으로 드러난 뿌리에 줄기는 팽창하며 딱딱하게 굳었고, 수관은 빛나는 나뭇잎 뭉치가 되었다. 멀리서 보면 작은 등대처럼 보여서 「등대 애시르나무」라는 이름을 얻었다.",
  str_item_intro_5422413 = "복잡한 변이를 거친 빛벼루 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 돌 받침 형태의 줄기와 수관 모두 금빛으로 빛나, 황금 궁전에 온 것만 같아서 「궁전 애시르나무」라는 별칭이 생겼다.",
  str_item_intro_5422421 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 애시르나무다. 일부 줄기와 딱딱한 수관이 합쳐져 속 빈 돌판이 되었다. 이 돌은 겉이 단단하고 얇아서 두드리면 다양한 소리가 나며, 심지어 어떤 사람은 이 수관을 이용해 말을 한다고 한다...",
  str_item_intro_5422422 = "복잡한 변이를 거친 빛바위 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 초록색의 거대한 수관은 푸른 보석 같다. 살짝 두드리기만 해도 다양한 맑은소리가 나서 「애시르나무의 음악가」라는 별명을 얻었다.",
  str_item_intro_5422423 = "복잡한 변이를 거친 빛바위 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 파란색 돌판에서 나는 은은한 소리와 약간의 떨림이 몽환적인 푸른 잔영을 이룬다.",
  str_item_intro_5422431 = "복잡한 변이를 거친 빛골 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 노란색 나무 속에서 빛이 날 때 줄기의 무늬에서 담황색 나뭇잎 그림자가 생겨, 환상수의 생명력이 다시금 느껴진다고 한다. 그래서 「애시르나무의 부활자」라는 별명을 얻었다.",
  str_item_intro_5422432 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 애시르나무다. 줄기는 속이 비었고 나무 속은 특이한 버섯 모양에 기묘한 빛이 난다. 위험을 감지하면 바깥 껍질이 뭉쳐 빛을 가린다고 해서 「빛을 감추는 애시르나무」라는 이름이 붙여졌다.",
  str_item_intro_5422433 = "복잡한 변이를 거쳐 나타난 빛골 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 나무에서 나오는 푸른 빛이 속 빈 줄기로부터 굴절되어, 흐르는 시냇물이 나무를 휘감고 있다고 착각하게 만들며, 나무에 물이 있다고 오해할 정도다...",
  str_item_intro_5422441 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 애시르나무다. 일부 가지와 잎이 결합하여 「랜턴」의 형태를 이루고 있으며, 「심지」 역할을 하는 가지는 심지어 따스한 빛을 발산할 수 있다! 이는 어두운 광야를 걷는 여행자들에게 등대가 되어 준다.",
  str_item_intro_5422442 = "복잡한 변이를 거친 등불의 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 줄기에 모종의 특별한 루미나가 담겨 있어서 「랜턴」이 온화한 남색 빛을 발한다고 한다.",
  str_item_intro_5422443 = "복잡한 변이를 거친 등불의 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 잎은 붉지만 「랜턴」은 옅은 붉은빛을 내며, 흰색 줄기에 빛이 비치는 모습은 독특한 매력이 있다.",
  str_item_intro_5422451 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 애시르나무다. 수관은 이미 사라진 상태지만, 밝은색 꽃잎으로 이루어진 덩굴이 나무줄기를 뒤덮고 있다. 어떤 덩굴은 아래로 처져 있고, 또 어떤 덩굴은 가지를 사이에 두고 서로 연결되어 있어 멀리서 보면 나무 위에 꽃 아치가 있는 것처럼 보인다.",
  str_item_intro_5422452 = "복잡한 변이를 거친 옥푸새 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 백색 꽃잎은 만지면 촉감이 매우 서늘하지만, 떼어 내 손에 쥐면 오히려 미약한 온기가 느껴진다.",
  str_item_intro_5422453 = "복잡한 변이를 거친 옥푸새 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 언뜻 보면 나뭇잎으로 착각할 정도로 푸른 녹색 꽃잎을 가지고 있다. 가까이에서 자세히 봐야만 구분할 수 있다.",
  str_item_intro_5422461 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 애시르나무다. 수관은 없지만 가지 끝에서 자라난 거대한 나뭇잎이 공처럼 안으로 말려 있다! 「빛망울」이라 불리는 이 원형 구체는 루미나를 품고 있는 듯하며, 바람이 솔솔 불면 부서진 나뭇잎 조각과 함께 루미나가 조금씩 흩날리며 주변을 반짝이게 만든다.",
  str_item_intro_5422462 = "복잡한 변이를 거친 어스름빛 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 바다처럼 푸르른 「빛망울」을 가지고 있다. 이 새파란 빛망울들이 바람에 살랑일 때면 거대한 물방울이 춤을 추고 있는 것처럼 보여 「환상수계의 수중 발레리나」라는 별명을 지녔다.",
  str_item_intro_5422463 = "복잡한 변이를 거친 어스름빛 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 강렬한 생명력을 지닌 노란색 「빛망울」을 가지고 있다. 이 나무가 품고 있는 왕성한 생명력이 주위 식물들이 쑥쑥 성장할 수 있도록 돕고 있는 게 느껴진다.",
  str_item_intro_5422471 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 애시르나무다. 수관은 완전히 변이해 한 조각으로 응축되었고, 사방으로 처지면서 독특한 그릇 형태가 되었다. 이 「그릇」의 중심에서는 기묘한 가지가 솟아났는데, 마치 횃불처럼 미미한 빛을 내어 이를 보는 관찰자들의 시선을 줄곧 사로잡는다.",
  str_item_intro_5422472 = "복잡한 변이를 거친 빛다발 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 그릇 형태의 수관은 사람을 한심하게 하는 푸른빛을 띄고 있다. 중간의 가지에서는 은은한 빛을 내 깊은 수역을 보는 느낌을 주어 「심연의 환상」이라고도 불린다.",
  str_item_intro_5422473 = "복잡한 변이를 거친 빛다발 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 그 아래에 서면 붉은 수관이 핏빛 석양처럼 하늘을 뒤덮는 모습을 볼 수 있어, 마치 황혼 속에 있는 듯한 착각을 하게 만든다.",
  str_item_intro_5422481 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 애시르나무다. 나무 전체가 단단해져 석대 같은 사물의 모습을 이루고 있으며, 꼭대기에서 떨어지는 시냇물이 아래의 나무 구멍으로 합쳐져 기묘한 풍경을 이룬다.",
  str_item_intro_5422482 = "복잡한 변이를 거친 하늘샘 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 흰색 몸체가 아래로 흐르는 하늘색 시냇물과 어우러져 제법 싱그러운 풍경을 이룬다. 시냇물 소리를 듣고 있으면 즐거운 마음이 들어 「기쁨의 물방울」이라고도 불린다.",
  str_item_intro_5422483 = "복잡한 변이를 거친 하늘샘 애시르나무다. 오색 결정 재배를 통해 얻은 품종으로, 줄기와 상단의 「가지」가 기묘한 남색이 되었으며, 떨어지는 노란색 시냇물을 보고 있으면 이상한 느낌이 든다. 때문에 「몽롱한 보랏빛」이라고도 불린다.",
  str_item_intro_5423111 = "막 재배한 기본종 플로레나무에서도 그 독특함을 확인할 수 있는데, 바로 활짝 피어난 꽃송이다.",
  str_item_intro_5423112 = "오색 결정으로 키워낸 자색 플로레나무다. 흐릿한 빛이 어른거린다.",
  str_item_intro_5423113 = "오색 결정으로 키워낸 황색 애시르나무다. 빛이 비추면 해가 지는 듯한 느낌이 든다.",
  str_item_intro_5423211 = "미세하게 변이한 우량종 플로레나무다. 이미 다른 품종이 되어버린 것 같다. 한 나무뿌리에서 나무줄기가 여러 개 뻗어 나오기 때문에 종종 많은 식물이 자란 것으로 오해받고는 한다. 겉으로 보기에는 기본종 플로레나무와 매우 달라 보이지만, 나뭇가지의 꽃송이들을 보면 그 기원을 충분히 짐작할 수 있다.",
  str_item_intro_5423212 = "미세하게 변이한 꽃가지 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 옅은 황색의 꽃은 작은 태양처럼 보인다. 한곳에 모여있으면 눈이 어지러울 정도다.",
  str_item_intro_5423213 = "미세하게 변이한 꽃가지 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 옅은 파란색의 꽃은 매우 가벼우며, 바람을 따라 움직일 때면 하늘위의 구름 같다.",
  str_item_intro_5423221 = "미세하게 변이한 우량종 플로레나무다. 나뭇가지가 굵어졌으며, 꽃송이는 완전히 다른 모양이 되었다. 나팔 형태의 꽃송이는 많은 꽃술을 가지고 있기 때문에 이와 같은 이름을 가지게 되었다.",
  str_item_intro_5423222 = "미세하게 변이한 번영의 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 파란색의 꽃이 품은 수분은 갈증을 해소해 줄 수 있다. 심지어 음료수도 만들 수 있다고 한다!",
  str_item_intro_5423223 = "미세하게 변이한 번영의 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 꽃술과 꽃은 모두 타오르는 듯한 빨간색을 띠고 있다. 일반적인 번영의 플로레나무와는 다르게 꽃술을 떼어내면 금방 마르고 부드러워져서 불을 붙이기 좋다고 한다.",
  str_item_intro_5423311 = "여러 차례의 변이를 거친 특산종 플로레나무다. 줄기 위에 꽃송이가 있으며, 뿌리 깊은 곳에서 자라난 여러 가지가 시종처럼 그 주위를 둘러싸고 있다. 「꽃을 수호하는 나무」라고 불리기도 한다.",
  str_item_intro_5423312 = "여러 차례의 변이를 거친 곧은줄기 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 꽃송이와 꽃잎이 황금색에 가까운 황색이다. 햇빛이 비칠 때 멀리서 보면 반짝이는 흔들림이 보이는 것만 같다.",
  str_item_intro_5423313 = "여러 차례의 변이를 거친 곧은줄기 플로레나무다. 연한 파란색의 꽃송이와 꽃잎으로 인해 나뭇가지와 나뭇잎이 날카롭게 보인다. 어떤 사람은 「푸른 칼날의 식물」이라고 부르기도 한다.",
  str_item_intro_5423321 = "여러 차례의 변이를 거친 소담칡 플로레나무다. 나뭇가지가 원형으로 구부러져 있으며, 모여있는 꽃송이로 만들어진 왕관은 밑으로 늘어져 있다. 어떻게 버티는 건지 신기할 정도다.",
  str_item_intro_5423322 = "여러 차례의 변이를 거친 소담칡 플로레나무다.오색 결정 재배를 통해 얻은 품종으로, 늘어진 꽃송이와 원형 가지는 천연의 문을 형성하고 있다. 이미 건설된 정원에 놓아도 아주 조화롭다.",
  str_item_intro_5423323 = "여러 차례의 변이를 거친 소담칡 플로레나무다. 꽃잎은 이미 신선한 백색으로 변했으며, 바람이 스칠 때 화단에 서 있으면 은은한 향기를 느낄 수 있다. 어떤 향수의 중요한 원료로 사용된다.",
  str_item_intro_5423331 = "여러 차례의 변이를 거친 특산종 플로레나무다. 나무줄기가 엉키고 구불거리며, 멀리서 보면 마치 활짝 피어난 꽃 같아서 그 위에 자라난 꽃이 제대로 보이지 않을 정도다. 학자들의 연구에 의하면, 그 꽃을 탐내는 어떤 생물로부터 꽃을 지키기 위해 가지와 줄기가 그런 형태로 자라기 시작했다고 한다.",
  str_item_intro_5423332 = "여러 차례의 변이를 거친 아름초 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 가지 끝이 옅은 남색으로 물들어 있어서 나뭇가지에서 떨어지는 물방울이 더 짙다. 필기에 사용할 수 있다고 하며, 훌륭한 염료이기도 하다.",
  str_item_intro_5423333 = "여러 차례의 변이를 거친 아름초 플로레나무다. 나뭇가지 끝은 연녹색이며, 나무뿌리 부분의 연못도 청록색을 띈다. 자연의 기운을 강하게 풍긴다.",
  str_item_intro_5423341 = "여러 차례의 변이를 거친 특산종 플로레나무다. 그 형태는 머나먼 곳의 한 나무와 매우 닮았다고 한다. 활짝 핀 꽃은 아름다울 뿐만 아니라 은은한 향도 머금고 있어서 오랫동안 지켜보고 있으면 무지개의 환상이 보일 때도 있다고 한다... 물론, 전설일 뿐이지만 그로 인해 이름이 붙여졌다.",
  str_item_intro_5423342 = "여러 차례의 변이를 거친 어득놀 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 자색 꽃송이가 특히 매혹적이다. 그 강렬한 색채로 인해 장식이나 꾸미기에 사용할 때 적절한 안배가 필요하다.",
  str_item_intro_5423343 = "여러 차례의 변이를 거친 어득놀 플로레나무다. 황색 꽃송이는 거의 종일 활짝 피어있으며, 강렬한 생명의 기운을 풍긴다. 이 꽃술로 만든 물약은 활력을 안겨준다는 소문도 있다. 「생명력이 가득한 무지개 나무」라고 불리기도 한다.",
  str_item_intro_5423411 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 플로레나무다. 꽃 화관은 하나뿐이지만 매우 거대하다. 화려한 색을 보유하고 있으며, 향기 속에도 위험한 달콤함을 품고 있다. 그 꽃은 훌륭한 조미료로 사용된다는 말도 있다. 꽃을 감상하다가 그 속에 푹 빠져버리는 경우가 많기 때문에 「요사한 매혹의 꽃」이라고도 불린다.",
  str_item_intro_5423412 = "여러 차례의 변이를 거친 매혹의 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 연한 남색의 화관을 보면 여름의 파도가 떠오른다. 심지어 바닷바람의 비린내마저 느껴지는 것 같다... 그래서 어떤 사람은 바닷가를 느끼고 싶다면 이 나무를 보면 된다고 말한다.",
  str_item_intro_5423413 = "복잡한 변이를 거친 매혹의 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 꽃이 더욱 위험한 분홍색으로 변한다. 단지 꽃을 보기만 해도 모든 걱정을 잊을 수 있기 때문에 오래도록 떠나기 싫어한다. 그렇기에 꽃을 감상하는 사람 중 일부는 너무 빠져들지 않도록 미리 알람을 맞춰둔다고 한다.",
  str_item_intro_5423421 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 플로레나무다. 꽃잎이 가득하며, 길고 가늘어서 멀리서 보면 소녀의 머리카락 같다. 그 질감 또한 매우 부드러워서, 이것으로 직물을 만들어보려고 한 사람도 있었지만, 나무에서 따는 순간 말라 부서져 버렸다고 한다.",
  str_item_intro_5423422 = "복잡한 변이를 거친 꽃무릇 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 남색 화관은 파란 머리카락을 가지고 있던 전설 속 「바다의 소녀」를 떠오르게 만든다. 누군가는 정말로 꽃 주위에서 바다의 냄새를 맡았다고 한다...",
  str_item_intro_5423423 = "복잡한 변이를 거친 꽃무릇 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 어떤 사람은 녹색의 잔털 속에 신비한 「꽃의 영혼」이 숨어 있다고 말한다. 만약 꽃의 영혼을 보게 된다면 첫눈에 반해버리고 말 것이다...",
  str_item_intro_5423431 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 플로레나무다. 거대한 쟁반 형태의 화관이 마치 무언가를 바라보는 것만 같다. 게다가 많은 사람의 시선을 받으면 주목받고 싶지 않다는 듯 살짝 옆으로 숨어버린다. 「긍지 높은 응시의 꽃」이라고 불리기도 한다.",
  str_item_intro_5423432 = "복잡한 변이를 거친 갈망의 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 빨간색 화관은 마치 타오르는 감정 같다. 어떤 사람은 꽃이 바라보는 하늘을 향해 활력을 뿜어내고 있다고 말한다.",
  str_item_intro_5423433 = "복잡한 변이를 거친 갈망의 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 꽃잎이 희미하다. 꽃이 향하는 방향을 바라보면 신비한 환상을 볼 수 있다고 하며, 사람마다 다른 것을 보게 된다고 한다. 그렇기에 「신비한 환상의 제작자」라고 불리기도 한다.",
  str_item_intro_5423441 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 플로레나무다. 아름다운 꽃잎이 겹겹이 쌓아져 있어 보는 이로 하여금 빠져들게 한다. 특히 소녀들에게 사랑받고 있다.",
  str_item_intro_5423442 = "복잡한 변이를 거친 숙녀의 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 푸른색 화관이 사람을 황홀하게 만든다. 많은 관람객이 나무에서 나는 산뜻한 향기가 마치 비 온 뒤의 푸른 하늘과 같다고 해 「맑은 하늘」이라고도 불린다.",
  str_item_intro_5423443 = "복잡한 변이를 거친 숙녀의 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 보라색의 꽃에 위험이 감돈다. 옆에서 보면 꽃잎이 살짝 흔들리며 요염한 분위기에 빠져든다고 하니... 조심해야 한다.",
  str_item_intro_5423451 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 플로레나무다. 거대한 화관이 천연 거름막 역할을 한다. 미끄러운 꽃잎 내벽을 통해 아침 이슬을 모아 줄기에 공급해 수분을 유지한다.",
  str_item_intro_5423452 = "복잡한 변이를 거친 새벽이슬 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 보라색 화관이 모아둔 이슬을 같은 보라색으로 만든다. 일부 학자들은 보라색의 이슬에는 신비로운 힘이 있다고 믿으며, 이를 잉크로 사용해 책을 만들기도 한다.",
  str_item_intro_5423453 = "복잡한 변이를 거친 새벽이슬 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 화관에 모인 이슬은 푸른빛을 띤다. 그걸 보기만 해도 마음의 불결함을 씻을 수 있을 것만 같아서 '새벽의 청결'이라고도 불린다.",
  str_item_intro_5423461 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 플로레나무다. 화관이 여러 개의 가볍고 부드러운 긴 꽃잎으로 이뤄져 있으며, 꽃술을 중심으로 교차하여 분포되어 있다. 어떤 디자이너가 이 플로레나무를 본 뒤로 이 꽃잎의 모양대로 매우 많은 치마를 디자인했다고 한다. 그래서 「미인의 치마」라는 별명이 생겼다.",
  str_item_intro_5423462 = "복잡한 변이를 거친 꽃치마 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 주황색 꽃잎이 상당한 유혹의 기운을 품고 있는 것 같다. 게다가 그 독특한 향기 때문에 자기도 모르게 매혹적이지만 위험한 존재를 떠올리게 된다...",
  str_item_intro_5423463 = "복잡한 변이를 거친 꽃치마 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 꽃잎이 하늘 같은 색을 띤다. 거기에 흰색 잎이 분포되어 있어 맑고 순결한 느낌을 준다. 아이들이 아주 좋아한다.",
  str_item_intro_5423471 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 플로레나무다. 화관과 꽃술이 나비 같은 모습을 띤다. 그 모습은 구경꾼들을 끌어당길 뿐만 아니라, 진짜 나비까지 끌어들여 주위를 맴돌게 만든다. 마치 그들의 신이 된 것처럼 말이다.",
  str_item_intro_5423472 = "복잡한 변이를 거친 파피용 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 멀리서 보면 거대한 노란 화관이 나무 위에 앉아 있는 나비처럼 보인다. 은은한 바람이 불어오면 더욱 구분하기가 어려워진다...",
  str_item_intro_5423473 = "복잡한 변이를 거친 파피용 플로레나무다. 오색 결정 재배를 통해 얻은 품종으로, 푸른 화관에 새겨져 있는 나비의 모습이 기이한 느낌을 준다. 그 참모습을 알아차리는 순간, 이 나무의 기묘함에 감탄할 수밖에 없다. 그래서 「이 세상에 없는 아름다운 나비」라는 별명이 생겼다.",
  str_item_intro_5424111 = "둥그스름한 뿌리만 봐도 희과수와 다른 품종목들의 차이가 드러나며, 희과수만의 독특함에 감탄이 나온다.",
  str_item_intro_5424112 = "오색 결정으로 키워낸 황색 희과수다. 노란색 열매와 잎이 추수를 앞둔 가을을 알리는 것만 같다.",
  str_item_intro_5424113 = "오색 결정으로 키워낸 자색 희과수다. 언뜻 보면 무언가 기묘하고 특이하다는 느낌을 받지만, 희과수의 수액은 사실 무미 무취이기 때문에 오히려 그 무엇보다도 맑고 깨끗함이 느껴진다.",
  str_item_intro_5424211 = "미세하게 변이한 우량종 희과수다. 뿌리가 굵고 튼튼하며, 열매 겉면에는 강력한 방어 작용을 하는 뾰족한 가시가 자라 있다. 나무 주위를 둘러싼 덩굴은 「다가오지 마」라는 의미를 표현하는 것 같다.",
  str_item_intro_5424212 = "미세하게 변이한 우람의 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 남색 덩굴, 잎과 줄기는 기본종과 다른 면모를 보이지만, 내부의 열매는 동일한 것 같다.",
  str_item_intro_5424213 = "미세하게 변이한 우람의 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 덩굴, 잎과 줄기가 다소 생기가 없는 느낌을 주지만, 내부의 열매는 속이 꽉 차 있어 시들해 보이는 겉모습은 위장일 뿐이라는 사실을 알 수 있다.",
  str_item_intro_5424221 = "미세하게 변이한 우량종 희과수다. 뿌리 부분의 열매가 완전히 다른 모양으로 변했으며, 분리되어 있는 열매와 잎은 각자 따로 영양분을 섭취할 수 있다고 한다. 따라서 한 부분에 결손이 일어나더라도 다른 부분의 성장에는 영향을 미치지 않아 일정한 생존율이 보장된다.",
  str_item_intro_5424222 = "미세하게 변이한 풍요의 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 겉에 붉은빛이 도는 이유는 수액에 포함된 특별한 성분 때문이라고 한다.",
  str_item_intro_5424223 = "미세하게 변이한 풍요의 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 열매의 껍질이 수분을 가지고 있지 않은 까닭에 전체적으로 독특한 노란빛을 띠며, 껍질을 벗기면 금세 부스러져 우듬지로 변한다.",
  str_item_intro_5424311 = "여러 차례의 변이를 거친 특산종 희과수다. 열매 바깥쪽은 이미 딱딱해져 돌처럼 변했다. 이 열매를 먹으려면 애를 많이 먹을 것 같다.",
  str_item_intro_5424312 = "여러 차례의 변이를 거친 곧은재 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 열매의 변이 여부는 파악할 수 없지만, 잎사귀만 봐도 이 열매를 먹는 건 자제하는 편이 낫겠다는 느낌을 어렴풋이 받을 수 있다.",
  str_item_intro_5424313 = "여러 차례의 변이를 거친 곧은재 희과수다. 수관과 잎사귀의 색이 매우 선명해 잎사귀 아래 자라는 「열매 옥석」과 강렬한 대비를 이룬다. 어떤 이들에게는 「생화에 뒤덮인 자갈」이라고 불린다.",
  str_item_intro_5424321 = "여러 차례의 변이를 거친 단물샘 희과수다. 줄기는 굴곡져 있지만, 열매는 의외로 반듯하게 반으로 갈라져 하늘이 내린 연못 같은 모습을 지녔다. 이 열매만 있다면 물 마실 걱정은 하지 않아도 된다.",
  str_item_intro_5424322 = "여러 차례의 변이를 거친 단물샘 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 열매가 반으로 갈라져 생긴 「열매 연못」에 담긴 과즙에서는 오묘한 맛이 느껴지는데, 이는 과즙 안에 아직 세간에 알려지지 않은 신비로운 향신료가 포함돼 있기 때문이라고 한다.",
  str_item_intro_5424323 = "여러 차례의 변이를 거친 단물샘 희과수다. 열매가 반으로 갈라져 생긴 「열매 연못」에 담긴 과즙이 더 맑고 깨끗할 뿐만 아니라, 약간의 시원함도 지녀 여름 나기의 좋은 동반자다.",
  str_item_intro_5424331 = "여러 차례의 변이를 거친 특산종 희과수다. 줄기가 뒤엉켜 있는 이유는 줄기 내부에 존재한 열매 때문이라고 전해진다. 하지만 몇몇 연구에 따르면 열매는 원래부터 굴곡져 있었으며, 「나무줄기」라 부르는 부위는 사실 열매의 겉껍질에 지나지 않는다고 한다.",
  str_item_intro_5424332 = "여러 차례의 변이를 거친 감로의 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 가지 끝 쪽이 녹색으로 물들어 있으며, 열매는 한 번 핥기만 해도 며칠은 입맛이 뚝 떨어질 정도로 맛이 떫고 쓰다.",
  str_item_intro_5424333 = "여러 차례의 변이를 거친 감로의 희과수다. 열매의 맛에 매우 큰 변화가 있었다는 점을 암시하듯 줄기 쪽 부분의 색상이 매우 눈에 띈다. 도전 정신이 투철한 이들의 경험담에 따르면, 열매에서 약간 알싸하면서도 새콤달콤한 맛이 난다고 한다.",
  str_item_intro_5424341 = "여러 차례의 변이를 거친 특산종 희과수다. 이 환상수 품종의 특징을 가장 잘 드러내는 형태를 지녔으며, 차곡차곡 쌓여 있는 거대한 열매 사이로 가지와 줄기가 뻗어 나와 있어 「명실상부한 열매 거목」이라는 별명을 보유하고 있다.",
  str_item_intro_5424342 = "여러 차례의 변이를 거친 큰열매 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 푸른빛이 도는 거대한 열매는 견실이라는 이름에 걸맞게 매우 실해 보인다. 일설에 따르면 이 열매 하나에 마을 하나가 필요로 하는 물의 양만큼의 수액이 들어 있다고 해, 「수조 환상수」라고도 불린다.",
  str_item_intro_5424343 = "여러 차례의 변이를 거친 큰열매 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 존재감을 과시하는 붉고 거대한 열매가 매우 눈에 띄기 때문에, 이 열매의 수액이 활력을 북돋는다는 이야기가 있었지만, 지금 보니 그저 전설일 뿐일지도 모르겠다.",
  str_item_intro_5424411 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 희과수다. 열매가 거대할 뿐만 아니라 기묘하면서도 화려한 색을 지녔으며, 나뭇가지가 복잡하게 얽혀 있다. 오래 바라보고 있으면 일종의 독점욕이 생겨 가족과 친구 사이에 분쟁을 초래하기도 해 「분쟁의 과실」이라는 이름을 얻었다.",
  str_item_intro_5424412 = "여러 차례의 변이를 거친 마루열매 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 초록빛 열매가 강렬한 생명력을 지니고 있다. 오래 바라보면 마치 숲에 있는 것처럼 벌레와 새의 지저귐이 들려오고, 바람에 나뭇잎이 나부낀다고 느낄 정도로 푹 빠지게 된다.",
  str_item_intro_5424413 = "복잡한 변이를 거친 마루열매 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 신선하고 눈에 띄면서 매력적인 분홍빛 열매를 가지고 있다. 열매를 오랜 시간 바라보고 있으면 갑자기 내부가 두근거리는 모습을 볼 수 있어 무척 기괴하다.",
  str_item_intro_5424421 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 희과수다. 크고 작은 열매가 여럿 쌓여 있으며, 사람에게 가장 일찍 발견된 환상수 중 하나라고 한다. 야생에서 자랐을 당시의 기록까지 남아 있어 「열매 환상수의 조상님」이라는 별명을 가지고 있다.",
  str_item_intro_5424422 = "복잡한 변이를 거친 맏뿌리 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 자꾸 짜내고 싶다는 생각이 드는 분홍빛 열매를 지녔다. 이렇게 짜낸 과즙으로 일국의 왕이 감탄을 금치 못할 정도로 훌륭한 맛을 자랑하는 음료를 만들 수 있다는 이야기가 전해져 내려와 「제왕의 음료 열매」라는 별명을 가지고 있다.",
  str_item_intro_5424423 = "복잡한 변이를 거친 맏뿌리 희과수, 오색 결정 재배를 통해 얻은 품종으로, 멀리서 바라보면 푸른 바닷물의 결정이라 여겨질 정도의 열매가 자란다. 심지어 열매 속에서 잔잔한 물결이 보이는 경우도 존재하는데, 이것이 관찰자가 본 환상인지, 아니면 사실인지는 알 수 없다.",
  str_item_intro_5424431 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 희과수다. 거대한 열매가 언제나 기묘한 기운을 내뿜고 있는데, 그 향을 맡으면 이유 없이 용기가 솟아오르고, 모든 곳을 정복하고 싶다는 생각이 들게 된다는 이야기 때문에 지금 같은 이름이 붙여졌다고 한다.",
  str_item_intro_5424432 = "복잡한 변이를 거친 천세의 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 이 나무의 초록빛 열매는 가장 흉포한 전사도 진정시킬 수 있어 명상과 사색에 매우 도움이 된다. 이 열매 덕분에 깨달음을 얻게 된 현자들이 많아 「깨달음의 열매」라는 별명을 지녔다.",
  str_item_intro_5424433 = "복잡한 변이를 거친 천세의 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 푸른빛이 도는 거대한 열매는 용기를 선사할 뿐만 아니라, 다른 사람의 지배에 순응하지 않는 강렬한 야심을 선사해, 돌아올 수 없는 패왕의 길을 걷도록 만들기에 「위험한 왕좌지재」라고 불린다.",
  str_item_intro_5424441 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 희과수다. 열매는 「줄기」에 숨겨져 있으며, 일부 학자들의 연구에 따르면 열매를 감싸고 있는 것은 줄기가 아니라 열매의 딱딱해진 외피라고 한다! 아무래도 이 나무는 사람들이 열매를 얻지 못하게 하기 위해 정말 많은 노력을 한 모양이다.",
  str_item_intro_5424442 = "복잡한 변이를 거친 은거의 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 녹색의 열매는 생명의 「근원」을 지니고 있다고 전해진다. 그 덕에 식물의 성장을 도와 풍작을 가져다줄 뿐만 아니라, 척박한 토양과 메마른 염분 지대를 개량할 수도 있다고 한다! 그래서 많은 사람이 그것을 「생명의 열매」라고 부른다.",
  str_item_intro_5424443 = "복잡한 변이를 거친 은거의 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 남색의 거대한 열매 속에는 감미로운 맑은 물이 담겨 있으며, 외부의 「나무껍질」은 강력한 보습력을 가지고 있어 사막에서도 열매의 수분을 잃지 않는다. 그야말로 살아있는 저수지나 다름이 없다...",
  str_item_intro_5424451 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 희과수다. 거대한 열매는 얼핏 보기에는 평범해 보이지만, 일정 시간 동안 매우 매력적인 향기를 풍긴다. 그 향기는 평생 잊을 수 없다고 한다! 때문에 평소에는 특별한 냄새가 나지 않음에도 불구하고 주변에 나비가 많이 날아다닌다.",
  str_item_intro_5424452 = "복잡한 변이를 거친 천향의 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 일부 전설에 따르면 그 보라색 열매는 수백 년에 한 번씩 열리는데, 온 대륙에 그 향기를 퍼트린다고 한다! 그리고 그 향기와 함께 세상에는 어떤 「왕」이 강림한다는 전설이 있다...",
  str_item_intro_5424453 = "복잡한 변이를 거친 천향의 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 다른 천향의 희과수와 달리 파란 열매에서 은은한 신선함이 느껴지며, 다른 냄새를 중화시킬 수도 있다고 한다! 따라서 정원사들 사이에서 꽤 인기가 있지만, 다른 곳에 옮겨 심을 수 없는 특성으로 인해 아쉬워할 뿐이다.",
  str_item_intro_5424461 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 희과수다. 겉껍질은 새장과 같은 모양을 이루고 있고, 내부의 열매는 매우 달콤한데, 가끔씩 내뿜는 안개에서 이를 알 수 있다. 이 안개는 다른 생물들이 다가오는 것을 막고, 열매를 노리지 못하게 한다고 전해진다.",
  str_item_intro_5424462 = "복잡한 변이를 거친 운무의 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 녹색 열매는 신맛이 강하고, 내뿜는 안개조차 코를 찌르는 냄새가 나기 때문에 맹독이 있다는 소문이 있으나, 실제로는 무해하다.",
  str_item_intro_5424463 = "복잡한 변이를 거친 운무의 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 푸른 과일의 과육 부분에 기묘한 변화가 발생해서 매우 질겨지고 탄성이 생겼다. 그 덕에 무거운 차가 밟고 지나가도 빠르게 원래 상태를 회복한다...",
  str_item_intro_5424471 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 희과수다. 열매가 두 부분으로 갈라졌는데, 주된 열매는 두꺼운 껍질에 싸여 있고, 가지 끝에 매달린 빛나는 「과일」들은 수관이 변이한 것이라고 한다! 하지만 모양, 냄새, 심지어 맛으로 보아도 쉽게 그 사실을 받아들이기가 어렵다...",
  str_item_intro_5424472 = "복잡한 변이를 거친 꽃등의 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 발산하는 푸른 빛에서는 바닷물의 숨결이 느껴진다고 하여 「바닷바람의 사자」라고도 불린다. 그러나 어떤 이들은 그것이 그저 과일 향이 가져다주는 환각 효과일 뿐이라고 주장하기도 한다.",
  str_item_intro_5424473 = "복잡한 변이를 거친 꽃등의 희과수다. 오색 결정 재배를 통해 얻은 품종으로, 상단의 「과일」이 발산하는 녹색 빛은 사람을 진정시키는 힘이 있어, 가장 사나운 동물조차 근처에 다가오면 온순해진다고 한다. 하지만 그것이 사실인지는 알 수 없다.",
  str_item_intro_5425111 = "이 유형의 환상수는 기본부터 다른 품종과는 매우 달라서, 정말 「나무」가 맞는 건지 의심하게 된다... 많은 학자들의 연구에 따르면 이것도 나무에 속하는 것이 맞다고 하지만, 확실히 사람들에게 기묘한 느낌을 준다고밖에 말할 수 없을 것 같다.",
  str_item_intro_5425112 = "오색 결정으로 재배한 적색 버섯나무다. 적색의 거대한 갓은 초조한 느낌이 들게 만든다. 그렇기 때문에 그 밑에서 더위를 피하는 건 보통은 좋은 선택이 아니다.",
  str_item_intro_5425113 = "오색 결정으로 재배한 남색 버섯나무다. 남색의 갓에서 광활한 하늘이 느껴지는 듯하다. 누군가는 그 주위에서 「구름의 향기」를 맡았다고 한다...",
  str_item_intro_5425211 = "미세하게 변이한 우량종 버섯나무다. 갓에 엄청난 변화가 생겼다. 부드럽지만 강인하며, 무게 때문에 밑으로 처져있어 돔 같은 느낌이 든다. 목재로 살짝 지탱하고 울타리를 더해주면 작은 집이 될 수도 있을 것 같다.",
  str_item_intro_5425212 = "미세하게 변이한 여린 버섯나무다. 오색 결정 재배를 통해 얻은 품종으로, 갓 내부가 하늘색으로 변해있다. 그 안에서 위를 바라보면 마치 바다에 있는 듯한 느낌이 든다.",
  str_item_intro_5425213 = "미세하게 변이한 여린 버섯나무다. 오색 결정 재배를 통해 얻은 품종으로, 붉은 갓 내부는 뭔가 무서운 느낌이 든다. 독이 있다는 얘기도 있지만, 사실 모두 편견으로 인한 소문이다.",
  str_item_intro_5425221 = "미세하게 변이한 우량종 버섯나무다. 줄기가 굵고 튼튼하며, 갓이 매우 작아져 마치 물통으로 변한 것만 같다. 실제로 굵은 줄기로 땅속에서 수분을 흡수하여 저장할 수 있기 때문에 천연 물 저장고이기도 하다. 그렇기에 「물 버섯」이라고도 불린다.",
  str_item_intro_5425222 = "미세하게 변이한 경음의 버섯나무다. 오색 결정 재배를 통해 얻은 품종으로, 표면은 붉은빛을 띠고 있지만, 내부에 저장되는 수분은 영향을 받지 않는다. 가까이 다가가면 안쪽에서 미세한 물소리가 들린다.",
  str_item_intro_5425223 = "미세하게 변이한 경음의 버섯나무다. 오색 결정 재배를 통해 얻은 품종으로, 대량의 수분을 저장하고 있는 남색의 갓은 「바다의 덮개」라고도 불린다. 갓 위에서 몸을 숙여 귀를 대면 굵은 줄기 속에서 파도 소리가 들린다고 한다.",
  str_item_intro_5425311 = "여러 차례의 변이를 거친 특산종 버섯나무다. 갓은 원래의 거대한 크기를 유지하고 있지만, 훨씬 두꺼워진 데다 기묘한 냄새가 가득하다...",
  str_item_intro_5425312 = "여러 차례의 변이를 거친 미혹의 버섯나무다. 오색 결정 재배를 통해 얻은 품종으로, 갓이 남색으로 변했다. 가까이 다가가지 않고 잠깐만 바라봐도 얕은 바다 밑에 있는 듯한 느낌이 든다.",
  str_item_intro_5425313 = "여러 차례의 변이를 거친 미혹의 버섯나무다. 갓은 아름다운 붉은 빛을 띠고 있다. 바라보고 있으면 대상을 유혹하고 심취하게 만들고 다가갈수록 그 힘이 강해진다. 하지만 나쁜 영향이라고는 전혀 없는 유혹이며, 그 이유는 여전히 밝혀지지 않고 있다.",
  str_item_intro_5425321 = "여러 차례의 변이를 거친 특산종 버섯나무다. 크기가 작아졌을 뿐만 아니라, 무리를 지어 성장하나, 그 형태는 크게 변하지 않았다. 가장 큰 특징은 갓이 다양한 빛으로 반짝인다는 것이며, 반짝거리는 가루를 뿜는다. 매우 아름답다.",
  str_item_intro_5425322 = "여러 차례의 변이를 거친 반짝이 버섯나무다. 오색 결정 재배를 통해 얻은 품종으로, 타오르는 듯한 붉은 색은 마치 모여있는 불꽃 같다. 반짝이는 가루는 불티가 날리는 것으로 오해받고는 한다. 그렇기에 「불붙은 버섯들」이라는 별명으로도 불린다.",
  str_item_intro_5425323 = "여러 차례의 변이를 거친 반짝이 버섯나무다. 오색 결정 재배를 통해 얻은 품종으로, 자색 갓이 요염해 보이며, 반짝이는 빛의 가루에는 사람을 취하게 하는 효과가 있다고 한다. 미혹의 버섯나무의 변종이거나 먼 친척이라고 주장하는 학자도 있지만 추측일 뿐이다.",
  str_item_intro_5425331 = "여러 차례의 변이를 거친 특산종 버섯나무다. 줄기가 휘어있으며, 두 개의 갓을 가지고 있다. 어떤 학자들은 이 버섯나무가 두 개의 갓을 유지하기 위해 지하에서 대량의 물을 빨아들이며, 최대 저장량보다 많은 물을 빨아들이는 탓에 갓에서 물이 비처럼 흘러내리는 것으로 추측하기도 한다.",
  str_item_intro_5425332 = "여러 차례의 변이를 거친 습기의 버섯나무다. 전체적으로 황색을 띠고 있으며, 떨어지는 빗방울도 옅은 석양의 기운을 담고 있다. 물방울이 많이 떨어질 때면 황혼의 빗줄기가 장막을 이루어 나무 주위에 나타난 듯한 느낌을 준다.",
  str_item_intro_5425333 = "여러 차례의 변이를 거친 습기의 버섯나무다. 오색 결정 재배를 통해 얻은 품종으로, 남색의 표면 때문에 바닷속 생물로 보이기도 한다. 떨어지는 빗방울은 마치 튕겨 나오는 푸른 물보라 같아서 「바닷물의 조종자」라는 별명으로 불리기도 한다.",
  str_item_intro_5425341 = "여러 차례의 변이를 거친 특산종 버섯나무다. 축 늘어져 있는 여러 개의 부드러운 나뭇가지는 이 버섯나무만의 특색이다. 언뜻 보면 노인의 수염 같기 때문에 마치 현자와도 같은 느낌을 준다. 그렇기에 「버섯나무의 현자」라는 별명으로 불리기도 한다.",
  str_item_intro_5425342 = "여러 차례의 변이를 거친 긴수염 버섯나무다. 오색 결정 재배를 통해 얻은 품종으로, 황색의 수염은 더욱 지혜로워 보인다. 심지어 어떤 사람은 빛의 보호를 의미한다고 말하기도 한다. 바람이 스쳐 지나가면 마치 태양과도 같은 찬란함이 느껴진다.",
  str_item_intro_5425343 = "여러 차례의 변이를 거친 긴수염 버섯나무다. 오색 결정 재배를 통해 얻은 품종으로, 수많은 녹색 수염이 마치 덩굴처럼 보인다. 갓 밑에서 바라보면 원시림에 있는 듯한 착각이 든다.",
  str_item_intro_5425411 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 버섯나무다. 갓이 매우 거대하면서도 얇다. 어떤 각도에서 보면 거의 투명하다는 얘기도 있다! 물론, 투명한 느낌은 얇은 갓 때문이 아니라 투명한 얼음이 떠오르는 한기 때문이라고 한다.",
  str_item_intro_5425412 = "여러 차례의 변이를 거친 냉기의 버섯나무다. 오색 결정 재배를 통해 얻은 품종으로, 황색의 갓에 가끔 뿜어져 나오는 한기를 더하면 땡볕 속에서도 추위가 느껴지는 듯한 착각이 든다고 한다. 그렇기에 「태양을 봉인한 얼음 지역의 기묘한 나무」라고도 불린다.",
  str_item_intro_5425413 = "복잡한 변이를 거친 냉기의 버섯나무다. 오색 결정 재배를 통해 얻은 품종으로, 갓이 눈을 찌르는 적색으로 변했다. 거기에 천연적인 투명감 때문에 자연의 산물이 아닌 인공적으로 만들어진 예술품처럼 보이기도 한다.",
  str_item_intro_5425421 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 버섯나무다. 갓이 비교적 「평범」해졌지만 가끔 기류를 뿜어내서 「숨을 쉬고 있다」는 착각을 하게 만든다. 거기에다 무리를 지어 성장하기 때문에 연이어 기류를 뿜기 시작하면 옅은 안개가 생기기도 한다.",
  str_item_intro_5425422 = "복잡한 변이를 거친 안개의 버섯나무다. 오색 결정 재배를 통해 얻은 품종으로, 붉은 갓이 「숨 쉴」 때면 가끔 보이는 미세하게 열리는 구멍은 상처를 연상시킨다. 거기에다 기류를 뿜을 때 가끔 피 안개가 응결되는 듯한 풍경이 연출되기도 한다. 그렇기에 「처참한 전장의 재현자」라고도 불린다.",
  str_item_intro_5425423 = "복잡한 변이를 거친 안개의 버섯나무다. 오색 결정 재배를 통해 얻은 품종으로, 남색 갓이 뿜는 안개는 「겨울」의 느낌을 준다. 그렇기에 많은 이들이 원래 북방에서 자라는 식물로 오해하기도 한다. 하지만 다들 틀렸다. 이 나무가 뿜는 기류는 전혀 차갑지 않으며, 오히려 어느 정도 온기가 느껴진다.",
  str_item_intro_5425431 = "복잡한 변이를 거쳐야만 생겨나는 희귀종 버섯나무다. 갓이 매우 커져서 줄기가 지탱할 수 있을지 의심이 들 정도다. 갓이 너무 거대한 탓에, 그 밑에서 위쪽을 바라보면 하늘이 완전히 가려진다. 그렇기에 「하늘을 가리는 나무」라고도 불린다.",
  str_item_intro_5425432 = "복잡한 변이를 거친 장막의 버섯나무다. 오색 결정 재배를 통해 얻은 품종으로, 녹색 갓에서 때때로 물풀의 향기가 느껴진다. 바라보고 있으면 마치 물가에 있는 듯한 착각이 든다. 이 나무는 근처의 수초에 영양분을 제공하여 성장을 돕는다고 하는데, 아무도 그 사실을 검증해 내지는 못했다.",
  str_item_intro_5425433 = "복잡한 변이를 거친 장막의 버섯나무다. 오색 결정 재배를 통해 얻은 품종으로, 선홍빛의 갓은 풍작의 느낌을 준다. 확실히 주위에서 과일의 풋내를 맡았다는 사람도 있다. 하지만 이 환상수는 전혀 먹을 수 없다. 특히 갓은 매우 단단하고 요리하기도 매우 어려운 데다 영양분도 전혀 없다.",
  str_item_intro_5510001 = "뚱뚱한 몸은 치명적인 독을 품고 있어 생존에 장애가 되지 않는다. 하지만 신선한 육질은 죽음을 두려워하지 않는 수많은 미식가를 사로잡았다.",
  str_item_intro_5510002 = "밝은 색상으로 유명하다. 수가 많고 육질이 연해서 식탁의 메인 요리가 된다.",
  str_item_intro_5510003 = "몸이 가늘고 칼과 비슷하게 생겨서 붙여진 이름이다. 항상 떼를 지어 다닌다.",
  str_item_intro_5510004 = "얼핏 보면 뱀처럼 보이지만, 실제로는 그보다 훨씬 가늘고 작은 지느러미가 있는 물고기다. 물 밑의 돌에 숨어있다가 갑자기 튀어나와 사람을 놀라게 만드는 것을 좋아한다.",
  str_item_intro_5510005 = "맑은 물에서 사는 물고기이며, 수가 많고 널리 분포되어 있어 여러 곳에서 볼 수 있다.",
  str_item_intro_5510006 = "이 물고기는 물속의 폭군 포식자이지만, 뛰어난 육질이 미식가들의 눈에 띄어 현재는 고급 연회의 「단골」이 되었다.",
  str_item_intro_5510007 = "가늘고 긴 작은 물고기로 강기슭에 모여서 쉬거나 헤엄친다. 물속의 미생물을 먹고 살아 고기는 먹고, 기름은 각종 염료로 만들 수 있다.",
  str_item_intro_5510008 = "무리 지어 행동하는 것을 좋아하며, 개체수가 많다. 성격이 난폭해 적을 향해 돌진한다. 청새치는 육질이 단단하며, 작은 비늘은 말려서 간식으로 먹을 수 있다.",
  str_item_intro_5520001 = "물속에서 천천히 헤엄치는 거북이로 뭍에서는 거의 움직이지 못한다. 속도가 너무 느린 탓인지 적을 상대할 때는 단단한 등껍데기에만 의존한다.",
  str_item_intro_5520002 = "희귀 수생생물로, 차가운 물을 매우 좋아한다고 하며, 이러한 습성 때문에 자주 언 바다의 수면 아래서 활동한다. 몸통 부분이 투명하고, 여러 빛깔로 색이 변하기도 해 무척이나 아름다워 천사라는 이름이 붙었다. 따뜻한 물에서는 거의 만나보기 힘든 어종이지만, 길을 잘못 들어 헤븐즈 가든에 출몰하게 된 모양이다...",
  str_item_intro_5520004 = "이 수생 생물은 매우 평평한 몸을 가지고 있으며, 매우 느리게 헤엄치며 강과 개울의 바닥에서 움직이고 쉬는 것을 좋아한다. 등에 기묘한 반점이 많기 때문에 어부들이 강을 관찰할 때면 마치 진주가 잔뜩 떨어져 있는 것처럼 보여 이름이 붙여지게 되었다.",
  str_item_intro_5520005 = "물밑을 기어 다니는 것을 좋아하는 생물로, 특이한 신체 구조를 지녔다고 알려져 있다. 이를 본 사람들은 처음에는 특이하게 생긴 해조류나 산호로 착각하지만, 천천히 움직이는 것을 본 뒤에야 살아있는 생물이라는 것을 알게 된다...",
  str_item_intro_5520006 = "일반적으로 해초, 산호에 서식하며, 심지어는 말미잘 사이에서도 생활하는 특이한 어종으로, 화려하고 눈에 띄는 외형을 지녔지만, 생김새는 웃음을 참을 수 없을 정도로 「유머러스」하다. 이 물고기가 나타나면 마치 「개그 재능」이 있는 것처럼 근처에 있는 수초들이 덩실덩실 춤을 추는 듯 움직이기 시작해, 광대물고기란 별명도 가지고 있다.",
  str_item_intro_5520007 = "최근에 발견된 듯한 수생 생물이다. 매끄러운 피부와 부드러운 근육, 우아하고 나른하게 수영하는 모습으로 순식간에 많은 사람들의 주목을 받았다. 어떤 사람들은 녀석이 물속을 누비며 헤엄치는 모습을 보기만 해도 심신이 즐거워지고 며칠간 쌓인 피로가 싹 풀리는 것 같다고 한다.",
  str_item_intro_5520016 = "넓은 수역을 좋아하지만 왜인지 이곳에 와 있다... 전체적으로 검은색이며, 모습이 매우 이상하기 때문에 한동안 사람들이 무서워하기도 했다. 사실 매우 온화하며, 물에서 유유히 돌아다니는 걸 좋아한다. 심지어 작은 수중 동물을 만났을 때 먼저 피하기도 한다.",
  str_item_intro_5520101 = "홍백꽃금붕어는 빛깔이 매우 아름다워 가장 귀하고 유명한 관상어 중 하나가 되었다. 「물속에 사는 보석」이라는 별명이 있으며, 기르는 사람에게 행운을 가져다준다고 한다.",
  str_item_intro_5520102 = "삼색꽃금붕어는 무늬가 다양하여 많은 사람에게 사랑받는다. 「우아한 신사 물고기」라고 불리며, 보고 있으면 마음이 편해진다. 사람들은 이 물고기가 가정의 평화를 가져다준다고 생각한다.",
  str_item_intro_5520103 = "고급 관상어로 헤엄치는 모습이 매우 우아하여 「헤엄치는 예술품」이라고 불린다. 이 물고기를 기르면 앞으로 닥칠 재앙을 없애준다고 한다.",
  str_item_intro_5520104 = "흑백꽃금붕어는 성격이 온화하고 자연스러운 무늬를 지니고 있다. 사람과 친해지는 것을 좋아하며, 특히 아이를 좋아한다. 일부 사람은 아이가 잘 클 수 있도록 보호해준다고 믿는다.",
  str_item_intro_5520105 = "햇빛을 받으면 비늘이 황금빛으로 빛나기 때문에 재물운을 불러온다고 여긴다. 이로 인해 여러 마리를 키우는 상인이 많다.",
  str_item_intro_5520201 = "물속에서 붉게 빛나는 관상어. 아주 선명한 비늘에 물 전체가 연분홍빛으로 물들면 매우 아름다운 광경을 볼 수 있다.",
  str_item_intro_5520202 = "붉은 비늘이 조금 「사악」해 보이지만, 이는 햇빛을 받아 주홍색으로 빛나는 것이며, 온몸에 루비 갑옷을 입은 것처럼 보이기도 한다.",
  str_item_intro_5520203 = "반짝이는 푸른 비늘 탓에 물속에서 천천히 헤엄치는 게 왠지 모를 시원함이 느껴져 무더운 여름에 특히 귀하다.",
  str_item_intro_5520204 = "가지런한 황금빛 물고기 비늘을 가진 물고기로, 전설 속의 장군이 떠오른다. 헤엄치는 모습도 매우 거만해서 주위의 작은 물고기들이 자리를 피할 정도다.",
  str_item_intro_5520205 = "다른 물고기에 비해 우아하고 여유롭다. 은백색의 비늘과 유선형의 몸통이 귀족 느낌을 자아낸다.",
  str_item_intro_5520301 = "납작한 몸통과 눈이 부신 색깔을 가진 이 물고기는 물에 빠진 나비처럼 나풀나풀 헤엄친다.",
  str_item_intro_5520302 = "흰 머리 검은 몸통을 가진 온화한 성격의 관상어다. 자세히 관찰하면 흑백의 경계에 있는 반점이 물고기마다 미세하게 다르다.",
  str_item_intro_5520303 = "몸통이 노란색과 흰색이 섞였으며, 세 부분으로 나뉜다고 하여 붙여진 이름이다. 성격이 요란스럽고 다른 물고기를 놀리기 좋아해 이 물고기만 있으면 물속이 떠들썩해진다.",
  str_item_intro_5520304 = "예쁜 파란색을 가진 관상어로 색깔이 다양하게 변하며, 수줍은 성격 탓에 얼굴을 내미는 걸 좋아하지 않는다. 돌과 수초 사이에 숨어 있을 때가 많다 보니 「수줍은 소녀」라는 별명이 붙었다.",
  str_item_intro_5520401 = "선명한 색과 날렵한 눈을 가졌으며, 다른 물고기와 친해지는 것을 좋아해 잘 배척당하지 않는다. 관상어 중에서 「사교의 꽃」이라고 불린다.",
  str_item_intro_5520402 = "등에 여러 색의 반점이 있어 붙여진 이름이다. 비슷한 색의 수초를 넣으면... 천연 보호색이 되니 세팅할 때 환경과 색상을 신경 써야 물고기를 찾아낼 수 있다.",
  str_item_intro_5520403 = "몸의 대부분이 검고, 등에 있는 흰색이 섞인 노란 지느러미가 특징이다. 평소에는 조용하지만 일단 화가 나면 상대와 끝장을 보는 성격이다. 가시가 있으니 만지면 안 된다.",
  str_item_intro_5520501 = "이 관상어는 기르는 사람이 극히 적다. 이유는... 너무 못생겼기 때문이다. 볼만한 건 빛나는 수염뿐이다.",
  str_item_intro_5520502 = "흰색의 등불아귀다. 사람과의 교감이 더 많아졌지만 빛이 조금 더 어두워졌다. 이는 어쩌면 대비가 되기 때문일지도 모른다.",
  str_item_intro_5520601 = "심해에 산다는 해마가 어째서 여기까지 왔는지 알 수 없다. 심해에 익숙하다 보니 평소에도 물 밑에 숨어있어서 발견하기 어렵다.\n평소에는 잘 보이지 않으며, 근처에 루미나가 있는 상황에서만 나타난다. 하지만 루미나의 기운이 너무 강하면 놀라서 도망갈지도 모른다.",
  str_item_intro_5520602 = "이 종류의 해마는 계곡물 돌 틈에서 서식하는 것을 선호한다. 매우 빠르게 움직이며, 돌이 노란색으로 물든 것처럼 보여서 지금의 이름이 붙여졌다.\n평소에는 잘 보이지 않으며, 근처에 루미나가 있는 상황에서만 나타난다. 하지만 루미나의 기운이 너무 강하면 놀라서 도망갈지도 모른다.",
  str_item_intro_5520603 = "이 해마는 보통 하천이나 계곡에 서식하며, 몸은 자연스러운 보호색을 띠고 있고, 세로로 헤엄치면서 계곡 물속에 잘 숨어 천적에게 쉽게 발각되지 않는다.\n평소에는 잘 보이지 않으며, 루미나에 대해 그다지 민감하지 않아서, 조금 더 강한 루미나로 유인해야만 모습을 드러낸다. 하지만 루미나의 기운이 너무 강하면 마찬가지로 놀라서 도망갈지도 모른다.",
  str_item_intro_5520701 = "강의 굴곡에 사는 것을 좋아하는 수중 생물로, 다리가 많고 매우 사나워 보인다. 하지만 그것은 위장일 뿐, 사실은 성격이 매우 온순하다. 평소에는 주로 해초 사이에 숨어서 지내기 때문에 흔히 볼 수 없다.",
  str_item_intro_5520702 = "깨끗한 강의 굽이진 지역에서 사는 것을 좋아하며, 몸의 대부분을 모래 안에 묻은 채 지낸다. 몸의 색이 모래와 비슷해서 다른 생물들의 눈에 잘 띄지 않는다. 따라서 손쉽게 매복 공격을 할 수 있다.",
  str_item_intro_5520801 = "매우 「작다」고 해도 무려 1킬로그램이나 된다. 그리고 이것이 「처비 피쉬」의 가장 작은 종류다! 평범해 보이지만 성장의 잠재력이 매우 크다...",
  str_item_intro_5520802 = "좀 커진 「처비 피쉬」로, 5킬로그램 정도 된다. 색이 좀 더 진하지만 잡기 어렵다. 아무래도 체중뿐만 아니라 경계심도 늘어난 것 같다.",
  str_item_intro_5520803 = "10킬로그램 가까이 되는 「처비 피쉬」다. 외형이 둥그스름해지기 시작했고, 큰 눈은 마치 「난 더 찔 수 있어」라고 말하는 것 같다.",
  str_item_intro_5520804 = "20킬로그램에 육박하는 무게는 「처비 피쉬」를 강자 중 하나로 만들어준다. 헤엄치는 속도는 느리지만 차분하고 느긋하게 움직이는 모습을 보고 있으면 이유는 모르지만 마음이 안정된다. 정말 신기하다.",
  str_item_intro_5520805 = "초특급 크기의 「처비 피쉬」! 50킬로그램! 「처비 피쉬」의 왕이라 할 수 있다. 큰 배는 마치 「내 무게는 모두 이곳에 있다」라고 말하는 것만 같다! 성격도 상당히 포악해서 다른 수중 생물은 대부분 피해 다닌다.",
  str_item_intro_5520806 = "체형은 작지만 가장 인기 있는 「처비 피쉬」가 된 것은 마치 도금한 것 같은 모습의 몸통 때문이다. 눈부신 비늘에는 다양한 별무늬가 있는데, 정말로 하늘에서 내려준 걸작이라고 감탄하지 않을 수 없다.",
  str_item_intro_5520811 = "이빨과 발톱을 가진 극도로 사나운 수생 생물처럼 보이지만, 사실 한 쌍의 거대한 집게는 그저 이동을 방해하는 돌과 수초 같은 장애물을 제거하는 데만 사용되며, 싸움은 부차적인 기능일 뿐이다. 실제로 성격은 매우 온화하며, 방어할 때만 용맹하게 싸운다.",
  str_item_intro_5520812 = "물속 바위 사이에 숨어 사는 것을 좋아하는 생물이다. 숨는다고 말은 하지만, 사실은 그저 물속에 있는 것이 좋을 뿐이다. 자신의 강한 집게로 돌을 옮겨 자신만의 「성」을 짓고, 그 안에 숨어서 운이 나쁘거나 호기심 많은 수생 생물을 습격해 만찬을 열곤 한다.",
  str_item_intro_5520014 = "온몸에 푸른 얼룩이 있는 것으로 유명하며, 강에서는 거의 볼 수 없다. 그러나 녀석이 모습을 드러내면 수많은 수중 생물들이 도망치는데, 그 이유는 주로 녀석의 체내에 맹독이 있기 때문이다. 녀석의 독은 한 방울만으로도 치명적이라고 한다. 따라서 녀석은 화려하고 이목을 끄는 외형을 하고 있지만, 다른 생물들의 관심을 받는 것을 조금도 두려워하지 않는다.",
  str_item_intro_5520901 = "매우 희귀한 물고기다. 화려한 색의 몸을 가지고 있으며, 몸집이 작고 속도가 매우 빠르다. 경계심이 높으며, 수면에서 약간의 인기척만 느껴져도 몸의 색을 숨겨버린다. 발견하기가 매우 어렵기 때문에 녀석을 잡으려면 큰 인내심이 필요하다. 매우 고생스럽지만, 녀석이 헤엄치며, 생기는 「오색의 끈」을 보면 그만한 가치가 있다.",
  str_item_intro_5530001 = "뜻밖의 수확! 조개가 때마침 진주를 품고 있다. 광택이나 형태를 보니 품질이 좋아 높은 가격에 팔 수 있을 것 같다.",
  str_item_intro_5530101 = "낡은 철제 깡통이다. 누가 버린 건진 몰라도 환경 보호에 너무 무관심한 것 같다...",
  str_item_intro_5530201 = "이 신발은 해초가 자기 집으로 삼았을 정도로 물속에서 오래 「생활」한 것 같다.",
  str_item_intro_5601101 = "“언젠가는 나도 하늘에서 내 집을 지킬 수 있을 거야.”",
  str_item_intro_5601201 = "“콜로서스를 인도하는 기묘한 에너지를 내가 이해할 수 있었으면 좋겠어...”",
  str_item_intro_5602101 = "“기억은 평생에 한 번이지만, 기록은 천 년 동안 전해진다. 그래서 나는 사람들이 찾아줄 때까지 기억하고 쓰고 간직할 것이다.”",
  str_item_intro_5602201 = "“난 세상 끝까지 가서라도 그 도면을 반드시 찾을 거야.”",
  str_item_intro_5602202 = "“누군가는 모든 것엔 대가가 있다고 하던데, 지식의 대가는 뭐죠?”",
  str_item_intro_5602203 = "“머리는 배움으로 유지되고, 삶은 감정으로 유지된다.”",
  str_item_intro_5603101 = "“쉽게 포기해선 안 돼. 실험에 99번 실패하더라도, 다음번에는 성공할지도 모르니까.”",
  str_item_intro_5603201 = "“한 물건을 다른 물건으로 바꿀 수 있는 궁극적인 원리는 무엇일까? 근원을 찾는 길을 갈 수 있다면 좋을 텐데.”",
  str_item_intro_5603202 = "“영감은 불꽃처럼 스쳐 간다. 이 불꽃이 영원할 수만 있다면 난 평생을 찾아 다니겠어.”",
  str_item_intro_5603301 = "“칼이란 날이 예리해야만 좋은 게 아냐. 가끔은 날이 무뎌야 효과적일 때도 있어. 그녀와 지내려면 가끔은 「무뎌야」 할지도...”",
  str_item_intro_5604101 = "“나무마다 자신의 운명이 있기 마련이죠. 저에게도 있을까요? 하루빨리 알 수 있었으면 좋겠네요...”",
  str_item_intro_5604201 = "“은색 잎? 그녀는 없다고 말했지만 난 믿을 수 없었지. 그래서 찾으러 온 거야.”",
  str_item_intro_5604202 = "“나이테는 나무 속에 새겨진 세월의 흔적이며, 역사이자 기억이다. 나무와 대화하면 우리가 모르는 과거를 알게 될지도 모른다... 그것이 바로 우리의 연륜이야.”",
  str_item_intro_5604203 = "“잎사귀와 나무가 엇갈린 그림자 사이로 그의 옆모습이 떠오르는 것만 같다. 이건 운명의 설계일까?”",
  str_item_intro_5604301 = "“그것들은 항상 조용히 성장하고 조용히 시들어. 그런 고고한 태도는 정말 배울 가치가 있는 것 같아.”",
  str_item_intro_5604302 = "“우리의 뿌리는 어디 있을까? 사는 동안 그걸 알 수 있었으면 좋겠는데...”",
  str_item_intro_5605201 = "“물결무늬를 보면 낚시를 가르쳐 주시던 아버지가 생각나.”",
  str_item_intro_5605301 = "“이 하얀 낚싯대는 어머니께서 물려주신 유품이야. 난 이걸 우리 딸한테 물려줄 거야.”",
  str_item_intro_5605302 = "“나와 그녀 사이에는 이 가느다란 실만이 남아 있어. 하지만 부디 이 실이 끊어지지 않았으면 좋겠어.”",
  str_item_intro_5605303 = "“그녀의 선물이 미끼라 할지라도, 난 기꺼이 그 미끼에 걸리겠어.”",
  str_item_intro_5605304 = "“때때로 낚시는 무언가를 낚기 위해서가 아니라, 파도에 비치는 빛을 보기 위해서 하는 것이다.”",
  str_item_intro_5605305 = "“난 물이 흐르는 방향은 알 수 있어. 하지만 언제쯤 그녀의 마음을 알 수 있을까...”",
  str_item_intro_5605306 = "“낚싯바늘이 살랑살랑 흔들린다는 건 물고기가 왔다는 뜻이야. 인생에도 이런 힌트가 있었으면 좋겠는데.”",
  str_item_intro_5606201 = "“아무것도 이루지 못하고, 발굴해내지 못한 우리 아버지처럼 되지 않기를. 부디 내게 행운을!”",
  str_item_intro_5606301 = "“성실함은 내 어리석음을 감추었지. 모두가 날 채광의 천재라고 부르게 만들겠어.”",
  str_item_intro_5606302 = "“암석을 무시하지 마. 가끔 안에서 보물이 나올 때도 있으니까.”",
  str_item_intro_5606303 = "“항상 곡괭이 끝을 날카롭게!”",
  str_item_intro_5606304 = "“광산을 파는 건 힘만으로 되지 않아. 사랑처럼 테크닉도 필요한 법!”",
  str_item_intro_5606305 = "“광맥도 전부 냄새가 달라! 내 코는 아주 민감하거든. 하지만 그 사람의 행방도 알 수 있다면 좋을 텐데...”",
  str_item_intro_5606306 = "“끈기 있게 계속하다 보면 분명히 그 광맥을 찾을 수 있을 거야. 그게 이 산에 있든 없든 상관없어.”",
  str_item_intro_5607201 = "“그는 바구니고, 제 마음은 그 속에 담겨 있어요.”",
  str_item_intro_5607301 = "“그녀가 내 마음을 채집해 준다면 정말 좋겠는데.”",
  str_item_intro_5607302 = "“난 어렸을 때 나무의 열매에 맞은 뒤로 지금까지 항상 운이 좋았어. 앞으로도 그랬으면 좋겠어.”",
  str_item_intro_5607303 = "“좋은 꿀을 찾으려면 꿀벌을 따라가야 하는 경우가 많아. 녀석들의 말을 내가 이해할 수만 있다면...”",
  str_item_intro_5607304 = "“마음에도 장갑이 있다면, 가시 돋친 「꽃」에 상처받지 않게 될까?”",
  str_item_intro_5607305 = "“단번에 열매를 찾으려면 눈썰미가 필요해. 응, 앞으로도 이 정도 수준을 유지할 수 있었으면 해.”",
  str_item_intro_5608101 = "“작물이 햇빛을 거부하지 않듯, 그도 날 거부하지 않기를.”",
  str_item_intro_5608201 = "“파종은 단지 수확만을 위한 것이 아니라 희망을 심는 것이다.”",
  str_item_intro_5608301 = "“난 풍차가 천천히 돌아가는 모습이 제일 좋아. 아무 생각 없이 온종일 볼 수 있거든...”",
  str_item_intro_5608302 = "“씨앗은 정말 신기해. 그렇게 작은 것에서 이렇게나 많은 작물이 자라나잖아! 그래서... 씨앗만 있다면 희망은 있어!”",
  str_item_intro_5608303 = "“작물은 양분으로 태양을 필요로 한다. 마치 내가 그녀를 필요로 하는 것처럼,”",
  str_item_intro_5608304 = "“햇빛이 너무 강하면 식물이 죽을 수 있어요. 그에 대한 관심도 마찬가지예요.”",
  str_item_intro_5608305 = "“농작물을 너무 촘촘하게 심으면 안 돼요. 반드시 밭고랑이 있어야 하죠. 아무래도 그녀와 어느 정도 거리를 둬야겠어요.”",
  str_item_intro_5609201 = "“손질할 필요가 없는 풀을 심을 수 있다면, 그걸로 커다랗고 편안한 담요를 만들 거야~”",
  str_item_intro_5609301 = "“물방울은 부드러우면서 단단해. 나도 그런 사람이 될 수 있을까?”",
  str_item_intro_5609302 = "“식물이 건강하게 자라려면 좋은 토양이 필요하죠. 저희도 그렇지 않나요? 장로님, 저희에게 다양한 배토를 주시고, 각자 바라는 사람이 되게 해주셔서 감사합니다.”",
  str_item_intro_5609303 = "“가장 달콤한 꿀을 가져다 미래의 자녀에게 주고 싶어요.”",
  str_item_intro_5609304 = "“휴, 벌처럼 자유롭게 춤출 수 있다면 좋을 텐데.”",
  str_item_intro_5609305 = "“아름다운 꽃들만 보지 말고 주위에 깔린 푸른 잎도 봐야 하는 법이죠. 그렇지 않나요~”",
  str_item_intro_5610101 = "“난 많은 가축 무리를 몰 수 있지만, 가족들의 마음은 이해할 수 없어. 부디 내 미래의 자식은 안 그랬으면 좋겠어.”",
  str_item_intro_5610201 = "“우유를 부을 때 컵 안에 웃는 얼굴 같은 무늬가 생기면 새해에 행운이 찾아온다고 해!”",
  str_item_intro_5610202 = "“외부의 마을에서는 순찰견을 가지고 방목을 한다고 들었어. 근데 나한텐 그 아이뿐인걸~”",
  str_item_intro_5610203 = "“저 멀리 사막에는 「낙타」라는 생물이 있다는데, 그 젖이 아주 맛있대~”",
  str_item_intro_5610204 = "“언젠가는 푸른 풀이 싹트는 걸 볼 수 있겠지. 그때가 되면 그 초원도 다시 나타날 거야.”",
  str_item_intro_5610301 = "“계곡 밖에는 더 넓은 초원이 있다고 들었지만, 난 이곳의 수풀이 마음에 들어.”",
  str_item_intro_5610302 = "“치즈는 세상에서 가장 맛있는 음식이야. 평생 매일 먹을 수 있다면 그곳이 바로 천국이겠지.”",
  str_item_intro_5610303 = "“사막 사람들은 수원지 근처에 지내면서 거기서 조금도 벗어날 수 없대. 그럼 아무래도 그녀가 내 수원지인 것 같아~”",
  str_item_intro_5611101 = "“바닷가 사람들이 작은 섬처럼 커다란 배를 본 적이 있다고 하던데, 정말 보고 싶어!”",
  str_item_intro_5611201 = "“만약 잠을 안 자도 된다면, 난 계속 보초병 일을 할 수 있겠지.”",
  str_item_intro_5611202 = "“내가 있는 한, 어떤 사악한 자도 이곳에 오지 못할 거야. 특히 저 아이들을 위협하는 자들은 절대...”",
  str_item_intro_5611203 = "“이곳의 수호자가 된 후로, 난 밤에도 쉴 수가 없게 됐어.”",
  str_item_intro_5611204 = "“그 어떤 세부적인 문제도 놓쳐서는 안 된다. 그렇지 않으면 큰 재앙으로 이어질 수 있다.”",
  str_item_intro_5611301 = "“3일 밤낮을 걸어도 피곤하지 않은 이 재능은 계곡을 순찰하고 외부인의 출입을 경계하는 데 쓰겠어.”",
  str_item_intro_5611302 = "“난 가족의 든든한 방패가 될 거야! 하하, 백야성의 기사 서약에서 배운 건데 좀 멋진 것 같아! 난 말한 건 반드시 지켜!”",
  str_item_intro_5611303 = "“저 횃불처럼 생긴 큰 나무들이 실제로 불을 밝힐 수 있다면, 밤에 가로등으로 사용할 수 있지 않을까?”",
  str_item_intro_6400001 = "획득 시 칭호: 대국을 여는 자 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400002 = "획득 시 칭호: 전술의 대가 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400003 = "획득 시 칭호: 전략에 통달한 자 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400004 = "획득 시 칭호: 재앙의 속박 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400005 = "획득 시 칭호: 루인 학살자 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400006 = "획득 시 칭호: 불굴의 의지 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400007 = "획득 시 칭호: 황금의 요새 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400008 = "획득 시 칭호: 하늘을 부리는 자 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400009 = "획득 시 칭호: 창궁을 거니는 자 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400010 = "획득 시 칭호: 계절의 인연 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400011 = "획득 시 칭호: 겨울과 봄 사이 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400012 = "획득 시 칭호: 깊은 잠의 소생 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400013 = "획득 시 칭호: 드러난 과거 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400014 = "획득 시 칭호: 수많은 만남 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400015 = "획득 시 칭호: 빛나는 인연 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400016 = "획득 시 칭호: 정상 정복 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400017 = "획득 시 칭호: 정점의 패자 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400018 = "획득 시 칭호: 드러난 과거 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400019 = "획득 시 칭호: 각성의 부름 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400020 = "획득 시 칭호: 심연의 주인 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400021 = "획득 시 칭호: 지혜를 깨우친 자 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400026 = "획득 시 칭호: 미지의 발걸음 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400030 = "획득 시 칭호: 해로의 수호자 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6400031 = "획득 시 칭호: 하늘의 호령 개방.\n획득 후 명함-칭호 화면에서 해당 칭호를 사용할 수 있다.",
  str_item_intro_6500001 = "초기 명함 장식이다. 명함-명함 장식 메뉴에서 해당 장식을 사용할 수 있다.",
  str_item_intro_6500002 = "초기 명함 장식이다. 명함-명함 장식 메뉴에서 해당 장식을 사용할 수 있다.",
  str_item_intro_6500003 = "초기 명함 장식이다. 명함-명함 장식 메뉴에서 해당 장식을 사용할 수 있다.",
  str_item_intro_6500004 = "초기 명함 장식이다. 명함-명함 장식 메뉴에서 해당 장식을 사용할 수 있다.",
  str_item_intro_6500005 = "초기 명함 장식이다. 명함-명함 장식 메뉴에서 해당 장식을 사용할 수 있다.",
  str_item_intro_6500008 = "새하얗게 뒤덮인 굽이굽이 이어진 언덕들의 차갑고 고요한 모습은, 흡사 또 다른 생명력을 지닌 것만 같다.",
  str_item_intro_6500011 = "안개가 자욱한 거리에서 은밀한 거래가 이루어지는 모습은 움브라톤의 또 다른 일상이다.",
  str_item_intro_6500014 = "일루미나 지하성 내의 정비공장이다. 많은 수의 파손된 장비를 빠르게 수리할 수 있으며, 대형 기계까지도 수리가 가능하다.",
  str_item_intro_6500015 = "백야성의 축제는 여느 때처럼 성대합니다.",
  str_item_intro_6500016 = "물줄기, 사거리... 지리와 지형의 편의성이 움브라톤의 번영을 일궈냈다.",
  str_item_intro_6500017 = "어둠이 태양을 집어삼키는 순간, 이는 모종의 격변을 예고하는 것일까.",
  str_item_intro_6500018 = "얼음과 추위로 가득한 북방, 그곳은 베들레헴에게 속한 곳으로, 그녀가 지키려는 땅이기도 하다.",
  str_item_intro_6500020 = "누가 뭐라고 해도 나쁜 사람들이 콘서트를 망치게 만들 순 없어! 이게 바로 정의야!",
  str_item_intro_6500021 = "얼음과 추위로 가득한 북방, 그곳은 베들레헴에게 속한 곳으로, 그녀가 지키려는 땅이기도 하다.",
  str_item_intro_6500024 = "그 순간, 모든 경계를 푼 듯 환하게 웃으며 앳된 모습을 드러낸 그녀. 이것은 두 사람만의 비밀이었다.",
  str_item_intro_6500026 = "레디젤 렌치의 축하 파티는 왠지 다양한 사막 진미의 향연으로 변한 것 같다.",
  str_item_intro_6500033 = "여행 도중 피로가 느껴진다면, 동료들과 함께 앉아 이야기를 듣는 것도 좋은 방법입니다.",
  str_item_intro_6500035 = "하늘의 도시에 내리쬐는 햇살은 오랜 세월 변하지 않았다. 지난날의 드레스를 입은 그녀는 저 거대한 유화 앞에 한참을 서서 무언가를 생각해 내고 있는 것 같다...",
  str_item_intro_6500036 = "플로리나가 곁에 있는 한, 아무리 위험한 바다라도 안전해진다.",
  str_item_intro_6500037 = "그저 오래전 모두에게 잊힌 사명을 완수하기 위해, 백여 년간 이곳을 지킨 누군가가 있다.",
  str_item_intro_6500038 = "산들바람은 과거의 그늘을 날려 보내고, 붉은 노을빛은 마치 화염처럼 모든 근심을 불태워, 당신에게 새로운 미래를 가져다줄 것이다.",
  str_item_intro_6500039 = "그녀는 마치 등탑처럼, 온 칠흑 같은 바다를 비추고, 모험가들이 집으로 돌아오는 길을 비출 것이다.",
  str_item_intro_6500041 = "추운 날씨, 눈과 얼음이 대지를 덮어버릴지라도, 동료들과 함께라면 언제나 마음속엔 온기가 있겠죠. 부디 즐거운 나날을 보내시길 바랄게요~",
  str_item_intro_6500042 = "샤엘은 높이 뛰어올라 습격해 온 적들을 물리쳤다. 이때 그녀는 비로소 그 누구도 알지 못했던 자신의 다른 모습을 보여주었다.",
  str_item_intro_6500043 = "사막의 변방에는 관측소가 연이어 세워져 있다. 머나먼 고향이 적의 습격을 받지 않도록, 그들은 이곳에서 지키고 있다.",
  str_item_intro_6500044 = "점포가 구름처럼 즐비하고, 사람이 시끌벅적 모여 있다. 주민과 여행객들이 쌍사성 번화가에 모여 저마다 원하는 상품을 고르고 있어 무척이나 떠들썩하다.",
  str_item_intro_6500045 = "「날 인정해 줘서 고마워. 만물은 백야 아래에!」",
  str_item_intro_6500046 = "「난 혼자 멍하니 있는 게 좋아. 하지만... 이젠 네가 곁에 있는 것도 나쁘지 않아.」",
  str_item_intro_6500047 = "「이 세상은 여전히 전쟁의 불길로 가득 차 있군. 넌 앞으로도 나와 함께 저 분쟁들을 해결해 줄 수 있겠나?」",
  str_item_intro_6500049 = "「개굴개굴개굴!」",
  str_item_intro_6500051 = "매의 무리 같은 드론들이 소녀를 둘러싸고 있고, 그녀는 당신을 돌아보았다.\n「이젠 괜찮아.」",
  str_item_intro_6500053 = "그녀는 눈부시게 웃으며 심연 속으로 뛰어들었다.\n「누구도 네 힘과 즐거움을 빼앗아 가지 못하게 해.」",
  str_item_intro_6500054 = "숙명의 분기점에 선 지금, 어떤 미래를 선택해야 할까.",
  str_item_intro_6500056 = "네가 경험한 모든 것이 진리의 결사가 미래로 나아가는 길을 인도할 거야.",
  str_item_intro_6500057 = "바닷바람, 빙수, 세발자전거. 그 소녀와 처음으로 함께 보낸 여름의 추억은 지금까지도 선명한 기억으로 남아 있다.",
  str_item_intro_6500058 = "재회의 맹세, 영혼이 만나는 곳",
  str_item_intro_9993001 = "전투 승리 후, 랜덤으로 파티 내 생존한 오로리안 중 1명의 HP를 20% 회복시킴",
  str_item_intro_9993002 = "서포터 클래스 오로리안의 전투 중 연쇄 스킬 및 액티브 스킬의 회복 효과 25% 증가",
  str_item_intro_9993003 = "전투에서 얻은 붕대의 회복 HP 80% 증가",
  str_item_intro_9993004 = "스나이퍼 클래스 오로리안의 속성 상성 효과 10% 증가",
  str_item_intro_9993005 = "버스터 클래스 오로리안이 15칸 이상 연결 시 연쇄 스킬 피해 30% 증가",
  str_item_intro_9993006 = "암귀가 받는 중독, 작열, 출혈 피해 50% 증가",
  str_item_intro_9993007 = "스나이퍼 클래스 오로리안의 연쇄 스킬 피해 15% 증가",
  str_item_intro_9993008 = "버스터 클래스 오로리안의 일반공격이 30% 확률로 150%의 피해를 입힘",
  str_item_intro_9993009 = "체인저 클래스 오로리안의 최대 HP 15% 증가",
  str_item_intro_9993010 = "스나이퍼 클래스 오로리안의 최대 HP 15% 증가",
  str_item_intro_9993011 = "버스터 클래스 오로리안의 최대 HP 25% 증가",
  str_item_intro_9993012 = "서포터 클래스 오로리안의 최대 HP 25% 증가",
  str_item_intro_9993013 = "모든 오로리안의 최대 HP가 5% 증가한다",
