  str_item_intro_9993026 = "숲 속성 오로리안 공격력 5% 증가",
  str_item_intro_9993027 = "숲 속성 오로리안 공격력 5% 증가",
  str_item_intro_9993028 = "숲 속성 오로리안 공격력 5% 증가",
  str_item_intro_9993029 = "번개 속성 오로리안 공격력 5% 증가",
  str_item_intro_9993030 = "번개 속성 오로리안 공격력 5% 증가",
  str_item_intro_9993031 = "번개 속성 오로리안 공격력 5% 증가",
  str_item_intro_9993032 = "번개 속성 오로리안 공격력 5% 증가",
  str_item_intro_9993033 = "번개 속성 오로리안 공격력 5% 증가",
  str_item_intro_9993034 = "전투 승리 시 체인저와 서포터 클래스 오로리안의 HP 3% 증가(최대 30%)",
  str_item_intro_9993035 = "전투 승리 시 스나이퍼와 버스터 클래스 오로리안의 공격력 1.5% 증가(최대 15%)",
  str_item_intro_9993036 = "전투 승리 시 파티 내 생존한 오로리안 중 랜덤 1명이 중첩 가능한 피해 감소 효과를 획득하며, 회당 1.5%의 피해 감소, 해당 비경 탐색 동안 지속됨",
  str_item_intro_9994001 = "암귀를 처치할 때마다 랜덤으로 파티 내 생존한 오로리안 중 1명의 HP를 10% 회복시킴",
  str_item_intro_9994002 = "중독 상태의 암귀가 중독 피해를 입을 때마다 서포터 클래스 오로리안이 해당 피해만큼 HP 회복",
  str_item_intro_9994003 = "버스터 클래스 오로리안이 상태 이상 암귀에게 주는 피해 30% 증가",
  str_item_intro_9994004 = "중독, 작열 또는 출혈 상태의 암귀 사망 시 모든 필드의 적에게 중독 3단계 부여",
  str_item_intro_9994005 = "암귀 턴 시작 시 중독, 작열 또는 출혈 상태의 암귀가 주변 2서클 내의 암귀에게 중독 효과 부여",
  str_item_intro_9994006 = "아군 파티에 상태 이상이 있을 때, 스나이퍼 클래스 오로리안 피해 30% 증가",
  str_item_intro_9994007 = "피해를 입을 때마다 버스터 클래스 오로리안이 5%의 피해 증가 획득(전투 종료 시 초기화)",
  str_item_intro_9994008 = "전투 시작 시 전장에 붕대 1개 소환",
  str_item_intro_9994009 = "HP가 70% 이상인 모든 스나이퍼 클래스 오로리안의 피해 20% 증가",
  str_item_intro_9994010 = "공격 시 버스터 클래스 오로리안이 잃은 HP의 10%만큼 피해 증가",
  str_item_intro_9994011 = "루미나 샘에서 MS치 5 추가 회복",
  str_item_intro_9994012 = "루미나 샘 HP 회복 선택 시 회복 인원 수 +1",
  str_item_intro_9994013 = "위험 구역 내 버스터 클래스 오로리안 공격력 +10%",
  str_item_intro_9994014 = "치명 구역 내 버스터 클래스 오로리안 공격력 +10%",
  str_item_intro_9994015 = "보물 도굴자의 도주 턴이 강제로 4턴 연장됨",
  str_item_intro_9994016 = "대형 암귀 처치 시 모든 오로리안 쿨다운 1턴 감소",
  str_item_intro_9994017 = "대형 암귀 처치 시 스나이퍼 클래스 오로리안 공격력 20% 증가",
  str_item_intro_9994018 = "대형 암귀 처치 시 파티 내 HP가 가장 적은 생존 오로리안의 HP가 20% 회복한다",
  str_item_intro_9994019 = "모든 소형 몬스터에 둔화 효과 부여",
  str_item_intro_9994020 = "모든 소형 몬스터의 초기 HP -20%",
  str_item_intro_9994021 = "모든 소형 몬스터 공격력 -10%",
  str_item_intro_9994022 = "전투 시작 시 액티브 스킬 쿨다운이 끝나지 않은 체인저 클래스 오로리안 쿨다운 -1",
  str_item_intro_9994023 = "획득 후 오로리안 주위를 떠다니며, 리더 공격 시 불 속성 피해를 1회 입힌다.",
  str_item_intro_9994024 = "획득 후 오로리안 주위를 떠다니며, 리더 공격 시 물 속성 피해를 1회 입힌다.",
  str_item_intro_9994025 = "획득 후 오로리안 주위를 떠다니며, 리더 공격 시 숲 속성 피해를 1회 입힌다.",
  str_item_intro_9994026 = "획득 후 오로리안 주위를 떠다니며, 리더 공격 시 번개 속성 피해를 1회 입힌다.",
  str_item_intro_9995001 = "파티에 있는 오로리안 사망 시 50% HP로 부활(각 전투에서 처음으로 치명적 피해를 입은 오로리안 한 명에게 1회만 발동)",
  str_item_intro_9995002 = "해당 성물 보유 시 체인저 클래스 오로리안이 받는 단일 피해가 최대 HP의 20%를 초과하지 않음",
  str_item_intro_9995003 = "서포터 클래스 오로리안의 초과된 치유량을 비율에 따라 1턴 지속되는 실드로 전환",
  str_item_intro_9995004 = "전투를 시작할 때마다 50% 확률로 충격파를 시전해 모든 적 대상을 1턴간 스턴시킴",
  str_item_intro_9995005 = "스나이퍼 클래스 오로리안의 일반공격 및 연쇄 스킬이 암귀의 실드를 즉시 제거함",
  str_item_intro_9995006 = "전투 시작 시 근처의 8개 칸 중에서 랜덤으로 4개 만색 칸 등장",
  str_item_intro_9995007 = "전투 시작 시 전장에서 MS치를 보충하는 루미나미터 1개 초기화",
  str_item_intro_9995008 = "전투 시작 시 랜덤으로 2x2칸 10곳에 낙뢰를 일으켜 범위 내 대상에게 고정 퍼센트의 피해를 입힘(오로리안에게는 효과 없음)",
  str_item_intro_9995009 = "이동하는 시작점에 폭탄을 한 개 남겨, 아군 행동 종료 후 폭발",
  str_item_intro_9995010 = "콤보 수가 5의 배수인 일반공격에 1회 폭발 효과 부여",
  str_item_intro_9995011 = "죽음의 숨결을 소환해 HP 7% 이하의 암귀를 즉사시킴",
  str_item_intro_9995012 = "버스터 클래스 오로리안이 연쇄 스킬 시전 시 연결을 시작한 위치에 현재 스킬을 시전한 오로리안의 분신을 만들고, 동시에 연쇄 스킬을 시전함",
  str_item_intro_9995013 = "운명의 주사위를 넣는 상자. 운명의 주사위를 소모하여 랜덤으로 비경 성물 1개를 획득할 수 있다.",
  str_item_intro_9995014 = "스나이퍼 클래스 오로리안이 40% 확률로 연쇄 스킬 1회 추가 발동",
  str_item_intro_9995015 = "오로리안 한 명이 액티브 스킬 시전 시 랜덤으로 체인저 클래스 오로리안 한 명의 쿨다운 -1",
  str_item_intro_9995016 = "스나이퍼 클래스 오로리안 일반공격이 암귀에게 둔화 효과를 부여함. 암귀의 이동력 -1",
  str_item_intro_9995017 = "전투 시작 시 모든 암귀에게 중상 효과를 부여하여, 암귀가 1칸을 이동할 때마다 3%의 피해를 입힘",
  str_item_intro_9995018 = "서포터 클래스 오로리안 일반공격 시 암귀에게 실명 효과를 부여하여, 암귀가 공격할 때 30% 확률로 명중할 수 없게 만듦",
  str_item_rpintro_9993001 = "따스한 빛을 발산하는 양초. 그 빛에는 오로리안의 상처를 치유하는 힘이 있다.",
  str_item_rpintro_9993002 = "구시대의 페인트. 루미나를 잘 흡수할 수 있다.",
  str_item_rpintro_9993003 = "회복 물약의 보조품. 전투원의 부상 회복을 돕는다.",
  str_item_rpintro_9993004 = "고대의 학자가 쓴 노트로 보인다. 상성 간의 기묘한 관계가 적혀 있으며, 전투원에게 상성에 맞춰 전투하는 방법을 알려줄 수 있다.",
  str_item_rpintro_9993005 = "구시대의 배지. 신비한 구조를 갖고 있어, 미시적인 차원에서 루미나를 연결시켜 전투력을 증가시킨다.",
  str_item_rpintro_9993006 = "구시대의 유물. 강렬한 저주가 걸려 있어서, 이것을 쓴 자가 독을 사용하면 치명상을 입힐 수 있다.",
  str_item_rpintro_9993007 = "구시대의 수호 부적. 미시적인 차원에서 루미나를 연결시켜, 전투에서 적에게 큰 피해를 입힐 수 있다.",
  str_item_rpintro_9993008 = "오래된 단검. 구시대의 고강도 합금을 사용하여, 굉장히 날카롭다.",
  str_item_rpintro_9993009 = "루미나가 주입된 가죽 갑옷. 가볍고 튼튼하여, 탐색자의 저항 능력을 높여 준다.",
  str_item_rpintro_9993010 = "루미나가 주입된 가죽 갑옷. 가볍고 튼튼하여, 탐색자의 저항 능력을 높여 준다.",
  str_item_rpintro_9993011 = "루미나가 주입된 가죽 갑옷. 가볍고 튼튼하여, 탐색자의 저항 능력을 높여 준다.",
  str_item_rpintro_9993012 = "루미나가 주입된 가죽 갑옷. 가볍고 튼튼하여, 탐색자의 저항 능력을 높여 준다.",
  str_item_rpintro_9993013 = "루미나가 주입된 가죽 갑옷. 가볍고 튼튼하여, 탐색자의 저항 능력을 높여 준다.",
  str_item_rpintro_9993014 = "신비한 빨간색 칠각 보석. 소지하면 불 속성 오로리안의 힘을 크게 증가시킨다.",
  str_item_rpintro_9993015 = "신비한 빨간색 칠각 보석. 소지하면 불 속성 오로리안의 힘을 크게 증가시킨다.",
  str_item_rpintro_9993016 = "신비한 빨간색 칠각 보석. 소지하면 불 속성 오로리안의 힘을 크게 증가시킨다.",
  str_item_rpintro_9993017 = "신비한 빨간색 칠각 보석. 소지하면 불 속성 오로리안의 힘을 크게 증가시킨다.",
  str_item_rpintro_9993018 = "신비한 빨간색 칠각 보석. 소지하면 불 속성 오로리안의 힘을 크게 증가시킨다.",
  str_item_rpintro_9993019 = "신비한 파란색 칠각 보석. 소지하면 물 속성 오로리안의 힘을 크게 증가시킨다.",
  str_item_rpintro_9993020 = "신비한 파란색 칠각 보석. 소지하면 물 속성 오로리안의 힘을 크게 증가시킨다.",
