  str_item_rpintro_9993022 = "신비한 파란색 칠각 보석. 소지하면 물 속성 오로리안의 힘을 크게 증가시킨다.",
  str_item_rpintro_9993023 = "신비한 파란색 칠각 보석. 소지하면 물 속성 오로리안의 힘을 크게 증가시킨다.",
  str_item_rpintro_9993024 = "신비한 초록색 칠각 보석. 소지하면 숲 속성 오로리안의 힘을 크게 증가시킨다.",
  str_item_rpintro_9993025 = "신비한 초록색 칠각 보석. 소지하면 숲 속성 오로리안의 힘을 크게 증가시킨다.",
  str_item_rpintro_9993026 = "신비한 초록색 칠각 보석. 소지하면 숲 속성 오로리안의 힘을 크게 증가시킨다.",
  str_item_rpintro_9993027 = "신비한 초록색 칠각 보석. 소지하면 숲 속성 오로리안의 힘을 크게 증가시킨다.",
  str_item_rpintro_9993028 = "신비한 초록색 칠각 보석. 소지하면 숲 속성 오로리안의 힘을 크게 증가시킨다.",
  str_item_rpintro_9993029 = "신비한 노란색 칠각 보석. 소지하면 번개 속성 오로리안의 힘을 크게 증가시킨다.",
  str_item_rpintro_9993030 = "신비한 노란색 칠각 보석. 소지하면 번개 속성 오로리안의 힘을 크게 증가시킨다.",
  str_item_rpintro_9993031 = "신비한 노란색 칠각 보석. 소지하면 번개 속성 오로리안의 힘을 크게 증가시킨다.",
  str_item_rpintro_9993032 = "신비한 노란색 칠각 보석. 소지하면 번개 속성 오로리안의 힘을 크게 증가시킨다.",
  str_item_rpintro_9993033 = "신비한 노란색 칠각 보석. 소지하면 번개 속성 오로리안의 힘을 크게 증가시킨다.",
  str_item_rpintro_9993034 = "구시대에서 남겨진 작은 조각상. 고강도 재료로 만들어져서 견고하면서도 가벼우며, 지닌 사람에게 축복을 내린다.",
  str_item_rpintro_9993035 = "구시대에서 온 무기. 고강도 재료로 만들어진 데다가 루미나까지 주입되어, 가지고 다니는 사람에게 강한 힘을 준다.",
  str_item_rpintro_9993036 = "구시대의 낡은 방패... 완벽한 원형이다. 태양의 힘이 주입되었다고 하며, 루미나의 힘으로 모든 치명적인 공격을 막아 준다.",
  str_item_rpintro_9994001 = "사악한 기운을 풍기는 참도. 고대의 치열한 전투에 많이 쓰였던 무기로 보이며, 한번 뽑으면 반드시 피를 봐야 한다.",
  str_item_rpintro_9994002 = "구시대에 의사가 쓰던 가면. 전란 시기에는 저주의 상징이었다.",
  str_item_rpintro_9994003 = "구시대의 명검. 사용자는 신에 필적하는 힘을 느낄 수 있다.",
  str_item_rpintro_9994004 = "강력한 전사가 직접 만들었다는 저주받은 물건. 적에게 벗어날 수 없는 죽음의 운명을 내린다.",
  str_item_rpintro_9994005 = "오래 전에 무명 작가가 그린 오래된 그림. 역병이 유행하던 당시의 참상을 그렸다. 작가도 그 역병에 걸려 죽고 난 후, 그림에 무서운 힘이 생겼다.",
  str_item_rpintro_9994006 = "구시대의 명검. 사용자는 유명한 반역자였는데, 죽을 때의 절규가 칼에 기묘한 힘을 불어넣었다.",
  str_item_rpintro_9994007 = "이 오래된 갑옷에는 「복수」라는 글자가 새겨져 있는데, 착용자는 갑옷에 숨겨진 끝없는 분노를 느낀다.",
  str_item_rpintro_9994008 = "온전히 보존된 여신 조각상. 빛의 백성들에게 치유의 힘을 제공한다.",
  str_item_rpintro_9994009 = "그녀와 함께라면 승리의 여신의 비호를 받아, 전투에서 불리해지지 않을 것이다.",
  str_item_rpintro_9994010 = "이 비수는 고대 문명의 내전 중에 만들어졌다고 하며, 불길한 기운을 발산한다. 꺼내면 반드시 피를 봐야 하며, 그렇지 않으면 평범한 칼날과 다름없다.",
  str_item_rpintro_9994011 = "구시대의 기술. 자그마한 상자에 불과하지만, 많은 루미나를 저장할 수 있다.",
  str_item_rpintro_9994012 = "과거에 어떤 사람이 남긴 접이식 침낭. 체력을 잘 회복할 수 있다.",
  str_item_rpintro_9994013 = "태양의 축복을 받은 총. 발사 속도는 느리지만 위력은 엄청나서, 강력한 적에 맞서 싸우기에 유용한 무기.",
  str_item_rpintro_9994014 = "오랜 세월 동안 여러 주인을 거쳤지만, 그 시간은 모두 길지 않았다...",
  str_item_rpintro_9994015 = "마비 광선을 발사하는 원거리 병기. 사거리가 짧고 위력이 크지 않아서, 좀도둑을 붙잡는 데 주로 사용한다.",
  str_item_rpintro_9994016 = "옛 용사의 광휘의 유물. 과거의 축복이 걸려 있어서, 강력한 적을 상대할 때 탁월한 효과를 발휘한다.(광휘의 유물 3종 동시 보유 시 효과 2배)",
  str_item_rpintro_9994017 = "옛 용사의 광휘의 유물. 과거의 축복이 걸려 있어서, 강력한 적을 상대할 때 탁월한 효과를 발휘한다.(광휘의 유물 3종 동시 보유 시 효과 2배)",
  str_item_rpintro_9994018 = "옛 용사의 광휘의 유물. 과거의 축복이 걸려 있어서, 강력한 적을 상대할 때 탁월한 효과를 발휘한다.(광휘의 유물 3종 동시 보유 시 효과 2배)",
  str_item_rpintro_9994019 = "옛 병사가 사용한 고전 무기. 과거의 축복이 걸려 있어서, 재빠른 적을 상대할 때 괜찮은 효과를 발휘한다.(은월 유물 3종 동시 보유 시 효과 2배)",
  str_item_rpintro_9994020 = "옛 병사가 사용한 고전 무기. 과거의 축복이 걸려 있어서, 재빠른 적을 상대할 때 괜찮은 효과를 발휘한다.(은월 유물 3종 동시 보유 시 효과 2배)",
  str_item_rpintro_9994021 = "옛 병사가 사용한 고전 무기. 과거의 축복이 걸려 있어서, 재빠른 적을 상대할 때 괜찮은 효과를 발휘한다.(은월 유물 3종 동시 보유 시 효과 2배)",
  str_item_rpintro_9994022 = "오래되고 신비한 코인. 이것을 가진 오로리안은 힘이 증가하며, 행동이 더욱 민첩해진다.",
  str_item_rpintro_9994023 = "구시대의 산물. 여러모로 콜로서스의 축소판으로 보이며, 전투에서 주인의 작전을 돕는다. 4가지 속성 플로터 보유 시 오로리안이 연쇄 스킬 시전 후 추가로 1회 강력한 공격을 한다.",
  str_item_rpintro_9994024 = "구시대의 산물. 여러모로 콜로서스의 축소판으로 보이며, 전투에서 주인의 작전을 돕는다. 4가지 속성 플로터 보유 시 오로리안이 연쇄 스킬 시전 후 추가로 1회 강력한 공격을 한다.",
  str_item_rpintro_9994025 = "구시대의 산물. 여러모로 콜로서스의 축소판으로 보이며, 전투에서 주인의 작전을 돕는다. 4가지 속성 플로터 보유 시 오로리안이 연쇄 스킬 시전 후 추가로 1회 강력한 공격을 한다.",
  str_item_rpintro_9994026 = "구시대의 산물. 여러모로 콜로서스의 축소판으로 보이며, 전투에서 주인의 작전을 돕는다. 4가지 속성 플로터 보유 시 오로리안이 연쇄 스킬 시전 후 추가로 1회 강력한 공격을 한다.",
  str_item_rpintro_9995001 = "이곳과 신비한 관계가 있는 인공 제품. 가지고 다니는 사람의 심장이 멈추더라도, 그 목숨을 즉시 되살려 준다.",
  str_item_rpintro_9995002 = "태양의 축복을 받은 강력한 전투 갑옷. 착용자는 혹독한 전투를 견딜 수 있게 된다.",
  str_item_rpintro_9995003 = "구시대의 신비한 장치. 흘러넘치는 루미나를 감지하여, 착용자를 보호하는 역장으로 전환시킨다.",
  str_item_rpintro_9995004 = "표면에 미세한 균열이 있는 거친 수정. 이것은 그 안에 과다한 루미나가 있음을 보여 준다. 살짝 만지기만 해도 방출되며, 전투에서 적을 기절시키기에 충분하다.",
  str_item_rpintro_9995005 = "구시대가 남긴 강력한 무기. 그 재료가 무엇인지는 알 수 없다. 그 날이 매우 날카로운 것만은 분명하며, 어떤 장갑도 뚫을 수 있을 듯하다.",
  str_item_rpintro_9995006 = "모든 색깔이 모여 있는 보석. 찬란하게 변하는 색을 지녔다.",
  str_item_rpintro_9995007 = "루미나 저장에 쓰이는 장치. 방출한 후 잃은 루미나를 보충할 수 있다.",
  str_item_rpintro_9995008 = "구시대의 명검. 번개의 힘이 봉인되어 있으며, 뽑기만 하면 순식간에 폭발하여 적을 소멸시킨다.",
  str_item_rpintro_9995009 = "구시대의 산물. 주로 추격병을 상대하는 용도로 사용된다. 안에 담긴 루미나의 힘이 지나가는 경로에 남아, 일정 시간 후 폭발하여 추격하는 적을 살상한다.",
  str_item_rpintro_9995010 = "구시대의 산물. 아름다워 보이지만 무서운 힘을 지녀, 적을 떨어지는 꽃처럼 폭발 속에서 죽게 한다.",
  str_item_rpintro_9995011 = "이 작은 조각상은 적의 생명의 숨결을 느낄 수 있어서, 위태로운 상태의 남은 적을 순식간에 죽인다.",
  str_item_rpintro_9995012 = "구시대의 강력한 장치. 환영을 생성하여 적의 눈을 속인다.",
  str_item_rpintro_9995013 = "고대 유물. 모든 사람의 운명을 볼 수 있지만, 아마도 환각일 것이다.",
  str_item_rpintro_9995014 = "이렇게 희귀한 빨간색 난초는 구시대에 특수 재배된 산물로, 반드시 짝을 이뤄 나타났다가 피고 진다. 이것을 가진 자는 신비한 링크를 얻어, 협동 작전을 더 잘하게 된다.",
  str_item_rpintro_9995015 = "구시대의 산물. 두 명의 전투자 간에 신비한 연결 작용을 한다.",
  str_item_rpintro_9995016 = "구시대 대전쟁의 혼란 속의 산물. 순간적으로 노쇠함을 느끼게 하고, 걸음이 갑자기 느려지게 만든다고 한다.",
  str_item_rpintro_9995017 = "지난날의 파괴적인 전쟁에서 나타난 신비한 물건이라고 한다. 강력한 저주의 힘을 지니고 있으며, 상대에게 중상을 입힐 수 있다.",
  str_item_rpintro_9995018 = "전투 중 렌즈에서 눈부신 빛을 발산하여, 상대의 눈을 멀게 할 수 있다. 또한 착용자가 그 빛에 면역이 되도록 보호하는 보조 장비.",
  str_item_gift_open_cond_1003 = "선물 10레벨 개방",
  str_item_gift_open_cond_1004 = "선물 20레벨 개방",
