  str_item_1602011 = "미아 더 러스트러스 소울",
  str_item_1602021 = "솔라드 디 올마이티 클레머",
  str_item_1502031 = "쟈키니",
  str_item_1602041 = "조슈아",
  str_item_1502051 = "블랑 더 푸라 코르디스",
  str_item_1602061 = "로렐라이",
  str_item_1602071 = "세나",
  str_item_1502081 = "보프",
  str_item_1501871 = "이천간",
  str_item_1601881 = "단당",
  str_item_1602371 = "마야",
  str_item_1602381 = "미트라",
  str_item_intro_1600011 = "북방의 대변인. 항상 가지고 다니는 거대한 거울은 그녀의 빼어난 용모를 비춰주며, 수많은 비밀 또한 숨기고 있다...",
  str_item_intro_1600021 = "진지하고 성실하며, 번개처럼 일을 처리하면서도 아무런 망설임이 없는 일루미나 연방의 군단장. 장도를 손에 들고 전쟁에서 큰 공을 세웠다.",
  str_item_intro_1600031 = "백야 업타운의 귀족 집사였으나, 다른 귀족의 심기를 거슬러 백야 다운타운으로 좌천되었다. 하지만 어떤 사람들의 말에 의하면, 그는 비밀 임무를 수행하고 있다고 한다...",
  str_item_intro_1600041 = "동물의 모습을 한 방랑자 두 명으로 이루어진 기묘한 팀. 지금은 떠돌이 용병이며, 강력한 전투력과 유머 감각으로 일대를 풍미하고 있다.",
  str_item_intro_1600051 = "움브라톤에 출몰하는 소녀. 웃음에 광기가 어린 여자아이로, 사람을 위험에 빠뜨리는 「놀이」를 좋아해 사람들에게 외면을 받는다.",
  str_item_intro_1600061 = "백야성 성주의 차녀. 어려서부터 독립적이고 강인한 성격을 갖도록 길러져, 타고난 재능과 노력으로 백야성의 호위대장이 되었다.",
  str_item_intro_1400071 = "레디젤 렌치에서 온 암살자 소녀. 독립적인 성격으로, 고난도의 임무를 잘 완수한다.",
  str_item_intro_1400081 = "레디젤 렌치의 엔지니어다. 햇빛 방출기 연구자로, 자신만의 전투 방식을 갖고 있다.",
  str_item_intro_1500091 = "진리의 결사 소속의 핸섬한 청년. 매혹적인 미소와 지성적 매력을 갖췄지만, 시도때도 없이 그가 인정한 학술 이념을 전파하는 수다쟁이.",
  str_item_intro_1600101 = "북방에서 온 천진난만한 소녀. 꿈을 가지고 여행을 갈망하며, 세상의 모든 사물을 낙관적으로 바라본다.",
  str_item_intro_1600111 = "일루미나 연방의 군단장. 「용의 힘」을 가진 청년 장교로, 차가워 보이지만 내면은 굉장히 믿음직한 동료이다.",
  str_item_intro_1500121 = "일루미나 연방의 용감한 소녀. 정의의 집행자이자 실천자로, 숭고한 이상을 품고 끊임없이 싸운다.",
  str_item_intro_1500131 = "북방에서 온 소녀. 강력한 마법으로 눈과 얼음을 조종할 수 있어, 모든 지역을 춥게 만든다.",
  str_item_intro_1600141 = "백야성의 성주. 불철주야로 백야성의 질서 유지에 힘쓰는 통치자로, 추호의 소홀함도 보이지 않는다.",
  str_item_intro_1400171 = "비록 몸집이 작은 소녀지만, 무려 레디젤 렌치의 작전팀 중 하나인 이카루가를 이끌고 있는 대장이다. 반응이 빠르고 동작이 민첩해서, 그녀를 따라잡을 수 있는 적은 별로 없다.",
  str_item_intro_1500181 = "레디젤 렌치의 인기 로커. 사기를 북돋울 뿐만 아니라 몸소 선두에 나서서 돌격에 앞장선다.",
  str_item_intro_1600191 = "치명적인 매력을 지닌 성숙한 여성. 어떤 금기의 지식을 가진 진리의 결사 멤버로, 모종의 「진리」를 널리 알리는 데 열중하고 있다...",
  str_item_intro_1500201 = "북풍",
  str_item_intro_1500211 = "이웃집 오빠 같은 일루미나 연방 멤버. 자연학에 대한 이해가 높으며, 원예에 뛰어나다. 자연의 힘을 이용해서 적을 공격하는 걸 좋아한다.",
  str_item_intro_1300221 = "토끼 탈을 쓴 광폭한 소년. 디젤과 폭력성에 심취해 있으며, 레디젤 렌치의 무법자 중 하나다.",
  str_item_intro_1600231 = "낯을 무척 가리는 이 소녀는 클라리넷으로 물을 조종하는 특수한 능력을 지니고 있으며, 다양한 이들이 뒤섞인 움브라톤에 자리를 잡았다.",
  str_item_intro_1500241 = "일루미나에서 온 콤비. 베니는 난폭하고 제멋대로이지만, 쿠로는 침착하고 냉정하다. 둘의 성격은 다르지만 엄청난 궁합을 자랑하는 일루미나의 뛰어난 전투 장교다.",
  str_item_intro_1600251 = "일루미나 연방의 군수장교, 열차 「피안호」를 소유하고 있다. 싸움이든 일상이든 항상 「피안호」와 긴밀한 호흡을 맞춘다.",
  str_item_intro_1600261 = "백야성 기사단 사천사 중 하나. 종종 솟아오르는 비관적인 감정은 그녀가 지닌 불꽃과 기묘한 대비를 이룬다.",
  str_item_intro_1600271 = "백야성 기사단의 유명한 사천사 중 하나이다. 엄숙하고 정직한 성격이며, 과거에 입은 중상으로 인해 일루미나의 개조를 받고 일부 감정을 잃어버리게 되었다.",
  str_item_intro_1600281 = "백야성 기사단 사천사 중 하나. 독특한 치료 능력과 긍정적이며 낙관적인 태도를 가졌다.",
  str_item_intro_1600291 = "백야성 기사단 사천사 중 하나. 조용하고 온화한 성격에, 어떤 일이 일어나도 담담하게 대처한다...",
  str_item_intro_1600301 = "레디젤 렌치의 수장, 솔직하고 호쾌한 아저씨, 많은 멤버들과 목숨을 맡길 정도로 두터운 우정을 쌓았다. 여동생을 매우 아끼며, 현재 레디젤 렌치의 생존을 지키려고 노력하고 있다.",
  str_item_intro_1500311 = "슈만",
  str_item_intro_1400321 = "백야성 심판소의 일원. 날개가 하나뿐인 천사다. 민감하고 자존심이 강한 성격으로, 젊지만 전투 경험이 많다.",
  str_item_intro_1500331 = "나이는 젊지만 견문이 적지 않다. 열정적인 노력가로, 일루미나 연방의 신임받는 청년 인재다.",
  str_item_intro_1500341 = "14행 시",
  str_item_intro_1400351 = "사방으로 뛰어다니는 쿠리어. 지독한 일벌레로, 일을 끝내지 않으면 잠을 이루지 못한다...",
  str_item_intro_1500361 = "움브라톤에서 온 방랑자. 반항적인 성격으로, 백야성의 질서에 꽤나 거부감을 느끼고 있다. 특히 귀족에 대해 알 수 없는 적개심을 가진 듯하다...",
  str_item_intro_1600381 = "거대 메카를 조종하는 소녀. 일루미나 연방의 현임 연구원장으로, 군대에서 퇴역한 천재소녀라고 한다.",
  str_item_intro_1400401 = "폭발을 좋아하는 소녀로, 폭발 소리만 들어도 말할 수 없이 흥분하는 레디젤 렌치 멤버.",
  str_item_intro_1400411 = "백야성에서 가이드 역할을 하고 있다. 큰일을 겪어도 무척 태연한 것을 보면, 과거에 심상치 않은 이력이 있는 듯하다.",
  str_item_intro_1400441 = "진지하고 성실한 일루미나 연방의 참모장. 일의 대소를 막론하고 모두 질서정연하게 처리한다.",
  str_item_intro_1300461 = "네 명의 아이들로, 백야성의 자체 방송 팀이다. 아카데미의 성가대 단원으로 겉보기에는 귀엽지만, 다른 사람을 조롱하는 취미가 있다...",
  str_item_intro_1300471 = "일루미나 연방의 천재 연구원. 탐구욕이 왕성하며, 세상에서 그녀의 관심을 끄는 것은 오직 지식과... 일루미나 연방의 어느 군단장뿐인 것 같다.",
  str_item_intro_1400481 = "나이는 젊지만 「디나 클랜」의 대장이다. 움브라톤에서 그녀는 뛰어난 결단력과 기묘한 암살 무기로 입지를 세웠다.",
  str_item_intro_1300491 = "크고 강인한 전사. 언제나 전신 갑옷을 입은 채 대검을 들고 움브라톤을 누빈다. 지금까지 투구를 벗은 적이 없으며, 과묵한 성격으로 대부분 말보다 무력의 대화를 선호한다.",
  str_item_intro_1200501 = "웃고 있어도 무섭게 느껴지는 상어! 작은 부락의 수호자. 사납고 무서워 보이지만, 사실은 따뜻한 성격이다.",
  str_item_intro_1300511 = "말수가 적은 악어 유탄수와 시끄러운 허풍쟁이인 악어새 저격수. 레드오일 렌치 안의 기묘한 콤비로, 믿을 만한 용병이다.",
  str_item_intro_1300521 = "일루미나 연방에 우편 배달 서비스를 제공하는 쿠리어. 본인은 사실 굉장히 게을러서 우체부로서의 성실함은 찾아볼 수 없으며, 일을 항상 미루거나 대충대충 처리한다...",
  str_item_intro_1300531 = "레디젤 렌치에서 온 상인. 교활하고 돈을 좋아하는, 어디서나 볼 수 있는 악덕 상인. 이득을 볼 수만 있다면, 그는 기꺼이 고용주를 위해 일한다...",
  str_item_intro_1300741 = "일루미나 연방의 하급 장교. 소극적인 성격을 가진 그는 주위 동료들과 잘 어울리지 못한다. 그 이유는 그의 신비한 혈통 때문이라고 한다...",
  str_item_intro_1300581 = "성실하고 적극적인 백야성의 신진 기사. 젊은 나이지만 중책을 맡고 있어서, 심하게 긴장하곤 한다.",
  str_item_intro_1400161 = "레디젤 렌치 멤버. 강력한 슈퍼 레일건을 가지고 다니며, 침입하는 모든 적을 없애버리는 저격수다.",
  str_item_intro_1400541 = "백야성 신참 야경꾼 대장. 차분하고 집중력이 좋으며, 어떤 일을 마주해도 놀랄 만큼 신중한 태도를 보인다.",
  str_item_intro_1400611 = "활발하고 낙천적인 일루미나 연방의 연구원이다. 독특한 능력으로 동료의 부정적인 감정을 흡수하며, 타인의 심리 트라우마를 치료한다.",
  str_item_intro_1400731 = "움브라톤 이스타반 상회의 새 멤버. 언제나 엄청난 흥분 상태다. 그녀들을 조심하라!",
  str_item_intro_1500421 = "일루미나 연방의 군단장. 무료한 평화를 견디지 못하는 전쟁광으로, 수단과 방법을 가리지 않고 승리를 추구한다.",
  str_item_intro_1500761 = "상냥하고 예의가 바르며, 항상 침착한 모습을 보이지만, 사실은 거짓말이 몸에 밴 신사로, 움브라톤의 유명한 사기꾼이다.",
  str_item_intro_1500781 = "움브라톤 「디나 클랜」의 멤버로, 소극적인 성격에 대인관계를 두려워한다. 언니인 디나와 서로 의지하며, 움브라톤에서 살아남기 위해 노력하고 있다.",
  str_item_intro_1600771 = "북방의 통치자. 오랫동안 쌓은 지식과 풍부한 경험을 지녀 어떤 일에도 쉽게 대응할 수 있으며, 쉽게 흔들리지 않는다.",
  str_item_intro_1300591 = "쿠리어 길드 멤버. 진리의 결사와 연락하는 일을 전담하고 있다. 일 처리도 대충이고 책임감도 부족하지만, 다행히 뭐든 솔직하게 말하는 편이라 사람들도 그녀의 결점을 참고 넘어가곤 한다.",
  str_item_intro_1300801 = "일루미나 연방 연구원으로, 기계와 모형을 광적으로 좋아하는 천재소녀다. 대인관계를 어려워하지만, 자신이 좋아하는 일에 대해 이야기할 때는 막힘이 없다.",
  str_item_intro_1300821 = "북방 송림지대의 수호자, 순진하고 귀여우며, 세상 물정을 잘 몰라 당황하는 경우가 많다. 특별하고 귀한 보석의 뿔을 가지고 있어 어릴 적부터 보호를 받아 왔다.",
  str_item_intro_1400451 = "진리의 결사 핵심 멤버이자 빅토리아의 추종자. 과묵한 성격의 그는 진리의 결사 이념을 굳게 믿으며, 진리의 결사 이념을 전하는 것을 평생의 목표로 삼았다.",
  str_item_intro_1400571 = "일루미나 연방 정보부장. 평소에는 자상하고 붙임성이 좋지만, 조금 게으른 면이 있다. 그러나 그녀의 내면에 있는 두 번째 인격은 무척 반항적이다.",
  str_item_intro_1400681 = "쿠리어 길드 멤버, 레디젤 렌치 구역을 담당하고 있다. 귀엽고 자신감이 넘치며, 항상 용감하게 도전한다. 편지를 배달할 때 사방을 돌아다니며 소란을 피우는 말썽꾸러기다.",
  str_item_intro_1400791 = "백야성 세무관. 이성적이고 공정함을 지키려 노력하며, 독립적인 성격이다. 모든 것을 금화의 가치로 환산하는 버릇이 있다.",
  str_item_intro_1400811 = "레디젤 렌치 망명대열 소대의 멤버. 자신감이 넘치는 열혈 바보로 속셈은 없으나, 어떤 일이든 일등이 되고 싶어 한다.",
  str_item_intro_1400831 = "일루미나 연방 연구기관의 시종, 겉모습과 대화 방식은 기계 같은 느낌이 드는 메이드지만, 실제로는 한 강력한 생명체의 복제인간이다.",
  str_item_intro_1601231 = "일루미나의 치안관으로, 임무 수행 시 돌발 상황이 발생하면 울음을 터트리곤 한다. 하지만 정의를 실현하기 위해 그녀는 여전히 낙천적으로 자신의 임무를 충실히 수행하고 있다.",
  str_item_intro_1601201 = "부유한 가문에서 태어난 귀족 소녀인 그녀는 지혜롭고 뛰어난 품성을 지니고 있으며, 집에 머무르며 독서를 하는 것을 좋아한다. 자신이 잠에서 깨운 거대한 갑주 「폼페이」가 그녀의 유일한 친구다.",
  str_item_intro_1500151 = "움브라톤의 미술품 상인으로, 호넷은 명화에 대한 식견이 뛰어나고, 실버는 뛰어난 그림 실력을 가지고 있다. 두 사람은 손발이 아주 잘 맞으며, 함께 용병 활동도 하고 있다.",
  str_item_intro_1501321 = "북방 소나무 계곡의 주민으로, 벌꿀과 벌꿀에 대한 모든 것을 무척이나 좋아한다. 그녀의 꽃 덩굴은 무척 아름다우며, 특수한 능력을 발휘하기도 한다.",
  str_item_intro_1601311 = "북방의 주민으로, 베들레헴과 밀접한 관계가 있다. 역사에 해박하며, 만물을 사랑하는 마음을 가졌다. 그는 북방이 오로리안의 마지막 낙원이라 여기며, 자신의 힘으로 북방을 지키고자 한다.",
  str_item_intro_1601331 = "토르는 매우 난폭한 악룡으로, 한때 신에게 도전했으나 패배해 이세계로 넘어가게 되었다. 그리고 그곳에서 코바야시를 좋아하게 되어, 메이드로서 그녀와 함께 생활하는 것을 선택했다.",
  str_item_intro_1601341 = "토르와 같은 드래곤으로, 생김새와 성격은 아직 어린애다. 장난을 치다 집에서 쫓겨난 후로는 계속 토르를 따라다니며 함께 지내고 있다.",
  str_item_intro_1501351 = "인간 세상의 다툼을 조화시켜 한때 「성해의 무녀」라 불렸다. 진지한 성격이며, 맛있는 음식을 좋아한다. 특히 디저트에 무척 약하다.",
  str_item_intro_1501361 = "한때는 문화를 관장하던 태고의 신이었다. 막강한 힘을 가졌지만, 평소에는 덜렁이 언니다.",
  str_item_intro_1401371 = "토르의 친구로, 원래의 세계에서는 동굴 안 보물을 지키고 있었다. 탐욕스러운 자들을 너무 많이 보아왔기 때문에, 타인에게 깊은 적의를 품고 있다.",
  str_item_intro_1601381 = "일루미나 연방의 연구원으로, 업무 중에는 이성적이고 능률이 높지만, 사적인 시간에는 게으르고 제멋대로다. 고대 과학 기술에 심취해 항상 바깥을 떠돌며 각종 유적을 조사하고 있다.",
  str_item_intro_1501391 = "백야성에서 태어난 여명 아카데미 학생회의 멤버로, 항상 플로리나를 따라다닌다. 기발한 발상을 잘 떠올리며, 가끔씩 사람을 놀라게 만드는 말을 꺼낸다.",
  str_item_intro_1601401 = "백야성에서 태어났고, 여명 아카데미에서는 학생회장을 맡았다. 겉모습은 차갑지만 따뜻한 마음으로 친구들을 돌보며, 훌륭한 기사가 되기 위해 계속해서 노력하고 있다.",
  str_item_intro_1601411 = "레디젤 렌치에서 태어났으며, 활발한 성격의 소유자로, 어렸을 때부터 탐험 이야기를 듣는 것을 좋아했다. 충분한 지식과 기술을 습득한 후, 루비는 자신만의 탐험을 시작했다.",
  str_item_intro_1501421 = "레디젤 렌치 멤버로, 항상 루비를 따라다닌다. 비록 말투에 가시가 있긴 하지만, 그저 겉으로만 다르게 표현할 뿐, 마음이 여리고 착한 아이다.",
  str_item_intro_1601431 = "운도의 무녀로, 학식이 있고 사리에 밝으며, 예의가 바른 사람이다. 운도를 통치하는 「쇼군」에 의해 길러졌으며, 자신의 힘으로 운도의 백성들이 겪는 고난을 해결할 수 있기를 바라고 있다.",
  str_item_intro_1501441 = "운도 출신의 키가 큰 여성으로, 한때 린네에 의해 구해졌다. 자신은 「그것들」을 볼 수 있다고 말하며, 조금 낯을 가리는 듯하다.",
  str_item_intro_1601451 = "운도에서 태어났으며, 전란에 휘말려 터전을 잃은 후 누군가에게 구해져 인술을 배우게 되었다. 그 경험은 그녀의 성격을 냉혹하게 만들었지만, 동료들에게는 매우 충직하다.",
  str_item_intro_1601461 = "운도에서 태어났으며, 한때 린 가문 상회에서 「기공술」을 배웠다. 뛰어난 무예 실력과 활발한 성격의 소유자로, 의협을 실천하며 사방을 유람하는 것을 즐긴다.",
  str_item_intro_1501471 = "운도에서 태어난 쌍둥이로, 해가 라면이라는 라면 포장마차 가게를 운영한다. 운도에서 인기가 매우 많으며, 돈을 벌면서 미식의 극한을 탐구하는 것이 꿈이다.",
  str_item_intro_1201631 = "북방에서 온 수수께끼의 생물로, 게임 제작에 몰두하고 있다. 누구를 만나든지 먼저 「선생님, 외주 계약하실래요?」라고 묻는다.",
  str_item_intro_1601481 = "제멋대로인 레디젤 렌치 탐색 소대의 멤버다. 오랜 시간 동안 혼자서 외부에서 레디젤 렌치에 도움이 되는 정보들을 조사해 왔고, 한때 전설의 레이서였다고 한다.",
  str_item_intro_1501491 = "레디젤 렌치의 보급 관리자다. 겉모습은 건들건들해 보이지만 실제로는 꼼꼼하고 빈틈없는 성격으로, 레디젤 렌치라는 대가족을 지키기 위해 온 마음을 다하고 있다.",
  str_item_intro_1601501 = "진리의 결사의 일원으로, 과묵하지만 능력은 매우 뛰어나다. 자신의 생각이나 야심이 없으며, 다른 사람이 자신에게 임무를 내려주는 것만을 기다린다.",
  str_item_intro_1601511 = "진리의 결사의 일원으로, 매우 게으른 것처럼 보이지만 흥분하면 다른 모습으로 변한다. 자신이 「그 동요」를 전파하기 위해 세상에 왔다고 굳게 믿고 있다.",
  str_item_intro_1501521 = "내성적이면서 고집이 센 소녀로, 진리의 결사의 핵심 멤버가 되기 위해 주변의 어른들에게 잘 보이고 싶어한다. 사실은 애정결핍인 탓에 사람들의 관심을 받고 싶을 뿐이다.",
  str_item_intro_1601551 = "일루미나 연방의 군단장. 「화음 연결」 장치를 사용한 후 겉모습과 능력 모두 변화가 발생했다. 그러나 속은 여전히 그 전쟁광이다.",
  str_item_intro_1601541 = "일루미나 연합 탐색대의 대장. 쾌활하고 친절한 성격과 선한 마음씨를 가지고 있다. 우연히 지하에 갇혀 있던 아이테르를 구해내면서 파란만장한 모험을 시작하게 되었다.",
  str_item_intro_1601531 = "일루미나 연방의 대원수. 용맹하고 전투 능력이 뛰어나며, 사리에 밝고 통치에 능숙해 일루미나인들의 존경을 받고 있다.",
  str_item_intro_1601561 = "움브라톤에 사는 백야성 귀족 가문 출신이다. 비록 가까이하기 어려운 것처럼 보이지만, 사실은 그리 친해지기 힘든 타입은 아니다... 아마도?",
  str_item_intro_1501571 = "운도에서 태어나 굴곡진 삶을 살아온 소녀로, 생계를 위해 아스트라 대륙에 오게 되었지만 얼떨결에 큰 빚을 지고 말았다. 지금은 그저 고용주에게 해고되지 않기를 바랄 뿐이다.",
  str_item_intro_1601581 = "이세계에서 온 소년. 「페르소나」라는 특수 능력을 사용할 수 있다. 가면 속에 진짜 얼굴을 숨기고, 코드네임으로 자신을 부르는 모습이 색다른 느낌을 준다. 이세계에서 세상을 떠들썩하게 만들었던 「마음의 괴도단」의 리더가 바로 이 조커다.",
  str_item_intro_1601591 = "이세계에서 온 「마음의 괴도단」의 멤버. 작전 참모 역할을 하며 괴도단의 행동 방침을 제시하는 소녀다. 「페르소나」의 능력을 사용할 수 있다.",
  str_item_intro_1501601 = "이세계에서 온 「마음의 괴도단」의 멤버. 독특한 기질로 세상과 조금 거리가 있어 보이는 소년이다. 「페르소나」의 능력을 사용할 수 있다.",
  str_item_intro_1501611 = "이세계에서 온 「마음의 괴도단」의 멤버. 모종의 이유로 괴도단과 일시적으로 함께 행동하고 있다. 「페르소나」의 능력을 사용할 수 있다.",
  str_item_intro_1501621 = "이세계에서 온 고양이처럼 생긴 신비한 존재. 사람의 말을 할 수 있다. 「마음의 괴도단」 멤버들에게 다양한 가르침을 주며, 「페르소나」의 능력을 사용할 수 있다.",
  str_item_intro_1601641 = "카렌 드 솔라드, 「하버 시티」의 여정에서 그녀의 능력에 변화가 일어났고, 「지도력」에 대한 이해 또한 더 깊어졌다.",
  str_item_intro_1501651 = "일루미나의 공학 천재. 내성적이며 낯을 가리지만 사람들과 소통하기를 갈망한다. 그녀의 꿈은 강력한 강화복을 만드는 것이다.",
  str_item_intro_1601661 = "꼬마 환상동물 트레이너로, 제멋대로이고 고집이 세지만, 의외로 잘 운다. 자신의 사부 비크보다 더 훌륭한 환상동물 마스터가 되기 위해서 끊임없이 노력 중이다.",
  str_item_intro_1601671 = "매직 핸드 빌 서커스단의 단장이며, 진리의 결사의 일원이기도 하다. 신비롭고, 기이하며, 과묵하다. 가장 위대한 마술사가 되겠다는 포부를 지니고 있다.",
  str_item_intro_1501681 = "암귀의 습격으로 고향을 떠나야만 했던 소녀로, 순수하고 활발한 성격이다. 에메랄드호를 지키는 것을 자신의 사명이라 여기며, 종종 서커스단의 바람잡이 게스트로 특별 출연한다.",
  str_item_intro_1501301 = "백야성의 트로이 가문 출신이다. 하지만 그토록 고귀한 출신에도 불구하고 이토록 낮은 직위에 머무르고 있는 것은 아마 그의 성격에서 이유를 찾을 수 있을 것이다.",
  str_item_intro_1501711 = "겉보기엔 냉정하지만, 사실은 무척 믿음직하다. 교회의 아이들을 지키기 위해 폴룩스와 함께 「레이븐즈 블러드」라는 코드네임의 자유 용병 일을 하고 있다.",
  str_item_intro_1601701 = "강인하고 노련한 그녀에게는 다시 떠올리고 싶지 않은 과거가 있다. 지금은 퇴락한 유포리아에서 한 교회를 지키면서 갈 곳 없는 아이들을 거두어 돌보고 있다.",
  str_item_intro_1401691 = "움브라톤에서 태어난 괴력 소녀, 멋진 외모 너머에는 순수하면서도 집념 강한 마음이 있다. 각종 임무를 완수하는 것을 의적의 수련으로 여기고 있다.",
  str_item_intro_1601721 = "햇살처럼 빛나는 낙천적이고 귀여운 소녀다. 영화에 대한 꿈을 이루기 위해 혼자서 움브라톤의 「알리우드」에 찾아왔다. 많은 고생을 하긴 했지만, 결코 물러서지 않는다.",
  str_item_intro_1601731 = "움브라톤 안데르센 가문의 에이스 집사, 우아하고 강한 완벽주의자다. 가주의 은정에 보답하기 위해서라면 그는 자신의 모든 것을 바칠 수 있다.",
  str_item_intro_1601751 = "악셀리아라는 이름의 「전쟁 기계」로, 일루미나 연방 소속이다. 이러한 명성에도 불구하고 비공식으로는 그녀의 몸 상태가 우려되고 있다.",
  str_item_intro_1501761 = "백야성의 전투의사, 한때 요하네스라는 의사의 도움을 받았고, 그때부터 그녀는 우수한 의사가 되겠다고 결심했다.",
  str_item_intro_1601771 = "움브라톤에서 태어난 유명한 아이돌이다. 타고난 행운을 가지고 있을 뿐만 아니라, 특유의 긍정적이고 낙관적인 태도는 모두를 매료시켰다.",
  str_item_intro_1601781 = "숲속에 숨어 사는 환상동물 마스터. 말이나 행동이 주변 사람들을 화나게 만드는 일이 많으며, 제자인 피아를 괴롭히기도 하지만, 환상동물에게는 무척 상냥한 편이다.",
  str_item_intro_1501801 = "지금은 작은 신문사의 인턴기자에 불과하지만, 뜨거운 열정을 불태우며 적극적으로 가십거리를 찾아 다닌다. 움브라톤에서 가장 유명한 대기자가 되는 꿈을 이루기 위해 오늘도 최선을 다한다.",
  str_item_intro_1601811 = "한때 용주 대륙 조나라의 대장군이었으나, 지금은 방랑자다. 언제 어디서나 그는 자신의 마음속에 있는 것만을 지킬 뿐이다.",
  str_item_intro_1601821 = "「신풍호」의 선장으로, 냉담하고 결단력이 있으며, 표리가 없는 사람이다. 목표는 가장 강력한 원양 함선을 만들어 가장 안전한 항로를 개척하는 것이다.",
  str_item_intro_1501831 = "명의 복존자 아래에서 의술을 배운 꼬마 의원이다. 어리지만 당차고 말이 신랄하다, 동시에 신뢰할 수 있는 좋은 의원이기도 하다. 그렇지만 칭찬이 독이 되는 면도 있다.",
  str_item_intro_1601841 = "쿠리어 길드 레디젤 렌치 지부의 장로다. 털털하고 제멋대로인 성격이지만 무척이나 지혜로운 관찰자이기도 하다.",
  str_item_intro_1501851 = "신참 쿠리어지만, 쿠리어 길드에서 몇 안 되는 성실하고 책임감 있는 사람이다. 하지만 가끔은 길드의 제도를 너무 엄격하게 준수한 탓에 실수를 할 때도 있다.",
  str_item_intro_1601861 = "작위를 계승한 백야성 귀족이자 심판소의 심판관이지만, 자주 잠에 빠져드는 「특별한 체질」을 지닌 소녀다.",
  str_item_intro_1601891 = "백야성의 심판관으로, 굳세고 정직한 성격이며, 악인과 악행을 증오한다. 모든 사람을 평등하게 대하지만, 한 편으로는 고집이 너무 세 다른 사람과 사이가 소원해지는 면모도 있다.",
  str_item_intro_1501901 = "백야성 심판소의 심판관으로, 훌륭한 재능을 가지고 있지만 야심은 그렇게 크지 않으며, 인생을 즐겁게, 풍족하게, 평온하게 보내고 싶어 한다.",
  str_item_intro_1601911 = "아인족 혈통을 지닌 움브라톤의 외톨이다. 친구가 별로 없고, 말을 과하게 직설적으로 하는 바람에 자주 불필요한 오해를 산다.",
  str_item_intro_1501931 = "귀족 가문 출신이지만, 주위에 휘둘리지 않고 자신의 신념을 따르겠다는 마음가짐을 가지고 있으며, 자신의 바람대로 백야성의 견습 심판관이 되었다.",
  str_item_intro_1601921 = "「강철가시 기사단」의 단장이다. 단호한 성격이며, 위엄이 느껴지면서도 친화력을 잃지 않는다. 오늘날 백야성이 지닌 부패한 폐단을 바꾸기 위해 힘쓰고 있다.",
  str_item_intro_1601991 = "일루미나의 군인 가정에서 태어났으며, 지금은 위원회의 상급 정보장교다. 그녀의 깊은 눈빛 너머에는 모든 계획이 하나하나 세워지고 있다.",
  str_item_intro_1502001 = "일루미나 연방의 정보장교로, 냉정하고 믿음직한 성격이다. 하지만 가끔 의외의 불만을 토로하곤 하는데, 그것이 의도적인 행동인지 아닌지는 아무도 알지 못한다.",
  str_item_intro_1602011 = "움브라톤에 숨어 사는 백야성의 기사이자, 사람들에게 언급되지 않는 솔라드의 장녀다. 순진하고 선량한 그녀는 왠지 아버지의 인정을 줄곧 갈망해 온 것 같다.",
  str_item_intro_1602021 = "검을 들고 암귀와의 전쟁에 나서던 전성기의 솔라드다. 그는 이제 막 즉위한 백야성의 통치자일 뿐만 아니라, 전장에 나아가 적을 쓰러트리는 전사다.",
  str_item_intro_1502031 = "북방의 사절로, 무척 열정적이고 활발하지만, 아직 점술에 능숙하지 않은 데다가 덤벙대는 성격 탓에 종종 말썽을 일으키곤 한다.",
  str_item_intro_1602041 = "사람들은 그녀의 모습이 이미 세상을 떠난 성주의 부인과 닮았다고 하지만, 사실은 같은 사람이 아닌 듯하다. 조슈아는 자신의 이상을 품고 세상의 더 많은 곳으로 갈 수 있길 바라고 있다...",
  str_item_intro_1502051 = "「나이트워치」 호위대의 대장 직위에서 오래전 은퇴한 블랑이 다시 작전복을 입었다. 전성기의 「미즈 로트」가 다시 돌아왔다!",
  str_item_intro_1602061 = "움브라톤에서 자란 부잣집 아가씨다. 집에서 여유롭게 살 수도 있었지만 자신의 꿈을 이루기 위해 창업을 선택했다.",
  str_item_intro_1602071 = "「지금을 살아간다」는 삶의 원칙을 고수하는 데누오 리조트의 총지배인이다. 겉보기에는 경박해 보이지만, 일 처리는 의외로 믿음직하다.",
  str_item_intro_1502081 = "콜로서스 「트래블러호」의 파일럿일 뿐만 아니라, 레디젤 렌치의 「책사」이기도 하다. 그러나 모두의 눈에는 그녀가 왠지 마스코트 같은 존재로 보이는 듯하다...",
  str_item_intro_1400861 = "백야성 여명 아카데미 멤버이자 장례 진행자. 적극적이고 대담하며, 자상하고 섬세한 면도 있다. 항상 미소와 침착함으로 모든 일을 대한다.",
  str_item_intro_1400911 = "백야성의 악사로, 자상한 성격이지만 마음이 무척 연약하며, 슬픈 기억에 쉽게 빠지곤 한다. 전쟁으로 가족을 잃은 탓에, 슬픔 속에 살며 이를 떨쳐내지 못한다.",
  str_item_intro_1500701 = "움브라톤의 외톨이. 「용의 힘」을 지니고 있다. 자부심이 무척 강하며 성격이 변덕스럽다. 항상 가문의 운명을 자신이 짊어지고 있다고 느낀다.",
  str_item_intro_1500751 = "레디젤 렌치의 기술자. 자신의 통신 기술에 무척 자부심이 있다. 통신 채널에서 남들을 놀리는 것을 즐기지만, 현실에서 문제가 발생하면 허둥지둥하곤 한다.",
  str_item_intro_1500841 = "움브라톤의 지하 리더, 과감하고 대범하며, 의리를 중시한다. 가혹한 생존 도전을 통해 지금의 명성과 지위를 얻게 되었다.",
  str_item_intro_1500881 = "레디젤 렌치 멤버. 주로 정찰을 담당한다. 소심하고 수줍음이 많으며, 행동이 서툴다. 전투 중에는 「흥분 상태」가 되어 강력한 힘을 발휘할 수 있지만, 제어가 되지 않는 탓에 마지 본인도 무척 고민하고 있다.",
  str_item_intro_1500901 = "레디젤 렌치의 아이돌 가수. 겉모습은 자상하고 아름답지만, 굉장히 무례한 팬을 만나면 난폭한 모습을 드러낸다.",
  str_item_intro_1500921 = "진리의 결사 멤버. 올곧은 성격으로 융통성이 없어서 목표를 정하면 전심전력을 다해 실현한다. 취향이 무척 독특하며, 종종 남들과 「말다툼」을 벌이곤 한다.",
  str_item_intro_1600601 = "레디젤 렌치의 간부, 명사수로 한때 현상금 사냥꾼이었다. 산만하고 냉소적이지만, 적에게는 무자비하다. 그녀의 수갑이 풀리는 순간을 본 자는 아무도 없다.",
  str_item_intro_1600641 = "일루미나 연방의 근위 군단장. 야심이 많으며 정정당당하게 일루미나 연방의 수장 자리에 도전하려 한다. 그녀는 기운이 넘치며, 조금도 지치는 기색 없이 권력을 거머쥐고 독점하고 싶어 한다.",
  str_item_intro_1600891 = "백야성 심판소 대심판관, 자상하고 정직하며, 강인함과 희생정신을 지니고 있다. 속으로는 조금 고집이 센 면도 있지만, 참고 겉으로 드러내지 않고 있을 뿐이다.",
  str_item_intro_1601031 = "진리의 결사에서 온 심문관으로, 빅토리아의 추종자이다. 눈동자에는 강력한 「재앙의 힘」을 지니고 있지만, 현재는 봉인되어 있다.",
  str_item_intro_1500871 = "무를 숭상하는 백야성의 귀족으로, 높은 지위와 강한 힘을 가지고 있다. 전통을 중시하고 책임감이 강하다. 약간 오만한 성격이지만, 다행히 최근에는 조금씩 바뀌고 있는 듯하다.",
  str_item_intro_1401011 = "일루미나의 연락원으로, 정보 전달 및 연락을 담당하고 있다. 열심히 일하며, 분위기 파악에 능숙하지만 가끔은 쓸데없는 농담이나 장난치는 것을 좋아한다.",
  str_item_intro_1401021 = "움브라톤 디나 클랜의 친구다. 제멋대로인 데다가 자유롭게 사는 걸 좋아한다. 입에 문 막대 사탕과 손에서 방출되는 전류가 트레이드 마크다.",
  str_item_intro_1500991 = "움브라톤의 떠돌이 용병으로, 저주를 안고 태어난 탓에 어려서부터 허약하고 병약했고, 마검에 기대어 생명을 유지하는 수밖에 없었다.",
  str_item_intro_1501001 = "진리의 결사의 멤버로 오래된 귀족 가문에서 태어났다. 어려서부터 비밀 묘지를 지키는 파수꾼으로 선택되어 엄격한 교육을 받았고, 지적이지만 냉담하다.",
  str_item_intro_1600931 = "일루미나에서 생명 과학 연구를 담당하는 수석연구원, 평소에는 빈둥대지만, 중요한 순간에는 냉정하고 침착한 모습을 보인다.",
  str_item_intro_1500981 = "그녀는 저주 때문에 일반적인 인간의 감정이 결핍되어 있다. 깨어났을 때 처음으로 보게 되는 사람에게 의지한다고 전해진다. 지금은 움브라톤에 은거하고 있으며, 이스타반 휘하의 암살자다.",
  str_item_intro_1400621 = "북방의 숲지기. 수려하고 차가운 외모를 지니고 있지만, 실제로는 상냥한 성격이며, 좋은 친구를 간절히 바라고 있는 소년이다. 아직 나이가 어려서 앳된 느낌이 남아 있다.",
  str_item_intro_1400951 = "동물과 비슷한 모습으로 태어난 그녀는 사방을 떠도는 용병이다. 자신이 본 것에 대해 뭐든지 한바탕 불평을 해야 하는 성격이다.",
  str_item_intro_1300941 = "북방에서 온 순찰대원. 순진하고 선량하며, 세상 물정을 잘 모른다. 그녀는 혼자서 익숙하게 추위 속을 순찰하며 사람들에게 봄의 기운과 희망을 나눠준다.",
  str_item_intro_1600961 = "일루미나에서 태어났으나, 할아버지에 대한 정보를 찾아 떠돌다 움브라톤까지 오게 되었다. 그녀는 무슨 일을 하든 흐리멍텅해 진실과 거짓을 잘 구분하지 못한다.",
  str_item_intro_1500971 = "움브라톤에 출몰하는 암살자로, 이스타반을 위해 「특별」 임무를 수행한다. 과거의 와타리는 뛰어난 의술을 지닌 외과 의사였다.",
  str_item_intro_1500561 = "아스트라 대륙을 홀로 누비는 암귀 사냥꾼. 사고방식이 독특하며, 사냥총과 노트를 항상 몸에 지니고 언제든지 암귀를 사냥할 준비가 되어 있다. 암귀를 사냥할 때마다 노트에 상세한 기록을 남기곤 한다.",
  str_item_intro_1701071 = "봉인된 고대의 영웅으로, 암귀를 증오해 신체를 개조했다. 한때는 매우 포악했지만, 침착하고 긍정적인 성격을 되찾았다.",
  str_item_intro_1701081 = "봉인된 고대의 영웅으로, 강한 힘을 얻기 위해 신체를 개조했다. 제어할 수 없는 힘 때문에 큰 화를 불러왔고, 지금도 여전히 죄책감에 빠져있다.",
  str_item_intro_1701091 = "봉인된 고대의 영웅으로, 개조되어 감정의 대부분을 잃어버렸다. 자신의 사명을 완수한 뒤 자신이 지키던 나라로부터 버림받았다고 한다.",
  str_item_intro_1701101 = "봉인된 고대의 영웅으로, 어릴 적부터 최전선에서 암귀와 맞서 싸웠다. 제멋대로인 성격에 수다쟁이다. 개조되긴 했지만 성실하고 순수한 마음은 여전히 남아있다.",
  str_item_intro_1501041 = "다크매터의 영향으로 두 눈이 멀게 되었다. 냉담하고 괴팍한 성격이지만, 익숙해지면 친근하게 대하며 할 말은 꼭 하는 솔직한 성격의 여자아이이다.",
  str_item_intro_1601051 = "사메야마의 여동생, 어린 시절 암귀의 영향으로 자신을 제어할 수 없어 한동안 자아를 잃어버렸었다. 완치된 후 마침내 원래의 천진난만하던 성격으로 돌아왔다.",
  str_item_intro_1500711 = "극동 출신으로, 움브라톤에 정착한 「흥신소」 주인이자, 이스타반의 맹우다. 괴팍하고 반항적이지만 일처리는 깔끔하다.",
  str_item_intro_1400671 = "북방에서 온 꼬마 아가씨, 아인족의 혈통을 가졌으며, 천진난만하고 호기심이 많다. 두 마법 인형과 함께 여행 중이다.",
  str_item_intro_1601111 = "진리의 결사 멤버. 강력한 「핏빛 수정 영역」의 힘을 지니고 있으며, 그것으로 적을 붙잡을 수 있다. 그러나 그 힘이 그녀의 의지에도 영향을 끼쳐 차갑고 과묵한 성격이 되었다. 마음속으로 항상 비관적인 생각을 품곤 한다.",
  str_item_intro_1601121 = "움브라톤에 사는 자유인으로, 성격이 거칠고 직설적이며, 강력한 화염의 힘을 지니고 있다. 새롭고 흥미로운 사물을 좋아한다.",
  str_item_intro_1501131 = "진리의 결사 소속의 음악가로, 겉보기엔 무척 친절하나, 궁극의 악장을 위해서라면 어떤 수단도 가리지 않는다. 자신의 음악에 무척 자부심이 있으며, 백야성의 음악 수준을 무척 경멸한다.",
  str_item_intro_1501141 = "겉보기에는 현상금 사냥꾼이지만, 사실은 진리의 결사 소속이다. 우아하고 쾌활하며, 진 종류의 술을 좋아한다. 지금은 진리의 결사를 위해 정보망을 구축하고 있고, 이와 동시에 「그 녀석」의 행방을 추적하고 있다.",
  str_item_intro_1601151 = "쿠리어 길드 멤버. 백야성의 업무를 담당하고 있다. 차분하고 우아한 성격이며, 동식물과 소통하는 신비한 힘을 가지고 있다. 항상 동물과 반딧불이들이 곁을 따라다닌다.",
  str_item_intro_1601161 = "마음씨가 착한 레디젤 렌치의 엔지니어로, 남의 부탁을 잘 거절하지 못한다. 때문에 각종 소동에 휘말리고 있어 무척 고민하고 있다. 각종 기계 수리에 능숙하며, 또한 자신만의 로봇을 만들기 위해 노력하고 있다.",
  str_item_intro_1401271 = "한때 레디젤 사막에서 생활했지만, 이후 진리의 결사에 가입했다. 기묘한 종이들을 조종해 적과 싸울 수 있다. 평소에는 성격이 연약해 보이지만, 집요할 정도로 영혼의 존재를 굳게 믿고 있다.",
  str_item_intro_1601191 = "일루미나의 신병, 천재적인 전투 능력을 지니고 있지만, 성격이 냉담하고 충동적이며 의사소통 요령이 부족하다. 전투에서 공을 세우고 자신을 증명하길 갈망하고 있다.",
  str_item_intro_1601221 = "움브라톤의 용병 총잡이다. 사격 실력이 매우 뛰어나며, 주도면밀하고 계산적인 성격이다. 골동품 수집을 좋아하며, 돈을 많이 벌어서 골동품 가게를 여는 것이 꿈이다.",
  str_item_intro_1601171 = "한때 일루미나 방어선에서 활약했던 베테랑이지만, 이제는 은퇴해 병참 임무를 담당하고 있다. 겉모습은 거칠어 보이지만 속마음은 세심하며, 전투에서 믿고 의지할 수 있는 전우다. 과거의 전쟁에서 얻은 부상으로 큰 실의에 빠진 적이 있지만, 지금은 극복했다고 한다.",
  str_item_intro_1601211 = "진리의 결사 멤버. 성격은 반항적이지만 의외로 이성적이고 선을 확실하게 지킨다. 한때 백야성의 수녀였으나 뜻밖의 사건으로 백야성의 위선을 깨닫게 되어 그곳을 떠났다. 그 후 백야성의 진상을 폭로하기 위해 힘쓰고 있다.",
  str_item_intro_1300651 = "쿠리어 길드 멤버로, 북방 구역을 담당하고 있다. 열정적인 쿠리어지만 다소 서툰 구석이 있다. 게다가 억양이 독특해서 더 순진하고 귀여워 보인다.",
  str_item_intro_1500551 = "백야성 심판소의 심판관. 완고하지만 실용주의적이며, 단호한 성격을 지니고 있다. 지금은 과거의 사건을 파헤치기 위해 분주하게 움직이고 있다.",
  str_item_intro_1601261 = "움브라톤 총상회의 책임자로, 이스타반의 조수이자 그의 양녀다. 진지하고 엄숙한 성격이며, 사업가의 행동 규범을 따른다.",
  str_item_intro_1601291 = "움브라톤 용병단의 부단장. 신용을 지키며, 움브라톤의 모든 소식을 이해하고 있다. 현재는 용병단을 성장시키기 위해 노력하고 있다.",
  str_item_intro_1602371 = "환신 일족의 후손이라고 한다. 기억을 거의 유지할 수 없지만, 그래도 무척 낙관적이고 선량한 성격이다. 자신을 받아 준 하버 시티에 보답하기 위해 노력하고 있다",
  str_item_intro_1602381 = "롱기누스 일족 출신인 미트라는 이천 년간 이어진 별들의 비밀을 지키는 사명을 계승했다. 차분하고 신중하며, 검은 깃털 아래에 날카로움을 숨기고 있다.",
  str_item_intro_1702361 = "한때 국왕의 오른팔이자 사일런트 예거의 대장이었다. 공의를 굳게 지키며, 결코 흔들리는 일이 없다. 비록 더는 루미나의 가호를 받을 수 없게 되었으나, 그는 여전히 별의 힘으로 미래를 개척한다.",
  str_item_get_discovery = "{0}",
