  str_item_get_cloudgardensitem23 = "특별 사건부 8탄 보상",
  str_item_get_cloudgardensitem24 = "특별 사건부 9탄 보상",
  str_item_get_cloudgardensitem25 = "헤븐즈 가든 내 오로리안들의 주거 환경이 비교적 편안해지면 랜덤으로 발생하는 히든 대화를 통해 획득",
  str_item_get_cloudgardensitem26 = "헤븐즈 가든 내 오로리안들의 주거 환경이 매우 편안해지면 랜덤으로 발생하는 히든 대화를 통해 획득",
  str_item_get_cloudgardensitem27 = "헤븐즈 가든 내 오로리안들의 주거 환경이 꽤 편안해지면 랜덤으로 발생하는 히든 대화를 통해 획득",
  str_item_get_cloudgardensitem28 = "「귀환의 선율: 탑과 족쇄」 이벤트에서 획득",
  str_item_get_cloudgardensitem29 = "「헤븐즈 가든의 슬로우 라이프」 이벤트에서 획득",
  str_item_get_cloudgardensitem30 = "「달빛 아래의 괴도」 이벤트에서 획득",
  str_item_get_cloudgardensitem31 = "일정 수량의 희망 주화 수집 시 획득",
  str_item_get_cloudgardensitem32 = "헤븐즈 가든 레벨 보상에서 도면 획득 후 바람의 탑에서 제작해 획득 가능",
  str_item_get_cloudgardensitem33 = "헤븐즈 가든 퀘스트 보상에서 도면 획득 후 바람의 탑에서 제작해 획득 가능",
  str_item_get_cloudgardensitem34 = "일정 수량의 희망 주화를 수집해 도면 획득 후 바람의 탑에서 제작해 획득 가능",
  str_item_get_cloudgardensitem35 = "헤븐즈 가든 상점에서 도면 획득 후 바람의 탑에서 제작해 획득 가능",
  str_item_get_cloudgardensitem36 = "헤븐즈 가든 소식에서 도면 획득 후 바람의 탑에서 제작해 획득 가능",
  str_item_get_cloudgardensitem37 = "헤븐즈 가든 소식 보상",
  str_item_get_cloudgardensitem38 = "헤븐즈 가든 내 오로리안들의 주거 환경이 비교적 편안해지면 랜덤으로 발생하는 히든 대화를 통해 도면 입수, 바람의 탑에서 제작해 획득",
  str_item_get_cloudgardensitem39 = "헤븐즈 가든 내 오로리안들의 주거 환경이 매우 편안해지면 랜덤으로 발생하는 히든 대화를 통해 도면 입수, 바람의 탑에서 제작해 획득",
  str_item_get_cloudgardensitem40 = "헤븐즈 가든 내 오로리안들의 주거 환경이 꽤 편안해지면 랜덤으로 발생하는 히든 대화를 통해 도면 입수, 바람의 탑에서 제작해 획득",
