  str_item_intro_5212001 = "「이 배는 내가 침몰시켰다! 다음은 너다! 으아아악! 왜 갑자기 내 손에서 미끄럼틀을 타는 거지? 뭐, 됐어. 너희가 기뻐 보이니까 이번엔 봐주겠어!」\n심해 괴물의 촉수를 본떠 제작된 미끄럼틀이라고 한다. 짜릿하지 않을까?",
  str_item_intro_5212002 = "누가 배의 돛대를 여기에 옮겨다 놓은 건지 모르겠다. 어쨌든 위로 기어 올라가면 먼 곳까지 볼 수 있다. 가끔은 「선장님! 육지입니다!」라고 외쳐 주면 바다를 항해하는 느낌이 든다.",
  str_item_intro_5212003 = "푹신한 백사장에서도 튼튼하게 서 있는 텐트다. 무척 가볍고, 무려 방화 재료로 만들어져 있다! 여행객이 텐트 안에서 불장난을 칠 수도 있다는 걸 고려한 것일지도.",
  str_item_intro_5212004 = "두 사람이 나란히 앉아서 탈 수 있는 그네다. 바닷가에서 타고 놀기 좋다. 살랑살랑 불어오는 바닷바람을 맞으며 그네를 탄다면 잊을 수 없는 아름다운 기억이 될 것이다.",
  str_item_intro_5212005 = "버려진 작은 배 반 척을 사용해 만든 그늘막 의자다. 어떤 선원들이 낸 독특한 아이디어인 모양이다.",
  str_item_intro_5212006 = "백사장에서 볼 수 있는 전시대다. 칸막이 판자에 여러 그림을 그릴 수 있는데, 가끔은 메모를 남기는 사람도 있다. 알록달록한 깃발들을 걸어 두면 여행객들의 시선을 사로잡을 수 있다.",
  str_item_intro_5212007 = "「폐품 재활용」 정신을 계승한 몇몇 선원들이 작은 배 반 척을 잘라 갑판으로 테이블과 의자를 만들었다. 용골로는 햇빛 가림용 덩굴 지지대를 만들었는데, 독특한 멋이 있다.",
  str_item_intro_5212008 = "조금 무게가 나가는 파라솔이라 옮길 때 애를 먹는다. 중앙 봉 끝 쪽이 뾰족해서 백사장에 꽂아 두기도 편하고, 고정도 튼튼하게 잘 된다.",
  str_item_intro_5212009 = "몸에 착 감기는 디자인을 채용한 덕에 누우면 정말 편하다. 팔과 다리도 시원하게 뻗을 수 있다.",
  str_item_intro_5212010 = "편하고 기능적인 테이블이다. 여행객이 이리저리 옮기기도 편해서 모두가 백사장에서 좋은 자리를 찾아 아름다운 시간을 보낼 수 있다.",
  str_item_intro_5212011 = "놀다가 피곤해져서 잠깐 쉬고 싶을 때 참 좋다. 앉아서 음료수를 조금 마시면 빠르게 기운을 차릴 수 있다.",
  str_item_intro_5212012 = "어라? 해저의 돌기둥과 산호? 언제 육지로 옮겨진 걸까? 자세히 보니 나무에 칠을 해 정교하게 만들어진 울타리였다. 아름다울 뿐만 아니라 해변이라는 환경에도 잘 어울린다.",
  str_item_intro_5212013 = "백사장을 옮겨 온 것처럼 네모난 구역에 고운 모래가 깔려 있다. 바닷가 분위기가 물씬 난다.",
  str_item_intro_5241018 = "커다란 상자 안에 미니어처 암석과 수초가 들어 있다. 물고기들이 편안히 헤엄을 칠 수 있도록 상자에 달린 기계 장치가 물을 순환시켜 준다.",
  str_item_intro_5241019 = "풍부한 색채를 지닌 산호 장식품이다. 돌로 만들어진 받침이 더해져 보는 사람에게 바닷속에 있는 것 같다는 느낌을 선사한다. 심지어는 물고기 떼가 지나가는 모습까지 볼 수 있다...",
  str_item_intro_5241020 = "신비한 고대 유적 중 하나로, 주변의 루미나를 흡수하여 무해한 빛을 발산한다고 한다. 장식이나 조명으로 매우 적합하며, 또는 먼곳으로 신호를 보내는 용도로도 사용할 수 있다.",
  str_item_intro_5212014 = "너무 커서 자연적으로 만들어진 것 같지 않은 조개다. 안에 진주가 들어 있었다면 분명히 진귀한 보물로 대접받았을 것 같다. 조개껍데기이긴 하지만, 누군가가 알뜰하게 활용해 안에 매트를 깔아 신기한 소파로 만들었다.",
  str_item_intro_5212015 = "해파리 모양의 풍선이다. 하늘에 날려 보내면 축 처져 있던 리본이 「촉수」가 된다. 하늘하늘 날아다니는 모습이 꼭 살아 있는 해파리 같지만, 사실은 그냥 하늘을 떠다니는 것뿐이다.",
  str_item_intro_5212016 = "겉모습 때문에 놀라지 마시라, 사실은 그냥 당신을 위해 길을 밝혀 주고 싶을 뿐이다. 입 안에는 이빨도 없다.",
  str_item_intro_5212027 = "긴 테이블과 함께 놓기 좋은 스툴이다. 높이 조절은 물론 회전 기능도 있어 어린이들에게 인기가 높다.",
  str_item_intro_5212028 = "빠질 수 없는 그린 컬러의 아이템. 스타일만으도 다른 장식물들과 잘 어우러지며, 여러 개를 배치해도 무난하다.",
  str_item_intro_5212029 = "일렬로 이어 붙여 영역을 나눌 때 사용한다. 도색까지 되어 있으니 다른 장식품을 걸어도 될 것 같다.",
  str_item_intro_5212030 = "윈델리온을 위해 특별히 만든 모종밭. 미리 키운 민들레가 축젯날 밤에 휘날려주길.",
  str_item_intro_5212031 = "가로등 프레임이 단순한 데다 일반 목재를 썼다곤 하지만, 중심 부분을 보강한 탓에 꽤나 견고하다. 거기다 조명을 달 수도 있고 작은 동물들이 잠시 쉬어갈 수도 있다.",
  str_item_intro_5212032 = "기념일 분위기를 풍기는 낮은 기둥. 일렬로 두면 울타리 효과를 내기에 충분하다.",
  str_item_intro_5234034 = "돌로 된 외관은 다소 투박해 보이지만, 내부 구조가 아주 멋지다. 공간도 넓어 입구를 살짝만 열어도 쉽게 쓰레기를 수거할 수 있다.",
  str_item_intro_5212020 = "길가에 두기 좋은 선반. 지나가던 사람이 작은 물건을 올려놓을 수도 있고, 취향에 따라 약간의 장식을 추가해 포인트를 줄 수도 있다.",
  str_item_intro_5212021 = "보기엔 크지만, 널빤지로 만들어 속이 비어있고 가벼워 빨리 옮기기에 좋다. 기념일에 보조 장식으로 많이 쓰인다.",
  str_item_intro_5212022 = "매우 단순한 통나무. 작은 동물들이 머물 수 있도록 내부를 보완한 듯하다. 그냥 기대어 쉬는 것도 가능할 것 같다......",
  str_item_intro_5212023 = "가벼운 조명 난간. 조명이나 기념일 분위기를 만들기 위해 여러 램프를 걸기에 충분할 만큼 독특한 구조로 되어 있다.",
  str_item_intro_5212024 = "기본 베이스는 나무막대와 흰 천이며, 그 위에 덩굴들, 푸른 잎과 꽃을 장식해 여러 기념일에 사용됐다. 그 아래를 지날 때 바람이 불어 천이 몸에 닿거나 꽃잎과 잎이 어깨에 떨어지면 한동안 행운이 함께한다고 한다.",
  str_item_intro_5212025 = "기념일에 누가 처음으로 이런 둥지를 만들었는지 모르지만, 당시 작은 동물들이 모여 축제를 함께 보냈다고 한다. 이후로 불문율이 되어 기념일마다 둥지를 찾는 사람들이 늘었다. 작은 동물들이 많이 올수록 축복을 받는다고 한다.",
  str_item_intro_5212026 = "기념일에 야외에 두는 테이블. 원목에 돌판이 지탱하고 있어 꽤 무겁다. 누군가 테이블 위에서 춤을 출지도 몰라 튼튼하게 만들었다고 한다.",
  str_item_intro_5234021 = "방이나 외곽의 캐비닛에도 놓을 수 있다. 나무판자는 나름 단단해 햇빛과 비를 견딜 수 있으나, 실내에서 당장 쓰지 않는 물건을 보관할 때 사용하곤 한다.",
  str_item_intro_5212018 = "윈델리온 때 걸어두는 오색 인형. 흔들면 안에 든 색종이와 리본이 쏟아져 아이들에게 인기가 높다. 방울이나 '행운 코인'을 넣어 목소리나 깜짝 보상으로 더 많은 아이들의 '관심'을 끌기도 한다.",
  str_item_intro_5212019 = "위에서 춤을 출 수 있을 만큼 커다란 북. 얇아도 아주 견고해 위에서 마구 뛰어도 깨지지 않는다! 특이한 구조 탓에 북소리가 멀리까지 울린다. 표면이 섬세해 연주에 따라 다양한 소리를 낸다.",
  str_item_intro_5241021 = "돌무덤쥐도 흔치 않은데, 전설의 돌무덤쥐 가족이라니! 어서 기념 사진을 찍으면 멤버가 될 수 있을지도 모른다.",
  str_item_intro_1601881 = "볼모 취급을 받는 업나라의 공주임에도 단당은 상당히 여유롭다. 그녀는 제나라에서 공부에 열중하면서 고향으로 돌아갈 기회를 기다리고 있다.",
  str_item_intro_5212017 = "고대 유물이라고 하나, 자세한 의미는 알 수 없다. 윈델리온 때는 아이테르들이 와서 축복과 소원을 빈다고 한다. 그걸 들은 밀랍이 석상에게 전하고, 석상이 신비한 힘으로 소원을 아이테르들을 돕는다고 한다.",
  str_item_intro_5271001 = "아주 커다란 수영장이다. 공간이 상당히 넓어야 설치할 수 있다. 물론 많은 사람이 같이 들어가 즐겁게 물놀이를 할 수 있을 정도로 넓다.",
  str_item_intro_5272001 = "일반적으로 수영장 옆에 놓는 작은 부스다. 샤워 설비가 갖추어져 있어서 몸을 깨끗이 씻을 수 있는 데다가, 더 중요한 기능인 '탈의실' 역할도 한다.",
  str_item_intro_5272002 = "수영은 정말 체력이 많이 드는 운동이다. 너무 피곤해졌을 땐 잠깐 쉬어 주자. 그러고 나서 기묘한 자동 장치 앞에 와서 아이스크림 한 개를 받아 간다면, 정말 더할 나위 없는 즐거움이라 할 수 있다.",
  str_item_intro_5272003 = "음악이 빠져서는 안 되는 법, 물놀이만 하면 쉽게 지루해질 수 있으니, 쉴 때는 여기서 노래를 부르며 스트레스도 풀어 보자. 리듬에 따라 춤을 춰도 좋다.",
  str_item_intro_5272004 = "공기가 가득 든 긴 의자다. 누워 있으면 아주 편하다. 물에 넣으면 작은 배 역할도 해낼 수 있다. 누워서 쉴 때도 좋고, 물 위를 떠다닐 때도 아주 좋다.",
  str_item_intro_5272005 = "안에 공기를 채워 넣었기 때문에 무척 가볍다. 여기저기 가지고 다닐 수 있을 뿐만 아니라 공기를 빼고 나면 접어서 배낭에 넣을 수도 있어서 공간을 차지하지 않는다.",
  str_item_intro_5272006 = "수영 실력이 별로인 사람들의 구원자! 이걸 사용하면 아무리 맥주병이라도 물에 뜰 수 있고, 심지어는 첨벙거리며 헤엄도 조금 칠 수 있다.",
  str_item_intro_5272007 = "수영장 물 밖에서든, 물 안에서든 다 사용할 수 있는 장난감이다. 공기를 채워 넣으면 탄성이 생겨 바닥에서 통통 튀긴다. 제일 중요한 건 물에 떨어뜨려도 가라앉지 않는다.",
  str_item_intro_5272008 = "수영은 체력이 많이 필요한 운동이다. 필요할 때는 체력이 돌아올 때까지 이 의자에 누워 있도록 하자. 물고기 모양 쿠션이 아주 편안하고, 바닷가 분위기가 가득하다.",
  str_item_intro_5272009 = "좀 커서 가지고 다니기는 불편하지만, 햇볕에 피부가 타는 걸 막는 데는 확실히 효과가 있다. 무더운 여름에는 소중한 시원함을 가져다준다.",
  str_item_intro_5272010 = "바닷속에서 가져온 여러 조개껍데기에 장식을 더해 마무리한 제품이다. 알맞은 위치에 두면 바다 분위기가 느껴질 것이다.",
  str_item_intro_5272011 = "불가사리는 정말 인기가 많다. 그저 불가사리 장식품 몇 개만 올려놓았을 뿐인데도 여러 사람의 눈길을 사로잡는다.",
  str_item_intro_5272012 = "고대의 어떤 기술로 제작된 전시 팻말이라고 한다. 자동으로 여러 이미지를 보여 준다! 기묘한 장치를 사용하면 팻말에 있는 정보도 변경할 수 있을 것 같은데, 뭔가 생각하지 못한 용도가 있는 모양이다...",
  str_item_intro_5271002 = "바다를 사랑한 어느 아이테르가 한 세트로 디자인한 것으로, 바다의 축복을 받을 수 있다고 한다! 바다를 여행할 계획이라면 여기서 잠깐 머무는 것도 좋을 것 같다.",
  str_item_intro_5272013 = "바다에서 이걸 본다면 항해 중 큰 수확이 있을 거다! 하지만 정말로 존재하는 걸까? 아니면 선원들의 상상일까? 뭐가 됐든 조각상 자체의 아름다움에 많은 젊은이가 찾는 곳이다.",
  str_item_intro_5272014 = "문어 몇 마리가 원양어선에 잘못 올라타 돌아갈 수 없게 됐지만, 선원들은 선의로 문어들을 풀어줬다. 그 후로 문어들은 며칠마다 작은 진주, 바다에 빠트린 화폐 같은 작은 선물들을 가져다줬다고 한다...그래서 이 조각상은 우정과 선물을 의미한다.",
  str_item_intro_5272015 = "많은 사람이 항해 중에 점프하는 돌고래를 본다면 평안이 함께한다고 말한다. 과연 돌고래들이 육지 여행자들도 축복할까?",
  str_item_intro_5271003 = "프로듀서들은 뛰어난 상상력을 바탕으로 여러 각도와 소품 배치, 카메라를 사용하여 짜릿하거나 아름다운, 또는 무서운 장면을 만들어 낼 수 있다. 또한, 책 속에만 담겨 있던 이야기를 생동감 넘치는 장면으로 변신시킬 수 있다.",
  str_item_intro_5273001 = "비록 사진일 뿐이지만, 그 풍경 속에는 왕실 궁전의 기세가 가득 담겨있다. 궁정극 장르의 영화를 찍기에 적합하다.",
  str_item_intro_5273002 = "진귀한 돌로 만들어진 것 같은 바닥이지만, 사실 종이 한 장이 깔린 것뿐이다! 소품의 성격을 띠는 「바닥」은 빠르게 교체할 수 있는 게 최고의 장점이다.",
  str_item_intro_5273003 = "이 「마법의 거울」은 소품이지만 매우 무겁다. 아무래도 강철로 만들어 진 것 같다... 물론 금도금과 보석은 모두 가짜다. 거울의 표면은 마법 거울의 느낌을 제대로 담고 있으며, 그 어떤 사물도 비치지 않는다. 대체 어떻게 한 걸까...? 정말 마법의 거울인 건 아니겠지?",
  str_item_intro_5273004 = "북방에서 찾아낸 진짜 등불 나무가 아니라 소품이다. 그저 보통 나무와 종이, 리본으로 장식한 것뿐이니, 절대 북방의 주민에게 선물해서는 안 된다.",
  str_item_intro_5273005 = "나무 옷걸이라고는 하지만 사실 저렴한 합판으로 만든 것이다. 정말로 옷을 걸기 위한 용도는 아니며, 보기에 그럴듯하기만 하면 된다.",
  str_item_intro_5273006 = "안쪽은 점토로 채우고 밖은 흰색 모래로 만든 인형이다. 슬쩍 보면 정말 눈을 쌓아서 만든 것만 같다. 하지만 이 인형은 녹지 않는다.",
  str_item_intro_5273007 = "소품 제작자들의 솜씨 덕에 이 나무 조각상은 정말 조각상처럼 생기가 가득하다. 중요한 건 아주 가볍기 때문에 촬영장에서 쉽게 옮길 수 있다는 것이다.",
  str_item_intro_5273008 = "낡은 물건을 씻고 말려서 만든 「소품」이다. 이곳저곳이 매우 낡아버린 물건이기는 하지만, 어떤 각도에서는 아직 새것 같다.",
  str_item_intro_5273009 = "저, 정말 허공에 떠 있을 수 있다니! 아무래도 진짜인 것 같다. 진짜든 가짜든 허공에 떠 있을 수 있는 원리는 알 수가 없다. 하지만 이걸 정말 촬영장에 둬도 되는 걸까?",
  str_item_intro_5273010 = "뒤에 붙여둔 배경판이기는 해도 아주 무서운 느낌이 든다. 소품 제작자들의 뛰어난 그림 때문일까? 아니면 이 나무집이 정말 무섭기 때문일까? 지금 생각해보면 공포 영화 속의 비명은 연기가 아닐지도 모르겠다.",
  str_item_intro_5273011 = "공포의 나무집 배경판과 함께 사용하는 소품이다. 넓게 깔면 오래되어 썩은 듯한 느낌이 난다. 공포 영화에 잘 어울린다.",
  str_item_intro_5273012 = "일부러 만들어낸 고서로, 많은 글씨가 쓰여 있다. 진짜처럼 보이기 위해 글과 편집 방식, 삽화... 심지어는 표지까지 똑같이 따라 했다고 한다. 어떤 면에서는 필사본과 다를 바가 없다. 하지만 그 안의 내용은 비밀이다!",
  str_item_intro_5273013 = "공중에 떠 있을 수 있는 소품이다. 안에는 풍선이 든 것 같다. 하늘로 날아가지 않도록 밑에 얇은 선으로 바닥에 고정해뒀다.",
  str_item_intro_5273014 = "일부 장난감들을 그대로 가져와 사용했다. 새 물건에 비해 약간 낡은 느낌이 난다. 기념일에 아이들을 즐겁게 해주기 위해 만들어진 것이었지만, 공포 영화 속에서는 무척이나 기괴한 느낌을 준다.",
  str_item_intro_5273015 = "「비석」이든 땅이든 사실 전부 나무 프레임과 나뭇조각에 종이를 덧씌워 만든 것이기 때문에 아주 가볍다. 중요한 건 빠르게 많이 만들 수 있다는 것이다. 촬영장에 배치하면 음산한 묘지 느낌을 빠르게 조성할 수 있다.",
  str_item_intro_5273016 = "나무와 금속 조각으로 만든 수화기다. 당연히 소통을 위해 사용하는 건 아니다. 즉, 공포 영화에서 통신기로 서로 대화하는 장면은 배우의 연기일 수도 있다는 것이다. 정말 힘든 일이다.",
  str_item_intro_5273017 = "가면은 공포 영화에 아주 잘 어울릴 것 같다. 하지만 저 모자는... 뭔가 사막의 풍경이 떠오를 것만 같다. 다른 영화 스타일을 추구하려는 걸까?",
  str_item_intro_5273018 = "화분과 흙은 모두 진짜지만 꽃은 가짜일 것이다. 헝겊을 자르고 그림을 더해서 만든 것이라고 한다. 저렴하고 빠르게 만들 수 있는 데다 영원히 시들지 않는다.",
  str_item_intro_5273019 = "배치해두면 술 향기와 은은한 건배 소리, 경쾌한 노래마저 들려오는 것만 같다. 이런 「바」에서는 어떤 장면을 연기하게 될까?",
  str_item_intro_5273020 = "다소 낡은 바닥이다. 꽤 오래돼 보이기 때문에 제대로 못 깔아도 상관없다. 이런 바의 나무 바닥은 가끔 구멍이 나 있어도 이상하지 않기 때문이다.",
  str_item_intro_5273021 = "어쩌면 가장 비싼 소품 중 하나일 것이다. 진짜 물건인 만큼, 음반을 올려두면 노래가 흘러나온다! 그렇기에 각본가들은 절대 「주인공이 플레이어를 부순다」와 같은 클리셰를 써서는 안 된다. 비록 어떤 각본에서는 상황을 충분히 드러낼 수 없을지도 모르지만, 촬영장에 무료로 음악을 더 해줄 수 있으니 「일거양득」인 셈이다.",
  str_item_intro_5273022 = "바 카운터는 합판으로 만든 것으로, 꽤 견고하다. 물론 진짜 나무로 만든 것만큼은 아니지만 말이다... 의자는 다른 바에서 사 온 것이다. 좀 낡았지만, 다시 칠하고 나니 새것처럼 사용할 수 있게 됐다.",
  str_item_intro_5273023 = "바의 분위기와 잘 어울리는 테이블과 의자다. 디자인이든 장식이든 「이 테이블과 의자는 바에 놓는 것」이라는 느낌을 준다. 한두 개 놓아두면 프로듀서의 구체적인 지시가 없어도 배우들이 이번 장면은 바에서 발생하는 일이라는 사실을 깨달을 수 있다.",
  str_item_intro_5273024 = "어떤 프로듀서가 이상한 소재의 영화를 촬영하기 위해 특별히 빌려온 테이블과 의자라고 한다. 배치해두면 일하는 분위기가 물씬 풍긴다. 하지만 이게 바에 어울릴까? 왠지 예산이 부족해서 다른 촬영장의 테이블과 의자를 강제로 가져온 것 같다.",
  str_item_intro_5273025 = "진짜 피아노는 너무 무거운데다 너무 비싸다! 그러니 가짜 피아노면 충분하다. 어차피 요즘 신예 배우들은 대부분 피아노를 칠 줄도 모르니 흉내 정도만 내도 된다.",
  str_item_intro_5273026 = "나무로 빠르게 만든 무대다. 진짜 무대만큼 튼튼하지는 않지만, 만드는 데 인력이 그렇게 필요한 편도 아니다. 망가지면 금방 새로 만들 수 있다.",
  str_item_intro_5273027 = "나무 칼꽂이는 진짜다. 하지만 그 위의 칼은 소품용 칼일 것이니 한두 번 긋는 것 정도는 문제없다. 날을 세우지 않았기 때문에 전투 장면에서 배우가 맞아도 크게 다치지 않는다.",
  str_item_intro_5273028 = "햇살이 들어오는 교실, 책상과 의자가 가지런히 놓여 있고, 분필 냄새가 어렴풋이 풍기는 것 같다.\n그리고 아마도 창가에서 두 번째 줄은 당신을 위해 준비된 좌석일 것이다.",
  str_item_intro_5273029 = "아주 흔한 나무 바닥이지만, 특수 처리가 되어 있어 내구성이 높아졌다. 걷기 전에 실내화로 갈아신어야 한다.",
  str_item_intro_5273030 = "이상하게 생긴 요리 기계이자 뽑기 기계다. 나온 물건을 열어보기 전까지는 안에 무엇이 들어 있는지 알기 어렵다.",
  str_item_intro_5273031 = "신비한 조리도구다. 튀기는 것보다 건강에 좋다고 하며, 초보자도 자유롭게 사용할 수 있다.",
  str_item_intro_5273032 = "속에서 보글보글 끓고 있다. 재료가 잘 어우러지도록 계속 저어줘야 한다.\n아름다운 소녀가 이 일을 하는 것을 좋아하지 않을 사람이 있을까.",
  str_item_intro_5273033 = "희미하게 이상한 냄새를 풍기는 수수께끼의 액체가 담긴 통이다.",
  str_item_intro_5273034 = "밤낮으로 작동해서 음식과 음료를 공급하는 기계다. 게으른 사람들의 구원자다.",
  str_item_intro_5273035 = "연주하는 데 기술이 필요하지만, 밤이 되어 아무도 없으면 끝없이 울린다.",
  str_item_intro_5273036 = "소품일 뿐이니 절대 먹어서는 안 된다!",
  str_item_intro_5273037 = "활기가 넘치는 객잔이다. 안에는 온갖 부류의 사람들이 섞여서 시끄러운 목소리를 내고 있다. 하지만 이곳에 어떤 사람이 있고, 어떤 일이 일어나게 될 것인지는 아무도 모른다.",
  str_item_intro_5273038 = "밟으면 나무 바닥이 삐걱거린다.",
  str_item_intro_5273039 = "객잔에서 음식값을 계산하는 계산대다. 주인장은 항상 여기 앉아 있다. 만약 혼자라서 외로울 때면 가서 그와 이야기를 나눌 수 있다.",
  str_item_intro_5273040 = "정교한 도자기다. 주인장이 장식품에 꽤나 안목이 있음을 알 수 있다.",
  str_item_intro_5273041 = "이상한 장식품이다. 어쩌면 어느 손님이 객잔에 선물한 것일지도 모른다.",
  str_item_intro_5273042 = "물고기 뼈로 만든 표본이다. 크기로 미루어 보면 살아 있을 때는 분명히 용맹했을 것이다.",
  str_item_intro_5273043 = "초라한 목제 가구다. 성질 급한 손님을 만나면 제일 먼저 해를 입는 물건이니 너무 비싸게 사지 않는 것이 좋다.",
  str_item_intro_5273044 = "익숙한 테이블과 의자다. 앉으면 집에 돌아온 듯한 느낌을 준다.",
  str_item_intro_5273045 = "보기에 매우 따뜻해 보이는 가구다. 겨울이라면 안에서 하루 정도 누워 있으면 아주 편할 것 같다.",
  str_item_intro_5273046 = "주인장이 만든 술이다. 뚜껑을 열면 깊은 향이 나며, 사람들은 종종 안개 속에서 길을 잃고, 이 생에서 다하지 못한 후회에 눈물을 흘린다.",
  str_item_intro_5273047 = "어디서 구했는지 모를 기념품이 매장에 이국적인 정취를 더한다. 어쩌면 사람들은 이것을 보고 연로한 주인장과 이국의 성배 사이에 기억할 만한 이야기가 있었지 않을까 상상할지도 모른다.",
  str_item_intro_5273049 = "차가운 바람이 불고, 까마귀 소리가 사방에서 들리며, 주변의 환경은 온통 스산하다. 홀로 걷는 영웅적인 무사는 위험한 길을 떠날 운명을 지니고 있다.",
  str_item_intro_5273050 = "난세의 시기에는 이런 이름 없는 땅이 많기 마련이다. 이곳을 잠행할 때는 발밑의 마른 풀이 소리를 내지 않도록 주의해야 하며, 자신의 숨소리도 남기지 말아야 한다.",
  str_item_intro_5273051 = "아무리 봐도 평범한 장식장처럼 보이지만, 함정을 건드리면 즉시 명검이 튀어나온다. 반드시 전문가의 지도하에 조작해야 한다.",
  str_item_intro_5273052 = "갈대 그림을 그린 데코 시트다. 촬영장에 부착하면 사람들에게 말을 타고 싶은 충동을 준다.",
  str_item_intro_5273053 = "보리밭 그림을 그린 데코 시트다. 촬영장에 부착하면 무사가 안에 숨어 있을까?",
  str_item_intro_5273054 = "해바라기 그림을 그린 데코 시트다. 촬영장에 부착하면 햇살이 비출 것 같다.",
  str_item_intro_5273055 = "어디서 온 것인지 알 수 없는 영사기다. 아래에 깔린 천에서도 세월의 흐름이 느껴진다. 비디오테이프를 넣으면 몇 가지 핵심 정보를 볼 수 있는 것 같다.",
  str_item_intro_5273056 = "어디서 온 것인지 알 수 없는 지도다. 전쟁 시기에 사용했던 군사 지도로 보이며, 몇 가지 중요한 정보를 기록하고 있는 것처럼 보인다.",
  str_item_intro_5273057 = "어디서 온 것인지 알 수 없는 우체통이다. 여기 얼마나 서 있었는지는 아무도 모른다. 우체통에 난 흔적을 자세히 관찰해 보면, 누군가 남긴 중요한 정보를 볼 수 있을 것 같다.",
  str_item_intro_5234040 = "약삭빠른 레디젤 렌치의 상인 조무, 여기에도 광고를 빼놓지 않는 것을 보면 모두에게 「레디젤 푸드 페스티벌」에 참여하라고 하는 것 같다. 혜택이 많다고 하지만 그쪽은 전부 사막인데 무슨 이상한 음식이 있는 건 아니겠지?",
  str_item_intro_5234041 = "「최연소 천재 미소녀가 제작, 연출, 주연, 촬영까지 모두 담당한 훌륭한 처녀작 영화」라고 하며, 무섭고도 웃긴다고 하는데 그건 광고만 봐도 알 수 있다. 과연 이 영화가 흥행할까? 그건 앞으로 지켜보는 수밖에 없을 것 같다.",
  str_item_intro_5234042 = "일루미나 연방의 모집판, 일루미나만의 독특한 분위기가 느껴진다. 「암귀와 맞서는 최후, 최강의 방어선에 우리와 함께 서자」라는 광고 문구가 매우 힘이 있다. 적지 않은 사람에게 감동을 줄 것이다.",
  str_item_intro_5234031 = "정수리에 가시가 자란 동물이다. 피부가 아주 거칠어 보이지만, 다행히도 그냥 조각상이다.",
  str_item_intro_5234032 = "아주 긴 뿔이 자라나 있지만, 온순해 보인다... 게다가 자꾸 만지고 싶어진다.",
  str_item_intro_5241014 = "무슨 일이지? 왜 콜로서스가 통통해져 버린 거지?! 그렇지만 아직도 날 수 있는 데다가, 사람을 데리고 하늘로 올라가 높은 곳에 있는 느낌을 누릴 수 있게 해 준다.",
  str_item_intro_5232007 = "정말 신기한 기술이다! 아직까지도 원리는 모르겠지만, 일단 앉으면 돌 의자가 붕 떠올라 자기 혼자 균형을 잡는다! 무서워하지 말고 한 번 앉아 보시라.",
  str_item_intro_5234035 = "이 고대 기념비에 새겨진 무늬들은 모두 질서 정연하게 규칙을 가지고 기묘한 도안을 형성했다. 어떤 수학 원리를 나타낸다고 하지만, 구체적으로 어떤 원리인지는 자세히 알 수 없다.",
  str_item_intro_5222001 = "어디서나 잘 자라는 관목 여러 그루를 한 곳에 심고 다듬어 만든 낮은 담장이다. 장식 효과도 있고 공간을 나눠야 할 때도 사용할 수 있다.",
  str_item_intro_5222002 = "키가 큰 편인 관목들을 한곳에 모아 심어 만든 담장이다. 정원에서 외벽 용도로 많이 사용된다. 몇몇 지방에서는 이런 높은 관목 담장을 대량으로 만들어 식물 미로를 조성한다고 한다.",
  str_item_condition_103 = "「π호 지하성」 기초 탐색 완료 시 획득",
