  str_item_use_3000281 = "영화 시나리오. 획득 후 헤븐즈 가든의 촬영장에서 영화를 촬영할 수 있다.",
  str_item_use_3000282 = "영화 시나리오. 획득 후 헤븐즈 가든의 촬영장에서 영화를 촬영할 수 있다.",
  str_item_use_3000283 = "영화 시나리오. 획득 후 헤븐즈 가든의 촬영장에서 영화를 촬영할 수 있다.",
  str_item_use_3000284 = "영화 시나리오. 획득 후 헤븐즈 가든의 촬영장에서 영화를 촬영할 수 있다.",
  str_item_use_3000285 = "영화 시나리오. 획득 후 헤븐즈 가든의 촬영장에서 영화를 촬영할 수 있다.",
  str_item_use_3000286 = "영화 시나리오. 획득 후 헤븐즈 가든의 촬영장에서 영화를 촬영할 수 있다.",
  str_item_use_3000297 = "영화 시나리오. 획득 후 헤븐즈 가든의 촬영장에서 영화를 촬영할 수 있다.",
  str_item_use_3000298 = "영화 시나리오. 획득 후 헤븐즈 가든의 촬영장에서 영화를 촬영할 수 있다.",
  str_item_use_3000299 = "영화 시나리오. 획득 후 헤븐즈 가든의 촬영장에서 영화를 촬영할 수 있다.",
  str_item_3661026 = "기념일 칠면조 만찬",
  str_item_intro_3661026 = "가구, 콜로서스의 방에 배치할 수 있다.\n축제에서 가장 중요한 대목은 역시 먹고 마시는 시간이다. 이 칠면조 만찬은 비주얼부터 맛까지 축제의 메인 요리 지위에 걸맞은 메뉴라고 할 수 있다. 절대 놓쳐선 안 된다!",
  str_item_3661181 = "콜로서스 벽시계",
  str_item_intro_3661181 = "가구, 콜로서스의 방에 배치할 수 있다.\n원래는 올빼미 모양의 벽시계였으나, 일부 상인들이 너무 평범하다고 생각해서 콜로서스로 교체했는데... 왠지는 모르겠지만 의외로 어울린다. 아쉽게도 날개는 움직일 수 없다.",
  str_item_3661182 = "스푼 나이트",
  str_item_intro_3661182 = "가구, 콜로서스의 방에 배치할 수 있다.\n자! 내 스푼을 받아라! 스푼 나이트는 유명한 푸드 파이터다. 그의 큰 배를 봐라. 심지어 갑옷도 특수 제작한 것이다! 그리고 입에서 흘러나온 침은... 설마 또 누군가의 식탁을 노리는 건 아니겠지?",
  str_item_3661027 = "골디의 응원 조명판",
  str_item_intro_3661027 = "가구, 콜로서스의 방에 배치할 수 있다.\n자! 함께 골디를 응원해요! 그녀의 노랫소리가 대륙 모든 곳에 퍼져나가게 하자구요!",
  str_item_3000289 = "이능력 경험치",
  str_item_3000290 = "이능력 포인트",
  str_item_3661183 = "DJ 테이블",
  str_item_intro_3661183 = "가구, 콜로서스의 방에 배치할 수 있다.\n오디오 앰프가 내장된 테이블로, 다양한 버튼을 조작해 거의 무한한 소리를 만들어내고, 리듬의 변화를 더할 수 있다. 기기를 다룰 수 있는 사람만 있다면 모두를 뜨거운 춤과 노래의 분위기에 빠트릴 수 있다.",
  str_item_3661184 = "꿈의 소녀 포스터",
  str_item_intro_3661184 = "가구, 콜로서스의 방에 배치할 수 있다.\n파이팅! 당신도 그녀와 같은 소녀가 될 수 있답니다! 무대에 올라 온 대륙에 사랑과 희망을 전파하세요! 그러니 언제라도 꿈을 포기해선 안 돼요!",
  str_item_3661185 = "투어독 인형",
  str_item_intro_3661185 = "가구, 콜로서스의 방에 배치할 수 있다.\n언제나 움브라톤 트렌드의 최전선에 서 보세요! 그저 서 있는 인형일 뿐이지만, 투어독은 그의 미적 안목을 드러내고 있습니다. 이 인형은 그의 팬들 사이에서 인기가 매우 많다고 하니, 빼앗기지 않게 조심하세요~",
  str_item_3661186 = "어썰트 워리어",
  str_item_intro_3661186 = "가구, 콜로서스의 방에 배치할 수 있다.\n강력한 음악을 연주할 수 있는 악기로, 그 소리는 나약한 사람들을 쓰러트릴 만큼 강렬하기에, 가장 용맹한 자만이 연주할 수 있다고 한다. 「다소」 시끄럽긴 하지만, 사람들로 가득 넘치는 콘서트에는 최적의 아이템이다.",
  str_item_5259309 = "잠재력의 팬던트",
  str_item_5259310 = "저주의 돌",
  str_item_5259311 = "수수께끼의 상자",
  str_item_5259410 = "버려진 칼날",
  str_item_5259411 = "광전사의 손목보호대",
  str_item_5259412 = "인연 조각상",
  str_item_5259505 = "에너지 벨트",
  str_item_5259506 = "광전사의 혼",
  str_item_5259507 = "빛의 대검",
  str_item_5259513 = "광전사의 갑옷",
  str_item_5259514 = "전투의 여신상",
  str_item_intro_5259301 = "15칸 이상 연결 시 연쇄 스킬 피해 증가",
  str_item_intro_5259302 = "피해 계산 시 아군이 불리한 속성의 영향을 무시함",
  str_item_intro_5259303 = "적에게 중독/작열/출혈 상태를 거는 즉시 추가 피해를 입힘",
  str_item_intro_5259304 = "아군의 최대 HP가 영구적으로 증가",
  str_item_intro_5259305 = "HP가 절반 미만으로 떨어질 경우 HP 회복 아이템이 필드에 생성됨",
  str_item_intro_5259306 = "웨이브가 시작될 때마다 HP 회복",
  str_item_intro_5259307 = "웨이브가 시작될 때마다 실드 획득",
  str_item_intro_5259308 = "턴마다 주변에 있는 보스를 제외한 적에게 높은 피해를 입힘",
  str_item_intro_5259309 = "아이테르 특수 장비 액티브 효과 쿨다운 -1",
  str_item_intro_5259310 = "턴마다 모든 적과 아군의 HP가 일정 비율만큼 감소",
  str_item_intro_5259311 = "랜덤으로 아이테르 특수 장비 1개 추가 획득",
  str_item_intro_5259401 = "디버프 상태에서 적이 받는 피해 증가",
  str_item_intro_5259402 = "오로리안의 초과 치유량이 비율에 따라 실드로 전환됨",
  str_item_intro_5259403 = "적 사망 시 필드 내 적과 아군 모두 중독\n아군이 받는 중독 피해 감소",
  str_item_intro_5259404 = "이상 상태에서 연쇄 스킬 피해 증가",
  str_item_intro_5259405 = "매우 낮은 확률로 보스를 제외한 적 즉시 처치",
  str_item_intro_5259406 = "액티브 스킬로 적 처치 시 아군의 HP 회복",
  str_item_intro_5259407 = "HP가 최대일 때 아군의 모든 피해 증가",
  str_item_intro_5259408 = "적의 맹독 피해 발동 시 아군의 HP 회복\n아군이 받는 중독 피해 감소",
  str_item_intro_5259409 = "적이 아군에게 피해를 입힐 시 피해 반사",
  str_item_intro_5259410 = "최소 3종의 서로 다른 주속성 오로리안 편대 편성 시 아군의 피해 증가",
  str_item_intro_5259411 = "오로리안이 부속성으로 입히는 피해가 감소하지 않음",
  str_item_intro_5259412 = "리더 변경 횟수 +5\n이번 턴에 처음 리더가 된 오로리안의 액티브 스킬 쿨다운 -1",
  str_item_intro_5259501 = "리더가 연결 시작 지점에서 연쇄 스킬을 추가로 시전",
  str_item_intro_5259502 = "일반공격 5회마다 폭발 효과 발생",
  str_item_intro_5259503 = "턴마다 주변 1서클에 소량의 만색 칸 생성",
  str_item_intro_5259504 = "HP가 10% 미만인 적 즉시 처치",
  str_item_intro_5259505 = "제자리에 멈춰 있을 시 액티브 스킬의 쿨다운 가속",
  str_item_intro_5259506 = "아군 오로리안의 방어력이 전부 공격력으로 전환됨",
  str_item_intro_5259507 = "연결되는 첫 번째 칸의 색상이 다음 칸과 다를 수 있으며, 주속성 발동으로 간주함",
  str_item_intro_5259508 = "숲 속성 칸을 만색 칸으로 간주",
  str_item_intro_5259509 = "물 속성 칸을 만색 칸으로 간주",
  str_item_intro_5259510 = "불 속성 칸을 만색 칸으로 간주",
  str_item_intro_5259511 = "번개 속성 칸을 만색 칸으로 간주",
  str_item_intro_5259512 = "아군의 피해가 대폭 증가하나, 연결할 때마다 파괴된 칸 생성",
  str_item_intro_5259513 = "아군의 HP가 낮을수록 연쇄 스킬 피해가 증가함",
  str_item_intro_5259514 = "리더 변경 횟수 +5\n이번 턴에서 리더였던 오로리안이 연결 색상을 무시하고 주속성에 따라 출전",
  str_item_rpintro_5259301 = "아군이 15칸 이상 연결 시 연쇄 스킬 피해 30% 증가",
  str_item_rpintro_5259302 = "아군이 피해를 입힐 시 불리한 속성의 피해 감소 효과 무시, 아군이 피해를 입을 시 불리한 속성의 피해 증가 효과 무시",
  str_item_rpintro_5259303 = "적에게 중독/작열/출혈 상태를 거는 즉시 대상의 HP가 자신의 공격력의 50%만큼 감소, 턴마다 각 대상에게 최대 1회 발동",
  str_item_rpintro_5259304 = "파티 내 오로리안의 HP 한도가 100% 증가하나, 현재 HP는 유지됨",
  str_item_rpintro_5259305 = "아군의 남은 HP가 50% 미만으로 떨어질 때마다 필드 내 랜덤 위치에 붕대가 나타나며, 아군이 붕대 통과 시 최대 HP의 20% 회복",
  str_item_rpintro_5259306 = "웨이브가 시작될 때마다 최대 HP의 20% 회복",
  str_item_rpintro_5259307 = "웨이브가 시작될 때마다 최대 HP의 40%에 해당하는 실드를 1턴간 획득",
  str_item_rpintro_5259308 = "턴이 시작될 때마다 주변 1서클 내에 있는 보스를 제외한 적에게 최대 HP의 50%에 해당하는 피해를 입힘",
  str_item_rpintro_5259309 = "이후 전투에서 아이테르 특수 장비 액티브 효과의 시전 쿨다운 -1",
  str_item_rpintro_5259310 = "턴이 시작될 때마다 필드 내 모든 적과 아군의 현재 HP 7% 감소(보스 타입의 적 포함)",
  str_item_rpintro_5259311 = "랜덤으로 다른 유형의 아이테르 특수 장비 1개 획득, 이후 전투에서 사용할 수 있으며, 쿨다운 턴 단독 계산",
  str_item_rpintro_5259401 = "적이 이상 상태 또는 디버프 효과 상태일 시 받는 모든 피해 20% 증가",
  str_item_rpintro_5259402 = "오로리안의 초과 치유량의 100%가 1턴간 지속되는 실드로 전환됨",
  str_item_rpintro_5259403 = "적이 사망할 때마다 필드 내 적과 아군 파티에 중독 1단계 부여, 아군이 받는 중독 피해 -50%",
  str_item_rpintro_5259404 = "아군 파티가 이상 상태일 시 연쇄 스킬 피해 30% 증가",
  str_item_rpintro_5259405 = "보스를 제외한 적이 피해를 입을 시 3% 확률로 즉시 사망",
  str_item_rpintro_5259406 = "액티브 스킬로 적을 처치할 때마다 아군이 시전자의 최대 HP의 15%에 해당하는 HP 회복",
  str_item_rpintro_5259407 = "아군 파티의 현재 HP가 최대일 때 입히는 모든 피해 20% 증가",
  str_item_rpintro_5259408 = "적이 중독 피해를 입을 때마다 아군이 중독 피해량의 100%에 해당하는 HP 회복, 아군이 받는 중독 피해 -50%",
  str_item_rpintro_5259409 = "적이 아군에게 피해를 입힐 시 아군이 입은 피해의 100%에 해당하는 피해 반사",
  str_item_rpintro_5259410 = "파티 내 최소 3종의 서로 다른 주속성 오로리안 편성 시 아군이 입히는 모든 피해 25% 증가",
  str_item_rpintro_5259411 = "오로리안이 부속성으로 피해를 입힐 시 주속성과 동일한 배율 적용",
  str_item_rpintro_5259412 = "획득 시 리더 변경 횟수 +5\n리더 교체 시 새로운 리더의 액티브 스킬 쿨다운 -1, 턴마다 각 오로리안당 1회만 발동 가능",
  str_item_rpintro_5259501 = "리더 오로리안이 연결 시작 위치에 분신을 만들고, 이번 턴에 연쇄 스킬을 동시에 시전함",
  str_item_rpintro_5259502 = "일반 공격의 콤보 수가 5의 배수일 시 적에게 폭발 효과 1회 추가",
  str_item_rpintro_5259503 = "턴이 시작될 때마다 주변 1서클 내 3개의 칸을 만색 칸으로 변경함",
  str_item_rpintro_5259504 = "남은 HP가 10% 미만인 적을 즉시 처치",
  str_item_rpintro_5259505 = "해당 턴에서 연결을 통해 이동하지 않으면 모든 쿨다운 중인 오로리안 액티브 스킬의 남은 쿨다운 턴 -1",
  str_item_rpintro_5259506 = "아군 파티의 모든 오로리안의 방어력이 0으로 감소하고, 자신의 공격력이 감소한 방어력만큼 증가함",
  str_item_rpintro_5259507 = "연결되는 첫 번째 칸의 색상이 다음 칸과 다를 수 있으며, 주속성 발동으로 간주함",
  str_item_rpintro_5259508 = "다른 색으로 연결 시 숲 속성 칸도 연결 가능",
  str_item_rpintro_5259509 = "다른 색으로 연결 시 물 속성 칸도 연결 가능",
  str_item_rpintro_5259510 = "다른 색으로 연결 시 불 속성 칸도 연결 가능",
  str_item_rpintro_5259511 = "다른 색으로 연결 시 번개 속성 칸도 연결 가능",
  str_item_rpintro_5259512 = "아군이 입히는 모든 피해가 25% 증가하나, 매회 연결 시작 지점이 5턴간 이동할 수 없는 파괴된 칸으로 변경됨",
  str_item_rpintro_5259513 = "아군의 감소한 HP 퍼센트에 따라 연쇄 스킬 피해 증가, 최대 80%",
  str_item_rpintro_5259514 = "리더 변경 횟수 +5\n이번 턴에서 리더였던 오로리안이 연결 색상을 무시하고 주속성에 따라 출전",
  str_item_intro_9994027 = "파티 내 최소 3종의 서로 다른 주속성 오로리안 편성 시 아군이 입히는 모든 피해 25% 증가",
  str_item_intro_9994028 = "오로리안이 부속성으로 입히는 피해가 감소하지 않음",
  str_item_intro_9994029 = "리더 변경 횟수 +3\n이번 턴에 처음 리더가 된 오로리안의 액티브 스킬 쿨다운 -1",
  str_item_intro_9995019 = "제자리에서 연속 터치해 이동하지 않을 시 액티브 스킬의 쿨다운 추가 1턴 감소",
  str_item_intro_9995020 = "아군 파티의 모든 오로리안의 방어력이 50%로 감소하고, 자신의 공격력이 감소한 방어력만큼 증가함",
  str_item_intro_9995021 = "아군의 감소한 HP 퍼센트에 따라 연쇄 스킬 피해 증가, 최대 80%",
  str_item_intro_9995022 = "리더 변경 횟수 +3\n이번 턴에서 리더였던 오로리안이 연결 색상을 무시하고 주속성에 따라 출전",
  str_item_rpintro_9994027 = "루미나를 완벽하게 융합할 수 있을 것 같아 보이는 매우 보기 드문 무기다.",
  str_item_rpintro_9994028 = "고대의 전사 중 하나가 전투 도중 자기 손을 완벽히 다루지 못해 전투에서 패배한 후, 오로지 그 결점을 보완하기 위해 이 손목보호대를 만들어 사용하기 시작했고, 사용한 이후부터는 전투에서 결코 불리해진 적이 없다고 한다.",
  str_item_rpintro_9994029 = "손은 마음을 이어줄 수 있는 통로다. 따라서 두 손을 마주 잡은 모습은 서로의 마음이 이어져 더는 떨어지지 않으리라는 사실을 나타낸다.",
  str_item_rpintro_9995019 = "고대의 유물이다. 착용자가 빠르게 다양하고 강력한 루미나틱스를 시전하도록 하는 힘을 가지고 있어, 여러 위험한 상황에 대처할 수 있다.",
  str_item_rpintro_9995020 = "「칼로 흥한 자, 칼로 망한다」는 옛말처럼, 자신의 목숨을 내놓을 각오로 달려든다면 매우 강한 적이라도 쓰러트릴 수 있다.",
  str_item_rpintro_9995021 = "세간에 떠도는 이야기에 등장하는 이 갑옷에서는 강력하고 무시무시한 힘이 느껴지며, 누군가는 이 갑옷을 진귀한 보물이라 생각하는 한편, 누군가는 이 갑옷을 저주라고 여긴다.",
  str_item_rpintro_9995022 = "이 조각상은 신이 아니라, 전투에 협조해 줄 수 있는 전설 속의 여전사를 조각한 것이라는 이야기가 있다.",
  str_item_3661187 = "용주 축복 매듭",
  str_item_intro_3661187 = "가구, 콜로서스의 방에 배치할 수 있다.\n노끈이 네모난 모양으로 솜씨 좋게 짜여 있어, 제작자의 기발함을 엿볼 수 있다. 용주 대륙에서 온 장식이라고 하며, 집에 걸어두면 사람들의 평안을 지켜준다고 한다.",
  str_item_3661188 = "높은 받침 등롱",
  str_item_intro_3661188 = "가구, 콜로서스의 방에 배치할 수 있다.\n용주 대륙에서 온 등롱이다. 독특한 목조 구조에 붉은 등롱을 곁들여 보는 이를 순식간에 다른 세계로 안내하는 것만 같다.",
  str_item_3661028 = "은하수 장식판",
  str_item_intro_3661028 = "가구, 콜로서스의 방에 배치할 수 있다.\n다양한 조명으로 장식판을 묶고, 조명을 비추면 은하수와 같은 빛의 풍경을 보여줄 수 있다. 벽에 걸어 감상할 수 있을 뿐만 아니라, 야외에서 나무에 걸면 어두운 날에도 별이 빛나는 하늘을 보는 듯한 착각을 일으킨다.",
  str_item_3010001 = "스타 마커(기간 제한)",
  str_item_intro_3010001 = "소집 신호 방출에 사용되는 전용 장치, 오로리안의 주의를 끌 수 있으며, 소집 신호에 응답한 오로리안을 파트너로 삼을 수 있다.\n본 아이템은 기간 한정 아이템으로, 유효 기한이 지나면 사라지므로 기한 내에 사용해 주세요. 유효 기한: 2023년 2월 9일 13:00",
