  str_item_intro_3010025 = "소집 신호 방출에 사용되는 전용 장치, 오로리안의 주의를 끌 수 있으며, 소집 신호에 응답한 오로리안을 파트너로 삼을 수 있다.\n본 아이템은 기간 한정 아이템으로, 유효 기한이 지나면 사라지므로 기한 내에 사용해 주세요. 유효 기한: 2024년 9월 4일 13:00",
  str_item_intro_3020025 = "특수한 도안 신호 방출에 사용되는 전용 장치, 오로리안의 주의를 끌 수 있다.\n본 아이템은 기간 한정 아이템으로, 유효 기한이 지나면 사라지므로 기한 내에 사용해 주세요. 유효 기한: 2024년 9월 4일 13:00",
  str_item_intro_3030025 = "외관이 반듯한 크리스탈 상자. 중심에서 빛이 나며, 프리즘에 많은 에너지를 제공할 수 있다.\n사용 시 60프리즘 획득 가능.\n본 아이템은 기간 한정 아이템으로, 유효 기한이 지나면 사라지므로 기한 내에 사용해 주세요. 유효 기한: 2024년 9월 4일 13:00",
  str_item_intro_3010026 = "소집 신호 방출에 사용되는 전용 장치, 오로리안의 주의를 끌 수 있으며, 소집 신호에 응답한 오로리안을 파트너로 삼을 수 있다.\n본 아이템은 기간 한정 아이템으로, 유효 기한이 지나면 사라지므로 기한 내에 사용해 주세요. 유효 기한: 2024년 9월 25일 13:00",
