  str_item_intro_3010027 = "소집 신호 방출에 사용되는 전용 장치, 오로리안의 주의를 끌 수 있으며, 소집 신호에 응답한 오로리안을 파트너로 삼을 수 있다.\n본 아이템은 기간 한정 아이템으로, 유효 기한이 지나면 사라지므로 기한 내에 사용해 주세요. 유효 기한: 2024년 10월 16일 13:00",
  str_item_intro_3020027 = "특수한 도안 신호 방출에 사용되는 전용 장치, 오로리안의 주의를 끌 수 있다.\n본 아이템은 기간 한정 아이템으로, 유효 기한이 지나면 사라지므로 기한 내에 사용해 주세요. 유효 기한: 2024년 10월 16일 13:00",
  str_item_intro_3030027 = "외관이 반듯한 크리스탈 상자. 중심에서 빛이 나며, 프리즘에 많은 에너지를 제공할 수 있다.\n사용 시 60프리즘 획득 가능.\n본 아이템은 기간 한정 아이템으로, 유효 기한이 지나면 사라지므로 기한 내에 사용해 주세요. 유효 기한: 2024년 10월 16일 13:00",
  str_item_intro_3010028 = "소집 신호 방출에 사용되는 전용 장치, 오로리안의 주의를 끌 수 있으며, 소집 신호에 응답한 오로리안을 파트너로 삼을 수 있다.\n본 아이템은 기간 한정 아이템으로, 유효 기한이 지나면 사라지므로 기한 내에 사용해 주세요. 유효 기한: 2024년 10월 16일 13:00",
  str_item_intro_3020028 = "특수한 도안 신호 방출에 사용되는 전용 장치, 오로리안의 주의를 끌 수 있다.\n본 아이템은 기간 한정 아이템으로, 유효 기한이 지나면 사라지므로 기한 내에 사용해 주세요. 유효 기한: 2024년 10월 16일 13:00",
  str_item_intro_3030028 = "외관이 반듯한 크리스탈 상자. 중심에서 빛이 나며, 프리즘에 많은 에너지를 제공할 수 있다.\n사용 시 60프리즘 획득 가능.\n본 아이템은 기간 한정 아이템으로, 유효 기한이 지나면 사라지므로 기한 내에 사용해 주세요. 유효 기한: 2024년 10월 16일 13:00",
  str_item_3000301 = "식재 주머니",
  str_item_intro_3000301 = "한데 뭉쳐 있는 식재들이다. 다양한 종류가 있다.\n음식 제조에 사용할 수 있다.",
  str_item_3000302 = "희귀한 오색 깃털",
  str_item_intro_3000302 = "어떤 신비로운 새의 깃털인지는 알 수 없지만, 색깔이 화려해서 취향이 맞는 일부 쿠리어 길드 멤버에게서 뭔가와 바꿀 수 있을지도 모른다.",
  str_item_3661189 = "장미 양초",
  str_item_intro_3661189 = "가구, 콜로서스의 방에 배치할 수 있다.\n꽃이 시들지 않고, 촛불이 꺼지지 않게 해, 이 순간의 아름다움과 추억이 오랫동안 마음에 남는다.",
  str_item_3661190 = "경청의 우편함",
  str_item_intro_3661190 = "가구, 콜로서스의 방에 배치할 수 있다.\n마음속 비밀을 말할 수가 없나요? 무언가에 대해 이야기하는 게 두렵나요? 이 우편함이 최고의 조력자가 될 것입니다. 인내심이 있고, 안전하며, 신뢰할 수 있는 훌륭한 친구니까요.",
  str_item_3661191 = "사랑의 테디베어",
  str_item_intro_3661191 = "가구, 콜로서스의 방에 배치할 수 있다.\n이렇게 귀여운 아기곰을 누가 거절할까요? 게다가 「하트」까지 있으니 말이죠. 누가 이걸 선물한다면, 상대의 마음을 바로 이해할 수 있을 것 같네요.",
  str_item_3661192 = "고백의 장미꽃",
  str_item_intro_3661192 = "가구, 콜로서스의 방에 배치할 수 있다.\n붉은색과 흰색의 꽃잎은 강한 감정으로 가득 차 있으며, 순수한 마음을 나타낸다. 이 꽃다발을 그 사람에게 건넬 때, 당신은 이미 그 세 글자를 말로 꺼낸 것과 다름없다.",
  str_item_3661029 = "하트 소파",
  str_item_intro_3661029 = "가구, 콜로서스의 방에 배치할 수 있다.\n크고 편안한 소파는 서로를 좋아하는 두 사람이 함께 눕기에 매우 적합하다. 물론 혼자라도 괜찮다. 포근한 소파에 감싸이는 느낌은 마치 상대가 곁에 있는 것 같기 때문이다...",
  str_item_3661193 = "순백의 날개",
  str_item_intro_3661193 = "가구, 콜로서스의 방에 배치할 수 있다.\n어떤 천사들은 사랑의 수호자라고 한다. 이 새하얀 깃털을 벽에 걸어 두면 사랑이 빨리 이루어질지도 모른다.",
  str_item_3661194 = "백조 케이크 타워",
  str_item_intro_3661194 = "가구, 콜로서스의 방에 배치할 수 있다.\n정교하게 만들어진 아름다운 백조 장식이 더해진 케이크 타워다. 식품이라기보다는 장식품에 더 가까워 먹기 아깝다는 느낌이 든다.",
  str_item_3661030 = "구름 속 별 풍선",
  str_item_intro_3661030 = "가구, 콜로서스의 방에 배치할 수 있다.\n놀이공원에 더 잘 어울리는 풍선이지만, 집에 장식해 두면 나름대로 특별한 느낌이 난다. 그렇지만 어딘가에 걸어 두지 않으면 하늘로 날아가 버릴 수도 있다.",
  str_item_3000308 = "증거 수집 기록",
  str_item_intro_3000308 = "범인의 일부 「특징」이 기록되어 있다. 진실을 찾는 데 도움이 될지도 모른다...",
  str_item_3661195 = "복고풍 축음기",
  str_item_intro_3661195 = "가구, 콜로서스의 방에 배치할 수 있다.\n다소 고전적인 축음기로, 수십 년 전 움브라톤에서 꽤 인기가 있었다고 하며, 부유한 사업가들의 필수품 중 하나였다. 제작자는 대부분 당시의 장인이었거나, 연구에 많은 노력을 기울인 모양이다. 덕분에 이 축음기의 음색과 장식 모두 나이 든 세대의 사람들이 과거의 음악과 세월에 심취할 수 있도록 한다.",
  str_item_3661196 = "단서 기록판",
  str_item_intro_3661196 = "가구, 콜로서스의 방에 배치할 수 있다.\n사건 분석을 위해 다양한 마인드맵을 그릴 수 있을 뿐만 아니라, 중요한 단서, 목격자 및 증거 사진, 곳곳에서 수집한 정보 등을 붙여두어, 언제든지 조사, 귀납, 총괄을 진행해 진상과 범인을 더 빨리 찾아낼 수 있다.",
  str_item_3661197 = "티 테이블",
  str_item_intro_3661197 = "가구, 콜로서스의 방에 배치할 수 있다.\n원래는 애프터눈 티를 마시며 카드놀이를 하는 테이블이었지만, 지금은 사건과 관련된 책과 신문이 쌓여 있고, 그 옆에는 돋보기, 파이프, 랜턴 등이 있다. 이 테이블의 주인은 틀림없이 탐정이거나 「탐정 마니아」로 보인다.",
  str_item_3661198 = "코트랙",
  str_item_intro_3661198 = "가구, 콜로서스의 방에 배치할 수 있다.\n조사를 위한 외출 시에는 반드시 필요한 복장이 있는데, 바로 롱코트다. 롱코트는 추운 밤 날씨를 견딜 수 있게 해줄 뿐만 아니라, 조사에 필요한 노트, 돋보기, 호신용 소형 무기 등을 주머니에 넣어둘 수 있다. 또한 모자는 방풍 효과도 있지만, 착용자를 더 탐정처럼 보이게 만들어 준다.",
  str_item_3661031 = "추리용 소파",
  str_item_intro_3661031 = "가구, 콜로서스의 방에 배치할 수 있다.\n어떤 탐정들은 소파에 앉아 다른 사람들이 수집한 다양한 단서에 의지해 사건의 진상을 추리하기만 하면 된다고 한다. 아무래도 이 소파는 휴식 용도도 있지만, 두뇌 회전을 더 빠르게 만들어 주는 모양이다.",
  str_item_3661199 = "파이프 선반",
  str_item_intro_3661199 = "가구. 콜로서스의 방에 배치할 수 있다.\n파이프가 가득 걸린 선반이다. 담배 냄새를 싫어할 수도 있지만, 색다른 스타일의 파이프를 수집하는 것도 꽤 가치 있는 일이다.",
  str_item_3661200 = "빈티지 망원경",
  str_item_intro_3661200 = "가구. 콜로서스의 방에 배치할 수 있다.\n멀리 있는 풍경을 눈에 담을 때 최고의 성능을 발휘한다. 렌즈는 매우 선명하지만, 전체적으로 금속으로 만들어졌기 때문에 어느 정도 무게가 나간다. 전용 삼각대에 올려놔야만 안정적으로 사용할 수 있다.",
  str_item_3661032 = "견고한 금고",
  str_item_intro_3661032 = "가구. 콜로서스의 방에 배치할 수 있다.\n상인들은 「대륙에서 가장 안전하고 가장 견고한 상품들의 감옥이다」라고 말하고는 한다. 커다란 손잡이는 매우 견고해 보이며, 두껍고 무거운 몸체는 대부분의 충격을 견뎌낼 수 있을 것 같다.",
  str_item_3661033 = "승리와 명예의 오리",
  str_item_intro_3661033 = "가구. 콜로서스의 방에 배치할 수 있다.\n그로누가 열심히 디자인한 오리다. 게임의 승리자에게 주는 선물이다! 매우 귀여울 뿐만 아니라, 금빛으로 빛나는 모습은 승리자의 명예를 상징하기도 한다.",
  str_item_3661207 = "질서의 카펫",
  str_item_intro_3661207 = "가구. 콜로서스의 방에 배치할 수 있다.\n머나먼 하늘에 있는 영원의 도시는 아스트라 대륙 문명의 빛이라고 할 수 있다. 이 카펫은 신분과 지위를 상징할 뿐만 아니라, 질서와 규칙을 상징하기도 한다.",
  str_item_3661208 = "영원의 깃발",
  str_item_intro_3661208 = "가구. 콜로서스의 방에 배치할 수 있다.\n「마지막 영원의 도시」를 상징하는 표식. 이 깃발이 대륙에 나타나면, 백야성의 문명의 빛이 이곳을 비출 것임을 의미한다.",
  str_item_3661201 = "클래식 하프",
  str_item_intro_3661201 = "가구, 콜로서스의 방에 배치할 수 있다.\n하프는 백야성에서 성대한 축제를 거행할 때만 사용된다. 특별한 루미나틱스로 보호되기 때문에 음색이 영원히 어긋나지 않으며, 오직 최고의 음악가만이 이를 사용해 찬송의 노래를 연주할 수 있다.",
  str_item_3661202 = "빛의 모래시계",
  str_item_intro_3661202 = "가구, 콜로서스의 방에 배치할 수 있다.\n「빛과 밤이 교차하는 때, 오직 이를 통해서만 정확한 시간을 계산할 수 있다.」 이 모래시계는 대륙에서 가장 미세한 모래 알갱이를 담은 것으로, 특별한 루미나틱스의 조정 덕분에 그 정확도는 최고의 시계에 버금간다고 한다.",
  str_item_3661203 = "구름 위의 분수",
  str_item_intro_3661203 = "가구, 콜로서스의 방에 배치할 수 있다.\n구름 위의 정원에서 물 흐르는 소리를 들었다면, 이것이 백야성의 분수대라는 사실에 놀라지 않는 것이 좋다. 경이로운 루미나틱스의 은총 덕분에 마치 물이 허공에서 생겨나서 아래로 이어지고, 이를 통해 하늘 위에서도 분수의 풍경을 감상할 수 있다.",
  str_item_3661204 = "최후의 검과 방패",
  str_item_intro_3661204 = "가구, 콜로서스의 방에 배치할 수 있다.\n영원히 함락되지 않는 도시인 백야성은 의심의 여지 없는 문명의 최후 방어선이다. 그리고 이 검과 방패는 바로 그 최후 방어선의 마지막 의지... 그것은 마지막 순간까지 싸우는 책임, 용기와 의지를 상징한다.",
  str_item_3661034 = "추억의 날 수정구슬",
  str_item_intro_3661034 = "가구, 콜로서스의 방에 배치할 수 있다.\n수정을 급하게 들여다보면 자신의 비친 모습만 엿볼 수 있지만, 수정을 자세히 들여다보면 과거의 모습을 볼 수 있다. 기억의 목소리는 눈앞을 헤매고 있다. 그걸 잡기 위해서는 그 안으로 깊이 빠져들어야만 한다...",
  str_item_3000325 = "마음의 이슬",
  str_item_intro_3000325 = "이 세상의 「눈물」이라는 말이 전해지며... 오직 「그 날」에만 얻을 수 있다. 안에는 어쩌면 이 세상의 진실이 담겨 있을지도 모른다.\n용도: [추억의 방] 속 물품 추억에 사용\n획득 방법: 프리즘을 소모하는 메인 스테이지 또는 자원 정비 스테이지 완료",
  str_item_3661205 = "벽걸이 쌍촛대",
  str_item_intro_3661205 = "가구, 콜로서스의 방에 배치할 수 있다.\n「어두운 밤에도 빛을 발해 사람들이 길을 찾을 수 있도록 해야 한다.」 이 촛대는 백야성의 특별한 루미나틱스를 가지고 있어 못에 걸지 않아도 스스로 벽에 붙으며, 촛불 또한 바람에 잘 꺼지지 않는다.",
  str_item_3661206 = "우아한 화병",
  str_item_intro_3661206 = "가구, 콜로서스의 방에 배치할 수 있다.\n백야성의 귀족들이 사용하던 거대한 화병이다. 우아한 형태로 유명하며, 화병 하나의 가격이면 평민들이 몇 년 동안 풍족한 삶을 누릴 수 있을 정도다. 그러나 상류층의 저택에서는 그저 흔히 보이는 장식에 불과하다.",
  str_item_3661035 = "화려한 드레스",
  str_item_intro_3661035 = "가구, 콜로서스의 방에 배치할 수 있다.\n이 드레스라면 에티켓이 가장 중요한 백야성에서도 예식, 축제, 무도회 등 어떤 성대한 행사에나 어울린다. 착용자가 뛰어난 외모와 너그러운 태도를 가지고 있다면, 모든 사람의 관심을 끌기에 충분하고, 사람들 사이에서 주목을 받게 될 것이다.",
  str_item_3661209 = "리조트 파라솔 의자",
  str_item_intro_3661209 = "가구, 콜로서스의 방에 배치할 수 있다.\n휴식과 자외선 차단을 모두 챙긴 리조트에 없어선 안 될 아이템. 두 가지 가구 중 하나라도 없으면 휴가철 느낌이 안 난다.",
  str_item_3661210 = "놀이공원 광고 벽",
  str_item_intro_3661210 = "가구, 콜로서스의 방에 배치할 수 있다.\n놀이동산마다 빠질 수 없는 물건이다. 거대한 크기에 눈에 띄는 다채로운 모양으로 「여기 좀 보고 가세요!」라 말하고 있는 듯하다.",
  str_item_3661211 = "휴가지의 아이스크림차",
  str_item_intro_3661211 = "가구, 콜로서스의 방에 배치할 수 있다.\n무더운 여름에 차가운 디저트를 제공하는 카트다. 놀이공원에서는 곳곳에 놓여있는 보급 지점이나 마찬가지다. 미련을 버리지 못하는 아이가 항상 주위에 맴돌곤 한다.",
  str_item_3661212 = "휴가지의 스프링 목마",
  str_item_intro_3661212 = "가구, 콜로서스의 방에 배치할 수 있다.\n아이들이 매우 좋아하는 놀이시설이다. 하단의 스프링은 탑승자에게 흔들리는 느낌을 주기 때문에 아이들이 여기저기서 비명을 지르고는 한다.",
  str_item_3661213 = "오아시스의 모터보트",
  str_item_intro_3661213 = "가구, 콜로서스의 방에 배치할 수 있다.\n생각지도 못했겠지만, 사막에서도 수상 경기를 치를 수 있다! 오아시스로부터 이어진 풍부한 물길 덕분에 모터보트가 버려지지 않고 힘을 발휘할 수 있기 때문이다.",
  str_item_3661214 = "사막 선인장 화분",
  str_item_intro_3661214 = "가구, 콜로서스의 방에 배치할 수 있다.\n사막에서 가장 흔하게 볼 수 있는 식물이다. 물이 없는 환경에 강하기 때문에 강인함의 상징으로 여겨지며, 화분에 옮겨 심어 집에 장식해 두기도 한다. 하지만 너무 자주 물을 준다면 선인장이 버티지 못할 수도 있다.",
  str_item_level_2905111 = "체인 존",
  str_item_10000100 = "물 계열 오로리안 선택상자",
  str_item_10000101 = "불 계열 오로리안 선택상자",
  str_item_10000102 = "숲 계열 오로리안 선택상자",
  str_item_10000103 = "번개 계열 오로리안 선택상자",
  str_item_intro_10000100 = "사용 시 특정 5성 오로리안 중 1명을 선택해 함께 모험을 진행할 수 있습니다.(<color=#ffffff>노아, 휴라드, 바튼, 클레이튼, 필리시, 와타리</color>)",
  str_item_intro_10000101 = "사용 시 특정 5성 오로리안 중 1명을 선택해 함께 모험을 진행할 수 있습니다.(<color=#ffffff>파우스트, 레지나, 베니&쿠로, 레오나, 이스타반, 마지, 바바라</color>)",
  str_item_intro_10000102 = "사용 시 특정 5성 오로리안 중 1명을 선택해 함께 모험을 진행할 수 있습니다.(<color=#ffffff>루이스, 로빈, 오디, 펙트, 아이리나, 스칼렛, 쿠스쿠타</color>)",
  str_item_intro_10000103 = "사용 시 특정 5성 오로리안 중 1명을 선택해 함께 모험을 진행할 수 있습니다.(<color=#ffffff>미아, 네메시스, 솔라드, 비비안, 키팅, 디나, 베벌리</color>)",
  str_item_3000327 = "플레이 코인",
  str_item_intro_3000327 = "토이 크레인 및 기타 게임 시설에서 사용되는 코인이다. 위에는 로렐라이가 웃는 모습이 새겨져 있으며, 마치 모든 손님들이 즐거운 시간을 보내기를 기원하는 듯하다.",
  str_item_3000328 = "데누오 패스 토큰",
  str_item_intro_3000328 = "데누오 리조트 내부에서 사용되는 화폐다. 품질과 색감이 좋으며, 다른 세력이 발행하는 화폐로 교환이 가능하다.\n경영 모드에서 건물 레벨업에 사용된다.",
  str_item_intro_3410627 = "구성: 노란색 중급 주문상자 15개, 노란색 초급 주문상자 25개, 2급 옥·번개 5개, 1급 옥·번개 8개, 35000 나이티움, 연합군 초급 주문상자 8개",
