  str_item_intro_3410643 = "구성: 빨간색 고급 주문상자 15개, 빨간색 중급 주문상자 25개, 2급 옥·불 30개, 1급 옥·불 7개, 121000 나이티움, 연합군 중급 주문상자 8개",
  str_item_intro_3410644 = "구성: 빨간색 특급 주문상자 15개, 빨간색 고급 주문상자 25개, 3급 옥·불 25개, 2급 옥·불 10개, 1급 옥·불 6개, 331000 나이티움, 연합군 고급 주문상자 8개",
  str_item_intro_3410645 = "구성: 노란색 중급 주문상자 15개, 노란색 초급 주문상자 25개, 2급 옥·번개 5개, 1급 옥·번개 8개, 35000 나이티움, 연합군 초급 주문상자 8개",
  str_item_intro_3410646 = "구성: 노란색 고급 주문상자 15개, 노란색 중급 주문상자 25개, 2급 옥·번개 30개, 1급 옥·번개 7개, 121000 나이티움, 연합군 중급 주문상자 8개",
  str_item_intro_3410647 = "구성: 노란색 특급 주문상자 15개, 노란색 고급 주문상자 25개, 3급 옥·번개 25개, 2급 옥·번개 10개, 1급 옥·번개 6개, 331000 나이티움, 연합군 고급 주문상자 8개",
  str_item_intro_3000900 = "부드러운 목화솜이다. 속을 채우는 데 사용하거나 화려한 장식품으로 만든다.",
  str_item_intro_3000901 = "아스트라 대륙에서 흔히 볼 수 있는 옷감이다. 튼튼하고 내구성이 좋으며, 염색이 쉽다.",
  str_item_intro_3000902 = "염색에 쓰이는 염료다. 사메야마가 보여준 것은 이 한 통뿐이지만, 사실 다른 색상의 염료도 많이 있다고 한다.",
  str_item_intro_3000903 = "의류 제작 시 많이 사용되는 단추다. 촉감이 차가워 아이들이 동전이라고 오해하기 쉽다.",
  str_item_intro_3000904 = "보기에는 평범한 실타래다. 이브가 순서를 어질러 놓을까 봐 사메야마가 검은색만 보여줬다고 한다.",
  str_item_7000100 = "찢어진 그림책",
  str_item_7000101 = "그림책 조각-의사",
  str_item_7000102 = "그림책 조각-빈 화분",
  str_item_7000103 = "진단서",
  str_item_7000104 = "홍차 찻잔",
  str_item_7000105 = "하얀 「개구리」",
  str_item_7000106 = "투박한 장난감",
  str_item_7000107 = "반성문",
  str_item_7000108 = "파손된 장부",
  str_item_7000109 = "연구원의 노트",
  str_item_7000110 = "귀여운 렌치",
  str_item_7000111 = "미니 머리띠",
  str_item_7000112 = "가이드 개구리",
  str_item_7000113 = "꽃씨",
  str_item_7000114 = "그림책 조각-새벽꽃",
  str_item_7000115 = "그림책 조각-렌치",
  str_item_7000116 = "그림책 조각-레디젤의 대장",
  str_item_7000117 = "그림책 조각-콜로서스",
  str_item_7000118 = "그림책 조각-흰개구리 왕자",
  str_item_7000119 = "완전한 그림책",
  str_item_intro_7000100 = "그림을 그릴 수 있는 책이다. 소녀와 세 사람이 즐거운 표정으로 함께 있는 모습이 그려져 있다. 하지만 이상하게도 얼굴 부분은 모두 찢겨서 사라졌다.",
  str_item_intro_7000101 = "찢어진 그림책에서 뜯긴 부분인 듯하다. 종잇조각에서 흰 가운을 입은 여자의 얼굴이 어렴풋이 보인다.",
  str_item_intro_7000102 = "빈 도자기 화분이 그려져 있는 종이다. 화분 안에는 흙이 반 정도 들어있다.",
  str_item_intro_7000103 = "조금 오래돼 보이는 종이다. 왠지 진단서처럼 보인다.",
  str_item_intro_7000104 = "정교하게 만들어진 홍차 찻잔이다. 가격이 꽤 나갈 것 같다.",
  str_item_intro_7000105 = "흰색의 작고 신기한 생물이다. 어디서 온 녀석인지는 아무도 모른다. 왠지 민들레를 좋아할 것만 같다.",
  str_item_intro_7000106 = "개성 있는 외모를 가진 장난감 인형이다. 센스는 평범하지만, 만듦새는 훌륭하다.",
  str_item_intro_7000107 = "삐뚤삐뚤한 글씨가 가득 쓰인 꾸깃꾸깃한 종이다. 악필이지만 그래도 작성자의 진심이 느껴진다.",
  str_item_intro_7000108 = "세월이 느껴지는 장부다. 원래 주인에겐 딱히 장부 쓰는 습관은 없었고, 오히려 자신의 천재적인 사고를 기록할 만한 매개체가 필요했던 것으로 보인다.",
  str_item_intro_7000109 = "세월이 느껴지는 노트다. 왠지 나이가 좀 있는 사람이 사용하던 것 같다.",
  str_item_intro_7000110 = "커다란 렌치다. 귀여운 스티커가 붙여져 있다.",
  str_item_intro_7000111 = "인형 정도 크기의 생물이 착용할 수 있을 정도로 작은 줄무늬 머리띠다.",
  str_item_intro_7000112 = "머리띠를 스카프처럼 두르고 있는 흰 개구리다. 더 멋있어 보인다.",
  str_item_intro_7000113 = "고독한 씨앗 하나가 마치 약속이라도 한 듯 한쪽 구석에서 발견되길 기다리고 있다.",
  str_item_intro_7000114 = "새벽을 맞이하는 꽃과 이름이 같은 소녀다. 꽃처럼 작고 찬란하다.",
  str_item_intro_7000115 = "거대한 렌치가 그려진 종이다. 이렇게나 큰 렌치는 분명히 아주 크고 멋진 사람의 소유일 것이다.",
  str_item_intro_7000116 = "풍파를 겪어도, 음모에 빠져도, 궁지에 몰려도 웃음을 잃지 않는 레디젤의 대장이다. 하지만 그 강철 같은 몸 안에도 자상한 마음이 있다.",
  str_item_intro_7000117 = "전설 속의 드래곤 형태를 한 콜로서스다. 귀여운 그림체를 통해 사람의 모습이 되었지만, 여전히 그 새하얀 날개를 볼 수 있다.",
  str_item_intro_7000118 = "바깥세상으로부터 온 백색의 사자.",
  str_item_intro_7000119 = "귀여운 그림이 그려진 그림책이다. 그림 속 사람들은 환하게 웃고 있다.",
  str_item_sub_intro_7000100 = "「즐거운 기억인데 여기저기 구멍이 나있네... 이때의 난 대체 누굴 그린 걸까?」",
  str_item_sub_intro_7000101 = "「의사 선생님의 얼굴을 찢어버리다니, 너무한 거 아니야? ...작은 동물이 물어뜯은 거였어? 그, 그러면 어쩔 수 없지, 뭐.」",
  str_item_sub_intro_7000102 = "「이브한테도 이런 도자기 화분이 있어! 그것도 아주 많이! 워낙 좋아해서 이만큼이나 수집해 버렸지 뭐야... 근데 왜 좋아했는지는 기억이 안 나.」",
  str_item_sub_intro_7000103 = "「공포, 분노, 고통... 네 몸과 마음을 해치던 부정적 요인을 모두 성공적으로 제거했어. 축하해, 이제 넌 건강한 아이가 됐어.」",
  str_item_sub_intro_7000104 = "「의사 선생님은 나 말고도 돌봐야 하는 환자가 있었어. 백야성에서 온 한 귀족 아가씨는 홍차를 좋아해서 가는 곳마다 찻잔을 들고 다녔는데... 그 아가씨도 지금쯤 완치됐겠지?」",
  str_item_sub_intro_7000105 = "「개구리가 뭐 어때서! 내가 개구리를 얼마나 좋아하는데... 응? 너 개구리가 아니라고?」",
  str_item_sub_intro_7000106 = "「사랑하는 ■■, 우리가 곁에 있어 주지 못할 때, 부디 이 작은 장난감이 네게 즐거움을 줄 수 있길...」",
  str_item_sub_intro_7000107 = "「앞으로 ■■ 앞에서는 험한 말을 하지 않는다. 잘 지키는지 모두가 서로 감시한다. 위반자는 핫소스를 생으로 18병 먹는다. 본인 포함 예외 없음.」",
  str_item_sub_intro_7000108 = "「그 강렬함에 충격을 받았다는 건 인정해야겠다. 나는 한때 ■■의 수준이 씨앗이 작용할 수 있는 한계치이며, ■■■■는 정신적인 측면을 돌파구로 삼아 씨앗이 인격에 미치는 영향을 찾아야 한다고 생각했다. 그러나 ■■■■의 원시적이고, 난폭하고, 상상을 뛰어넘는 강력함에 나는 매료될 수밖에 없었고, 씨앗이 이 정도의 효과를 낼 수 있음에 놀랐다. 오직 이런 강대한 힘만이 ■■■■의 요구에 부합했고, 나는 세상을 바꿀 수 있는 ■■의 힘이 절실히 필요했다.」",
  str_item_sub_intro_7000109 = "「현장에 도착했을 때 우리는 파멸적인 파괴의 흔적에 큰 충격을 받았다. 우리는 어떠한 개체가 거대한 에너지를 방출하여 지하에서부터 지표면까지의 모든 시설과 건물을 파괴했을 것이라 추측했다... 그게 대체 어떤 괴물일지 상상조차 되지 않는다...」",
  str_item_sub_intro_7000110 = "「어디서 봤던 것 같은데, 이 꽃 모양 스티커도... 내가 붙인 건가?」",
  str_item_sub_intro_7000111 = "「흰색 머리띠에... 검은색 줄무늬... 어디서 본 것 같은데...」",
  str_item_sub_intro_7000112 = "「나한테 하고 싶은 말이 있는 거야? 갈 길을 잃은 나한테 길을 알려 주려고?」",
  str_item_sub_intro_7000113 = "「내 세상에서 꽃을 가져가 버린다면, 내 마음도 더욱 깊은 심연에 빠지겠지...」",
  str_item_sub_intro_7000114 = "「크림슨 밸리로 돌아가서 그곳에 꽃을 가득 심고 싶어.」",
  str_item_sub_intro_7000115 = "「겨우 이런 그림 실력으로 이 렌치의 강함을 그려낼 수 있을까... 으, 대신 못 그렸다고 하는 사람은 이 렌치의 강함을 맛보게 되겠지...」",
  str_item_sub_intro_7000116 = "「오빠는 항상 날 찾아내 주었어!」",
  str_item_sub_intro_7000117 = "「맞혀보자, 이렇게나 예쁜 콜로서스를 조종하는 건 어떤 사람일까? ...내가 트래블러호를 놀렸다고? 아, 아니거든! 억울해!」",
  str_item_sub_intro_7000118 = "「살아남아. 우린 다시 만나게 될 거야.」",
  str_item_sub_intro_7000119 = "「진실된 세상, 그리고 진실된 행복.」",
  str_item_get_7000100 = "「꿈의 세계 - 망각과 소생의 날」에서 획득",
