  str_item_7000202 = "성적표",
  str_item_7000203 = "교편",
  str_item_7000204 = "판례(1)",
  str_item_7000205 = "비밀조사 보고서",
  str_item_7000206 = "판례(2)",
  str_item_intro_7000200 = "모양도 색깔도 모든 게 특이한 돋보기. 사건 조사에 있어 없어선 안 될 물건이다.\n",
  str_item_intro_7000201 = "금빛으로 빛나는 깃털펜. 손에 들면 무게감이 꽤나 느껴진다.\n",
  str_item_intro_7000202 = "전과목 최우수 성적을 받은 여명 아카데미 성적표다.\n",
  str_item_intro_7000203 = "모퉁이에 놓인 볼품없는 교편이다. 이리돈이 어린 시절의 기억을 떠올리게 만든다.\n",
  str_item_intro_7000204 = "「로델 노베쿠르」라는 심판관이 남긴 판례다. 판결 내용도 심판관 본인만큼 차갑고 냉정하다.\n",
  str_item_intro_7000205 = "이리돈의 아버지가 작성한 비밀조사 보고서다. 이리돈의 아버지는 유언장 사건의 재판 전부터 남작의 유언장이 다른 의도가 있다는 것을 이미 알고 있었다.\n",
  str_item_intro_7000206 = "「로델 노베쿠르」라는 심판관이 남긴 판례다. 그의 판결로 한 가문이 끝장나 버렸다.\n",
  str_item_sub_intro_7000200 = "「잘못 들은 걸까요... 방금 돋보기가 제 이름을 부른 것 같았는데요... 크흠, 그럴 리가 없겠죠. 근데 뭔가 낯이 익은데... 이거, 제 돋보기인가요? 이게 어떻게 된 걸까요... 이런 일조차 기억을 못 하다니...」",
  str_item_sub_intro_7000201 = "「왜 전 뭘 해도 사람들의 인정을 받지 못하는 걸까요... 아버님께도, 또래들에게도...」",
  str_item_sub_intro_7000202 = "「제가 정말 전력을 다하고 있지 않은 걸까요...」",
  str_item_sub_intro_7000203 = "「얼마나 노력해야... 어두웠던 어린 시절을 잊을 수 있을까요.」",
  str_item_sub_intro_7000204 = "「전 이 판결의 방향을 따라야 하는 걸까요...」",
  str_item_sub_intro_7000205 = "「제가 한 일은 대체...」",
  str_item_sub_intro_7000206 = "「제겐... 저만의 답이 있을 거예요.」",
  str_item_7000300 = "증거 획득",
  str_item_7000301 = "증언 획득",
  str_item_7000302 = "증거 획득",
  str_item_7000303 = "증언 획득",
  str_item_7000304 = "법조항 획득",
  str_item_7000305 = "법조항 획득",
  str_item_7000306 = "증거 획득",
  str_item_7000307 = "증거 획득",
  str_item_7000308 = "증언 획득",
  str_item_7000309 = "증언 획득",
  str_item_7000310 = "법조항 획득",
  str_item_7000311 = "법조항 획득",
  str_item_7000312 = "증거 획득",
  str_item_7000313 = "증거 획득",
  str_item_7000314 = "증언 획득",
  str_item_7000315 = "증언 획득",
  str_item_7000316 = "법조항 획득",
  str_item_7000317 = "법조항 획득",
  str_item_7000318 = "황금 저울추",
  str_item_7000319 = "황금 저울추",
  str_item_7000320 = "황금 저울추",
  str_item_intro_7000300 = "노틸리는 휘장을 가지고 있지 않았다.",
  str_item_intro_7000301 = "학생회원의 증언: 팜은 집안 사정이 어렵다.",
  str_item_intro_7000302 = "노틸리와 팜은 경쟁 관계다.",
  str_item_intro_7000303 = "문지기의 증언: 노틸리는 자습실에 간 적이 있다.",
  str_item_intro_7000304 = "재산침해죄",
  str_item_intro_7000305 = "공공질서방해죄",
  str_item_intro_7000306 = "검증 결과 팜의 할아버지의 유언장은 진짜다.",
  str_item_intro_7000307 = "팜의 할아버지가 자살에 쓴 칼에 제리의 지문이 묻어 있다.",
  str_item_intro_7000308 = "이웃의 증언: 팜의 할아버지는 손녀에게 모든 것을 물려주겠다고 했다.",
  str_item_intro_7000309 = "공증인의 증언: 팜의 할아버지가 유언장을 쓸 때는 아무 이상이 없었다.",
  str_item_intro_7000310 = "문서위조죄",
  str_item_intro_7000311 = "유산상속법",
  str_item_intro_7000312 = "고티에의 방에 있던 피로스 가문의 휘장",
  str_item_intro_7000313 = "밀렌 고티에의 스케치북에 쓰인 악담",
  str_item_intro_7000314 = "고티에 가문이 피로스 가문 사람을 잡아 실험에 사용했다.",
  str_item_intro_7000315 = "피로스 가문은 지금도 피의 수정에 대해 연구하고 있다.",
  str_item_intro_7000316 = "반역죄",
  str_item_intro_7000317 = "허위사실유포죄",
  str_item_intro_7000318 = "「여명 휘장 도난 사건」 증거 수집 성공!",
  str_item_intro_7000319 = "「팜의 할아버지의 유언장」 증거 수집 성공!",
  str_item_intro_7000320 = "「고티에 가문의 반란」 증거 수집 성공!",
  str_item_sub_intro_7000300 = "　사건에 대한 팜의 설명을 듣고 화가 난 노틸리는 팜에게 왜 자신을 모욕하는지 끈질기게 물었다. 자신의 결백을 증명하기 위해 노틸리는 자진해서 이리돈에게 몸수색을 요청했고, 노틸리에게서는 아무것도 발견되지 않았다.",
  str_item_sub_intro_7000301 = "　자습실로 가는 길, 한 학생회 멤버가 조심스레 이리돈을 불러세웠다. 그는 격앙된 채 이리돈에게 「팜의 가문은 원래 귀족이 아니고, 부모님도 제대로 된 공직에 나선 적도 없으며, 어떤 이유인지 돈이 급한 것 같다」고 말했다.",
  str_item_sub_intro_7000302 = "　이리돈은 아카데미의 게시판에서 신전으로부터 온 공고문을 보게 되었고, 그것은 신전에서 올해 팜과 노틸리 두 명의 견습 수녀 중 최종 선택되는 한 명만이 신전에 남을 수 있다는 내용이었다.",
  str_item_sub_intro_7000303 = "　자습실 근처에 온 이리돈은 나이가 지긋한 경비원이 졸고 있는 모습을 보게 되었다. 그는 이리돈이 아카데미에 있을 때 많은 도움을 줬던 사람이었고, 그 역시 이리돈을 기억하고 있었다. 경비원은 오늘 팜을 제외하고 자습실에 들어간 것은 노틸리 밖에 없었으며, 노틸리가 왜 손수건을 대고 문을 열었는지 의아했지만, 결벽증이 있는 것일지도 모른다며 당시에는 대수롭지 않게 생각했다고 말했다.",
  str_item_sub_intro_7000304 = "　타인의 재산을 훔치고 그 액수가 상당한 경우, 훔친 자는 3년 이상 10년 이하의 징역 및 벌금형에 처한다.",
  str_item_sub_intro_7000305 = "　공공연히 타인을 모욕하거나 고의로 비방한 정황이 심한 경우, 3년 이하의 징역 및 벌금형에 처한다.",
  str_item_sub_intro_7000306 = "　제리는 이리돈에게 자신의 유언장을 건냈고, 분석 결과 이 유언장은 팜의 할아버지가 쓴 것임이 확인되었다. 그 내용은 팜의 할아버지가 제리에게 작위와 재산을 물려주겠다는 것이었지만, 「나는 살 만큼 살았으니, 이제 후회는 없다」는 부분에 이리돈은 신경이 쓰였다. 마치 그는 유언장을 쓸 때 이미 삶을 끝내려는 뜻을 품은 것처럼 보였다.",
  str_item_sub_intro_7000307 = "　팜의 할아버지의 집에 온 이리돈은 그가 숨을 끊을 당시 사용했던 작은 과도를 발견했고, 과도를 자세히 검사한 결과 제리의 지문이 발견되었다. 그러나 제리는 평소에 자신이 식사를 준비하기 때문에, 식기에 지문이 묻는 것은 당연하다고 설명했다. 이리돈은 현장을 다시 조사하면서 팜의 할아버지가 스스로 목숨을 끊었음을 확인했다.",
  str_item_sub_intro_7000308 = "　이리돈은 팜의 할아버지의 이웃을 방문해 이야기를 들어보았다. 이웃에 따르면 그는 생전 아들을 탐탁지 않아 했지만, 손녀 자랑은 무척이나 자주 했다고 한다. 또 작위와 재산은 손녀에게 물려줄 것이고, 아들에게는 한 푼도 주지 않겠다고 말하고 다녔다고 한다.",
  str_item_sub_intro_7000309 = "　유언의 공증인은 학식이 있는 늙은 하인으로, 팜의 할아버지의 공증인을 맡게 되어 영광이라고 말했다. 그러나 이 말을 꺼낸 직후 하인은 뭔가 잘못 말하기라도 한 듯 어색하게 진술을 이어 나갔다. 그의 말에 따르면 유언장 작성 당시 팜의 할아버지에게는 그 어떤 이상한 조짐도 없었으며, 자신도 그의 의사를 여러 차례 확인했다고 한다.",
  str_item_sub_intro_7000310 = "　공문서 및 사문서를 위조하고, 사기 행위에 사용한 자는 3년 이상 10년 이하의 징역 및 벌금형에 처한다.",
  str_item_sub_intro_7000311 = "　유언장이 적법하고 유효하다고 판단되면, 그 내용에 의거해 재산을 분배해야 한다.",
  str_item_sub_intro_7000312 = "　이리돈은 고티에 가문이 유배된 다운타운의 주거지에 몰래 잠입했고, 집 한구석에서 피로스 가문의 휘장을 발견했다. 고티에 가문과 피로스 가문은 피의 수정 사건으로 인해 함께 다운타운에 유배되었다. 설마 두 가문이 반역을 꾀하기라도 했단 말인가. 이리돈은 도저히 생각을 이어갈 수 없었다. 「팜도 피로스 가문의 일원인데...」",
  str_item_sub_intro_7000313 = "　이리돈은 허름한 집을 또 하나 발견했고, 그 안에서 「밀렌 고티에」라고 쓰인 스케치북을 발견했다. 스케치북에는 난해한 추상적인 그림들이 그려져 있었는데, 눈을 가늘게 뜨고 보니 패턴과 패턴 사이에 한 줄의 숨겨진 글씨를 알아볼 수 있었다. 「다들 뭐 때문에 나한테... 대체 왜, 왜, 왜냐고! 난 반드시... 나만의 운명을 손에 쥐고 말겠어... 그들의 힘을 빌려서라도.」",
  str_item_sub_intro_7000314 = "　거리에 갑자기 이상한 형태의 암귀가 나타나자, 이리돈은 망설이지 않고 암귀의 가슴을 찔렀다. 그대로 쓰러진 암귀는 갑자기 정신을 차린 듯했고, 무슨 할 말이 있는 것처럼 사람들 쪽으로 손을 들었다. 암귀에게 다가간 이리돈은 그가 작게 내뱉는 말을 들을 수 있었다. 「고티에 가문이... 우리 피로스 가문에... 복수한... 거야... 우린... 놈들한테 잡혀서... 실험을 당했어... 놈들이... 반란을 일으킬 거야!」",
  str_item_sub_intro_7000315 = "　다음 수사 방향을 고민하던 이리돈의 앞에 남루한 옷차림의 행인이 조용히 다가왔다. 행인은 다운타운의 모든 동태를 파악했다면서, 최근 피로스 가문이 피의 수정 연구를 이어가고 있다고 폭로했다. 이리돈이 왜 자신에게 그런 말을 하냐고 묻자 행인은 입을 벌려 검은 이를 드러내며 말했다. 「절 미드가든으로 다시 데려가 주실 수 있겠습니까?」",
  str_item_sub_intro_7000316 = "　백야성의 통치 전복을 계획하거나 실행한 자는 종신형에 처하고, 심한 경우 사형에 처할 수 있다.",
  str_item_sub_intro_7000317 = "　고의로 타인의 유언비어를 퍼뜨린 자는 1년 이하의 징역 및 벌금형에 처한다.",
  str_item_sub_intro_7000318 = "　이리돈은 증거와 증언을 토대로 노틸리가 여명 휘장을 훔쳤다는 사실을 순조롭게 밝혀냈다.",
  str_item_sub_intro_7000319 = "　유언장이 유효하다고 판단되어, 하인 제리는 팜의 할아버지의 작위와 모든 재산을 상속받게 되었다...",
  str_item_sub_intro_7000320 = "　가장 완벽한 증거와 증언을 수집하여, 밀렌 고티에가 피로스 사람을 유괴하고 인체 실험과 역모를 도모했다는 사실이 확인되었다.",
  str_item_7000400 = "녹슨 열쇠",
  str_item_7000401 = "디나의 과자",
  str_item_7000402 = "새 집의 설계도",
  str_item_7000403 = "장엄한 트럼본",
  str_item_7000404 = "새 악보",
  str_item_7000405 = "디나 조각상",
  str_item_7000406 = "로빈 조각상",
  str_item_7000407 = "항아리 속의 여인 조각상",
  str_item_7000408 = "흰돌고래 조각상",
  str_item_intro_7000400 = "고모가 코놀리에게 준 다락방 열쇠다. 낡은 자물쇠 소리가 타인에게 피해를 주지 않도록 조심해서 사용해야 한다.\n",
  str_item_intro_7000401 = "코놀리가 디나를 위해 가져온 과자다. 결국 어인 경비병들이 가져가 버렸다. 디나의 요구대로 속에는 설탕을 넣지 않았다.\n",
  str_item_intro_7000402 = "물의 주인을 위해 세운 궁전의 설계도다. 물의 주인이 말한 것은 왠지 이게 아닌 것 같지만, 해석의 권한은 코놀리 여왕에게 있다.\n",
  str_item_intro_7000403 = "마을 주민들이 코놀리를 위해 찾아낸 새 악기다. 더 크고 힘 있는 소리가 나서 분노를 더 잘 표출할 수 있다.\n",
  str_item_intro_7000404 = "코놀리가 낡은 다락방에서 찾아낸 물의 악보다. 지금은 새로운 이름이 사인되어 있다.\n",
  str_item_intro_7000405 = "해저 마을의 예술가가 디나를 위해 만든 조각상이다. 현재는 코놀리 여왕이 연설 연습할 때 객석에 두는 용도로 쓰고 있다.\n",
  str_item_intro_7000406 = "해저 마을의 예술가가 로빈을 위해 만든 조각상이다. 현재는 코놀리 여왕이 연설 연습할 때 객석에 두는 용도로 쓰고 있다.\n",
  str_item_intro_7000407 = "해저 마을의 예술가가 한 정체불명의 고문을 위해 만든 조각상이다. 현재는 코놀리 여왕이 연설 연습할 때 객석에 두는 용도로 쓰고 있다.\n",
  str_item_intro_7000408 = "해저 마을의 예술가가 여왕의 잘생긴 물고기 친구를 위해 만든 조각상이다. 현재는 코놀리 여왕이 연설 연습할 때 객석에 두는 용도로 쓰고 있다.\n",
  str_item_sub_intro_7000400 = "“그녀는 다락방에서 자고 남들이 싫어하는 걸 먹어~ 말소리는 작고 먼 구석에 숨어 있지~ 낮엔 방 청소를 하고 밤엔 악기를 꺼내~ 음악으로 외로운 마음을 달래지~”",
  str_item_sub_intro_7000401 = "“내 과자! 그거 코놀리가 나한테 준 건데!...... 이런 댕댕이 녀석들 눈치도 없이 싹 다 먹어버렸네!”",
  str_item_sub_intro_7000402 = "“라하호환 해위 을움다름아... 한대위... 의계세이!”",
  str_item_sub_intro_7000403 = "“고통과 슬픔은...... 음악으로 구해질 거예요!”",
  str_item_sub_intro_7000404 = "“전에 저한테 새 이름을 지어달라고 했거든요. 그래서 잔뜩 생각해 봤어요... 루빈스타인, 살리에리, 레오폴트, 드보르자크... 다 좋아하시는 음악들인데... 네? 좀 더 다정한 이름이면 좋겠다고요?”",
  str_item_sub_intro_7000405 = "“뭐야, 내가 너무 날카롭다고? 손발 대신인데 안 날카로우면 어떡해?”",
  str_item_sub_intro_7000406 = "“음... 전에 어떤 물고기가 나더러 납작하고 존재감 없다고 말한 적 있긴 해... 하지만 그게 내 생존법인걸...”",
  str_item_sub_intro_7000407 = "“나와서 다시 그리라고? 참나, 그럼 돈을 내야지.”",
  str_item_sub_intro_7000408 = "“나랑 코놀리 여왕이 무슨 관계냐고? 후후! 그건 비밀이야~”",
  str_item_7000801 = "골동품",
  str_item_intro_7000801 = "쌍사성의 모퉁이 곳곳에서 발견된 골동품이다. 용주에서 생산된 문화재는 외국에서도 귀하게 여겨지며, 일부는 주문과 보수 지급을 통한 정당한 거래로 들여온 것이나, 일부는 어둠 속 도적들의 손을 통해 훔쳐 들여온 것이기도 하다.",
  str_item_6030101 = "작은 그림책",
  str_item_6030102 = "미소의 온도",
  str_item_6030103 = "이브의 여명",
  str_item_6030104 = "백야 신전",
  str_item_6030105 = "균형 유지",
  str_item_6030106 = "순수한 기도",
  str_item_6030107 = "물의 암호",
  str_item_6030108 = "사랑의 독주",
  str_item_6030109 = "화려한 집",
  str_item_6030110 = "자등나무의 꿈",
  str_item_6030111 = "꽃과 마검",
  str_item_6030112 = "꿈을 실은 조각배",
  str_item_6030113 = "그의 수호",
  str_item_6030114 = "그녀의 맹세",
  str_item_6030115 = "프리토리언의 검",
  str_item_6030116 = "달콤한 기관차",
  str_item_6030117 = "헌터스톤의 새 복장",
  str_item_6030118 = "크림의 숲",
  str_item_6030119 = "인식표",
  str_item_6030120 = "별의 빛",
  str_item_6030121 = "일루미나 깃발",
  str_item_6030122 = "나시리스의 그리움",
  str_item_6030123 = "네포리스의 염원",
  str_item_6030124 = "북쪽 나라의 거울",
  str_item_intro_6030101 = "동행 기념훈장.\n작은 그림책에 그려진 유치한 그림에서 애틋한 감정이 엿보인다.",
  str_item_intro_6030102 = "동행 기념훈장.\n종말이 다가올지라도, 그는 여동생을 위해 적절한 온도의 물을 준비해 줄 것이다.",
  str_item_intro_6030103 = "동행 기념훈장.\n어두운 세월 속에서 이 꽃은 그녀의 여명이었다.",
  str_item_intro_6030104 = "동행 기념훈장.\n백야성 신전의 인정이다.",
  str_item_intro_6030105 = "동행 기념훈장.\n그 어떤 기울어진 저울도 이리돈의 눈을 피할 순 없다.",
  str_item_intro_6030106 = "동행 기념훈장.\n당시의 파로마는 여전히 믿고 있었다...",
  str_item_intro_6030107 = "동행 기념훈장.\n이는 위대한 물의 주인께서 베푸시는 호의다! 세속의 존재는 어서 몸을 바쳐 은혜를 받아라!",
  str_item_intro_6030108 = "동행 기념훈장.\n이 연주에는 가족의 소망, 동료들의 친절, 그리고... 사랑과 용기가 있다.",
  str_item_intro_6030109 = "동행 기념훈장.\n그저 임시 거처를 찾으려 했을 뿐이었지만, 생각지도 못하게 멋진 거처를 만들게 되었다.",
  str_item_intro_6030110 = "동행 기념훈장.\n지금 이 순간 느껴지는 온기는 찬란한 아침 햇살일까, 아니면 날카로운 가시 너머에서 당신이 전하는 온기일까.",
  str_item_intro_6030111 = "동행 기념훈장.\n많은 사람들은 가시나무에도 꽃이 핀다는 사실을 모른다. 등꽃보다 작은 그 옅은 자색의 꽃은 마치 검객의 치맛자락 같다.",
  str_item_intro_6030112 = "동행 기념훈장.\n어느 날 그녀가 유유히 흐르는 골드리버를 지날 때면, 그녀는 꿈속에서 배를 탔던 것을 떠올리고, 다시 누군가와 함께 같은 배를 타게 되길 기대할 것이다.",
  str_item_intro_6030113 = "동행 기념훈장.\n「네가 있으니까, 이 세계에 지킬 가치가 있는 거야.」",
  str_item_intro_6030114 = "동행 기념훈장.\n「네가 있으니까, 이 세계를 지켰으면 좋겠어.」",
  str_item_intro_6030115 = "동행 기념훈장.\n프리토리언의 사랑을 받아 전례 없이 강한 힘을 얻었다. 어쩌면 그러한 덕분에 그녀는 또 다른 방식으로 그의 곁에 남을 수 있었던 것일지도 모른다...",
  str_item_intro_6030116 = "동행 기념훈장.\n떠날 때는 차갑고 무자비한 기계라고 생각했지만, 돌아왔을 때는 녀석의 달콤함을 깨달을 수 있었다.",
  str_item_intro_6030117 = "동행 기념훈장.\n어딜 가도 떨쳐버릴 수 없다면... 그냥 독특한 패션 아이템이라고 생각하자.",
  str_item_intro_6030118 = "동행 기념훈장.\n진한 크림이 흐르는 나무, 달콤한 열매가 맺힌 작은 꽃들... 기회가 또 있다면, 이곳에서 피크닉을 즐기고 싶다.",
  str_item_intro_6030119 = "동행 기념훈장.\n모든 인식표, 모든 생명, 모든 찬란한 영혼이 안식을 얻기를.",
  str_item_intro_6030120 = "동행 기념훈장.\n저들은 누구의 부모인가, 누구의 아이인가, 누구의 형제자매인가. 기념비에 새겨진 이름은 침묵하며 앞길을 비추고 있다.",
  str_item_intro_6030121 = "동행 기념훈장.\n나팔 소리가 울리고 깃발이 펄럭인다. 아스트라의 가장 헌신적인 방어군은 물러서는 법을 모르며, 어둠을 최전선 너머로 물리쳤다.",
  str_item_intro_6030122 = "동행 기념훈장.\n「언니랑 같이 있고 싶어...」",
  str_item_intro_6030123 = "동행 기념훈장.\n「동생이랑 함께 살아가고 싶어...」",
  str_item_intro_6030124 = "동행 기념훈장.\n그 거울은 수많은 붕괴의 순간을 기록했고, 때로는 다른 것들을 기억하기도 했다.",
  str_item_6130101 = "망각과 소생의 동행",
  str_item_6130102 = "동행의 거울",
  str_item_6130103 = "동행 연주판",
  str_item_6130104 = "동행의 그리운 꿈",
  str_item_6130105 = "동행의 사랑",
  str_item_6130106 = "동행의 귀로",
  str_item_6130107 = "동행하는 군인",
  str_item_6130108 = "동행의 거울",
  str_item_intro_6130101 = "동행 기념판.\n끝났다. 지나간 것은 지나간 대로, 집으로 돌아가자.",
  str_item_intro_6130102 = "동행 기념판.\n거울 속의 그대여, 함께 깨어나길.",
  str_item_intro_6130103 = "동행 기념판.\n「내 마음이 이토록 강했던 것도, 목소리가 이렇게 아름다운 것도 처음이야.」",
  str_item_intro_6130104 = "동행 기념판.\n매일 아침 눈을 뜨면 저주와 싸워야 하지만, 그녀의 꿈은 무척이나 밝다. 깨끗하고 활기찬 도시에서 희미한 아침 햇살을 맞이하는 것이 바로 그녀의 꿈이다.",
  str_item_intro_6130105 = "동행 기념판.\n천 년의 세월이 먼지처럼 사라져 버릴지라도, 내 마음은 변하지 않을 것이다.",
  str_item_intro_6130106 = "동행 기념판.\n「뿌우우── 덜컹덜컹──」 열차는 선로를 따라 밝은 꿈속을 달렸다. 크림의 숲, 꿀의 샘, 여행자의 발효된 아쉬움을 지나...",
  str_item_intro_6130107 = "동행 기념판.\n「나는 백 번의 단련으로 강철이 되고, 천 번의 담금질로 일루미나가 되리니, 수만 번의 연마도 이겨낼 것이다. 예리한 금속의 탄환은 용감히 나아가는 우리들의 원대한 소원을 감싸주고 있다.」",
  str_item_intro_6130108 = "동행 기념판.\n「그녀의 몸은 눈 속에 묻혀 있고, 그녀의 영혼은 거울 속에 갇혀 있다. 그녀의 얼굴은 져버린 꽃잎으로 덮여 있지만, 그녀의 사랑은 결코 시들지 않을 것이다.」",
  str_item_3001000 = "꿈의 파편",
  str_item_intro_3001000 = "진실과 거짓을 구분하기 어려운 이야기에서 획득한 조각, 현실의 흔적을 말해주고 있다. [꿈의 흔적]에서 아이템 보상으로 교환할 수 있다.",
  str_item_get_3001000 = "꿈의 세계 - 테마 상점 화폐 만료 전환",
  str_item_3001001 = "탈바꿈의 꽃술",
  str_item_intro_3001001 = "도전을 맞이하고 성장을 이룬 후 남은 기념품이다. [꿈의 세계] - [망각과 소생의 날] - [기억의 공방]에서 아이템 보상으로 교환할 수 있다.",
  str_item_get_3001001 = "[꿈의 세계]-[망각과 소생의 날] 스테이지",
  str_item_3001002 = "가라앉은 의식 조각",
  str_item_intro_3001002 = "도전을 맞이하고 성장을 이루는 과정에서 얻은 조각이다. [꿈의 세계] - [망각과 소생의 날] - [기억의 공방]에서 아이템 보상으로 교환할 수 있다.",
  str_item_get_3001002 = "[꿈의 세계]-[망각과 소생의 날] 스테이지",
  str_item_3001003 = "마음",
  str_item_intro_3001003 = "이브의 이성과 정신을 유지해 주는 요소다. 「꿈의 세계 - 망각과 소생의 날」 스테이지 도전에 사용할 수 있으며, 매일 14:00에 3개 회복된다(최대치일 경우 회복되지 않음).",
  str_item_get_3001003 = "시간에 따라 자동 회복",
  str_item_3001004 = "미소의 물",
  str_item_intro_3001004 = "이브가 애용하는 물컵이다. 일반적인 물이지만 이브에게 끝없는 힘을 가져다준다. 수집 시 「행복을 인도하는 미소」의 레벨을 높일 수 있다.",
  str_item_get_3001004 = "[꿈의 세계] 내 스테이지 [꿈] 난이도 3성 첫 클리어 시 획득",
  str_item_3001005 = "도량의 무게추",
  str_item_intro_3001005 = "진정한 자신을 찾았을 때 손에 넣은 저울추다. 인생이라는 저울을 측량할 때 사용한다. [꿈의 세계] - [금빛 물결 아래의 심판] - [심판 경매]에서 아이템 보상으로 교환할 수 있다.",
  str_item_get_3001005 = "[꿈의 세계] - [금빛 물결 아래의 심판] 스테이지",
  str_item_3001006 = "정의의 양초",
  str_item_intro_3001006 = "마음속 이상을 위해 정의를 추구하는 길에 남겨진 별빛 촛불이다. [꿈의 세계] - [금빛 물결 아래의 심판] - [심판 경매]에서 아이템 보상으로 교환할 수 있다.",
  str_item_get_3001006 = "[꿈의 세계] - [금빛 물결 아래의 심판] 스테이지",
  str_item_3001007 = "마음",
  str_item_intro_3001007 = "이성과 맑은 정신을 유지하는 요소. 탐색 시 소모되며, 시간이 지남에 따라 회복된다.",
  str_item_get_3001007 = "시간에 따라 자동 회복",
  str_item_3001008 = "정의의 빛",
  str_item_intro_3001008 = "이리돈이 자신의 힘으로 되찾은 정의의 빛이다. 누적 시 「진상의 초점」의 레벨을 높일 수 있다.",
  str_item_get_3001008 = "[꿈의 세계] 내 스테이지 [꿈] 난이도 3성 첫 클리어 시 획득",
  str_item_3001010 = "음색 소라",
  str_item_intro_3001010 = "음악이 울려 퍼지는 소라다. 안에는 오래된 악장의 일부가 기록돼 있다. [꿈의 세계] - [코놀리와 환상의 바다] - [언더워터 카페]에서 아이템 보상으로 교환할 수 있다.",
  str_item_get_3001010 = "꿈의 세계 - 코놀리와 환상의 바다 스테이지",
  str_item_3001011 = "맛있는 해초",
  str_item_intro_3001011 = "해저 구석에서 자라는 형광 조류다. 인기 심해 음료를 만드는 데 사용할 수 있다. [꿈의 세계] - [코놀리와 환상의 바다] - [언더워터 카페]에서 아이템 보상으로 교환할 수 있다.",
  str_item_get_3001011 = "꿈의 세계 - 코놀리와 환상의 바다 스테이지",
  str_item_3001012 = "마음",
  str_item_intro_3001012 = "이성과 맑은 정신을 유지하는 요소. 탐색 시 소모되며, 시간이 지남에 따라 회복된다.",
  str_item_get_3001012 = "꿈의 세계 - 코놀리와 환상의 바다 스테이지",
  str_item_3001013 = "계약 연구",
  str_item_intro_3001013 = "코놀리는 물의 주인이 말한 모든 것을 이해하기 위해 신비한 두족류의 생각을 자신과 연결했다. 누적 시 「물의 촉수」의 레벨을 높일 수 있다.",
  str_item_get_3001013 = "[꿈의 세계] 내 스테이지 [꿈] 난이도 3성 첫 클리어 시 획득",
  str_item_3001014 = "자등나무 비녀",
  str_item_intro_3001014 = "작지만 단단한 꽃으로 만든 비녀다. [꿈의 세계] - [주렴 너머의 꿈 ~검의 노래~] - [꽃길 상점]에서 아이템 보상으로 교환할 수 있다.",
  str_item_get_3001014 = "꿈의 세계 - 주렴 너머의 꿈 ~검의 노래~ 스테이지",
  str_item_3001015 = "고대 동전",
  str_item_intro_3001015 = "녹으로 얼룩진 동방의 고대 주화다. 역사가 흐르면서 이미 본래 지니고 있던 화폐의 기능을 잃어버렸다. [꿈의 세계] - [주렴 너머의 꿈 ~검의 노래~] - [꽃길 상점]에서 아이템 보상으로 교환할 수 있다.",
  str_item_get_3001015 = "꿈의 세계 - 주렴 너머의 꿈 ~검의 노래~ 스테이지",
  str_item_3001016 = "마음",
  str_item_intro_3001016 = "이성과 맑은 정신을 유지하는 요소. 탐색 시 소모되며, 시간이 지남에 따라 회복된다.",
  str_item_get_3001016 = "꿈의 세계 - 주렴 너머의 꿈 ~검의 노래~ 스테이지",
  str_item_3001017 = "논검의 일념",
  str_item_intro_3001017 = "모든 전투는 협객의 검술에 대한 시련이다. 끝없는 축적은 질적인 변화로 이어지기 마련이다. 누적 시 「검의 마음」의 레벨을 높일 수 있다.",
  str_item_get_3001017 = "[꿈의 세계] 내 스테이지 [꿈] 난이도 3성 첫 클리어 시 획득",
  str_item_3001018 = "운영 자금",
  str_item_intro_3001018 = "움브라톤 사람들이 흔히 쓰는 용어를 사용하자면, 자온상회는 처음에는 그저 「유령 상회」일 뿐이었다. 그러나 자금이 있는데도 사업을 하지 않는 것은 그 창립자의 스타일이 아니었다. 그러니 실제로 한번 뛰어들지 않을 이유가 없었다.",
  str_item_3001019 = "길운",
  str_item_intro_3001019 = "경영 과정에서 자금 유통을 통해 얻은 길한 기운이다. 풍수 레벨업에 사용하며, 악령 퇴치에 도움을 준다.",
  str_item_3001021 = "은백의 화환",
  str_item_intro_3001021 = "승리와 평화를 상징하는 올리브 가지 화환이다. [꿈의 세계] - [잠든 감시자의 천 년] - [된바람 시장]에서 아이템 보상으로 교환할 수 있다.",
  str_item_get_3001021 = "[꿈의 세계] - [잠든 감시자의 천 년] 스테이지",
  str_item_3001022 = "감시자의 주화",
  str_item_intro_3001022 = "노스윈드 군단의 개선을 기념하는 청동 기념주화다. [꿈의 세계] - [잠든 감시자의 천 년] - [된바람 시장]에서 아이템 보상으로 교환할 수 있다.",
  str_item_get_3001022 = "[꿈의 세계] - [잠든 감시자의 천 년] 스테이지",
  str_item_3001023 = "마음",
  str_item_intro_3001023 = "이성과 맑은 정신을 유지하는 요소. 탐색 시 소모되며, 시간이 지남에 따라 회복된다.",
  str_item_get_3001023 = "시간에 따라 자동 회복",
  str_item_3001024 = "향기로운 보리 이삭",
  str_item_intro_3001024 = "사람을 안심시키는 보리의 향기는 맹세 속 미래의 삶에 대한 기대이며, 이는 검 속의 영혼에게 떠나지 말 것을 끊임없이 상기시켜 준다. 누적 시 「검의 혼」의 레벨을 높일 수 있다.",
  str_item_3001025 = "신전의 파편",
  str_item_intro_3001025 = "성전의 한쪽 면이 무너지고, 아름답게 조각된 벽돌과 성전에 바치던 귀중한 기물들도 파편으로 변했다. 그러나 이 조각들이 모든 가치를 잃은 것은 아니었다.",
  str_item_3001026 = "팝핑 캔디",
  str_item_intro_3001026 = "「팝핑 캔디」라고 불리는 희귀 식물의 열매다. 꿈의 세계-기이한 미식 마을-미식 배달에서 아이템 보상으로 교환할 수 있다.",
  str_item_get_3001026 = "꿈의 세계-기이한 미식 마을 스테이지",
  str_item_3001027 = "크림 원목",
  str_item_intro_3001027 = "크림의 숲에서 자라는 튼튼한 나무를 가공해 만든 목재다. 꿈의 세계-기이한 미식 마을-미식 배달에서 아이템 보상으로 교환할 수 있다.",
  str_item_get_3001027 = "꿈의 세계-기이한 미식 마을 스테이지",
  str_item_3001028 = "마음",
  str_item_intro_3001028 = "이성과 맑은 정신을 유지하는 요소. 탐색 시 소모되며, 시간이 지남에 따라 회복된다.",
  str_item_get_3001028 = "시간에 따라 자동 회복",
  str_item_3001029 = "소중한 마음",
  str_item_intro_3001029 = "펙트의 솔직한 관심과 부름... 헌터스톤은 한 번도 감히 욕심을 부려본 적 없었다. 누적 시 「헌터스톤」의 레벨을 높일 수 있다.",
  str_item_3001030 = "정교한 식기",
  str_item_intro_3001030 = "장인의 손길로 만들어져 내려온 정교한 작품이다. 최고의 식재료를 더 매력적으로 만들어 준다.",
  str_item_3001031 = "계명성 훈장",
  str_item_intro_3001031 = "일루미나의 오래된 훈장이다. 이제 더는 수훈되지 않기에 그 의미는 매우 깊다. 훈장 자체는 그리 값어치가 있는 물건이 아니며, 오직 영웅의 영광스러운 사적을 통해 명예롭게 여겨져 값을 매길 수 없는 보물이 되는 것이다. 영웅들에게 주어지는 훈장은 그들이 받아 마땅한 무한한 감사 속 작은 선물일 뿐이다. [꿈의 세계] - [여명을 비추는 별의 밤] - [환상의 배급부]에서 아이템 보상으로 교환할 수 있다.",
  str_item_get_3001031 = "꿈의 세계 - 여명을 비추는 별의 밤 스테이지",
  str_item_3001032 = "일루미나 교환권",
  str_item_intro_3001032 = "일루미나 내에서 널리 쓰이는 교환권이다. 노동 및 복무 기간에 따라 상이한 포인트를 얻을 수 있으며, 이를 사용해 다양한 물자로 교환할 수 있다. [꿈의 세계] - [여명을 비추는 별의 밤] - [환상의 배급부]에서 아이템 보상으로 교환할 수 있다.",
  str_item_get_3001032 = "꿈의 세계 - 여명을 비추는 별의 밤 스테이지",
  str_item_3001033 = "마음",
  str_item_intro_3001033 = "이성과 맑은 정신을 유지하는 요소. 탐색 시 소모되며, 시간이 지남에 따라 회복된다.",
  str_item_get_3001033 = "시간에 따라 자동 회복",
  str_item_3001034 = "호각",
  str_item_intro_3001034 = "날카로운 호각 소리는 늘 군인들의 신경을 거슬리게 만든다. 하지만 그 소리가 없는 곳이 과연 더 안심할 수 있는 곳일까. 누적 시 「스핏저 탄두」의 레벨을 높일 수 있다.",
  str_item_3001035 = "워게임 모형",
  str_item_intro_3001035 = "워게임은 일루미나의 얼마 없는 오락 중 하나다. 그러나 여전히 전투의 특성을 유지하고 있다. 정교한 워게임 모형에는 제작자의 마음이 담겨 있다.",
  str_item_3001036 = "말린 꽃 책갈피",
  str_item_intro_3001036 = "소녀들이 책을 읽을 때 쓰곤 하는 수제 책갈피다. 꽃과 함께 그녀는 많은 우화집을 읽으며, 그 작게 흩어진 과거들을 증명하고자 했다. 꿈의 세계-거울 속 세계 · 눈 속의 소네트-이름 없는 시장에서 아이템 보상으로 교환할 수 있다.",
  str_item_get_3001036 = "꿈의 세계 - 거울 속 세계 · 눈 속의 소네트 스테이지",
  str_item_3001037 = "거울 조각",
  str_item_intro_3001037 = "이 조각들은 마법 거울의 힘을 지니고 있을 뿐만 아니라, 거울 속 세계의 기반을 담고 있다. 꿈의 세계-거울 속 세계 · 눈 속의 소네트-이름 없는 시장에서 아이템 보상으로 교환할 수 있다.",
  str_item_get_3001037 = "꿈의 세계 - 거울 속 세계 · 눈 속의 소네트 스테이지",
  str_item_3001038 = "마음",
  str_item_intro_3001038 = "이성과 맑은 정신을 유지하는 요소. 탐색 시 소모되며, 시간이 지남에 따라 회복된다.",
  str_item_get_3001038 = "시간에 따라 자동 회복",
  str_item_3001039 = "거울 속 세계의 꽃",
  str_item_intro_3001039 = "나시리스의 힘은 종종 꽃의 형태로 나타나며, 이는 영역의 그림자에서도 예외가 아니다.",
  str_item_3001040 = "북방 우화집",
  str_item_intro_3001040 = "나시리스는 자신의 기억을 되찾고 싶었고, 다른 이들에게 도움을 청하면서도 자신이 지니고 있는 단서를 결코 포기하지 않았다.",
  str_item_not_enough_plm = "피라칸타 꽃봉오리 아이템 부족",
  str_item_3751396 = "선글라스의 다크서클",
  str_item_3751397 = "더스크 타운의 수녀",
  str_item_3751551 = "신임 대원수의 고민",
  str_item_intro_3751396 = "부디 광명이 더스크 타운을 덮은 어둠을 몰아낼 수 있기를.",
  str_item_intro_3751397 = "다크서클? 아니거든?",
  str_item_intro_3751551 = "업무 보고 말고 다른 얘기 좀 하면 안 될까?",
  str_item_3000131 = "교향시 특별 소집 스타 마커",
  str_item_intro_3000131 = "[황혼의 교향시] 한정 소집에서 1회 소집을 진행할 수 있습니다.\n본 아이템은 기간 한정 아이템으로, [황혼의 교향시] 한정 소집 종료 전에 사용해야 합니다. 기간 만료 시 아이템은 사라지며, 다른 아이템으로 전환되지 않습니다.",
  str_item_10000992 = "클레이튼 조력 선택상자",
  str_item_intro_10000992 = "사용 시 오로리안 클레이튼을 당신의 모험에 합류시킬 수 있습니다.",
  str_item_1000099 = "클레이튼 조력 선택상자",
  str_item_intro_1000099 = "사용 시 오로리안 클레이튼을 당신의 모험에 합류시킬 수 있습니다.",
  str_item_3755023 = "얌전한 멍멍이 인형",
  str_item_3755024 = "개구리(?)",
  str_item_3755025 = "여명의 꽃",
  str_item_intro_3755023 = "획득 시 해당 아바타 개방.\n끼잉끼잉... 끼이이잉... 마음에 들어?",
  str_item_intro_3755024 = "획득 시 해당 아바타 개방.\n민들레야? 거기 서~",
  str_item_intro_3755025 = "획득 시 해당 프레임 개방.\n새벽을 상징하는 작고 하얀 꽃...",
  str_item_3661219 = "찬란한 결단의 기사 조각상",
  str_item_intro_3661219 = "가구, 콜로서스의 방에 배치할 수 있다.\n기사 시절의 이리돈을 모티브로 만든 조각상이다. 어느 소녀가 미처 주지 못한 선물인 듯하다.\n「이리돈 님, 지금까지 절 도와주시고 돌봐 주셔서 정말 감사해요. 부디 앞으로도 정의와 인애, 신념을 가지고 백야성을 더욱 밝은 미래로 이끌어 주시길 바랄게요.」",
  str_item_3661220 = "순수한 수녀 조각상",
  str_item_intro_3661220 = "가구, 콜로서스의 방에 배치할 수 있다.\n수녀 시절의 파로마를 모티브로 만든 조각상이다. 어느 아버지가 미처 주지 못한 선물인 듯하다.\n「팜, 네가 그 순수함과 선량함을 영원히 간직했으면 좋겠구나. 부디 우리 가족이 영원히 행복하고 즐겁기를...」",
  str_item_3751039 = "산처럼 견고한 의지",
  str_item_3751040 = "빛의 끝자락",
  str_item_3751041 = "유구한 승리의 노래",
  str_item_3751398 = "지식을 향한 갈망",
  str_item_3751399 = "수호의 힘",
  str_item_3751400 = "뭐라고요?",
  str_item_intro_3751039 = "획득 시 해당 아바타 개방.\n「드니에르, 라인하르트... 앞으로 무슨 일이 있더라도, 우린 모두 각자의 길을 찾을 수 있었으면 좋겠다.」",
  str_item_intro_3751040 = "획득 시 해당 아바타 개방.\n「난 누구와도 적이 될 생각은 없어. 그런 일에는 관심 없거든. 그저 저들이 내 앞길을 막아섰을 뿐이야.」",
  str_item_intro_3751041 = "획득 시 해당 아바타 개방.\n「누구라도 여명의 빛이 될 수 있다. 그건 너일 수도, 나일 수도 있지. 그저 오로리안들이 나아갈 수 있도록 짐을 짊어지면 되는 거다.」",
  str_item_intro_3751398 = "획득 시 해당 아바타 개방.\n「별이 빛나는 하늘은... 마치 세상의 모든 비밀을 모아 놓은 무한한 도서관 같아.」",
  str_item_intro_3751399 = "획득 시 해당 아바타 개방.\n「언젠간 나도 운명이 내게 준 이 힘을 제대로 다룰 수 있게 될 거야.」",
  str_item_intro_3751400 = "획득 시 해당 아바타 개방.\n「아?」",
  str_item_3751552 = "금기의 주제",
  str_item_intro_3751552 = "획득 시 해당 아바타 개방.\n「다시는 그런 썰렁한 농담하지 마!」",
  str_item_3751553 = "즐거운 트위티",
  str_item_intro_3751553 = "획득 시 해당 아바타 개방.\n「이제 곧 휴가가 시작될 거예요. 트위티는 휴가를 어떻게 보낼지 이미 생각해 두었답니다. 그녀의 계획은 과연 무엇일까요?」",
  str_item_3763034 = "따스한 선물",
  str_item_intro_3763034 = "획득 시 해당 프레임 개방.\n자리야는 당신이 북방의 날씨를 견디지 못할까 걱정이 돼서 자기 모자를 주었습니다.",
  str_item_3661215 = "사무용 테이블",
  str_item_intro_3661215 = "가구, 콜로서스의 방에 배치할 수 있다.\n세련된 원목 테이블이다. 일하는 동안 편안함을 느끼게 해 준다.",
  str_item_3661216 = "작은 티 테이블",
  str_item_intro_3661216 = "가구, 콜로서스의 방에 배치할 수 있다.\n목제 티 테이블이다. 상판의 일부는 대리석으로 만들어졌으며, 무척 정교해 보인다.",
  str_item_3661217 = "부엉이 사이드테이블",
  str_item_intro_3661217 = "가구, 콜로서스의 방에 배치할 수 있다.\n부엉이 한 마리가 작은 테이블 위에 서 있다. 마치 먼 곳을 응시하고 있는 것만 같다.",
  str_item_3661218 = "마법 빗자루",
  str_item_intro_3661218 = "가구, 콜로서스의 방에 배치할 수 있다.\n어떤 전설에서는 이것을 타고 날 수 있다고 한다. 과연 그 영감의 원천은 어디서 온 것일까?",
  str_item_5234055 = "보트 장식품",
  str_item_intro_5234055 = "밝은색의 배를 세워 장식품으로 만들었다. 이것을 보는 사람들이 먼 항해를 떠나고 싶은 충동을 주진 않을까?",
  str_item_3661052 = "부유하는 파이어플라이",
  str_item_intro_3661052 = "가구, 콜로서스의 방에 배치할 수 있다.\n떠 있기만 하고, 돌아다닐 수는 없다... 이걸로 뭘 해야 할까? 예를 들면... 뭔가 매달아 둔다거나? 아니면 난간으로 쓸 수 있으려나?",
  str_item_3000338 = "유적 파편",
  str_item_intro_3000338 = "아마 고대 유적에서 나온 파편일 것이다. 오랜 세월이 흘러 사방으로 흩어졌다. 만약 이것의 가치를 인정하는 사람이 있다면, 이를 얻기 위해 일정한 보수를 지급할 의향이 있을 것이다.",
  str_item_3751401 = "렉커의 농구",
  str_item_3751402 = "탁구 신인 바이스",
  str_item_3751403 = "프로게이머 그로누",
  str_item_3751404 = "사격의 제왕 카론",
  str_item_intro_3751401 = "획득 시 해당 아바타 개방.\n내 레이업 슛을 봐! 으앗, 왜 백보드에 맞고 튕겨 나온 거야?!",
  str_item_intro_3751402 = "획득 시 해당 아바타 개방.\n운동은 곧 생명! 비록 탁구는 신인이지만 그래도 난 최선을 다할 거야~",
  str_item_intro_3751403 = "획득 시 해당 아바타 개방.\n게임이라면 절대 누구한테도 꿀리지 않는다구~ e스포츠 종목에서 활약하는 내 멋진 모습을 잘 봐 둬!",
  str_item_intro_3751404 = "획득 시 해당 아바타 개방.\n나의 화려한 공연을 사격장에서도 선보여 주도록 하지!",
  str_item_3440011 = "빛의 보물상자",
  str_item_intro_3440011 = "나이티움*10000, 나이티움*5000, 2급 옥·공통*2, 1급 옥·공통*3, 영질*100, 영질*50 중에서 랜덤으로 한 가지를 획득한다.",
  str_item_3440012 = "계몽의 상자",
  str_item_intro_3440012 = "나이티움*5000, 나이티움*2000, 나이티움*1000, 2급 옥·공통*1, 1급 옥·공통*2, 영질*30 중에서 랜덤으로 한 가지를 획득한다.",
  str_item_3440013 = "심해 보물상자",
  str_item_intro_3440013 = "사용 시 다음 아이템 중에서 랜덤으로 1개 획득: 익명의 선물 패키지*1, 연합군 고급 주문상자*2, 나이티움*20000, 2급 옥·공통*4.",
  str_item_3440019 = "해령의 보물상자",
  str_item_intro_3440019 = "사용 시 다음 아이템 중에서 랜덤으로 1개 획득: 익명의 선물 패키지*1, 연합군 고급 주문상자*2, 나이티움*20000, 2급 옥·공통*4.",
  str_item_3755036 = "심판기사 이리돈",
  str_item_intro_3755036 = "획득 시 해당 아바타 개방.\n「그 어떤 작은 단서도 놓치지 않겠어요!」",
  str_item_3755037 = "팜의 요리",
  str_item_intro_3755037 = "획득 시 해당 아바타 개방.\n「보기엔 그저 그렇지만, 아주 맛있을 거라고 장담해요!」",
  str_item_6110001 = "동행의 훈풍 기념판",
  str_item_intro_6110001 = "동행 기념판.\n표면의 문양을 보고 있으면 바닷바람을 타고 멀리서 온 손님의 모습과, 은은한 비파 연주와 깃발이 펄럭이는 소리가 떠오른다...",
  str_item_3661221 = "기념열차 모형",
  str_item_intro_3661221 = "유명 배우 카론이 영화 시사회에 참가한 관객들에게 주는 선물이다. 카론의 파워풀한 연기처럼 웅장한 기관차의 형상은 관객들에게 깊은 인상을 남겼다.\n「이 감동을 깊이 새겨라!」",
  str_item_3000027 = "위시 티켓",
  str_item_3000028 = "위시 벌룬",
  str_item_intro_3000027 = "코스튬 투표 이벤트에서 좋아하는 오로리안에게 투표할 수 있다.\n「과연 이 마음이 잘 전해질 수 있을까요?」",
  str_item_intro_3000028 = "코스튬 투표 이벤트에서 마음에 드는 코스튬에 투표할 수 있다.\n「날아가지 않게 조심해서 상대방에게 잘 전해주세요~」",
  str_item_3661222 = "클라리넷 소녀 조각상",
  str_item_3661223 = "물의 여왕 조각상",
  str_item_intro_3661222 = "가구, 콜로서스의 방에 배치할 수 있다.\n카페의 특별한 주전자로 만들어졌으나, 주둥이의 디자인 때문에 좋은 평가는 받지 못했다.\n「제, 제 모습으로 이런 짓하지 마세요!」",
  str_item_intro_3661223 = "가구, 콜로서스의 방에 배치할 수 있다.\n정교한 여왕의 조각상이다. 무게를 줄이기 위해 속은 비어 있다. 누군가가 이런 디자인으로 해초 주스를 보관하는 용기를 만들자고 제안했지만, 여왕에게 거절당했다.\n「흑, 어째서... 왜 나만 항상 이런 일이...」",
  str_item_3661224 = "의료용 사물함",
  str_item_3661225 = "병상",
  str_item_3661226 = "카트",
  str_item_3661227 = "벤치 의자",
  str_item_intro_3661224 = "가구, 콜로서스의 방에 배치할 수 있다.\n각종 용기가 들어있는 목재 사물함이다. 부디 이 약물이 다른 이들의 고통을 줄일 수 있었으면...",
  str_item_intro_3661225 = "가구, 콜로서스의 방에 배치할 수 있다.\n환자들을 위한 병상이다. 몸이 불편하다면 여기에서 잠시 휴식을 취하자.",
  str_item_intro_3661226 = "가구, 콜로서스의 방에 배치할 수 있다.\n간이 의료용 카트다. 물품 적재량은 부족하지만, 그래도 매우 중요하다.",
  str_item_intro_3661227 = "가구, 콜로서스의 방에 배치할 수 있다.\n벤치 의자다. 옆에 있는 동료들과 대화를 나누면 초조한 기분을 달랠 수 있을지도 모른다.",
  str_item_5234056 = "평온한 정원",
  str_item_intro_5234056 = "바람 쐬며 휴식하기 좋은 공간이다. 고민이 있다면 이곳에 들려보자.",
  str_item_3000344 = "수납병",
  str_item_intro_3000344 = "얼마나 수집해야 끝이 날까...",
  str_item_3000345 = "플레이 티켓",
  str_item_intro_3000345 = "움브라톤 상회가 발부한 플레이 티켓이다. 외관은 평범하며, 「럭키박스」 대유행의 지정 화폐이다.",
  str_item_3661228 = "화로 게",
  str_item_3661229 = "복선 모형",
  str_item_intro_3661228 = "가구, 콜로서스의 방에 배치할 수 있다.\n흔히 용주의 장인이 정교한 물건을 만들 때 곁에서 돕는 기관수로, 선극이 직접 만든 것이다. 그러나 오랜 시간이 흘러 더는 본연의 기능을 발휘하지 못하게 되었다. 그래도 장식품으로 두는 것도 나쁘지 않을 것이다.",
  str_item_intro_3661229 = "가구, 콜로서스의 방에 배치할 수 있다.\n용주 사람들은 바다로 나가는 배에 많은 소원을 빌곤 한다. 예를 들어 배의 목재 이음매 사이에 동전과 청동 거울을 박아 달과 칠성의 형태를 만드는데, 이는 좋은 운수와 순조로운 항해를 의미한다. 비록 이 배는 선극이 만든 모형일 뿐이지만, 갖춰야 할 세세한 묘사와 정성은 결코 실물 못지않다.",
  str_item_3763035 = "치료 약물",
  str_item_intro_3763035 = "획득 시 해당 프레임 개방.\n걱정하지 마, 널 해치진 않을 테니까...",
  str_item_3751554 = "허약",
  str_item_intro_3751554 = "획득 시 해당 아바타 개방.\n「크흠... 나, 난 괜찮아. 조금 쉬면 나아질 거야.」",
  str_item_3751555 = "고마운 마음",
  str_item_intro_3751555 = "획득 시 해당 아바타 개방.\n「오늘은 내가 살게~」",
  str_item_3751405 = "의사의 신념",
  str_item_intro_3751405 = "획득 시 해당 아바타 개방.\n「앉아. 내가 좀 봐 줄 테니까.」",
  str_item_3751406 = "힘의 설득",
  str_item_intro_3751406 = "획득 시 해당 아바타 개방.\n「너한테 빚지고 안 갚는 녀석 있으면 나오라고 해!」",
  str_item_3751407 = "해저의 옛 물건들",
  str_item_intro_3751407 = "획득 시 해당 아바타 개방.\n깊은 바다에 묻혀 있는 보물이다. 마모로 인한 손상, 바닷물의 침식에 저항하며 육지로 돌아갈 그날만을 기다리고 있다.",
  str_item_3751408 = "선극의 초대",
  str_item_intro_3751408 = "획득 시 해당 아바타 개방.\n「아이테르가 믿는 이념이 우리 일족과 비슷하다고 들었어. 어때? 업나라에 와서 우리 일족이랑 교류해 볼래?」",
  str_item_3751556 = "구리 기물",
  str_item_intro_3751556 = "획득 시 해당 아바타 개방.\n「실제 기능은 없는 기관술 피조물일 뿐이야. 마음에 들면 다행이고.」",
  str_item_3751409 = "끝없는 금화",
  str_item_intro_3751409 = "획득 시 해당 아바타 개방.\n「비록 내 재산의 1%도 안 되지만, 거저 들어온 재물을 가지지 않을 이유는 없는걸.」",
  str_item_3751410 = "섀도우마스터의 휴식 시간",
  str_item_intro_3751410 = "획득 시 해당 아바타 개방.\n「곧 기념일이 다가오는군. 그럼 조금 쉬어보도록 할까.」",
  str_item_3751557 = "체크메이트",
  str_item_intro_3751557 = "획득 시 해당 아바타 개방.\n「망설이지 말고, 절묘한 수로 승리를 거두어야 한다.」",
  str_item_3751558 = "행운의 금화",
  str_item_intro_3751558 = "획득 시 해당 아바타 개방.\n「새해엔 반드시 행운이 찾아올 당신에게 이 행운의 금화를 드립니다.」",
  str_item_3763036 = "안개의 뱀",
  str_item_intro_3763036 = "획득 시 해당 프레임 개방.\n휘감고 있는 안개의 뱀이 모든 것을 집어삼킨다.",
  str_item_3751411 = "티타임",
  str_item_intro_3751411 = "획득 시 해당 아바타 개방.\n「3시가 되었구나, 차를 마시겠느냐.」",
  str_item_3751559 = "흐드러진 산벚꽃",
  str_item_intro_3751559 = "획득 시 해당 아바타 개방.\n「어쩌면 어느 산에 일찍 흐드러진 벚꽃의 색채가 히이로의 얼굴을 낯선 빛깔로 물들인 것일지도 모릅니다.」",
  str_item_3751560 = "괴짜의 행복 피자",
  str_item_intro_3751560 = "획득 시 해당 아바타 개방.\n「날 만족시키는 건 음식이 아니라 지혜야.」",
  str_item_3751412 = "지혜의 사령관",
  str_item_intro_3751412 = "획득 시 해당 아바타 개방.\n「오로리안의 적은 오로리안이야.」",
  str_item_3763037 = "벚꽃의 선물",
  str_item_intro_3763037 = "획득 시 해당 프레임 개방.\n벚꽃 일족의 혈통은 일족을 대신해 묵묵히 히이로를 지켜주고 있습니다.",
  str_item_3751561 = "호랑이 테테",
  str_item_3751562 = "순한맛",
  str_item_3751563 = "약간 매운맛",
  str_item_3751564 = "중간 매운맛",
  str_item_3751565 = "아스트랄 매운맛",
  str_item_intro_3751561 = "획득 시 해당 아바타 개방.\n「이렇게 귀엽고 맛있는 힘을 가진 호랑이라니, 누구라도 안아주고 싶어질 거예요~」",
  str_item_intro_3751562 = "획득 시 해당 아바타 개방.\n「레디젤 렌치 사람들에게 이런 매운 정도는 아무것도 아니다.」",
  str_item_intro_3751563 = "획득 시 해당 아바타 개방.\n「업나라 사람들은 약간 매운맛을 좋아한다. 비록 마귀의 매운맛은 단당에게 조금은 과할지도 모르지만, 요리 솜씨가 뛰어난 그녀는 이 맛의 매력을 이해할 수 있을 것이다.」",
  str_item_intro_3751564 = "획득 시 해당 아바타 개방.\n「‘식사는 우아하게!’ 카렌은 입안의 자극 때문에 백야성 기사의 테이블 매너를 잃는 일은 없어야 한다고 거듭해서 자신을 타일렀다.」",
  str_item_intro_3751565 = "획득 시 해당 아바타 개방.\n「“아아아아~ 아스트랄 매운맛!” 이것은 팔가조가 칠리 소스를 먹은 후 한참 뒤에 내뱉은 첫 번째 말이었다.」",
  str_item_9997004 = "구급 붕대",
  str_item_9997005 = "은월 방패",
  str_item_9997008 = "치유의 조각상",
  str_item_9997009 = "저주의 돌",
  str_item_9997010 = "죽음의 편지",
  str_item_9997011 = "광전사의 갑옷",
  str_item_9997012 = "태양의 영광",
  str_item_9997013 = "뇌격자",
  str_item_9997014 = "만색 보석",
  str_item_9997015 = "빛의 대검",
  str_item_9997016 = "은월 사냥칼",
  str_item_9997017 = "은월 장궁",
  str_item_9997018 = "날카로운 단검",
  str_item_9997019 = "글레어 고글",
  str_item_9997020 = "편광 페인트",
  str_item_9997021 = "떨어지는 벚꽃",
  str_item_9997023 = "와해의 가면",
  str_item_9997024 = "심판의 손",
  str_item_9997025 = "적멸의 여신상",
  str_item_9997026 = "에너지 벨트",
  str_item_9997027 = "루미나 실드",
  str_item_9997028 = "사신의 응시",
  str_item_9997029 = "연계의 호부",
  str_item_9997030 = "인연 조각상",
  str_item_9997031 = "잠재력의 팬던트",
  str_item_9997033 = "이동식 에너지 장치",
  str_item_9997035 = "소울 커터",
  str_item_9997003 = "치료 양초",
  str_item_9997006 = "경건함의 증명",
  str_item_9997007 = "태양의 방패",
  str_item_9997032 = "공명 배지",
  str_item_9997022 = "접이식 침낭",
  str_item_9997036 = "고대 학자의 노트",
  str_item_9997037 = "역병 유작",
  str_item_9997038 = "버려진 칼날",
  str_item_9997034 = "폭렬 슈즈",
  str_item_9997039 = "행운 코인",
  str_item_9997040 = "쌍성란",
  str_item_9997041 = "빙원 플로터",
  str_item_9997042 = "태양 플로터",
  str_item_9997043 = "나무 플로터",
  str_item_9997044 = "천둥 플로터",
  str_item_9997045 = "여명의 접시",
  str_item_9997046 = "분해 수정",
  str_item_9997047 = "루미나 마법상자",
  str_item_intro_9997004 = "전투 시작 시 전장에 붕대 1개 소환",
  str_item_intro_9997005 = "전투 시작 시 최대 HP의 20%에 해당하는 실드 획득, 2턴간 지속",
  str_item_intro_9997008 = "전투 시작 시 현재 HP가 30% 미만일 시 30%까지 회복",
  str_item_intro_9997009 = "턴이 시작될 때마다 현재 HP의 7%를 잃고 주변 2서클 범위 내 적에게 파티 평균 공격력 150%의 피해를 입힘",
  str_item_intro_9997010 = "오로리안의 액티브 스킬 피해 50% 증가, 액티브 스킬을 시전할 때마다 현재 HP의 8% 감소",
  str_item_intro_9997011 = "아군의 감소한 HP 퍼센트에 따라 연쇄 스킬 피해 증가, 최대 40%",
  str_item_intro_9997012 = "현재 HP가 70% 이상일 시 오로리안이 입히는 피해가 20% 증가",
  str_item_intro_9997013 = "오로리안이 동시에 3명 이상의 적 공격 시 낙뢰를 시전해 모든 적을 공격, 파티 평균 공격력 100%의 피해를 입힘",
  str_item_intro_9997014 = "턴이 시작될 때마다 필드에 랜덤으로 만색 칸 1개가 생성됨",
  str_item_intro_9997015 = "한번의 터치로 최소 15칸을 없애면 오로리안 연쇄 스킬 피해가 30% 증가한다. 없앤 칸이 8개 미만이면 연쇄 스킬을 시전할 수 없다.",
  str_item_intro_9997016 = "적과 가까울수록 오로리안의 연쇄 스킬 피해가 증가함, 최대 20%",
  str_item_intro_9997017 = "적과 멀수록 오로리안의 연쇄 스킬 피해가 증가함, 최대 30%",
  str_item_intro_9997018 = "버스터 클래스 오로리안이 30% 확률로 연쇄 스킬 1회 추가 발동",
  str_item_intro_9997019 = "스나이퍼 클래스 오로리안의 연쇄 스킬 대상 +1",
  str_item_intro_9997020 = "서포터 클래스 오로리안의 전투 중 연쇄 스킬 및 액티브 스킬의 회복 효과 25% 증가",
  str_item_intro_9997021 = "전투 시작 시 체인저 클래스 오로리안의 액티브 스킬 쿨다운 턴 수 1 감소",
  str_item_intro_9997023 = "오로리안이 액티브 스킬 또는 연쇄 스킬을 시전해 피해를 입힐 시 30% 확률로 대상의 중독/작열/출혈 효과를 즉시 1회 결산",
  str_item_intro_9997024 = "적이 이상 상태 또는 디버프 효과 상태일 시 받는 모든 피해 20% 증가",
  str_item_intro_9997025 = "죽음의 숨결을 소환해 HP 7% 이하의 적을 즉사시킴",
  str_item_intro_9997026 = "터치해 제거 후 이번 턴에 오로리안이 연쇄 스킬을 시전하지 않을 시 모든 오로리안의 액티브 스킬 쿨다운 턴 수 1 감소",
  str_item_intro_9997027 = "오로리안의 초과 치유량이 비율에 따라 1턴간 지속되는 실드로 전환됨",
  str_item_intro_9997028 = "중독/작열/출혈 효과를 보유 중인 적 사망 시 랜덤으로 필드 내 다른 적에게 중독 효과 1단계 부여",
  str_item_intro_9997029 = "진영 지원 스킬 발동에 필요한 칸 제거 수량 5개 감소",
  str_item_intro_9997030 = "오로리안이 액티브 스킬 시전 시 인연 관계인 오로리안의 액티브 스킬 쿨다운 턴 수 1 감소",
  str_item_intro_9997031 = "전투 시작 시 첫 번째로 시전한 액티브 스킬의 쿨다운 턴 수 2 감소",
  str_item_intro_9997033 = "턴이 시작될 때마다 전장 랜덤 위치에 표식 1개 생성, 표식 제거 후 이번 턴 동안 연쇄 스킬 피해 25% 증가",
  str_item_intro_9997035 = "오로리안이 피해를 입힐 시 2%의 흡혈 획득, 턴이 시작될 때마다 현재 HP의 15%를 잃음",
  str_item_intro_9997003 = "전투 승리 후 최대 HP 10% 회복",
  str_item_intro_9997006 = "전투 승리 후 모든 오로리안의 최대 HP 3% 증가",
  str_item_intro_9997007 = "전투 승리 후 모든 오로리안의 방어력 1.5% 증가",
  str_item_intro_9997032 = "전투 승리 후 모든 오로리안의 공격력 1% 증가",
  str_item_intro_9997022 = "획득 시 총 턴 수 +10 ",
  str_item_intro_9997036 = "터치해 칸 제거 시 25% 확률로 제거 횟수 1회 증가",
  str_item_intro_9997037 = "터치해 칸 제거 시 제거 범위 내 적에게 랜덤으로 중독/출혈/작열 효과 1단계 부여",
  str_item_intro_9997038 = "터치해 칸 제거 시 제거 범위 내 적에게 파티 평균 공격력 120%의 피해를 입힘",
  str_item_intro_9997034 = "적이 이번 턴에 터치해 제거한 구역을 1칸 이동할 때마다 파티 평균 공격력 150%의 피해를 입음",
  str_item_intro_9997039 = "전투 시작 시 랜덤으로 아이테르 특수 장비 1종의 사용 횟수 1회 획득",
  str_item_intro_9997040 = "아이테르 특수 장비 획득: 칸 2개를 선택해 만색 칸으로 전환, 칸을 60개 제거할 때마다 사용 횟수 1회 획득",
  str_item_intro_9997041 = "아이테르 특수 장비 획득: 선택한 3*3 범위 내 물 속성 칸 제거, 칸을 50개 제거할 때마다 사용 횟수 1회 획득",
  str_item_intro_9997042 = "아이테르 특수 장비 획득: 선택한 3*3 범위 내 불 속성 칸 제거, 칸을 50개 제거할 때마다 사용 횟수 1회 획득",
  str_item_intro_9997043 = "아이테르 특수 장비 획득: 선택한 3*3 범위 내 숲 속성 칸 제거, 칸을 50개 제거할 때마다 사용 횟수 1회 획득",
  str_item_intro_9997044 = "아이테르 특수 장비 획득: 선택한 3*3 범위 내 번개 속성 칸 제거, 칸을 50개 제거할 때마다 사용 횟수 1회 획득",
  str_item_intro_9997045 = "아이테르 특수 장비 획득: 전체 칸 초기화, 칸을 80개 제거할 때마다 사용 횟수 1회 획득",
  str_item_intro_9997046 = "아이테르 특수 장비 획득: 한 가지 속성을 선택해 모든 해당 속성 칸 초기화, 칸을 80개 제거할 때마다 사용 횟수 1회 획득",
  str_item_intro_9997047 = "아이테르 특수 장비 획득: 1칸을 선택해 가장 가까운 같은 속성의 칸 4개 제거, 칸을 60개 제거할 때마다 사용 횟수 1회 획득",
  str_item_rpintro_9997004 = "회복 물약의 보조품. 전투원의 부상 회복을 돕는다.",
  str_item_rpintro_9997005 = "옛 병사가 사용한 고전적인 무기다. 과거의 축복이 걸려 있어 재빠른 적을 상대할 때 괜찮은 효과를 발휘한다.",
  str_item_rpintro_9997008 = "온전히 보존된 조각상. 착용자에게 치유의 힘을 제공한다.",
  str_item_rpintro_9997009 = "구시대의 산물이다. 사용자를 저주하고 그에 상응하는 힘을 준다.",
  str_item_rpintro_9997010 = "지난날의 파괴적인 전쟁에서 나타난 신비한 물건이라고 한다. 강력한 저주의 힘을 지니고 있으며, 상대에게 중상을 입힐 수 있다.",
  str_item_rpintro_9997011 = "그것을 입으면 당신의 아픔이 곧 힘이 되어 당신을 승리로 이끌 것이다.",
  str_item_rpintro_9997012 = "그녀와 함께라면 승리의 여신의 비호를 받아, 전투에서 불리해지지 않을 것이다.",
  str_item_rpintro_9997013 = "구시대의 명검. 번개의 힘이 봉인되어 있으며, 뽑기만 하면 순식간에 폭발하여 적을 소멸시킨다.",
  str_item_rpintro_9997014 = "모든 색깔이 모여 있는 보석. 찬란하게 변하는 색을 지녔다.",
  str_item_rpintro_9997015 = "구시대의 대검이다. 그것을 움켜쥐면 몸 안에 힘이 넘침을 느낄 수 있다.",
  str_item_rpintro_9997016 = "옛 병사가 사용한 고전적인 무기다. 과거의 축복이 걸려 있어 재빠른 적을 상대할 때 괜찮은 효과를 발휘한다.",
  str_item_rpintro_9997017 = "옛 병사가 사용한 고전적인 무기다. 과거의 축복이 걸려 있어 재빠른 적을 상대할 때 괜찮은 효과를 발휘한다.",
  str_item_rpintro_9997018 = "오래된 단검. 구시대의 고강도 합금을 사용하여, 굉장히 날카롭다.",
  str_item_rpintro_9997019 = "전투 중 렌즈에서 눈부신 빛을 발산하여, 상대의 눈을 멀게 할 수 있다. 또한 착용자가 그 빛에 면역이 되도록 보호하는 보조 장비.",
  str_item_rpintro_9997020 = "구시대의 페인트. 루미나를 잘 흡수할 수 있다.",
  str_item_rpintro_9997021 = "구시대의 산물. 아름다워 보이지만 무서운 힘을 지녀, 적을 떨어지는 꽃처럼 폭발 속에서 죽게 한다.",
  str_item_rpintro_9997023 = "구시대의 유물. 강렬한 저주가 걸려 있어서, 이것을 쓴 자가 독을 사용하면 치명상을 입힐 수 있다.",
  str_item_rpintro_9997024 = "구시대의 명검. 사용자는 신에 필적하는 힘을 느낄 수 있다.",
  str_item_rpintro_9997025 = "이 작은 조각상은 적의 생명의 숨결을 느낄 수 있어서, 위태로운 상태의 남은 적을 순식간에 죽인다.",
  str_item_rpintro_9997026 = "몸에 꼭 맞는 벨트다. 작동 조건에 맞으면 착용자에게 필요한 루미나를 제공한다.",
  str_item_rpintro_9997027 = "구시대의 신비한 장치. 흘러넘치는 루미나를 감지하여, 착용자를 보호하는 역장으로 전환시킨다.",
  str_item_rpintro_9997028 = "강력한 전사가 직접 만들었다는 저주받은 물건. 적에게 벗어날 수 없는 죽음의 운명을 내린다.",
  str_item_rpintro_9997029 = "구시대의 수호 부적. 미시적인 차원에서 루미나를 연결시켜, 전투에서 적에게 큰 피해를 입힐 수 있다.",
  str_item_rpintro_9997030 = "구시대의 산물이다. 인연 오로리안이 일정한 루미나를 회복하도록 해준다.",
  str_item_rpintro_9997031 = "구시대의 산물이다. 사용 시 잃은 루미나의 일부를 빠르게 보충할 수 있다.",
  str_item_rpintro_9997033 = "루미나 저장에 쓰이는 장치. 방출한 후 잃은 루미나를 보충할 수 있다.",
  str_item_rpintro_9997035 = "사악한 기운을 풍기는 참도. 고대의 치열한 전투에 많이 쓰였던 무기로 보이며, 한번 뽑으면 반드시 피를 봐야 한다.",
  str_item_rpintro_9997003 = "따스한 빛을 발산하는 양초. 그 빛에는 오로리안의 상처를 치유하는 힘이 있다.",
  str_item_rpintro_9997006 = "구시대에서 남겨진 작은 조각상. 고강도 재료로 만들어져서 견고하면서도 가벼우며, 지닌 사람에게 축복을 내린다.",
  str_item_rpintro_9997007 = "구시대의 낡은 방패... 완벽한 원형이다. 태양의 힘이 주입되었다고 하며, 루미나의 힘으로 모든 치명적인 공격을 막아 준다.",
  str_item_rpintro_9997032 = "구시대의 배지. 신비한 구조를 갖고 있어, 미시적인 차원에서 루미나를 연결시켜 전투력을 증가시킨다.",
  str_item_rpintro_9997022 = "과거에 어떤 사람이 남긴 접이식 침낭. 체력을 잘 회복할 수 있다.",
  str_item_rpintro_9997036 = "고대의 학자가 쓴 노트로 보인다. 상성 간의 기묘한 관계가 적혀 있으며, 전투원에게 상성에 맞춰 전투하는 방법을 알려줄 수 있다.",
  str_item_rpintro_9997037 = "오래 전에 무명 작가가 그린 오래된 그림. 역병이 유행하던 당시의 참상을 그렸다. 작가도 그 역병에 걸려 죽고 난 후, 그림에 무서운 힘이 생겼다.",
  str_item_rpintro_9997038 = "루미나를 완벽하게 융합할 수 있을 것 같아 보이는 매우 보기 드문 무기다.",
  str_item_rpintro_9997034 = "구시대의 산물. 주로 추격병을 상대하는 용도로 사용된다. 안에 담긴 루미나의 힘이 지나가는 경로에 남아, 일정 시간 후 폭발하여 추격하는 적을 살상한다.",
  str_item_rpintro_9997039 = "오래되고 신비한 코인. 이것을 가진 오로리안은 힘이 증가하며, 행동이 더욱 민첩해진다.",
  str_item_rpintro_9997040 = "이렇게 희귀한 빨간색 난초는 구시대에 특수 재배된 산물로, 반드시 짝을 이뤄 나타났다가 피고 진다. 이것을 가진 자는 신비한 링크를 얻어, 협동 작전을 더 잘하게 된다.",
  str_item_rpintro_9997041 = "구시대의 산물이다. 여러모로 콜로서스의 축소판으로 보이며, 전투에서 주인의 작전을 돕는다.",
  str_item_rpintro_9997042 = "구시대의 산물이다. 여러모로 콜로서스의 축소판으로 보이며, 전투에서 주인의 작전을 돕는다.",
  str_item_rpintro_9997043 = "구시대의 산물이다. 여러모로 콜로서스의 축소판으로 보이며, 전투에서 주인의 작전을 돕는다.",
  str_item_rpintro_9997044 = "구시대의 산물이다. 여러모로 콜로서스의 축소판으로 보이며, 전투에서 주인의 작전을 돕는다.",
  str_item_rpintro_9997045 = "구시대의 산물. 두 명의 전투자 간에 신비한 연결 작용을 한다.",
  str_item_rpintro_9997046 = "표면에 미세한 균열이 있는 거친 수정. 이것은 그 안에 과다한 루미나가 있음을 보여 준다. 살짝 만지기만 해도 방출되며, 전투에서 적을 기절시키기에 충분하다.",
  str_item_rpintro_9997047 = "구시대의 기술. 자그마한 상자에 불과하지만, 많은 루미나를 저장할 수 있다.",
  str_item_3000349 = "공중상회 토큰",
  str_item_intro_3000349 = "공중상회에서 제공하는 혜택 토큰이다. 오랜 고객에게만 얻을 기회가 주어진다.",
  str_item_3000134 = "탐욕의 뱀 특별 소집 스타 마커",
  str_item_intro_3000134 = "[탐욕의 뱀] 한정 소집에서 1회 소집을 진행할 수 있습니다.\n본 아이템은 기간 한정 아이템으로, [탐욕의 뱀] 한정 소집 종료 전에 사용해야 합니다. 기간 만료 시 아이템은 사라지며, 다른 아이템으로 전환되지 않습니다.",
  str_item_3420133 = "2.5주년 특선 소집상자",
  str_item_intro_3420133 = "지정 6성 오로리안 명단 중 1명을 선택해 함께 싸울 수 있습니다. 선택 범위: <color=#ffffff>단당/자리야/안토니/로렐라이/세나/조슈아/솔라드 디 올마이티 클레머/잉겔/레오/하티/티나/레인/예리아/목월백/종서/비크/악셀리아/리리카/미노스/폴룩스/제노/피아/카렌 더 스몰더링 소울/니나/바튼 더 데프트 블레이드/길스/레노어/아주르/요우/아메모리/린네/플로리나/루비/시오반/노비오/헤이디/베델/루크/파로마/그람/레비/스모키/플뢰르/베릴/히이로/사메야마/이브/우리엘/카렌/시로나/샤리/라파엘/코놀리/카론/엘시/빅토리아/요나/나시리스/가브리엘/미자드/미카엘/그로누/이리돈/레이스</color>\n※주의: 2.5주년 특선 소집상자는 사용 기한이 존재하며, 기간 만료 시 자동으로 3000루맘버로 전환되어 우편으로 지급됩니다. 사용 기간: 2024년 2월 28일 18:00",
  str_item_3661231 = "그림자의 권좌",
  str_item_intro_3661231 = "가구, 콜로서스의 방에 배치할 수 있다.\n뻣뻣한 가죽, 위압적인 형태... 공중상회가 이스타반을 위해 특별히 제작한 고급스러운 의자다. 덕분에 동일한 모델의 가격이 아무리 비싸더라도 불티나게 팔리고 있다.",
  str_item_3661232 = "부유 비공정 모형",
  str_item_intro_3661232 = "가구, 콜로서스의 방에 배치할 수 있다.\n공중상회가 제작한 관광, 쇼핑, 레저, 휴양 기능을 결합한 「부유 비공정」이다. 물론 고객이 선택할 수 있는 다양한 모델을 제공하고 있다. 이 모델은 크기가 가장 큰 것은 아니지만, 가장 섬세한 품질을 보여준다.",
  str_item_3661233 = "반짝반짝 조명",
  str_item_intro_3661233 = "가구, 콜로서스의 방에 배치할 수 있다.\n다양한 색상의 조명이 어두운 공간을 비추고 있다. 부디 축하할 가치가 있는 날에 이 빛들이 당신에게 따스함을 선사하기를.",
  str_item_3661234 = "성야의 선물상자",
  str_item_intro_3661234 = "가구, 콜로서스의 방에 배치할 수 있다.\n오로리안들이 마음을 담아 당신에게 준 선물이다. 비록 가치는 그리 크지 않지만, 그들의 정성과 노력으로 가득 차 있다. 부디 이 선물이 내년에도 당신에게 행운을 가져다주기를.",
  str_item_5234057 = "얼음 마차",
  str_item_intro_5234057 = "얼음으로 만든 마차다. 수정처럼 맑은 외관은 보는 이의 마음을 편하게 만들어 준다.",
  str_item_3661236 = "변장 검사 조각상",
  str_item_3661237 = "배를 탄 검사 조각상",
  str_item_3661241 = "부르 선풍기",
  str_item_3661242 = "식물 야간등",
  str_item_intro_3661236 = "가구, 콜로서스의 방에 배치할 수 있다.\n어느 기교사가 만든 기관 인형으로, 인형의 버튼을 누르면 랜덤으로 옷을 갈아입혀 준다. 용주의 한 공연 예술에서 영감을 받아 만들었다고 한다.\n「용주 사람으로 분장하려면... 옷을 빨리 갈아입는 기술도 배워야 하는 건가요?」",
  str_item_intro_3661237 = "가구, 콜로서스의 방에 배치할 수 있다.\n기교사가 검사와의 협력 성공 기념으로, 임무를 수행 중인 검사의 모습을 모델로 만든 조각상이다.\n「배의 맞은편에 빈자리를 남겨두고 싶다고? 좋아, 태우고 싶은 사람이 생기면 언제든지 말해.」",
  str_item_intro_3661241 = "가구, 콜로서스의 방에 배치할 수 있다.\n일루미나 과학자의 실험실 전용 선풍기다. 스탠드가 자유롭게 구부러지고, 어디에나 붙일 수 있다. 소문에 따르면 이 선풍기는 「부르」라는 이름의 로봇에서 영감을 얻어 만들어졌다고 한다.",
  str_item_intro_3661242 = "가구, 콜로서스의 방에 배치할 수 있다.\n잘 디자인된 전구다. 실내 식물의 성장에 필요한 조명을 제공할 뿐만 아니라, 실내에 따뜻하고 자연스러운 분위기를 조성할 수 있다.",
  str_item_3000352 = "아이테르의 깃털",
  str_item_intro_3000352 = "독특한 모양의 깃털이다. 아이테르 일족에게는 매우 큰 가치가 있다고 한다.",
  str_item_3661243 = "교자 소파",
  str_item_3661244 = "세화-「진」",
  str_item_3661238 = "폭죽 장식",
  str_item_3661239 = "새해맞이 장식",
  str_item_3661240 = "골동품 선반",
  str_item_intro_3661243 = "가구, 콜로서스의 방에 배치할 수 있다.\n만두 모양의 빈백이다. 원래는 음성 장치가 내장되어 있어서 다음 대사를 재생하고 있었다.\n「만두 만두 만만두!」\n「모두 함께 만두를 빚자!」\n그러나 일부 오로리안들이 시끄럽다고 불만을 품고 장치를 떼어냈고, 지금은 콜로서스가 고요를 되찾았다.",
  str_item_intro_3661244 = "가구, 콜로서스의 방에 배치할 수 있다.\n용녀가 그려진 세화다. 새해의 복을 기원하는 제나라의 인기 상품이다. 다만 용녀의 진짜 모습을 보여주는 것은 진예가 당신에게 준 이 「예술 사진」 한 장뿐이다.",
  str_item_intro_3661238 = "가구, 콜로서스의 방에 배치할 수 있다.\n용주의 전통 축제가 곧 시작된다. 콜로서스에 있는 용주 동료들이 축제 분위기를 느낄 수 있도록, 모두가 함께 만든 폭죽 장식을 가져왔다. 부디 이 장식이 불길한 일들을 모두 몰아내고, 새해에 행운이 늘 이어지길.",
  str_item_intro_3661239 = "가구, 콜로서스의 방에 배치할 수 있다.\n현재 쌍사성 가게에서 불티나게 팔리는 물건이다. 용주 대륙에서 새해나 명절을 보낼 때 꼭 장식하는 물건 중 하나이며, 미래에 대한 멋진 소망을 상징한다.",
  str_item_intro_3661240 = "가구, 콜로서스의 방에 배치할 수 있다.\n쌍사성의 장인이 자랑하는 작품이다. 목각 솜씨가 정교하고, 설계가 훌륭하다. 소품을 수납하거나 그 독특한 조형을 감상할 수 있다. 콜로서스에 배치하면 실내에 고전적인 분위기가 더해질 것이 틀림없다.",
  str_item_intro_3763039 = "획득 시 해당 프레임 개방.\n아름다운 복숭아꽃, 찬란하게 빛나네. 복숭아꽃 바르게 찍히니, 행운이 찾아오리.",
  str_item_intro_3751417 = "획득 시 해당 아바타 개방.\n「아이테르가 새해 선물로 받은 특별한 모자를 기분 좋게 쓰고 있네요!」",
  str_item_intro_3751566 = "획득 시 해당 아바타 개방.\n「이 몸이 가호를 내리나니, 한없는 축복을 받거라!」\n해신으로 간주되는 용녀는 정말로 사람들에게 속세의 행복을 줄 수 있을까요? 진예는 잘 모르겠지만, 그래도 해볼 생각인 모양이네요!",
  str_item_intro_3751567 = "획득 시 해당 아바타 개방.\n「내 미각은 정확하다고!」\n아스트라 대륙의 대사인 조종사는 미식 평가에도 능숙하고, 안목이 매우 높답니다.",
  str_item_intro_3763038 = "획득 시 해당 프레임 개방.\n「복이 담긴 엽서를 수집하면 신룡을 소환할 수 있습니다!」\n소문이 사실인지 아닌지는 모르겠지만, 카드 수집 요행은 용주의 새해에 확실히 신선하고 즐거운 경험을 선사했습니다.",
  str_item_intro_3751413 = "획득 시 해당 아바타 개방.\n「이 몸은 부유섬의 거대한 기계 갑주, 사막의 엄청나게 시끄러운 가무 공연, 지하실에서 투사들이 비무를 펼치는 모습이 보고 싶구나...」\n새해에는 용왕님에게도 많은 소원이 있답니다.",
  str_item_intro_3751414 = "획득 시 해당 아바타 개방.\n사람을 잡아먹는 뿔 달린 맹수... 움브라톤에도 있답니다! 알리우드에서 제작한 공포 영화 《사당이 살아있다!》, 춘삭절에 절찬리 상영 중!\n「그래서... 내가 연기하는 배역이 대체 뭐냐고...」",
  str_item_intro_3751415 = "획득 시 해당 아바타 개방.\n「받아, 그냥 한번 만들어 본 거야... 내가 아이스크림밖에 못 만드는 건 아니라구!」\n수많은 실패 끝에 자리야가 유일하게 성공한 제품입니다. 감정을 표현하기 위해 특별히 단맛을 더 높였습니다.",
  str_item_intro_3751416 = "획득 시 해당 아바타 개방.\n부디 오늘의 모임으로 당신이 「집」의 힘을 느낄 수 있길 바랍니다. 어느 곳에 있든지, 우리는 모두 같은 하늘을 보게 될 것입니다.",
  str_item_intro_3751568 = "획득 시 해당 아바타 개방.\n「날 좋아한다는 사람이 많긴 하지만, 난 조종사가 제일 특별하다고 생각해. 역시 우린 정말 통하는 게 있다니까!」",
  str_item_intro_3751569 = "획득 시 해당 아바타 개방.\n「소, 손하트를 해달라고?! ...뭐, 좋아. 그럼 내 성의를 감사하게 받아... 우쭐대지 말고!」",
  str_item_3763039 = "애정운",
  str_item_3751417 = "용 모자와 아이테르",
  str_item_3751566 = "용의 해, 용주, 용의 소녀",
  str_item_3751567 = "미식의 대사",
  str_item_3763038 = "용과 함께하는 새해",
  str_item_3751413 = "새해의 소원",
  str_item_3751414 = "새해 축하 공연",
  str_item_3751415 = "달콤한 선물",
  str_item_3751416 = "화목한 대가족",
  str_item_3751568 = "플뢰르의 마음",
  str_item_3751569 = "자리야의 마음",
  str_item_3763041 = "천일의 왕관",
  str_item_3751420 = "관월 기사의 날",
  str_item_3751419 = "천 개의 낮과 밤을 넘어",
  str_item_3751570 = "타오르는 영계",
  str_item_3763040 = "최후의 불꽃",
  str_item_3751421 = "천일의 마음",
  str_item_3751422 = "사랑을 쏘아 맞히는 날",
  str_item_intro_3751421 = "획득 시 해당 아바타 개방.\n「조종사, 여길 봐!」\n천일의 여정 동안 늘 사랑이 함께해 왔습니다. 앞으로도 모두의 축복을 받으며 계속해서 나아가 주세요!",
  str_item_intro_3751422 = "획득 시 해당 아바타 개방.\n「행동을 개시하죠. 어쩌면 오늘이 바로 우리의 운명을 결정할 순간일지도 모릅니다!」",
  str_item_intro_3763041 = "획득 시 해당 프레임 개방.\n「견고한 자에게 영광을!」\n천일의 의지, 천일의 동행. 당신의 인도와 수호에 감사드리며, 앞으로도 계속해서 함께 나아갈 수 있길 바랍니다.",
  str_item_intro_3751420 = "획득 시 해당 아바타 개방.\n「참여하시겠습니까? 관월제의 특별 재판입니다.」",
  str_item_intro_3751419 = "획득 시 해당 아바타 개방.\n「이 하늘 아래에서 함께 천일의 시간을 함께해 주셔서 감사합니다. 앞으로도 잘 부탁드리겠습니다.」",
  str_item_intro_3751570 = "획득 시 해당 아바타 개방.\n「나와 함께 영계에 가라앉아 줄래? 그럼... 자, 손을 잡아. 함께 희망을 불태우자.」",
  str_item_intro_3763040 = "획득 시 해당 프레임 개방.\n「마법약의 효과가 사라지고, 이 몸이 불꽃으로 변해도... 넌 남은 불씨를 따라 날 찾아줄래?」",
  str_item_3751042 = "공감하는 동료",
  str_item_3751043 = "단련의 성과",
  str_item_3751044 = "진리와 함께",
  str_item_3751045 = "여정의 호위",
  str_item_3751046 = "다과회의 단골손님",
  str_item_3751047 = "나의 이야기",
  str_item_3751048 = "전우 형제",
  str_item_3751573 = "숨은 여우",
  str_item_3763042 = "개굴개굴",
  str_item_intro_3751042 = "획득 시 해당 아바타 개방.\n「나도 알아. 조종사 일은 쉬운 게 아니란 거. 계속 힘내.」",
  str_item_intro_3751043 = "획득 시 해당 아바타 개방.\n「지금까지 잘 견뎠다. 꽤 하잖아! 그럼 앞으로도 같이 단련하자고!」",
  str_item_intro_3751044 = "획득 시 해당 아바타 개방.\n「기억하렴. 시간이 얼마나 흐르더라도, 진리는 영원히 함께한단다.」",
  str_item_intro_3751045 = "획득 시 해당 아바타 개방.\n「앞으로의 여정에서는 저도 당신을 확실하게 지키겠습니다.」",
  str_item_intro_3751046 = "획득 시 해당 아바타 개방.\n「내가 너한테 애프터눈 티를 벌써 몇 번이나 줬더라?」",
  str_item_intro_3751047 = "획득 시 해당 아바타 개방.\n「내 이야기는 이미 들려줬어. 그럼 넌?」",
  str_item_intro_3751048 = "획득 시 해당 아바타 개방.\n「이렇게 오래 알고 지냈는데, 우린 당연히 진작부터 친밀한 형제라고!」",
  str_item_intro_3751573 = "획득 시 해당 아바타 개방.\n「잘 숨었어? 아직이야!」",
  str_item_intro_3763042 = "획득 시 해당 프레임 개방.\n「무척 익숙해 보이는 모습이다.」",
  str_item_intro_3751423 = "획득 시 해당 아바타 개방.\n「개굴↗개굴↘개굴↗개굴──」",
  str_item_intro_3751424 = "획득 시 해당 아바타 개방.\n「어떻게 해야 할지... 그 답은 줄곧 내 마음 속에 있었던 거야?」",
  str_item_3751423 = "흰개구리 왕자",
  str_item_3751424 = "등대 아래의 답",
  str_item_3440014 = "신기한 개굴 주머니",
  str_item_intro_3440014 = "「나」는 그저 불쌍한 개구리일 뿐이야. 내가 평생 모은 건 모두 너한테 줬어.",
  str_item_intro_3440015 = "초특가 행운 복주머니 보상은 대부분 거대한 속임수일 뿐이야.",
  str_item_intro_3440016 = "행운이 계단처럼 올라가는 게 꼭 내 인생 같네.",
  str_item_intro_3440017 = "한 번만 더! 왠지 곧 천장일 것 같아!",
  str_item_intro_3440018 = "이 복주머니만 뽑으면 난 「뒤로」를 누르고 화면을 닫고 게임을 끌 거야.",
  str_item_3751574 = "최애의 골디",
  str_item_intro_3751574 = "획득 시 해당 아바타 개방.\n「모두의 시선을 빼앗는 그녀는 완벽하고 반짝이는 아이돌이랍니다.」",
  str_item_3751425 = "나른한 아이돌",
  str_item_intro_3751425 = "획득 시 해당 아바타 개방.\n「하암~ 잠옷만 입으면 졸려~」",
  str_item_3763043 = "최애의 마시멜로",
  str_item_intro_3763043 = "획득 시 해당 프레임 개방.\n「통통 튀는 귀여운 모습, 푹신푹신 부드러운 솜털, 또 누군가가 녀석에게 반했습니다.」",
  str_item_3751572 = "아빠 어디가?",
  str_item_intro_3751572 = "획득 시 해당 아바타 개방.\n「아버지, 본 기계에게 어디로 가시는지 말씀해 주세요.」",
  str_item_3751571 = "미소의 축복",
  str_item_intro_3751571 = "획득 시 해당 아바타 개방.\n「본 기계는 이 부품을 아버지에게 주겠습니다. 부디 아버지의 표정이 화면에 표시된 것과 일치하기를 바랍니다.」",
  str_item_3751429 = "안녕, 복슬아",
  str_item_intro_3751429 = "획득 시 해당 아바타 개방.\n「안녕, 복슬아! 집처럼 따스한 콜로서스는 모든 마음 약한 알바생을 환영해!」",
  str_item_3751430 = "훈장과 명예",
  str_item_3751577 = "호크아이 소대, 집결!",
  str_item_3751578 = "기쁨의 축하",
  str_item_3751579 = "그대 곁 천년의 봄",
  str_item_3763046 = "그대를 위한 오색실",
  str_item_3763047 = "잉어 깃발",
  str_item_intro_3751430 = "획득 시 해당 아바타 개방.\n「좋아, 오늘도 내 명예를 더럽히지 않았어。」",
  str_item_intro_3751577 = "획득 시 해당 아바타 개방.\n「눈은 매의 눈처럼 날카롭게, 공격은 발톱처럼 예리하게, 움직임은 날갯짓처럼 신속하게.」",
  str_item_intro_3751578 = "획득 시 해당 아바타 개방.\n「즐거운 축제! 자, 같이 외쳐 봐!」",
  str_item_intro_3751579 = "획득 시 해당 아바타 개방.\n「지금부터 앞으로 사방 천지의 모든 만물과 만나고 행하는 모든 일이 그대의 뜻대로 백년 천년까지 이루어지길 바라마.」",
  str_item_intro_3763046 = "획득 시 해당 프레임 개방.\n「그대가 득의만면, 파죽지세, 유지경성, 백절불굴하기를, 이 진예와 함께 더 많은 재미난 순간들을 몸소 겪을 수 있길 바라노라.」",
  str_item_intro_3763047 = "획득 시 해당 프레임 개방.\n운도에서 유행하는 깃발이다. 성장과 용기의 상징이다.",
  str_item_3751581 = "감동의 맛",
  str_item_3751582 = "맛있는 케이크",
  str_item_3751580 = "「비밀의 송곳니」의 소유주",
  str_item_intro_3751581 = "획득 시 해당 아바타 개방.\n「케르~ 이게 바로... 누군가에게 사랑받는다는 느낌 케르?」",
  str_item_intro_3751582 = "획득 시 해당 아바타 개방.\n「어디 한 입... 으음... 한 입 더!」",
  str_item_intro_3751580 = "획득 시 해당 아바타 개방.\n「난 움브라톤의 게임 센터, 『비밀의 송곳니』의 소유주, 바티아야. 게임 세계에 온 걸 환영해.」",
  str_item_3751436 = "강인한 눈빛",
  str_item_3751583 = "반란의 화염",
  str_item_3751584 = "찾아온 손님",
  str_item_3751585 = "우리의 우정을 위해 건배",
  str_item_3763048 = "일루미나의 미래를 바라보며",
  str_item_3763049 = "비밀 열쇠",
  str_item_intro_3751436 = "획득 시 해당 아바타 개방.\n「너희가 있으니까 정말 좋다!」",
  str_item_intro_3751583 = "획득 시 해당 아바타 개방.\n「반드시 더 강해져야만 해. 가장 높은 정점에 선 오로리안보다도 더 강해지는 거야.」",
  str_item_intro_3751584 = "획득 시 해당 아바타 개방.\n「설령 오늘 죽게 되더라도, 네 진짜 모습을 봐야겠어.」",
  str_item_intro_3751585 = "획득 시 해당 아바타 개방.\n「그와 친분을 맺는 것은 물론 괜찮겠지만, 조금 더 정중한 태도를 취해줬으면 좋겠군. 그 사람은 이 라인하르트의 손님이니 말이야.」",
  str_item_intro_3763048 = "획득 시 해당 프레임 개방.\n「걱정 마라. 모든 것은 변하기 마련이다. 어떤 변화는 탄식을 부르기도 하지만, 적어도 내가 보기엔── 가슴 벅찬 변화가 더 많다.」",
  str_item_intro_3763049 = "획득 시 해당 프레임 개방.\n「희미한 촛불을 통해 검은 상자가 지키고 있는 비밀을 엿볼 수 있을까?」",
  str_item_3751438 = "진리 통찰",
  str_item_3751586 = "신성한 계시",
  str_item_3763050 = "찬란한 길",
  str_item_intro_3751438 = "획득 시 해당 아바타 개방.\n「진리를 탐구하는 자는 마치 머나먼 별빛을 쫓는 것과 같아. 영혼의 눈이 있어야만 통찰할 수 있단다.」",
  str_item_intro_3751586 = "획득 시 해당 아바타 개방.\n「저는 참회합니다! 저는 속죄합니다! 저는... 진리의 축복을 받은 자입니다.」",
  str_item_intro_3763050 = "획득 시 해당 아바타 개방.\n「부디 진리가 널 축복하고, 앞으로의 삶을 찬란하게 비추길 바라마.」",
  str_item_3751426 = "라이자의 반짝임",
  str_item_3751427 = "클라우디아의 미소",
  str_item_3751428 = "파트리샤의 고집",
  str_item_3751575 = "새로운 모험을 향해",
  str_item_3751576 = "화려한 여름꽃",
  str_item_3751587 = "야심가 해군왕",
  str_item_3751588 = "수상 드론",
  str_item_3763044 = "스파클 레버리에",
  str_item_3763045 = "찬란한 바닷바람",
  str_item_3763051 = "여름을 품에 안고",
  str_item_3763052 = "압도적인 부",
  str_item_3763053 = "맹세를 지키는 자",
  str_item_3751444 = "시합을 즐겨줘",
  str_item_3751443 = "바다의 요정",
  str_item_3751589 = "동화 속 공주님",
  str_item_3751594 = "스틱스의 사냥신",
  str_item_3751593 = "황금의 뱀",
  str_item_3751592 = "맹세의 독자",
  str_item_3751591 = "그라디우스",
  str_item_intro_3751594 = "획득 시 해당 아바타 개방.\n「검은 날개는 스틱스 강을 가르는 날카로운 칼날이다.」",
  str_item_intro_3751593 = "획득 시 해당 아바타 개방.\n「비즈니스든, 즐거움이든, 돈만 충분하다면 네 요구는 뭐든지 만족시켜 줄 수 있어!」",
  str_item_intro_3751592 = "획득 시 해당 아바타 개방.\n「천년의 맹세는 결코 잊혀지지 않는다. 롱기누스 일족의 소원은 오직 영웅의 위업을 이룬 자에게만 바쳐진다.」",
  str_item_intro_3751591 = "획득 시 해당 아바타 개방.\n「눈앞의 적은 모두 없애고, 나의 검으로 별들의 이야기를 지키리라.」",
  str_item_intro_3763052 = "획득 시 해당 프레임 개방.\n「부귀란 눈부신 거란다!」",
  str_item_intro_3763053 = "획득 시 해당 프레임 개방.\n「검은 날개는 천년의 맹세를 수호하고 있다.」",
  str_item_intro_3751444 = "획득 시 해당 아바타 개방.\n「시합에 참가한 선수들이 순위를 쟁취하려고 노력하는 모습을 보세요. 이번 시합을 즐겨 주시고 참가자들을 격려해 주세요!」",
  str_item_intro_3751443 = "획득 시 해당 아바타 개방.\n「마야는 물이 좋고, 재미있는 수영을 좋아해. 같이 시합에 참가할래~? 모두와 함께 즐거움을 느끼는 거야~」",
  str_item_intro_3751589 = "획득 시 해당 아바타 개방.\n「마야는 좋은 꿈을 꾸고 싶어. 이 세상에 슬픔이 없어져서 영원히 즐거웠으면 좋겠어...」",
  str_item_intro_3751426 = "획득 시 해당 아바타 개방.\n「이게 뭘까? 두근두근하네...」",
  str_item_intro_3751427 = "획득 시 해당 아바타 개방.\n「어서 와. 오늘 모험은 어땠어? 재미있는 이야기가 있다면 들려줬으면 좋겠어.」",
  str_item_intro_3751428 = "획득 시 해당 아바타 개방.\n「아, 미안해요. 실례되는 모습을 보였네요. 자세를 바꾸고 다시 해 볼게요.」",
  str_item_intro_3751575 = "획득 시 해당 아바타 개방.\n「새로운 모험을 향해, 출발!」",
  str_item_intro_3751576 = "획득 시 해당 아바타 개방.\n「친구와 함께하는 여름은 역시 최고야~」",
  str_item_intro_3751587 = "획득 시 해당 아바타 개방.\n「이 거친 성질로 육지를 정복했으니까, 이제 바다를 상대로도 문제없을 거다... 아마도...?」",
  str_item_intro_3751588 = "획득 시 해당 아바타 개방.\n「삐빅, 수상 항해 모드를 실행합니다...」",
  str_item_intro_3763044 = "획득 시 해당 프레임 개방.\n「이 빛을 받으면 주변의 모든 사람들의 마음이 밝아지는 것을 느낄 수 있습니다.」",
  str_item_intro_3763045 = "획득 시 해당 프레임 개방.\n「아스트라에 오게 된 건 이번 여름 가장 놀라운 일이었어!」",
  str_item_intro_3763051 = "획득 시 해당 프레임 개방.\n「보기만 해도 함께 바다를 품에 안고 싶은 스타일리쉬한 튜브입니다. 짧은 여름휴가를 놓치지 말고, 서둘러 함께 여름을 품어보세요!」",
  str_item_3661248 = "고대 영웅 조각상",
  str_item_3661249 = "고대 장교 조각상",
  str_item_intro_3661248 = "가구, 콜로서스의 방에 배치할 수 있다.\n최근 발굴된 고대 조각상이다. 의복과 머리 장식으로 보았을 때 고대에 존경을 받았던 한 평민 전사의 모습으로 추정된다. 고고학자들은 해당 시기에 보통은 귀족들만이 자신의 조각상을 만들 권리가 있었음을 지적하였으며, 이를 통해 이 전사는 전투에서 매우 큰 공을 세웠기 때문에 사람들이 주도적으로 그의 조각상을 만들었음을 알 수 있다.\n「그녀가 사랑하는 이 세계는 내가 지킬 것이다!」",
  str_item_intro_3661249 = "가구, 콜로서스의 방에 배치할 수 있다.\n최근 발굴된 고대 조각상이다. 의복과 머리 장식으로 보았을 때 군에서 높은 지위에 있던 한 장교의 모습으로 추정된다. 고고학자들은 해당 시기 군대의 장교는 대부분 귀족 출신이라는 점을 지적하였으며, 따라서 이 조각상은 다른 평민 조각상과 달리 귀족을 섬기는 전문 조각가가 만들었을 가능성이 높다.\n「앞으로의 일은 내게 맡겨라.」",
  str_item_3661250 = "눈여우 조각상",
  str_item_3661251 = "소나무 촛대",
  str_item_3661252 = "로빈의 책꽂이",
  str_item_3661253 = "컬렉션 오디오",
  str_item_3661254 = "릴렉스 테이블",
  str_item_intro_3661250 = "가구, 콜로서스의 방에 배치할 수 있다.\n북방인들이 사랑하는 조각상이다. 그 원형은 한 북방 수비대원인데, 전쟁에서 전사한 중요한 동료를 추모하기 위해 만들어졌다고 한다.",
  str_item_intro_3661251 = "가구, 콜로서스의 방에 배치할 수 있다.\n질 좋은 소나무로 제작한 분위기 있는 촛대로, 우아한 소나무 향이 은은하게 퍼져 숙면을 돕는 작용을 한다.",
  str_item_intro_3661252 = "가구, 콜로서스의 방에 배치할 수 있다.\n심플한 구조의 책장이다. 좋은 목재를 사용해 은은한 향기가 난다.",
  str_item_intro_3661253 = "가구, 콜로서스의 방에 배치할 수 있다.\n엄숙한 행사에 어울리는 우아한 스피커다. 흘러나오는 음악은 안시아가 익숙할 만한 폭발적인 메탈 음악보다는 의장대 행사에 가까운 느낌이다.",
  str_item_intro_3661254 = "가구, 콜로서스의 방에 배치할 수 있다.\n아름답고 합리적인 가격의 릴렉스 테이블이다. 도시 거주자들에게 하루의 휴식을 제공하기에 충분하며, 어디에 있든 베스트셀러 아이템이 된다.",
  str_item_3661256 = "빈티지 괘종",
  str_item_3661257 = "장식 그림 「달밤」",
  str_item_3661258 = "사냥개 인형",
  str_item_3661260 = "레디젤 바비큐 그릴",
  str_item_intro_3661256 = "가구, 콜로서스의 방에 배치할 수 있다.\n시계의 프레임은 정교한 금속으로 제작되었으며, 표면은 특수 처리되어 세월이 쌓인 구릿빛 색채를 드러낸다.",
  str_item_intro_3661257 = "가구, 콜로서스의 방에 배치할 수 있다.\n아름다운 장식 그림이다. 깊은 밤하늘을 배경으로 달이 그림의 중앙을 차지해 은은한 빛을 발하고 있다.",
  str_item_intro_3661258 = "가구, 콜로서스의 방에 배치할 수 있다.\n사냥개 모양의 인형이다. 그 눈은 마치 「봤노라멍, 원하노라멍, 잡았노라멍」이라고 말하는 듯하다.",
  str_item_intro_3661260 = "가구, 콜로서스의 방에 배치할 수 있다.\n레디젤 렌치 캠프에서 가장 흔히 볼 수 있는 그릴이다. 버려진 구리와 고철로 만들어졌지만, 구워낸 요리는 무척이나 향기롭다고 한다... 적어도 레디젤 렌치의 사람들은 그렇게 생각한다.",
  str_item_3661265 = "우아한 여행자 조각상",
  str_item_3661266 = "기괴한 당근 조각상",
  str_item_intro_3661265 = "가구, 콜로서스의 방에 배치할 수 있다.\n전설에 따르면 한 여행자가 달콤한 땅에 「구르메」라는 작은 마을을 세웠다고 한다. 그곳에는 끝없는 젖과 꿀이 흐른다고 하는데...\n「그 마을, 대체 어디 있는 거야? 설마... 다른 세계에 있나?」",
  str_item_intro_3661266 = "가구, 콜로서스의 방에 배치할 수 있다.\n당근을 싫어하는 아이들의 마음속에는 발톱과 녹색 눈을 가진 당근이 있다... 왠지 암귀보다 더 무서운 것 같다.\n「케르... 난 그냥 불쌍한 당근일 뿐이다 케르...」",
  str_item_3661267 = "고전 아케이드 게임기",
  str_item_intro_3661267 = "가구, 콜로서스의 방에 배치할 수 있다.\n「콜로서스에서 지낼 거면, 이걸 챙겨야 해... 안 그러면 난 살아갈 수 없어.」\n동료의 부탁인 이상 조종사는 직접 운반을 도왔다. 그 대가는 근육 부상이었지만.",
  str_item_3661268 = "픽셀 선글라스 벽장식",
  str_item_intro_3661268 = "가구, 콜로서스의 방에 배치할 수 있다.\n「잉겔, 넌 졌어. 전리품을 두고 가.」\n잉겔로부터 얻은 전리품이다. 왠지 어떤 게임의 굿즈인 것 같다.",
  str_item_3661271 = "인형 보관함",
  str_item_intro_3661271 = "가구, 콜로서스의 방에 배치할 수 있다.\n쉽게 물건을 잃어버리는 인형 수집가에게 있어서는 세계 최고의 발명품이라고 할 수 있다.",
  str_item_3661272 = "고양이발 괘종",
  str_item_intro_3661272 = "가구, 콜로서스의 방에 배치할 수 있다.\n최고의 귀여움을 자랑하는 고양이 육구 벽시계다! 만지면 부드럽고 말랑말랑하다! 벽에 걸어야 한다는 단점 정도는 무시할 수 있지 않을까...",
  str_item_3661273 = "신예 연설대",
  str_item_intro_3661273 = "가구, 콜로서스의 방에 배치할 수 있다.\n일루미나에는 이런 말이 있다. 「입학할 때 연설대에서 큰 소리로 자신의 꿈을 말한 신입생은 모두 훗날 존경 받는 영웅이 되었다.」",
  str_item_3661274 = "무쇠 벽난로",
  str_item_intro_3661274 = "가구, 콜로서스의 방에 배치할 수 있다.\n일루미나에서 생산한 무쇠 벽난로다. 우수한 보온성 외에도 차분한 외관과 따뜻한 불씨로 방을 늘 아늑하게 만들어 준다.",
  str_item_3661275 = "계시의 자리",
  str_item_intro_3661275 = "가구, 콜로서스의 방에 배치할 수 있다.\n왈라지 마을의 고급 침대다. 따뜻하고 편안하며, 특유의 클래식한 맛이 돋보인다. 진리의 결사의 신도들은 이를 하늘의 계시가 강림할 침대로 받들고 있다.",
  str_item_3661276 = "미래를 비추는 거울",
  str_item_intro_3661276 = "가구, 콜로서스의 방에 배치할 수 있다.\n「진리를 탐색하는 자, 고대의 나무 거울에서 미래를 엿볼 수 있을 것이다.」 대체 누가 이런 광고 문구를 쓴 것일까...",
  str_item_3661277 = "용맹한 군인 조각상",
  str_item_intro_3661277 = "가구, 콜로서스의 방에 배치할 수 있다.\n암귀들의 압도적인 공격에 돌진하는 나팔조차 포효에 묻혀버렸다. 그러나 한 명의 용감한 군인이 군기를 들고 전진했고, 그 뒤를 수천수만의 군인들이 따라왔다.\n「그 용맹하고 두려움 없으며, 희생을 두려워하지 않는 이에게 바친다.」",
  str_item_3661278 = "파멸의 종 조각상",
  str_item_intro_3661278 = "가구, 콜로서스의 방에 배치할 수 있다.\n추악하고 무서운 모습의 조각상이다. 그 사나운 모습은 사람들로 하여금 녀석이 세상의 적으로 태어났다고 믿게 만든다.\n녀석이 움직일 때면 몸의 금속 갑옷이 서로 부딪혀 울리는데, 그것은 생명을 증오하는 파멸의 종소리다.",
  str_item_3661262 = "유적 수호자 모형",
  str_item_intro_3661262 = "가구, 콜로서스의 방에 배치할 수 있다.\n유적 수호자에 푹 빠져 있던 플뢰르가 제작한 모형이다.\n「이것도 일종의 메카라고 할 수 있겠지!」",
  str_item_3661263 = "연금솥",
  str_item_intro_3661263 = "가구, 콜로서스의 방에 배치할 수 있다.\n이것만 있으면 콜로서스에 라이자의 아틀리에를 차릴 수 있다!",
  str_item_3661264 = "모험 사진",
  str_item_intro_3661264 = "가구, 콜로서스의 방에 배치할 수 있다.\n여름이 지나고 나면, 이 여름이 또 그리워지겠지!",
  str_item_3661279 = "여름바람 방향타",
  str_item_intro_3661279 = "가구, 콜로서스의 방에 배치할 수 있다.\n손을 얹으면 바닷바람의 잔잔한 바람이 느껴지는 듯하며, 여름 바다의 신선한 숨결을 완벽하게 붙잡아 둔 것만 같다. 항해 마니아를 위한 필수 가구다.",
  str_item_3661280 = "여름바람 튜브",
  str_item_intro_3661280 = "가구, 콜로서스의 방에 배치할 수 있다.\n클래식한 배색과 견고한 소재를 자랑한다. 집에 둘 때나, 항해 중에 실제로 사용할 때나, 모두 멋진 장면을 만들어 줄 수 있을 것이다.",
  str_item_3661281 = "여름바람 깃발",
  str_item_intro_3661281 = "가구, 콜로서스의 방에 배치할 수 있다.\n심플하면서도 우아한 장식용 깃발이다. 바다의 분위기를 더해야 하는 모든 공간에 적합하다.",
  str_item_3661282 = "바닷새 소라고둥",
  str_item_intro_3661282 = "가구, 콜로서스의 방에 배치할 수 있다.\n「큰 소라고둥, 삐이이~ 갈매기가 들으면 날지 않아~」\n대체 누가 이 노래를 콜로서스에 퍼트리기 시작한 것인지 모르겠다.",
  str_item_3661283 = "릴렉스 버블건",
  str_item_intro_3661283 = "가구, 콜로서스의 방에 배치할 수 있다.\n받침대에 고정된 거품 물총이다. 왠지 누르기만 하면 거품이 발사되는 것 같다.\n「정말 느긋한 기분이 드는 도구네. 사람들을 꿈에 빠트리지만 않는다면 좋을 텐데~」",
  str_item_3661284 = "흰 수선화 조각상",
  str_item_intro_3661284 = "가구, 콜로서스의 방에 배치할 수 있다.\n나시리스는 수선화를 기르는 것을 좋아한다. 그녀는 자신의 꽃을 매우 중요하게 생각하며, 함부로 꽃을 밟는 녀석은 거울 호수에 집어던질 것이다.",
  str_item_3661285 = "순결한 백합 조각상",
  str_item_intro_3661285 = "가구, 콜로서스의 방에 배치할 수 있다.\n네포리스는 백합을 기르는 것을 좋아했다. 그녀는 꽃을 따서 다른 이들에게 선물로 주었고, 그 향기는 오래도록 남아 있었다.",
  str_item_3661286 = "별들이 빛날 때",
  str_item_intro_3661286 = "가구, 콜로서스의 방에 배치할 수 있다.\n미트라의 그림이다. 아킬레스가 보여준 찰나의 미소를 담고 있다.\n불굴의 유성이여, 부디 동료들과 함께 다시 빛나 주길.",
  str_item_3661287 = "쌍검",
  str_item_intro_3661287 = "가구, 콜로서스의 방에 배치할 수 있다.\n사일런트 예거의 대장과 부대장의 무기를 모방한 제품이다.\n목도하라! 이는 개척의 극의이자 수호의 결심이니! 이것이야말로 사일런트 예거의 진정한 의미다.",
  str_item_3661288 = "맹금류 횃대",
  str_item_intro_3661288 = "가구, 콜로서스의 방에 배치할 수 있다.\n미트라가 새들을 위해 준비한 횃대다.\n이 위에서는 무척이나 순종적이지만, 녀석들의 발톱은 무척 매섭다.",
  str_item_3661289 = "별들",
  str_item_intro_3661289 = "가구, 콜로서스의 방에 배치할 수 있다.\n복원된 옛 작품이다.\n만약 하늘을 가른 별들이 언젠가는 세월의 따스함을 느끼며, 그들이 돌아갈 곳에 도달한다면...\n부디 그들 모두가 때늦은 행복을 손에 넣을 수 있기를.",
  str_item_3661290 = "달의 소리",
  str_item_intro_3661290 = "가구, 콜로서스의 방에 배치할 수 있다.\n루트비히라는 한 아이테르가 만든 곡이다.\n달빛처럼 고결하고 우아하면서도, 쉽게 가라앉지 않는 슬픔을 드러내고 있다. 부디 그들이 늦은 행복을 손에 넣을 수 있기를.",
  str_item_9998002 = "독의사 가면",
  str_item_9998003 = "반란의 메아리",
  str_item_9998004 = "심판의 손",
  str_item_9998005 = "사신의 응시",
  str_item_9998006 = "와해의 가면",
  str_item_9998007 = "역병 유작",
  str_item_9998008 = "월 브레이커",
