  str_item_9998053 = "루미나 실드",
  str_item_9998054 = "루미나 마법상자",
  str_item_9998055 = "피해 증가 장치",
  str_item_9998056 = "충전 사탕 병",
  str_item_9998057 = "고대 학자의 노트",
  str_item_9998058 = "이동식 에너지 장치",
  str_item_9998059 = "폭렬 슈즈",
  str_item_9998060 = "수수께끼의 상자",
  str_item_9998061 = "만색 보석",
  str_item_9998062 = "패럴라이저",
  str_item_9998063 = "죽음의 편지",
  str_item_9998064 = "은월 방패",
  str_item_9998065 = "떨어지는 벚꽃",
  str_item_9998066 = "경건함의 증명",
  str_item_9998067 = "절약 전술",
  str_item_9998068 = "진형 방패 공격",
  str_item_9998069 = "진형의 협주곡",
  str_item_9998070 = "진형의 제기",
  str_item_9998071 = "진형의 북",
  str_item_9998072 = "진형의 군기",
  str_item_9998073 = "소울 커터",
  str_item_9998074 = "폭격자",
  str_item_9998075 = "만색 마름쇠",
  str_item_9998076 = "편광 페인트",
  str_item_intro_9998002 = "턴이 시작될 때마다 모든 적에게 랜덤으로 중독/출혈/작열 효과 1단계 부여, 4회 반복. 오로리안이 입히는 피해 15% 감소",
  str_item_intro_9998003 = "적이 이상 상태 또는 디버프 효과 상태일 시 받는 모든 피해 20% 증가",
  str_item_intro_9998004 = "칸 제거 시 제거 범위 내 적에게 랜덤으로 중독/출혈/작열 효과 1단계 부여, 5회 반복",
