  str_item_intro_9998016 = "오로리안이 액티브 스킬로 동시에 3명 이상의 적 공격 시 낙뢰를 시전해 모든 적을 공격, 파티 평균 공격력 200%의 피해를 입힘",
  str_item_intro_9998017 = "리더 변경 후 새로운 리더의 액티브 스킬 쿨다운 턴 수 -1, 오로리안별로 턴마다 최대 1회 발동 가능",
  str_item_intro_9998018 = "파티의 HP가 1%가 되면 HP 자물쇠 1턴 적용, 이후 최대 HP의 20% 회복(전투마다 1회 발동, 총 2회 발동 제한)",
