  str_item_intro_9998024 = "서포터 클래스 오로리안의 전투 중 연쇄 스킬 및 액티브 스킬의 회복 효과 40% 증가",
  str_item_intro_9998025 = "파티 내 오로리안의 주속성 1종류마다 오로리안이 입히는 피해 6% 증가, 최대 24% 증가",
  str_item_intro_9998026 = "오로리안이 피해를 입힐 시 불리한 속성의 피해 감소 효과 무시, 피해를 입을 시 불리한 속성의 피해 증가 효과 무시",
  str_item_intro_9998027 = "오로리안이 부속성으로 피해를 입힐 시 주속성과 동일한 피해 배율 적용",
  str_item_intro_9998028 = "인연 오로리안이 제거한 칸의 속성을 무시하고 연쇄 스킬 시전 가능",
  str_item_intro_9998029 = "인연 오로리안 1그룹당 턴이 시작될 때마다 파티의 최대 HP 5% 회복",
  str_item_intro_9998030 = "인연 오로리안 1그룹마다 칸 제거 시 40% 확률로 아이테르 특수 장비 에너지 1포인트 충전, 다수의 인연 그룹 존재 시 개별 발동",
  str_item_intro_9998031 = "인연 오로리안이 서로 20%의 기본 공격력 계승",
  str_item_intro_9998032 = "오로리안이 액티브 스킬 시전 시 인연 관계인 오로리안의 액티브 스킬 쿨다운 턴 수 1 감소, 전투당 최대 5회 발동",
