  str_item_intro_9998040 = "현재 HP가 50% 이상일 시 오로리안이 입히는 피해가 30% 증가, HP 차이 1%당 피해 5% 감소",
  str_item_intro_9998041 = "턴이 시작될 때마다 현재 HP의 7%를 잃고 주변 2서클 범위 내 적에게 파티 평균 공격력 150%의 피해를 입힘",
  str_item_intro_9998042 = "전투 시작 시 현재 HP의 70%를 잃고, 필드 내 모든 적에게 잃은 HP의 300%에 해당하는 피해를 입힘",
  str_item_intro_9998043 = "오로리안의 액티브 스킬 피해 80% 증가, 액티브 스킬을 시전할 때마다 현재 HP의 8% 감소",
  str_item_intro_9998044 = "터치해 제거한 칸 수량 무시, 제거할 때마다 반드시 오로리안의 최고 단계 연쇄 스킬 시전",
