  str_item_intro_9998050 = "오로리안이 입히는 피해 20% 증가, 턴 경과 시 소모 수량 1배 증가",
  str_item_intro_9998051 = "파티 내 모든 오로리안의 방어력 제거, 기본 방어력의 50%를 공격력으로 전환",
  str_item_intro_9998052 = "보유 중인 계몽 장비 1개당 모든 오로리안의 최대 HP 2% 증가",
  str_item_intro_9998053 = "보유 중인 계몽 장비 1개당 모든 오로리안의 방어력 1.5% 증가",
  str_item_intro_9998054 = "보유 중인 계몽 장비 1개당 모든 오로리안의 공격력 1% 증가",
  str_item_intro_9998055 = "턴이 시작될 때마다 전장 랜덤 위치에 피해 증가 장치 1개 생성, 장치 제거 후 이번 턴 동안 연쇄 스킬 피해 35% 증가",
  str_item_intro_9998056 = "웨이브가 시작될 때마다 전장에 충전 사탕 병 1개 생성, 제거 후 랜덤 아이테르 특수 장비 1개의 사용 횟수 1회 획득",
