  str_item_intro_9998058 = "웨이브가 시작될 때마다 전장에 이동식 에너지 장치 1개 생성, 제거 후 턴 수 3포인트 획득",
  str_item_intro_9998059 = "턴이 시작될 때마다 발밑의 칸을 부수며, 오로리안이 입히는 피해 15% 증가",
