  str_item_intro_9998063 = "터치해 칸 제거 시 제거 범위 내 적에게 파티 평균 공격력 150%의 피해를 입힘",
  str_item_intro_9998064 = "터치해 칸 제거 시 제거한 칸 1개마다 최대 HP의 0.5%에 해당하는 실드 획득, 1턴간 지속",
  str_item_intro_9998065 = "한번의 터치로 최소 15칸을 없애면 오로리안 연쇄 스킬 피해가 30% 증가한다. 없앤 칸이 7개 미만이면 연쇄 스킬을 시전할 수 없다.",
