  str_item_intro_9998071 = "터치해 칸 제거 시 제거한 칸 1개마다 이번 턴에 진영 지원 스킬의 최종 피해 5% 증가",
  str_item_intro_9998072 = "파티의 진영 지원 스킬과 진영이 같은 오로리안 한 명당 진영 지원 스킬 최종 피해 25% 증가",
  str_item_intro_9998073 = "파티의 진영 지원 스킬과 진영이 같은 오로리안 한 명당 모든 오로리안의 기본 방어력과 최대 HP 3% 증가",
