  str_item_4090264 = "마법약의 밤",
  str_item_intro_4090264 = "「조종사, 난 오로리안을 그만두겠어!」\n허무를 참을 수 없었던 우리엘은 마법약을 이용해 다른 존재로 변신하려 했다. 그러나 마법약을 마신 후 그녀는 그 소원을 이루지 못했고, 오히려 기묘한 만취 상태에 빠지고 말았다. 원래는 우울하고 냉담했던 그녀는 갑자기 적극적으로 변했고, 당신과 함께 특별한 일들을 시도하길 갈망했다. 이제 앞으로의 하루를 그녀와 어떻게 보내야 할까.",
