  str_item_intro_9011001 = "턴 시작 시 필드 내 모든 적에게 4444의 고정피해를 입히고, HP가 6% 미만인 적 제거",
  str_item_intro_9011002 = "파티 내 오로리안 주속성 개수에 따라 전투 시작 시 주변에 만색 칸 2회 갱신, 이후 턴마다 갱신",
  str_item_intro_9011003 = "3번째 턴에 모든 칸이 만색 칸으로 전환되며, 연결 종료 시 모든 만색 칸이 초기화됨",
  str_item_intro_9011004 = "HP가 최대인 오로리안이 입히는 모든 피해 15% 증가",
  str_item_intro_9011005 = "꿈을 먹는 그림자 스테이지 클리어 시 현재 보유 중인 꿈의 금화 30% 증가",
  str_item_intro_9011006 = "일회성: 꿈 폭탄 2개 획득",
  str_item_intro_9011007 = "현재 보유한 꿈의 금화가 많을수록 일반공격 피해 증가",
  str_item_intro_9011008 = "연결되는 첫 번째 칸의 색상이 다음 칸과 다를 수 있으며, 두 속성 오로리안이 모두 출전함",
  str_item_intro_9011009 = "장착되지 않은 모든 판타즘 스톤을 랜덤으로 새로운 판타즘 스톤로 바꾸며(새 판타즘 스톤의 레벨은 기존보다 낮을 수 없음), 각각 30%의 확률로 성급 증가",
  str_item_intro_9011010 = "연결을 통해 지나간 칸이 리더의 속성일 시 2칸마다 판타즘 스톤 에너지 1 충전",
  str_item_intro_9011011 = "판타즘 스톤 스킬이 2개의 랜덤 수치 중 높은 쪽을 기준으로 피해를 입히며, 수치 범위가 10% 증가함",
  str_item_intro_9011012 = "획득 시 이후 획득하는 판타즘 스톤의 기본 성급은 1성이 됨",
  str_item_intro_9011013 = "드림카드 선택 시 선택 가능한 카드 수가 1장 감소하나, 카드를 통해 획득하는 보상 효과가 2배로 증가함",
  str_item_intro_9011014 = "전투 진입 후 모든 오로리안의 HP 한도 20% 감소, 행동 시 선택 가능한 드림카드 수 +1",
  str_item_intro_9011015 = "연결 시작 전, 오로리안이 위치를 이동할 때마다 착지 지점 마름모 범위에 평균 공격력의 150%에 해당하는 피해를 입히며, 1서클 이동할 때마다 판타즘 스톤 에너지 1 충전",
  str_item_intro_9011016 = "체인저 및 서포터 클래스 오로리안의 연쇄 스킬이 피해를 입힐 시 대상에게 랜덤으로 중독/출혈/작열 상태 1회 부여",
  str_item_intro_9011017 = "중독/출혈/작열 상태의 적에게 피해를 입힐 시 효과별 피해가 일정량 증가",
  str_item_intro_9011018 = "대상에게 중독/출혈/작열 상태 부여 후 일정 확률로 랜덤 1회 추가 부여, 본 효과는 반복 발동이 가능하며, 발동 시마다 확률이 절반으로 감소함",
  str_item_intro_9011019 = "적 사망 시 필드 내 모든 적에게 랜덤으로 중독/출혈/작열 상태 1회 부여",
  str_item_intro_9011020 = "리더 일반공격 시 전체 파티 공격력의 50%에 해당하는 불 속성 피해를 추가로 입힘",
  str_item_intro_9011021 = "리더 일반공격 시 전체 파티 공격력의 50%에 해당하는 번개 속성 피해를 추가로 입힘",
  str_item_intro_9011022 = "리더 일반공격 시 전체 파티 공격력의 50%에 해당하는 숲 속성 피해를 추가로 입힘",
  str_item_intro_9011023 = "리더 일반공격 시 전체 파티 공격력의 50%에 해당하는 물 속성 피해를 추가로 입힘",
  str_item_intro_9011024 = "턴이 시작될 때마다 가장 가까운 불 속성 칸 3개를 만색 칸으로 전환함",
  str_item_intro_9011025 = "턴이 시작될 때마다 가장 가까운 번개 속성 칸 3개를 만색 칸으로 전환함",
  str_item_intro_9011026 = "턴이 시작될 때마다 가장 가까운 숲 속성 칸 3개를 만색 칸으로 전환함",
  str_item_intro_9011027 = "턴이 시작될 때마다 가장 가까운 물 속성 칸 3개를 만색 칸으로 전환함",
  str_item_intro_9011028 = "턴이 시작될 때마다 주변 모든 적의 발아래 최대 1개의 칸을 만색 칸으로 전환함",
  str_item_intro_9011029 = "피해를 입을 시 주변 2서클 내 3개의 칸을 만색 칸으로 전환함",
  str_item_intro_9011030 = "턴이 시작될 때마다 HP가 낮은 오로리안을 손실 HP의 퍼센트에 비례해 회복시킴",
  str_item_intro_9011031 = "전투 승리 후 모든 오로리안의 HP를 20% 회복시킴",
  str_item_intro_9011032 = "이번 턴에 짙은 칸 획득 시 투지 1단계 획득",
  str_item_intro_9011033 = "서포터 클래스 오로리안이 액티브/연쇄 스킬을 시전해 파티 치료 시 투지 1단계 획득",
  str_item_intro_9011034 = "액티브 스킬로 적을 넉백/끌어당길 시 대상의 수에 따라 투지 획득, 턴마다 최대 3회 발동",
  str_item_intro_9011035 = "적에게 중독/출혈/작열 상태가 부여될 때마다 투지 1단계 획득, 턴마다 최대 4회 발동",
  str_item_intro_9011036 = "꿈의 세계 레벨이 오를 때마다 해당 레벨의 4배에 해당하는 꿈의 금화 획득.",
  str_item_intro_9011037 = "꿈의 이자가 증가할 때마다 해당 수치의 7배만큼 증가함",
  str_item_intro_9011038 = "전투에서 암귀를 처치할 때마다 꿈의 금화 4개 획득",
  str_item_intro_9011039 = "일회성: 보유한 드림카드 중 5장을 뽑고, 걸음 수의 합만큼 꿈의 이자를 획득함",
  str_item_intro_9011040 = "보물 영역에서 동시에 2개의 보상 획득",
  str_item_intro_9011041 = "위험 영역을 통과할 때마다 꿈의 경험치 30 획득",
  str_item_intro_9011042 = "상품 구매 시 가격 인하, 꿈의 장비·오로리안·상품 갱신 비용 35% 감소",
  str_item_intro_9011043 = "획득 후 미개척 영역에 오로리안 파견 시 곧바로 귀환하며, 파견으로 획득하는 꿈의 금화, 꿈의 이자가 2배로 증가함",
  str_item_intro_9011044 = "캠프를 통과할 때마다 꿈의 경험치 40 획득",
  str_item_intro_9011045 = "일회성: 모든 오로리안이 현재 HP의 70%를 잃고, HP를 잃은 오로리안 1명당 꿈의 경험치 25 획득",
  str_item_intro_9011046 = "일회성: 현재 꿈의 금화의 절반 소모, 꿈의 금화 1개당 꿈의 경험치 2 획득",
  str_item_intro_9011047 = "오로리안 액티브 스킬 피해가 대폭 증가하나, 피해를 입힐 시 자신의 HP도 하락함",
  str_item_9011048 = "폭격자",
  str_item_9011049 = "분쇄자",
  str_item_9011050 = "킹 슬레이어",
  str_item_9011051 = "월 브레이커",
  str_item_9011052 = "패럴라이저",
  str_item_9011053 = "뇌격자",
  str_item_intro_9011048 = "<link=\"1005\"><color=#98500f><u>알고리즘 업그레이드 모듈</u></color></link> 활성화: 필드에 적의 수가 적을수록 최종 피해 증가",
  str_item_intro_9011049 = "<link=\"1005\"><color=#98500f><u>알고리즘 업그레이드 모듈</u></color></link> 활성화: 리더 일반공격 시 <link=\"1006\"><color=#98500f><u>과부하 수치</u></color></link> 3포인트 획득",
  str_item_intro_9011050 = "<link=\"1005\"><color=#98500f><u>알고리즘 업그레이드 모듈</u></color></link> 활성화: 오로리안의 액티브 스킬에 피격된 적 1명당 <link=\"1006\"><color=#98500f><u>과부하 수치</u></color></link> 4포인트 획득",
  str_item_intro_9011051 = "<link=\"1005\"><color=#98500f><u>알고리즘 업그레이드 모듈</u></color></link> 활성화: 턴 시작 시 파티의 HP가 낮을수록 더 많은 <link=\"1006\"><color=#98500f><u>과부하 수치</u></color></link> 획득",
  str_item_intro_9011052 = "<link=\"1005\"><color=#98500f><u>알고리즘 업그레이드 모듈</u></color></link> 활성화: 피해를 입을 때마다 <link=\"1006\"><color=#98500f><u>과부하 수치</u></color></link> 8포인트 획득",
  str_item_intro_9011053 = "<link=\"1005\"><color=#98500f><u>알고리즘 업그레이드 모듈</u></color></link> 활성화: 데이터 폭격 발동에 필요한 <link=\"1006\"><color=#98500f><u>과부하 수치</u></color></link>가 120포인트로 증가, 대형 몬스터에 대한 피해 증가",
  str_item_intro_9011054 = "오로라 타임 조건 달성 시 오로라 타임에 진입하지 않는 대신 1 MS치 획득, 또한 골드 5개 획득(웨이브 변동 및 전투 승리로 인해 건너뛴 오로라 타임 포함)",
  str_item_intro_9011055 = "적 사망 시 발아래 최소 1칸이 짙은 칸으로 전환됨",
  str_item_intro_9011056 = "턴이 시작될 때마다 리더와 동일 속성인 가장 가까운 칸 2개를 짙은 칸으로 전환함",
  str_item_intro_9011057 = "꿈의 장비 선택 항목 +1",
  str_item_intro_9011058 = "꿈의 장비 선택 시 첫 새로고침 무료",
  str_item_intro_9011059 = "보유 중인 꿈의 장비 1개당 스나이퍼, 버스터 클래스 오로리안의 공격력 0.5% 증가",
  str_item_intro_9011060 = "보유 중인 꿈의 장비 1개당 체인저, 서포터 클래스 오로리안의 방어력 2% 증가",
  str_item_intro_9011061 = "보유 중인 꿈의 장비 1개당 모든 오로리안의 최대 HP 1.5% 증가",
  str_item_intro_9011062 = "턴이 시작될 때마다 시계 1개 갱신(최대 1개 존재), 획득 시 스킬 쿨다운 턴 수가 가장 많은 오로리안의 스킬 쿨다운 -1",
  str_item_intro_9011063 = "피해를 입힌 대상에게 <link=\"1010\"><color=#98500f><u>실명</u></color></link> 효과 부여",
  str_item_intro_9011064 = "피해를 받을 때마다 전체 오로리안이 5%의 피해 보너스 획득, 최대 30%(전투 종료 시 초기화)",
  str_item_intro_9011065 = "일반공격 피해 30% 증가, 피해를 입을 시 해당 효과 소멸",
  str_item_intro_9011066 = "모든 오로리안의 방어력이 절반으로 감소하며, 감소한 방어력만큼 자신의 공격력 증가",
  str_item_intro_9011067 = "리더 오로리안이 연결 시작 위치에 분신을 만들고, 이번 턴에 연쇄 스킬을 동시에 시전함",
  str_item_intro_9011068 = "파티 내 오로리안의 주속성 1종마다 피해 3.5% 증가",
  str_item_intro_9011069 = "부속성이 주속성 배율에 따라 피해를 입히며, 주속성과 부속성이 동일할 시 배율이 추가로 증가함",
  str_item_intro_9011070 = "이전 리더가 연결 속성을 무시하고 출전 가능",
  str_item_intro_9011071 = "각 전투당 리더 변경 횟수 +2\n리더 교체 시 새로운 리더의 액티브 스킬 쿨다운 -1, 턴마다 각 오로리안당 1회만 발동 가능",
  str_item_intro_9011072 = "연결 또는 위치이동 시마다 기존 칸이 리더와 동일한 속성이 됨",
  str_item_intro_9011073 = "아군이 입히는 모든 피해가 15% 증가하나, 매회 연결 시작 지점이 8턴간 이동할 수 없는 파괴된 칸으로 변경됨",
  str_item_intro_9011074 = "액티브 스킬로 적을 넉백/끌어당길 시 적이 이동한 한 칸마다 3000의 고정피해를 입힘",
  str_item_intro_9011075 = "모든 오로리안의 돌파 레벨 +1(최대 돌파 오로리안은 적용되지 않음)",
  str_item_intro_9011076 = "일회성: 오로리안 1명을 선택해 파티에 합류시킴(최대 돌파 상태)",
  str_item_intro_9011077 = "버스터 클래스 오로리안의 연쇄 스킬이 명중 대상에게 <link=\"1003\"><color=#98500f><u>융해</u></color></link> 효과를 1회 부여함",
  str_item_intro_9011078 = "버스터 클래스 오로리안의 액티브 스킬이 40% 확률로 대상에게 <link=\"1011\"><color=#98500f><u>마비</u></color></link> 효과를 부여함",
  str_item_intro_9011079 = "버스터 클래스 오로리안의 최고 단계 연쇄 스킬 범위가 2서클로 확대됨",
  str_item_intro_9011080 = "버스터 클래스의 오로리안 일반공격에 방어무시 피해 추가, 대상에게 오로리안이 잃은 HP의 10%에 해당하는 피해를 입힘",
  str_item_intro_9011081 = "버스터 클래스 오로리안의 일반공격이 30% 확률로 1.5배의 피해를 입힘",
  str_item_intro_9011082 = "출전한 버스터 클래스 오로리안 1명당 모든 버스터 오로리안이 입히는 연쇄 스킬 피해 4% 증가",
  str_item_intro_9011083 = "스나이퍼 클래스 오로리안의 일반공격이 대상에게 자신의 공격력의 20%에 해당하는 <link=\"1004\"><color=#98500f><u>심판 수치</u></color></link> 추가",
  str_item_intro_9011084 = "스나이퍼 클래스 오로리안의 연쇄 스킬이 여러 칸 크기의 적에게 입히는 피해 증가",
