  str_item_8800421 = "「구리 벽장식」 연금술 레시피",
  str_item_intro_8800103 = "눈소나무 꼭대기에 맺힌 차가운 이슬을 채집한 것이다. 너무 맑아서 영혼까지 정화할 수 있을 듯하다.",
  str_item_intro_8800102 = "추운 날씨에 피어난 꽃이다. 은은한 향기를 풍긴다.",
  str_item_intro_8800101 = "어디에서나 볼 수 있는 얼음 조각이다. 대량으로 모이면 차가운 공기가 생성된다.",
  str_item_intro_8800203 = "매콤한 고급 버터다. 레디젤의 열정과 생명력을 느낄 수 있다.",
  str_item_intro_8800202 = "암석 표면에서 뜨거운 기름이 흘러나오고 있다.",
  str_item_intro_8800201 = "거친 붉은 모래는 사막의 온기를 간직하고 있다.",
  str_item_intro_8800303 = "무성한 가지들 사이로 흐르는 놀라운 생명력을 느낄 수 있다.",
  str_item_intro_8800302 = "희망의 씨앗을 품은 가벼운 솜털이 바람을 타고 퍼져나간다.",
  str_item_intro_8800301 = "평범한 녹색 씨앗이 땅에서 나오기를 기다리고 있다.",
  str_item_intro_8800403 = "매우 귀중하고 희귀한 크리스탈이다. 아침 햇살처럼 눈부신 빛을 발산하고 있다.",
  str_item_intro_8800402 = "안에서 천둥의 힘이 빛나고 있는 노란 보석이다.",
  str_item_intro_8800401 = "눈에 띄지 않는 광석이다. 일반 돌보다 약간 무겁다.",
  str_item_intro_8800113 = "영양 에센스는 식물과 동물에게 활력과 건강을 가져다준다.",
  str_item_intro_8800213 = "달콤하고 부드러우며, 한입 먹을 때마다 행복한 맛이 난다.",
  str_item_intro_8800313 = "외형과 촉감 모두 뛰어난 인형이다. 유행하는 선물이 될 가능성이 높다.",
  str_item_intro_8800413 = "매력적인 빛을 반사하는 수정구슬이다. 실내 공간 장식에 적합하다.",
  str_item_intro_8800112 = "매우 빠르게 작용하는 상처 연고다. 가정과 여행의 필수품이다.",
  str_item_intro_8800212 = "실크처럼 부드럽다. 마찰을 줄여 다양한 용도로 사용할 수 있다.",
  str_item_intro_8800312 = "녹색 생태 분재, 햇볕이 잘 드는 곳에서 잘 자란다.",
  str_item_intro_8800412 = "매우 날카롭고, 거리낌 없이 잘린다. 솜씨 좋은 장인의 선택.",
  str_item_intro_8800111 = "다른 물체를 식힐 수도 있고, 직접 마실 수도 있다.",
  str_item_intro_8800211 = "강력한 폭발물이다. 주의하여 사용해야 한다.",
  str_item_intro_8800311 = "견고하고 소박한 다용도 아마포다.",
  str_item_intro_8800411 = "벽에 거는 간단한 장식품이다. 절제된 아름다움을 지니고 있다.",
  str_item_intro_8800123 = "「영양 보충제」 연성에 필요한 조건이 기록된 레시피.",
  str_item_intro_8800223 = "「맛있는 케이크」 연성에 필요한 조건이 기록된 레시피.",
  str_item_intro_8800323 = "「화려한 인형」 연성에 필요한 조건이 기록된 레시피.",
