  str_item_intro_8800321 = "「아마포」 연성에 필요한 조건이 기록된 레시피.",
  str_item_intro_8800421 = "「구리 벽장식」 연성에 필요한 조건이 기록된 레시피.",
  str_item_8800005 = "유적 파편",
  str_item_intro_8800005 = "원래 유적의 일부였던 돌조각이다. 수천 년의 세월이 남긴 흔적을 엿볼 수 있다.",
  str_item_8800006 = "채집 운반자",
  str_item_intro_8800006 = "연금술 소재 채집 전용으로 쓰이는 운반자다. 매일 05:00에 2개 보충된다.",
  str_item_8800008 = "점포 자금",
  str_item_intro_8800008 = "연금술 점포를 운영하여 얻은 자금이다. 클라우디아의 도움을 받는다면 이 점포는 아스트라 대륙에서 분명히 크게 유명해질 수 있을 것이다.",
  str_item_8800010 = "SP",
  str_item_intro_8800010 = "연금술 점포에서 열심히 일해서 얻은 보상이다. 스킬트리의 부적과 특수기 레벨업에 사용된다.",
  str_item_8800011 = "하급 연금술 소재 상자",
  str_item_intro_8800011 = "하급 연금술 재료가 담긴 상자다.",
  str_item_8800012 = "중급 연금술 소재 상자",
  str_item_intro_8800012 = "중급 연금술 재료가 담긴 상자다.",
  str_item_8800013 = "상급 연금술 소재 상자",
  str_item_intro_8800013 = "상급 연금술 재료가 담긴 상자다.",
  str_item_1602411 = "페피타",
  str_item_intro_1602411 = "자유롭게 춤추는 화염 같은 소녀로, 일루미나 출신이지만 진리의 결사에 가입했다. 그녀는 누구에게도 복종할 생각이 없으며, 그저 자신의 의지로 재미를 찾고 싶을 뿐이다.",
  str_item_3220241 = "페피타 솔람버",
  str_item_intro_3220241 = "페피타 돌파 시 필수 아이템.\n그다지 정교해 보이지는 않는 보석이다. 그러나 손에 쥐고 있으면 방출되는 열은 극도로 강렬해 그 불굴의 본성을 드러낸다.",
  str_item_3777777 = "새로운 옷을 입을 수가 있어!",
  str_item_intro_3777777 = "내 새로운 옷은 과연 어떤 모습일까? 기대되네! 얼른 입어보고 싶어!",
  str_item_1701103 = "적막의 성녀"
